  },
  AvgCommunicate_100438_Content_13 = {Text = "¡Ah!"},
  AvgCommunicate_100438_Content_14 = {
    Text = "¿Está bien? ¿Está bien?"
  },
  AvgCommunicate_100438_Content_15 = {
    Text = "¡Modelos gratis, para ayudarte a buscar el arte más perfecto! ¿Dónde encontrar un modelo tan cooperativo?"
  },
  AvgCommunicate_100438_Content_16 = {
    Text = "...Tiene sentido."
  },
  AvgCommunicate_100438_Content_17 = {
    Text = "¡Nos vemos en el estudio mañana!"
  },
  AvgCommunicate_100438_Content_2 = {
    Text = "¡Clases magistrales de pintura que enseño personalmente, todos los materiales de pintura que atesoro están a tu disposición! ¿Estás emocionado?"
  },
  AvgCommunicate_100438_Content_3 = {
    Text = "¿hay algo así de bueno?"
  },
  AvgCommunicate_100438_Content_4 = {
    Text = "¡Estoy muy emocionado!"
  },
  AvgCommunicate_100438_Content_5 = {
    Text = "Como un gran pintor y un educador experimentado, la generosidad ha sido siempre una de mis características más destacadas. Sin embargo, por favor entiende que la creación de cualquier arte maravilloso requiere de la chispa de la inspiración..."
  },
  AvgCommunicate_100438_Content_6 = {
    Text = "¿Puedo pedirte que seas el modelo de mi obra como recompensa por la enseñanza?"
  },
  AvgCommunicate_100438_Content_7 = {
    Text = "¡Lo sabía..."
  },
  AvgCommunicate_100438_Content_8 = {
    Text = "¿Está bien? ¿Está bien?"
  },
  AvgCommunicate_100438_Content_9 = {
    Text = "¡Clases magistrales gratuitas, espacio de estudio gratuito, materiales de pintura gratuitos, todo gratis!"
  },
  AvgCommunicate_100438_Option_3 = {
    Text = "¿hay algo así de bueno?"
  },
  AvgCommunicate_100438_Option_4 = {
    Text = "¡Estoy muy emocionado!"
  },
  AvgCommunicate_100439_Content_1 = {
    Text = "¡Declaro que la imagen de expresión es el arte más grande de la nueva era!"
  },
  AvgCommunicate_100439_Content_10 = {
    Text = "Dado que es así, ¿podrías recomendarme a los pintores de estas imágenes de expresiones?"
  },
  AvgCommunicate_100439_Content_11 = {
    Text = "Por supuesto que sí."
  },
  AvgCommunicate_100439_Content_2 = {
    Text = "¿Hablas en serio?"
  },
  AvgCommunicate_100439_Content_3 = {
    Text = "¡Por supuesto! Siempre soy serio frente al arte."
  },
  AvgCommunicate_100439_Content_7 = {Text = "..."},
  AvgCommunicate_100439_Content_8 = {
    Text = "No spam. Estoy de acuerdo con lo que piensas."
  },
  AvgCommunicate_100439_Content_9 = {
    Text = "¡Genial! Sabía que podrías entender el arte que hay en mis ojos, no por nada eres el Guardián del Secreto."
  },
  AvgCommunicate_100440_Content_1 = {
    Text = "Esta noche, la oscuridad es perfecta, ¡es hora de llevar a cabo nuestra operación secreta!"
  },
  AvgCommunicate_100440_Content_10 = {
    Text = "Aclara tus palabras, ¿cuál es tu plan? Ten cuidado, podría decírselo a Dursayn."
  },
  AvgCommunicate_100440_Content_11 = {
    Text = "Solo quiero ir a la cocina a robar algunos ingredientes, en cuanto a mi compañera artista... no traicionaré a Shan."
  },
  AvgCommunicate_100440_Content_12 = {Text = "¡Maldito."},
  AvgCommunicate_100440_Content_13 = {
    Text = "......Tan fácil lo has explicado todo."
  },
  AvgCommunicate_100440_Content_14 = {
    Text = "¿Olvidaste las consecuencias de ser descubierto robando ingredientes de la cocina como modelo la última vez?"
  },
  AvgCommunicate_100440_Content_15 = {
    Text = "La última vez fue la última vez... Esta vez elegí especialmente el día del Festival de los Espíritus, y además tengo a Shan ayudándome, ¡no habrá problema."
  },
  AvgCommunicate_100440_Content_16 = {
    Text = "¿No se lo digas a Dursayn, por favor?"
