  },
  AvgCommunicate_100440_Content_7 = {
    Text = "Lo siento, esto iba dirigido a mi compañero artístico, así que considera que no lo has recibido."
  },
  AvgCommunicate_100440_Content_8 = {
    Text = "Compañero artístico... no puede ser..."
