  AvgCommunicate_100440_Content_9 = {
    Text = "Compañero artístico... no puede ser..."
  },
  AvgCommunicate_100440_Option_2 = {
    Text = "¿Operación secreta?"
  },
  AvgCommunicate_100440_Option_3 = {
    Text = "¿Y esto qué tipo de arte novedoso es?"
  },
  AvgCommunicate_100440_Option_8 = {
    Text = "¿Quién es tu compañero artístico?"
  },
  AvgCommunicate_100440_Option_9 = {Text = "..."},
  AvgCommunicate_121371_Content_1 = {
    Text = "La vi, despreocupada e incomprensible."
  },
  AvgCommunicate_121371_Content_2 = {
    Text = "La preferencia por los objetos externos es también absurdamente ingenua."
  },
  AvgCommunicate_121371_Content_3 = {
    Text = "......Murphy me dijo que no compró ninguna de las nuevas muñecas y vestidos que quería seleccionar este trimestre."
  },
  AvgCommunicate_121371_Content_4 = {
    Text = "Todos los números de la lotería han sido comprados con antelación. ¿Quién podría ser? Es tan difícil de adivinar."
  },
  AvgCommunicate_121371_Content_5 = {
    Text = "Como alguien que ha soportado durante más tiempo, es razonable recibir una pequeña compensación."
  },
  AvgCommunicate_121371_Content_6 = {
    Text = "......Por ejemplo, tener suficientes reliquias marinas para permitirte hacer lo que desees con el dinero?"
  },
  AvgCommunicate_121371_Content_7 = {Text = "Heh."},
  AvgCommunicate_121371_Content_8 = {
    Text = "Aunque debo admitir que sus elecciones y suerte anteriores quizás fueron un poco mejores que las mías."
  },
  AvgCommunicate_121371_Content_9 = {
    Text = "Pero ella debería entender que no toda rebelión contra el destino puede tener éxito."
  },
  AvgCommunicate_121372_Content_1 = {
    Text = "¡Usurpación! ¡Descortés! ¡Imperdonable!"
  },
  AvgCommunicate_121372_Content_10 = {Text = "Yo..."},
  AvgCommunicate_121372_Content_11 = {Text = "Tú..."},
  AvgCommunicate_121372_Content_12 = {
    Text = "Los estudiantes que pasan acariciando a los gatos están a punto de causar un fenómeno de congestión en el campus junto con los gatos, es un talento verdaderamente asombroso."
  },
  AvgCommunicate_121372_Content_13 = {
    Text = "Voy enseguida a salvarte."
  },
  AvgCommunicate_121372_Content_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_121372_Content_3 = {
    Text = "¡Es simplemente incomprensible! ¿Por qué Misaq dejaría entrar a esta criatura en el dormitorio!"
  },
  AvgCommunicate_121372_Content_4 = {
    Text = "Espera, escucho a alguien gritando en el edificio del dormitorio; ¿eres tú?"
  },
  AvgCommunicate_121372_Content_5 = {
    Text = "¡¿Cómo puede haber tantos gatos reunidos en la puerta?!"
  },
  AvgCommunicate_121372_Content_6 = {
    Text = "Estas pequeñas cosas malvadas y astutas me han estado siguiendo desde que aparecí; debe haber alguna conspiración, ¡quieren hacerle daño a la princesa!"
  },
  AvgCommunicate_121372_Content_7 = {
    Text = "......Creo que una criatura malvada que pretende hacer daño a alguien no debería yacer en el suelo con el vientre hacia arriba."
  },
  AvgCommunicate_121372_Content_8 = {
    Text = "El gato parece gustarte de una manera un poco inusual."
  },
  AvgCommunicate_121372_Content_9 = {
    Text = "¡Una tontería! En mi calidad de princesa, te ordeno que los eches de inmediato, de lo contrario, yo, yo..."
  },
  AvgCommunicate_121372_Option_10 = {Text = "Ya voy"},
  AvgCommunicate_121372_Option_11 = {Text = "tú"},
  AvgCommunicate_121375_Content_1 = {
    Text = "Sé lo que quieres decir, ellos lo hicieron voluntariamente."
  },
  AvgCommunicate_121375_Content_10 = {
    Text = "Considerando tu sinceridad... esta princesa te concede este honor."
  },
  AvgCommunicate_121375_Content_11 = {
    Text = "Bueno, entonces quiero ver una caja de tartas de frambuesa con mantequilla fresca."
  },
  AvgCommunicate_121375_Content_12 = {
    Text = "Te doy un cuarto de hora."
  },
  AvgCommunicate_121375_Content_13 = {
    Text = "¡Esto no cuenta como \"realmente necesario\", ¿verdad?!"
  },
  AvgCommunicate_121375_Content_14 = {Text = "¿Hm?"},
  AvgCommunicate_121375_Content_15 = {
    Text = "...Está bien, lo entiendo, no lo haré, hay muchos peces."
  },
  AvgCommunicate_121375_Content_16 = {
    Text = "Voy ahora, no dejes que aparezcan más cabezas de pescado en Misaq."
  },
  AvgCommunicate_121375_Content_2 = {
    Text = "Aunque no sé cómo lograste ponerte en contacto con ellos, ya no puedes dejar que el Generador Marino aparezca en Misaq, que haga recados por ti, que haga fila, o incluso que haga tu tarea."
  },
  AvgCommunicate_121375_Content_3 = {
    Text = "¿Sabes cuántos profesores y estudiantes se quejan de que los cuadernos de tareas se han vuelto pegajosos?"
  },
  AvgCommunicate_121375_Content_4 = {
    Text = "Solo son hormigas que vienen persiguiendo, queriendo servirme."
  },
  AvgCommunicate_121375_Content_5 = {
    Text = "Odio que me quiten la libertad, pero en cuanto al disfrute—nunca he tenido objeciones."
  },
  AvgCommunicate_121375_Content_6 = {
    Text = "Entonces, ¿por qué no aprovechar los desechos?"
  },
  AvgCommunicate_121375_Content_7 = {
    Text = "Porque no me gusta el olor del pescado."
  },
  AvgCommunicate_121375_Content_8 = {
    Text = "Porque no es seguro."
  },
  AvgCommunicate_121375_Content_9 = {
    Text = "Si es absolutamente necesario, te ayudaré a manejar los asuntos triviales, excluyendo la tarea."
  },
  AvgCommunicate_121375_Option_7 = {
    Text = "Porque no me gusta el olor del pescado"
