  AvgCommunicate_123719_Content_10 = {
    Text = "Qué pena, todavía mantenía la razón."
  },
  AvgCommunicate_123719_Content_11 = {
    Text = "Pero no puedo garantizar cuánto tiempo puedo mantenerme racional; cada minuto y segundo que paso aquí es un desafío para mis nervios."
