  },
  AvgCommunicate_123719_Content_15 = {
    Text = "Por ellos, puedo olvidar el aburrimiento de este mundo durante 0.01 segundos."
  },
  AvgCommunicate_123719_Content_2 = {Text = "¿¿¿???"},
