  },
  AvgCommunicate_123720_Content_1 = {
    Text = "Guardián, el informe sobre la Asamblea del Amanecer Estrellado ya está listo, ¡recuerda revisarlo~"
  },
  AvgCommunicate_123720_Content_10 = {
    Text = "Solo estaba repitiendo las cortesías necesarias en el informe."
  },
  AvgCommunicate_123720_Content_11 = {
