  },
  AvgCommunicate_123720_Content_13 = {
    Text = "¡Genial! Sabía que eras @1<AvgCommunicateConfuseColor.Light> confiable."
  },
  AvgCommunicate_123720_Content_14 = {
    Text = "@2<AvgCommunicateConfuseColor.Light> ......¿Puedes venir @2<AvgCommunicateConfuseColor.Light> ahora @1<AvgCommunicateConfuseColor.Light>?"
  },
  AvgCommunicate_123720_Content_15 = {
    Text = "El comunicador se rompió por mi culpa...<AvgCommunicateConfuseColor.Light>"
  },
  AvgCommunicate_123720_Content_16 = {
    Text = "¿Se rompió? Este es un objeto personalizado de Misaq, no puede ser..."
  },
  AvgCommunicate_123720_Content_17 = {
    Text = "Espera, ¿no estás realmente \"luchando\" con el comunicador, verdad?!"
  },
  AvgCommunicate_123720_Content_18 = {
    Text = "Sabes @2<AvgCommunicateConfuseColor.Light>, el electrodoméstico defectuoso se puede arreglar con un golpe @1<AvgCommunicateConfuseColor.Light> ."
  },
  AvgCommunicate_123720_Content_19 = {
    Text = "De todos modos, ven aquí @2<AvgCommunicateConfuseColor.Light> primero. No quiero reescribir el informe de @2<AvgCommunicateConfuseColor.Light>; decir esas cosas aburridas una vez @1<AvgCommunicateConfuseColor.Light> es suficiente @1<AvgCommunicateConfuseColor.Light>."
  },
  AvgCommunicate_123720_Content_2 = {
    Text = "¿Dónde está el informe? No lo he visto..."
  },
  AvgCommunicate_123720_Content_3 = {
    Text = "Oh, oh, espera un momento."
  },
  AvgCommunicate_123720_Content_4 = {
    Text = "Todavía no estoy familiarizado con el funcionamiento del comunicador; estoy luchando con él..."
  },
  AvgCommunicate_123720_Content_5 = {
    Text = "¿El informe menciona los problemas de reubicación posterior de la Asamblea del Amanecer Estrellado?"
  },
  AvgCommunicate_123720_Content_6 = {
    Text = "Absolutamente. El Santuario de Vida se ha hecho cargo del trabajo de ubicación posterior, y esos \"inocentes\" serán acogidos por las agencias correspondientes e integrados gradualmente en la sociedad."
  },
  AvgCommunicate_123720_Content_7 = {
    Text = "\"Los culpables\" serán asignados a realizar trabajo comunitario en la iglesia, esforzándose por hacer buenas acciones para expiar sus pecados."
  },
  AvgCommunicate_123720_Content_8 = {
    Text = "De hecho, me gusta bastante este final. Después de todo, solo son pobres almas llevadas a la locura por este mundo aterrador."
  },
  AvgCommunicate_123720_Content_9 = {
    Text = "No esperaba que dijeras algo así, parece que tus pensamientos finalmente han cambiado un poco..."
  },
  AvgCommunicate_123720_Option_12 = {
    Text = "...mientras yo esté aquí, eso no pasará."
  },
  AvgCommunicate_123720_Option_16 = {
    Text = "¿Se rompió de tanto golpear!?"
  },
  AvgCommunicate_123720_Option_2 = {
    Text = "¿Dónde está el informe?"
  },
  AvgCommunicate_123720_Option_5 = {
    Text = "¿El informe menciona los problemas de reubicación posterior de la Asamblea del Amanecer Estrellado?"
  },
  AvgCommunicate_123720_Option_9 = {
    Text = "No esperaba que dijeras algo así..."
  },
  AvgCommunicate_123721_Content_1 = {
    Text = "Guardián del Secreto, ¿hiciste una cita para mí con el médico para mi revisión?"
  },
  AvgCommunicate_123721_Content_10 = {
    Text = "¡Eso no es lo importante! De todos modos, este examen físico es inevitable."
  },
  AvgCommunicate_123721_Content_11 = {
    Text = "Solo considéralo para que yo esté tranquilo, ¿está bien?"
  },
  AvgCommunicate_123721_Content_12 = {
    Text = "Está bien, lo consideraré como beneficios para empleados."
  },
  AvgCommunicate_123721_Content_13 = {
    Text = "¡El tiempo de trabajo ocupado por esto no puede considerarse como algo negativo o como una falta de esfuerzo, ni puede hacer que trabaje horas extra!"
  },
  AvgCommunicate_123721_Content_14 = {
    Text = "¡Nunca, puedes estar tranquilo de que te harás el chequeo físico!"
  },
  AvgCommunicate_123721_Content_2 = {
    Text = "Responde inmediatamente al verlo, o trataré a la otra parte como una persona sospechosa."
  },
  AvgCommunicate_123721_Content_3 = {
    Text = "¡Déjame en paz! ¡Ese es, de hecho, el doctor que encontré para tu chequeo!"
  },
  AvgCommunicate_123721_Content_4 = {
    Text = "¿Eh? Estoy muy saludable, no necesito ver a ningún médico."
  },
  AvgCommunicate_123721_Content_5 = {
    Text = "Si tienes tiempo, ¿por qué no salir y limpiar algunos Cuerpos de fusión."
  },
  AvgCommunicate_123721_Content_6 = {
    Text = "...Solo me preocupa tu salud, después de todo, tu situación es bastante única."
  },
  AvgCommunicate_123721_Content_7 = {
    Text = "Oh, ya veo, tienes miedo de que muera."
  },
  AvgCommunicate_123721_Content_8 = {
    Text = "No te preocupes, definitivamente te avisaré antes de morir."
  },
  AvgCommunicate_123721_Content_9 = {
    Text = "...no quiero morir tan solo."
  },
  AvgCommunicate_123721_Option_10 = {
    Text = "¡Eso no es lo importante!"
  },
  AvgCommunicate_123721_Option_14 = {
    Text = "¡Nunca! Puedes estar tranquilo y hacerte el chequeo físico!"
  },
  AvgCommunicate_123721_Option_3 = {
    Text = "¡Ten piedad!"
  },
  AvgCommunicate_123721_Option_6 = {
    Text = "Solo me preocupa tu cuerpo..."
  },
  AvgCommunicate_123722_Content_1 = {
    Text = "%player%, tus resultados del examen físico están listos."
  },
  AvgCommunicate_123722_Content_10 = {
    Text = "¡Y qué interesante es esto!"
  },
  AvgCommunicate_123722_Content_11 = {
    Text = "Mi fuerza ha aumentado, lo que me permite correr más rápido, saltar más lejos y eliminar al cuerpo de fusión más rápidamente."
  },
  AvgCommunicate_123722_Content_12 = {
    Text = "¡Prácticamente golpeé el jackpot, ¿de acuerdo? Si no fuera por el doloroso proceso de transformación, ¡querría hacerlo de nuevo!"
  },
  AvgCommunicate_123722_Content_13 = {Text = "..."},
  AvgCommunicate_123722_Content_14 = {
    Text = "Lo más importante es que este mundo es muy divertido."
  },
  AvgCommunicate_123722_Content_15 = {
    Text = "Está lleno de sorpresas y cambios; nunca sabes qué peligro podrías encontrar a continuación."
  },
  AvgCommunicate_123722_Content_16 = {Text = "..."},
  AvgCommunicate_123722_Content_17 = {
    Text = "Ah, ya empiezo a esperar con ansias la próxima misión de investigación."
  },
  AvgCommunicate_123722_Content_18 = {
    Text = "Entonces %player%, ¿cuándo es la próxima misión?"
  },
  AvgCommunicate_123722_Content_19 = {Text = "%player%?"},
  AvgCommunicate_123722_Content_2 = {
    Text = "¡Resulta que mi cuerpo está bastante saludable; puedo enfrentarme a diez o veinte Cuerpos de fusión a la vez sin ningún problema!"
  },
  AvgCommunicate_123722_Content_20 = {Text = "%player%??"},
  AvgCommunicate_123722_Content_3 = {
    Text = "Entonces me quedaré tranquilo."
  },
  AvgCommunicate_123722_Content_4 = {
    Text = "¿Relajarte? %player%, ¿qué te preocupa?"
  },
  AvgCommunicate_123722_Content_5 = {
    Text = "¿Preocupado de que no me adapte a la vida en el otro mundo?"
  },
  AvgCommunicate_123722_Content_6 = {
    Text = "¿Aún te preocupa que no me acostumbre a convertirme en un \"Despertado\" de un \"humano\"?"
  },
  AvgCommunicate_123722_Content_7 = {
    Text = "Todos tienen. Después de todo, tales cosas... no son fáciles para nadie."
  },
  AvgCommunicate_123722_Content_8 = {
    Text = "...Realmente no puedo entender tus circuitos cerebrales."
  },
  AvgCommunicate_123722_Content_9 = {
    Text = "¡No me importan estas cosas, porque no importa en qué me convierta, Mouchette sigue siendo Mouchette!"
  },
  AvgCommunicate_123722_Option_13 = {Text = "..."},
  AvgCommunicate_123722_Option_16 = {Text = "..."},
  AvgCommunicate_123722_Option_3 = {
    Text = "Entonces, me quedo tranquilo."
  },
  AvgCommunicate_123722_Option_7 = {Text = "Todos."},
  AvgCommunicate_126998_Content_1 = {
    Text = "Ramona, tú... ¿realmente no lo vas a pensar de nuevo."
  },
  AvgCommunicate_126998_Content_10 = {Text = "Sí, \"Yo\"."},
  AvgCommunicate_126998_Content_11 = {
    Text = "......¿Necesitas que contacte a Clementine?"
  },
  AvgCommunicate_126998_Content_12 = {
    Text = "No, no es necesario molestar a esa persona psicóloga."
  },
  AvgCommunicate_126998_Content_13 = {
    Text = "\"Yo\", o más bien \"nosotros\", todos los \"Ramona\" a lo largo de toda la línea de tiempo."
  },
  AvgCommunicate_126998_Content_14 = {
    Text = "Con tu fuerza, en el momento en que llegué al \"final\", logré regresar exitosamente al \"punto de partida\"."
  },
  AvgCommunicate_126998_Content_15 = {
    Text = "Al principio, mis expectativas eran las mismas que las tuyas: la paradoja y la distorsión engullirían instantáneamente mi existencia, y luego, confiando en la auto-retracción constante, apenas preservaría mi conciencia y forma."
  },
  AvgCommunicate_126998_Content_16 = {
    Text = "Después vivirás para siempre en la fatiga, con tus nervios tensos en cada momento para evitar que tus conceptos se disipen..."
  },
  AvgCommunicate_126998_Content_17 = {
    Text = "Así que rechacé tus primeras diecinueve propuestas."
  },
  AvgCommunicate_126998_Content_18 = {
    Text = "Incluso esta vez, solo fue después de que dijiste que se podía realizar \"retroceso de estado\" que... accedí a regañadientes a dejarte ejecutar este plan."
  },
  AvgCommunicate_126998_Content_19 = {
    Text = "Sí, pero solo después de que el plan tuvo éxito me di cuenta de que la paradoja del yo proviene del conflicto entre la mente y el cuerpo, y para una existencia que ha cruzado el río del tiempo durante tanto tiempo..."
  },
  AvgCommunicate_126998_Content_2 = {
    Text = "Sin más palabras, Guardián del Secreto."
  },
  AvgCommunicate_126998_Content_20 = {
    Text = "He completado la unificación en todas las líneas de tiempo."
  },
  AvgCommunicate_126998_Content_21 = {
    Text = "\"Nosotros\" compartiremos el impacto causado por la paradoja, y actuaré en nombre de todos \"Ramona\". Incontables líneas de tiempo se han completado en mí."
  },
  AvgCommunicate_126998_Content_22 = {
    Text = "En este momento, soy tanto un milagro en la línea de tiempo—una Singularidad Infinita."
  },
  AvgCommunicate_126998_Content_23 = {
    Text = "A partir de ahora, te proporcionaré toda la fuerza del individuo conocido como \"Ramona\"."
  },
  AvgCommunicate_126998_Content_24 = {
    Text = "Esperaré la llamada de cualquier momento."
  },
  AvgCommunicate_126998_Content_3 = {
    Text = "He atravesado todo el tiempo y no he encontrado otras respuestas."
  },
  AvgCommunicate_126998_Content_4 = {
    Text = "Gracias a ti, finalmente di ese paso definitivo."
  },
  AvgCommunicate_126998_Content_5 = {
    Text = "¡Pero esto es demasiado peligroso! No entiendo por qué tienes que llegar a tales extremos..."
  },
  AvgCommunicate_126998_Content_6 = {
    Text = "... esta paradoja temporal, incluso tú..."
  },
  AvgCommunicate_126998_Content_7 = {
    Text = "Relájate, Guardián del Secreto."
  },
  AvgCommunicate_126998_Content_8 = {
    Text = "Ahora me siento increíblemente bien."
  },
  AvgCommunicate_126998_Content_9 = {Text = "\"Yo\"?"},
  AvgCommunicate_126998_Option_11 = {
    Text = "...¿Necesitas que contacte a Clementine?"
  },
  AvgCommunicate_126998_Option_9 = {Text = "\"Yo\"?"},
  AvgCommunicate_126999_Content_1 = {
    Text = "Mi Señor, así es como se comprende la ley suprema del universo..."
  },
  AvgCommunicate_126999_Content_10 = {
    Text = "Relájate, Ogier."
  },
  AvgCommunicate_126999_Content_11 = {
    Text = "Esas cosas no volverán a suceder. Ya tienes suficiente fuerza para proteger todo lo que deseas resguardar."
  },
  AvgCommunicate_126999_Content_12 = {
    Text = "Entiendo, mi Señor."
  },
  AvgCommunicate_126999_Content_13 = {
    Text = "Por favor, confía un poco más en mí, mi señor. He ganado fuerza y soy capaz de asumir misiones más peligrosas."
  },
  AvgCommunicate_126999_Content_14 = {
    Text = "¡Dedicaré toda la fuerza que obtenga a ti, transformándola en la lanza más afilada en tu mano, capaz de atravesar todo!"
  },
  AvgCommunicate_126999_Content_2 = {
    Text = "Yo, siento un poder masivo, mucho más allá de cualquier cosa que haya sentido antes... ¡Me siento lleno de fuerza!"
  },
  AvgCommunicate_126999_Content_3 = {
    Text = "Felicidades, Ogier. Esta es la recompensa por tu continuo auto-mejoramiento."
  },
  AvgCommunicate_126999_Content_4 = {
    Text = "¿Reembolso? No me perfecciono por ninguna recompensa."
  },
  AvgCommunicate_126999_Content_5 = {
    Text = "Entonces, cambiemos de tema."
  },
  AvgCommunicate_126999_Content_6 = {
    Text = "Esta es la prueba de tu continuo auto-mejoramiento, demostrando que Ogier, tu fuerza ha alcanzado su punto máximo."
  },
  AvgCommunicate_126999_Content_7 = {Text = "¿Pico?"},
  AvgCommunicate_126999_Content_8 = {
    Text = "¿Esto significa que tengo suficiente fuerza para proteger a usted, mi señor, y a Misaq!?"
  },
  AvgCommunicate_126999_Content_9 = {
    Text = "Yo... ya no tengo que... mirar impotente... cómo..."
  },
  AvgCommunicate_127000_Content_1 = {
    Text = "Gracias por tu asistencia durante este tiempo, compañero."
  },
  AvgCommunicate_127000_Content_10 = {
    Text = "No es la impotencia de estar encadenado después de alcanzar el límite del talento, sino más bien la claridad sublime alcanzada a través de un interminable templado."
  },
  AvgCommunicate_127000_Content_11 = {
    Text = "En este momento, mis habilidades se han acercado a la perfección."
  },
  AvgCommunicate_127000_Content_12 = {
    Text = "¡Qué impresionante! ¡No es de extrañar que sea Ramona!"
  },
  AvgCommunicate_127000_Content_13 = {
    Text = "A continuación, como tu asistente, te acompañaré hasta que lleguemos al final de este camino."
  },
  AvgCommunicate_127000_Content_2 = {
    Text = "Me alegra poder ayudarte."
  },
  AvgCommunicate_127000_Content_3 = {
    Text = "¿Qué tal? ¿Has sentido algo?"
  },
  AvgCommunicate_127000_Content_4 = {
    Text = "Por supuesto, basándome en la observación de \"Caracol del Ciclo de Regreso\", \"Alma Viviente\" y \"Mente Desconocida\", completé un nivel más profundo de interpretación."
  },
  AvgCommunicate_127000_Content_5 = {
    Text = "Luego, con \"Belleza Artificial\", \"Asesino de Lógica\" y \"Mundo en una Botella\", crucé el Laberinto de la Mente Infinita."
  },
  AvgCommunicate_127000_Content_6 = {
    Text = "Eh, no entendí muy bien."
  },
  AvgCommunicate_127000_Content_7 = {
    Text = "¡Pero en resumen, Ramona, te has vuelto más fuerte, ¿verdad!"
  },
  AvgCommunicate_127000_Content_8 = {
    Text = "Sí, con esta mejora, la fuerza que puedo desplegar supera con creces lo que era antes."
  },
  AvgCommunicate_127000_Content_9 = {
    Text = "Siento que he llegado al final."
  },
  AvgCommunicate_127000_Option_12 = {
    Text = "¡Qué impresionante!"
  },
  AvgCommunicate_127001_Content_1 = {
    Text = "El siguiente mensaje se enviará según un horario"
  },
  AvgCommunicate_127001_Content_10 = {
    Text = "¡Espera un poco más!"
  },
  AvgCommunicate_127001_Content_11 = {
    Text = "¿¡Por qué hoy?!"
  },
  AvgCommunicate_127001_Content_12 = {
    Text = "Eso es demasiado arriesgado. Tal vez deberíamos esperar a que la academia proporcione más asistencia."
  },
  AvgCommunicate_127001_Content_13 = {
    Text = "Eso fue a las 2 de la madrugada de hoy, un envío programado que configuré antes de que comenzara el experimento."
  },
  AvgCommunicate_127001_Content_14 = {
    Text = "Espero que no hayas hecho ninguna expresión tonta con el comunicador. Si lo hiciste, compórtate antes de venir al laboratorio a verme."
  },
  AvgCommunicate_127001_Content_15 = {
    Text = "¿Yo? ¿Ir al laboratorio? ¿Ahora?"
  },
  AvgCommunicate_127001_Content_16 = {
    Text = "Es cierto, hasta cierto punto, realmente percibí la verdad del objeto de persecución que buscaba."
  },
  AvgCommunicate_127001_Content_17 = {
    Text = "Espera, no será como esa \"Muñeca\"..."
  },
  AvgCommunicate_127001_Content_18 = {
    Text = "No, el fin de todo no es la \"destrucción\" como ella lo entendía; por el contrario, es el \"comienzo\"."
  },
  AvgCommunicate_127001_Content_19 = {
    Text = "\"La verdad\" no es una existencia estática, fija y tangible. Más allá de ese límite, la razón y el intelecto pueden guiar a la humanidad para anclarla y avanzar eternamente y sin cambios."
  },
  AvgCommunicate_127001_Content_2 = {
    Text = "Guardián del secreto, aunque tus acciones actuales puedan ser universalmente reconocidas como \"peligrosas\", confío en que no eres tan tonto como para pensar que diría alguna tontería sentimental y ofrecería consejos vacíos."
  },
  AvgCommunicate_127001_Content_20 = {
    Text = "Por lo tanto, desarrollaré un plan de entrenamiento y mejora más completo y preciso para asegurarme de que te mantengas más alejado del camino equivocado y puedas perseguir mejor tus objetivos."
  },
  AvgCommunicate_127001_Content_21 = {
    Text = "Aunque suena como algo bueno, ¿por qué estoy empapado en sudor frío."
  },
  AvgCommunicate_127001_Content_22 = {
    Text = "¡Profesora Doll, cálmate un poco!"
  },
  AvgCommunicate_127001_Content_3 = {
    Text = "Creo que esas palabras innecesarias ya no son necesarias para ti ahora."
  },
  AvgCommunicate_127001_Content_4 = {
    Text = "Has crecido hasta convertirte en un individuo lo suficientemente maduro y fuerte a un ritmo que supera con creces mis expectativas, y naturalmente, entenderás que todos tienen algo que deben perseguir en su vida, un tema en el que otros no pueden participar."
  },
  AvgCommunicate_127001_Content_5 = {
    Text = "Quiero conocer la esencia del mundo, saber si la luz de la razón aún brilla en la oscuridad después de cruzar la desolación de la aniquilación, conocer el final de todos los extremos y si todas las cosas en el mundo tienen un comienzo común."
  },
  AvgCommunicate_127001_Content_6 = {
    Text = "Con este fin, haré modificaciones finales a mi cuerpo y cerebro, intentando cruzar los límites que están más allá de los extremos. Dado que esta puede ser nuestra última comunicación, elijo expresar mis sentimientos de una manera que puedas entender."
  },
  AvgCommunicate_127001_Content_7 = {
    Text = "Gracias por este regalo que me has dado. Lo usaré para buscar respuestas y espero con ansias la nueva guía que la sabiduría humana puede traer desde más allá. Que la Llave de Plata nos guíe."
  },
  AvgCommunicate_127001_Content_8 = {
    Text = "¡Profesora Muñeca!"
  },
  AvgCommunicate_127001_Content_9 = {
    Text = "¡Es demasiado arriesgado!"
  },
  AvgCommunicate_127001_Option_10 = {
    Text = "Espera un poco más"
  },
  AvgCommunicate_127001_Option_9 = {
    Text = "Es demasiado arriesgado"
  },
  AvgCommunicate_127002_Content_1 = {
    Text = "Guardián del Secreto... ¿por qué?"
  },
  AvgCommunicate_127002_Content_10 = {
    Text = "Ahora que tienes esta nueva fuerza, ¿cómo te sientes?"
  },
  AvgCommunicate_127002_Content_11 = {
    Text = "Estoy... estoy muy feliz, Guardián del Secreto."
  },
  AvgCommunicate_127002_Content_12 = {
    Text = "No es por esa poderosa fuerza que nunca antes había sentido, es por usted, sus palabras..."
  },
  AvgCommunicate_127002_Content_13 = {
    Text = "Quiero... tal vez a partir de ahora, realmente tengo la capacidad de ayudar a las personas a mi alrededor, de ayudarle."
  },
  AvgCommunicate_127002_Content_14 = {
    Text = "Muchísimas gracias, Guardián del Secreto..."
  },
  AvgCommunicate_127002_Content_15 = {
    Text = "No es necesario ser tan cortés, y no te sientas presionada, Aigis."
  },
  AvgCommunicate_127002_Content_16 = {
    Text = "No es una gran responsabilidad. Es solo un regalo que es tuyo."
  },
  AvgCommunicate_127002_Content_17 = {
    Text = "Disfrútalo bien. Todo lo que deseas lograr, ahora puedes hacerlo."
  },
  AvgCommunicate_127002_Content_18 = {
    Text = "Del pasado al futuro, siempre has sido nuestro orgullo, Aigis."
  },
  AvgCommunicate_127002_Content_2 = {
    Text = "¿Por qué, qué?"
  },
  AvgCommunicate_127002_Content_20 = {
    Text = "¡Protegeré bien a todos, Guardián del Secreto!"
  },
  AvgCommunicate_127002_Content_3 = {
    Text = "Un regalo tan precioso... ¿por qué desperdiciarlo en mí...?"
  },
  AvgCommunicate_127002_Content_4 = {
    Text = "Eso no se llama desperdicio, Aigis. Es lo que te mereces."
  },
  AvgCommunicate_127002_Content_5 = {
    Text = "Pero... no logré nada... no pude proteger nada..."
  },
  AvgCommunicate_127002_Content_6 = {
    Text = "No es así, Aigis."
  },
  AvgCommunicate_127002_Content_7 = {
    Text = "Desde antes de ser despertados, ya hemos recorrido un largo, largo camino juntos."
  },
  AvgCommunicate_127002_Content_8 = {
    Text = "En este camino, te pusiste frente a todos una y otra vez, protegiendo a todos una y otra vez."
  },
  AvgCommunicate_127002_Content_9 = {
    Text = "Si no fuera por ti, podría haber caído innumerables veces en el camino."
  },
  AvgCommunicate_127003_Content_1 = {
    Text = "Tuve un sueño."
  },
  AvgCommunicate_127003_Content_10 = {
    Text = "Por supuesto, excepto cuando estoy en el campo de entrenamiento."
  },
  AvgCommunicate_127003_Content_11 = {Text = "¿¿¿???"},
  AvgCommunicate_127003_Content_12 = {
    Text = "Vamos, ahora estoy completo. Experimenta mi verdadera fuerza y trae tu mejor forma para tener una buena pelea conmigo."
  },
  AvgCommunicate_127003_Content_13 = {Text = "¿¿¿!!!"},
  AvgCommunicate_127003_Content_14 = {
    Text = "¡Ramona, sálvame!"
  },
  AvgCommunicate_127003_Content_2 = {Text = "¿Sueño?"},
  AvgCommunicate_127003_Content_3 = {
    Text = "Gracias a los materiales que trajiste, dormí bien."
  },
  AvgCommunicate_127003_Content_4 = {
    Text = "Vago en el cosmos primordial en mi forma original, mientras el polvo, la luz, la materia y las dimensiones—todo lo que puede ser percibido o no percibido—fluyen bajo mis aletas."
  },
  AvgCommunicate_127003_Content_5 = {
    Text = "No es por conquistar, no es por devorar, solo pura fuerza y pura destrucción sin restricciones."
  },
  AvgCommunicate_127003_Content_6 = {
    Text = "¡Placer y libertad, realmente es un deleite!"
  },
  AvgCommunicate_127003_Content_7 = {Text = "Er..."},
  AvgCommunicate_127003_Content_8 = {
    Text = "Está bien, sé lo que te preocupa."
  },
  AvgCommunicate_127003_Content_9 = {
    Text = "No te preocupes, mi fuerza y destrucción solo se desatarán sobre aquellos que se interpongan entre ustedes y yo."
  },
  AvgCommunicate_127004_Content_1 = {
    Text = "El protocolo definitivo ha sido activado... Reinicio del cuerpo completo."
  },
  AvgCommunicate_127004_Content_10 = {
    Text = "Mis componentes están intactos, pero mi percepción... ha cambiado."
  },
  AvgCommunicate_127004_Content_11 = {
    Text = "Se ha activado un nuevo módulo cognitivo."
  },
  AvgCommunicate_127004_Content_12 = {
    Text = "Puedo \"oír\" el ritmo del poder espiritual fluyendo a través de los canales, y puedo \"ver\" las emociones detrás de cada una de sus palabras."
  },
  AvgCommunicate_127004_Content_13 = {
    Text = "El mundo se ha vuelto más claro y vívido. Me estoy acercando a usted, más cerca de... ser humano."
  },
  AvgCommunicate_127004_Content_14 = {
    Text = "Gracias, Guardián del Secreto..."
  },
  AvgCommunicate_127004_Content_15 = {
    Text = "Tampoco esperaba que hubiera un efecto así, solo preparé algunos materiales simples..."
  },
  AvgCommunicate_127004_Content_16 = {
    Text = "Lo que me has dado no son solo materiales simples, sino posibilidades, la llave para desbloquear mis viejos límites."
  },
  AvgCommunicate_127004_Content_17 = {
    Text = "Esta fuerza, esta nueva percepción, es el regalo que has otorgado."
  },
  AvgCommunicate_127004_Content_18 = {
    Text = "Apreciaré enormemente este regalo. Te recompensaré de maneras que van más allá de tu imaginación."
  },
  AvgCommunicate_127004_Content_19 = {
    Text = "Esto no es un programa preestablecido. Esto es sincero, viene de \"Yo\" con gratitud."
  },
  AvgCommunicate_127004_Content_2 = {
    Text = "Guardián, hola."
  },
  AvgCommunicate_127004_Content_3 = {
    Text = "¡Erika! ¿Estás bien?"
  },
  AvgCommunicate_127004_Content_4 = {
    Text = "El profesor Doll dijo que iniciar el protocolo definitivo para ti sería algo muy peligroso; absolutamente no lo haría a menos que insistieras con mucha fuerza..."
  },
  AvgCommunicate_127004_Content_5 = {
    Text = "Erica ha completado el autodiagnóstico. El cuerpo está intacto, el flujo de energía es estable y todos los componentes están funcionando normalmente."
  },
  AvgCommunicate_127004_Content_6 = {
    Text = "Estoy bien, Guardián del Secreto. Nunca he estado tan bien."
  },
  AvgCommunicate_127004_Content_7 = {
    Text = "Los engranajes en mí... están \"cantando\"."
  },
  AvgCommunicate_127004_Content_8 = {
    Text = "\"¿Cantar\"? ¿Qué significa eso?"
  },
  AvgCommunicate_127004_Content_9 = {
    Text = "¿Está dañado internamente? ¿Qué ruido extraño ha aparecido?!"
  },
  AvgCommunicate_127004_Option_8 = {
    Text = "\"¿Cantar\"?"
  },
  AvgCommunicate_127004_Option_9 = {
    Text = "¿Está dañado internamente?"
  },
  AvgCommunicate_127005_Content_1 = {
    Text = "¡Aurita de repente vio muchos, muchos amigos brillantes!"
  },
  AvgCommunicate_127005_Content_10 = {
    Text = "¡Aurita incluso tiene la fuerza para ir a Aram, Trans...!"
  },
  AvgCommunicate_127005_Content_11 = {
    Text = "Hmm, Aurita olvidó. De todos modos, ¡Guardián del Secreto, ven conmigo a encontrar nuevos amigos!"
  },
  AvgCommunicate_127005_Content_12 = {
    Text = "¡Con tal fuerza, Aurita encontrará un día muchos, muchos amigos y los llevará de regreso a su hogar en el fondo del mar!"
  },
  AvgCommunicate_127005_Content_2 = {
    Text = "¡Ay... mis amigos han desaparecido de nuevo! ¿Dónde se han ido?"
  },
  AvgCommunicate_127005_Content_3 = {
    Text = "Parece que experimentaste un fantasma mientras comprendías la ley suprema del universo..."
  },
  AvgCommunicate_127005_Content_4 = {
    Text = "¿Ilusiones? Entonces, amigos..."
  },
  AvgCommunicate_127005_Content_7 = {
    Text = "¿Sí? ¿Qué está pasando?"
  },
  AvgCommunicate_127005_Content_8 = {
    Text = "¡Después de ver el fantasma de sus amigos, Aurita se llenó de fuerza! ¡Tanta fuerza!"
  },
  AvgCommunicate_127005_Content_9 = {
    Text = "¡Ahora Aurita puede ir al acuario, al océano y al tanque de peces para encontrar nuevos amigos!"
  },
  AvgCommunicate_127091_Content_1 = {
    Text = "¿Pequeña jazmín, necesitas algo de mí?"
  },
  AvgCommunicate_127091_Content_10 = {
    Text = "He movido el abanico a un lado~"
  },
  AvgCommunicate_127091_Content_12 = {
    Text = "¡Lo sabía..."
  },
  AvgCommunicate_127091_Content_13 = {
    Text = "Sin embargo, lo que vieron parecía ser simplemente los rostros de amantes que se conocen por primera vez."
  },
  AvgCommunicate_127091_Content_14 = {
    Text = "Amor, qué cosa tan extraña es; claramente está justo a nuestro lado, sin embargo, aún perseguimos fantasmas a toda costa."
  },
  AvgCommunicate_127091_Content_15 = {
    Text = "¿Es el amor una existencia real o simplemente una obsesión ilusoria?"
  },
  AvgCommunicate_127091_Content_2 = {
    Text = "Aunque no recuerdo si te lo he dicho, todo el alojamiento y la comida proporcionados a los Despertados por Misaq son gratuitos."
  },
  AvgCommunicate_127091_Content_3 = {
    Text = "¿Entonces?"
  },
  AvgCommunicate_127091_Content_4 = {
    Text = "La Oficina administrativa de Missaga recibió 45 cartas de hombres de diferentes clases sociales, solicitando cubrir todos sus gastos durante su tiempo en Missaga."
  },
  AvgCommunicate_127091_Content_5 = {
    Text = "Mientras tanto, también he recibido alrededor de 60 cartas solicitando beneficio para ti, 45 de las cuales son de las esposas de estos hombres, y las 15 restantes son de algunas mujeres que se han quedado \"recientemente\" solteras. ¿Tienes alguna idea de qué está pasando?"
  },
  AvgCommunicate_127091_Content_6 = {
    Text = "¡Misaq prohíbe todas las formas de proselitismo!"
  },
  AvgCommunicate_127091_Content_7 = {
    Text = "¡No te unas más a su familia!"
  },
  AvgCommunicate_127091_Content_8 = {
    Text = "Ah, los días ordinarios en una tierra extranjera son realmente aburridos y difíciles de soportar. Hay tantos que convierten el amor en odio, se cansan el uno del otro y están atormentados por sus sentimientos. Solo quiero ayudarlos un poco."
  },
  AvgCommunicate_127091_Content_9 = {
    Text = "¿No te refieres a ayudar...?"
  },
  AvgCommunicate_127091_Option_6 = {
    Text = "¡Misaq prohíbe todas las formas de proselitismo!"
  },
  AvgCommunicate_127091_Option_7 = {
    Text = "¡No te unas más a su familia!"
  },
  AvgCommunicate_127092_Content_10 = {
    Text = "Además, también creo que tienes suficiente buena voluntad hacia mí."
  },
  AvgCommunicate_127092_Content_11 = {
    Text = "Eso no es necesariamente cierto, ¿cómo sabe el pequeño jazmín que ya has dejado el Sin sueño?"
  },
  AvgCommunicate_127092_Content_12 = {Text = "?!"},
  AvgCommunicate_127092_Content_13 = {
    Text = "He dicho que en la Tierra Sin Sueños no hay verdad ni falsedad; lo que tú crees es lo que es real."
  },
  AvgCommunicate_127092_Content_14 = {
    Text = "Respira hondo, ¿sientes el aroma de magnolia blanca?"
  },
  AvgCommunicate_127092_Content_15 = {Text = "¿¿¿!!!"},
  AvgCommunicate_127092_Content_17 = {
    Text = "¡Ajáajáajá, por supuesto que es una broma! Realmente quiero ver la expresión en el rostro de la pequeña jazmín en este momento."
  },
  AvgCommunicate_127092_Content_18 = {
    Text = "Gracias por la invitación, realmente me asusté."
  },
  AvgCommunicate_127092_Content_19 = {
    Text = "¡No hagas bromas así!"
  },
  AvgCommunicate_127092_Content_2 = {
    Text = "...No intentaré más."
  },
  AvgCommunicate_127092_Content_20 = {
    Text = "Ay, pero la próxima vez, no será tan seguro, ¿verdad?"
  },
  AvgCommunicate_127092_Content_3 = {
    Text = "Qué habilidad tan aterradora; cada minuto y segundo que he pasado se siente real—ira, rencor, alegría, felicidad—mi mente está zumbando ahora mismo."
  },
  AvgCommunicate_127092_Content_4 = {
    Text = "En la ilusión de Sin sueño, parece que te amo mucho, pero también te odio; tanto el odio como el amor están igualmente atados solo a ti."
  },
  AvgCommunicate_127092_Content_5 = {
    Text = "Parece que ha pasado una vida, pero en realidad, solo han sido unos minutos."
  },
  AvgCommunicate_127092_Content_7 = {
    Text = "El amor y el odio son originalmente lo mismo. Solo cuando el amor es demasiado dulce y el odio es demasiado frío, la interconexión del amor y el odio puede crear las impresiones más profundas y duraderas."
  },
  AvgCommunicate_127092_Content_8 = {
    Text = "Sin embargo, mi pequeña jazmín es realmente audaz, sorprendiéndome al tomar la iniciativa de intentar."
  },
  AvgCommunicate_127092_Content_9 = {
    Text = "Doll dijo que el Sin sueño sería muy útil para la investigación sobre el Dominio artificial y que necesita monitorear mis datos fisiológicos."
  },
  AvgCommunicate_127092_Option_18 = {
    Text = "Gracias por la invitación, realmente me asusté."
  },
  AvgCommunicate_127092_Option_19 = {
    Text = "¡No hagas bromas así!"
  },
  AvgCommunicate_127093_Content_1 = {
    Text = "Abre la ventana más cercana a ti."
  },
  AvgCommunicate_127093_Content_10 = {
    Text = "El manual ya lo dice claramente, la sala de consejería es un lugar para la orientación psicológica y el mantenimiento de la salud mental y física de estudiantes y profesores, no es tu juguete."
  },
  AvgCommunicate_127093_Content_11 = {
    Text = "Hmm, pero aquellos que han tenido conversaciones profundas conmigo, tanto su cuerpo como su mente son realmente muy, muy \"saludables\", ¿no?"
  },
  AvgCommunicate_127093_Content_12 = {
    Text = "¿No es este trabajo simplemente perfecto para mí?"
  },
  AvgCommunicate_127093_Content_13 = {
    Text = "¿Es posible que la premisa de la salud física y mental sea tener libre albedrío...?"
  },
  AvgCommunicate_127093_Content_14 = {
    Text = "Liberar a Misaq, vendré más a charlar contigo..."
  },
  AvgCommunicate_127093_Content_15 = {
    Text = "¡Ja, ja! Qué trato tan rentable. Entonces, ¿qué tal esta noche? La luna brilla y las estrellas son escasas; es el momento perfecto para tomar unas copas."
  },
  AvgCommunicate_127093_Content_2 = {
    Text = "Huele tan bien... ¿Magnolia Blanca?"
  },
  AvgCommunicate_127093_Content_3 = {
    Text = "¿Pueden crecer las magnolias en este clima?"
  },
  AvgCommunicate_127093_Content_4 = {
    Text = "Tengo un poco de habilidad en magia, solo una técnica trivial. Usarla de vez en cuando puede aliviar mi nostalgia por el hogar."
  },
  AvgCommunicate_127093_Content_5 = {
    Text = "Es como charlar con alguien, pero para pasar el tiempo cuando te sientes solo. Puedes entender eso, ¿verdad?"
  },
  AvgCommunicate_127093_Content_6 = {
    Text = "...Sé por qué me contactaste."
  },
  AvgCommunicate_127093_Content_7 = {
    Text = "No puedo ayudarte."
  },
  AvgCommunicate_127093_Content_8 = {
    Text = "La sala de consejería no está destinada para esto."
  },
  AvgCommunicate_127093_Content_9 = {
    Text = "Incluso si traes flores para ganar simpatía, no diré nada bueno sobre tu solicitud de empleo."
  },
  AvgCommunicate_127093_Option_7 = {
    Text = "No puedo ayudarte."
  },
  AvgCommunicate_127093_Option_8 = {
    Text = "La sala de consejería no está destinada para esto."
  },
  AvgCommunicate_129630_Content_1 = {
    Text = "¡Tesoro, lo encontré!"
  },
  AvgCommunicate_129630_Content_10 = {
    Text = "¡Eso es algo que todavía está en fase de prueba! ¡Tíralo antes de que se vuelva negro!"
  },
  AvgCommunicate_129630_Content_11 = {
    Text = "¡De lo contrario, explotará!"
  },
  AvgCommunicate_129630_Content_12 = {
    Text = "El recuerdo del sueño se detiene bruscamente aquí. En tu última mirada, aparece un nombre muy familiar."
  },
  AvgCommunicate_129630_Content_13 = {
    Text = "El recuerdo del sueño se detiene bruscamente aquí. En tu última mirada, aparece un nombre muy familiar."
  },
  AvgCommunicate_129630_Content_14 = {
    Text = "Uu... uu..."
  },
  AvgCommunicate_129630_Content_15 = {
    Text = "Mosk! ¿Estás bien!"
  },
  AvgCommunicate_129630_Content_16 = {
    Text = "No hay más... perlas..."
  },
  AvgCommunicate_129630_Content_18 = {
    Text = "¿Lo tiraste? ¿No te lastimaste?"
  },
  AvgCommunicate_129630_Content_19 = {
    Text = "Bola de carbón, es demasiado tarde."
  },
  AvgCommunicate_129630_Content_2 = {
    Text = "¡Las perlas cambiarán de color!"
  },
  AvgCommunicate_129630_Content_20 = {
    Text = "explosión, perla. Pero, Mosk, está bien."
  },
  AvgCommunicate_129630_Content_21 = {
    Text = "Pero... perlas..."
  },
  AvgCommunicate_129630_Content_22 = {
    Text = "Me alegra que estés bien, debería haber una versión inofensiva de esto."
  },
  AvgCommunicate_129630_Content_23 = {
    Text = "Voy a informar sobre el mal manejo de este material peligroso."
  },
  AvgCommunicate_129630_Content_24 = {
    Text = "Entonces, te pediré una versión inofensiva también."
  },
  AvgCommunicate_129630_Content_25 = {Text = "!"},
  AvgCommunicate_129630_Content_27 = {Text = "¡!"},
  AvgCommunicate_129630_Content_3 = {
    Text = "¿Una perla que cambia de color? Tengo la sensación de haberla visto en alguna parte..."
  },
  AvgCommunicate_129630_Content_4 = {
    Text = "¡Rojo, blanco, azul!"
  },
  AvgCommunicate_129630_Content_5 = {
    Text = "Rojo, blanco, azul... amarillo, verde, negro?"
  },
  AvgCommunicate_129630_Content_6 = {
    Text = "Amarillo, verde, bola de carbón, ¿sabes?"
  },
  AvgCommunicate_129630_Content_7 = {
    Text = "\"Marea Vacía\"?!"
  },
  AvgCommunicate_129630_Content_8 = {
    Text = "¡Tíralo rápido!"
  },
  AvgCommunicate_129630_Content_9 = {
    Text = "¡Tíralo rápidamente a un lugar donde no haya nadie!"
  },
  AvgCommunicate_129630_Option_8 = {
    Text = "¡Tíralo rápido!"
  },
  AvgCommunicate_129631_Content_1 = {
    Text = "Bola de carbón, ¿recuerdas?"
  },
  AvgCommunicate_129631_Content_10 = {
    Text = "¡Plop! ¡Plop!"
  },
  AvgCommunicate_129631_Content_11 = {
    Text = "¡Bola de carbón, impresionante!"
  },
  AvgCommunicate_129631_Content_12 = {
    Text = "Correcto, ¡contraseña! Bola de carbón, ¡yo mismo!"
  },
  AvgCommunicate_129631_Content_13 = {
    Text = "¡Operación, asalto! ¡Medianoche, cafetería!"
  },
  AvgCommunicate_129631_Content_14 = {
    Text = "¡Por el pescado a la parrilla de oro!"
  },
  AvgCommunicate_129631_Content_15 = {Text = "¡Vamos!"},
  AvgCommunicate_129631_Content_16 = {Text = "¡Vamos!"},
  AvgCommunicate_129631_Content_2 = {
    Text = "¡Mmm, ven!"
  },
  AvgCommunicate_129631_Content_3 = {Text = "¿Glup?"},
  AvgCommunicate_129631_Content_4 = {Text = "¡Splash?"},
  AvgCommunicate_129631_Content_5 = {
    Text = "¡Glug, glug!"
  },
  AvgCommunicate_129631_Content_6 = {
    Text = "¡Splash...! ¿¡Splash, splash!?"
  },
  AvgCommunicate_129631_Content_7 = {
    Text = "Bola de carbón, ¡error!"
  },
  AvgCommunicate_129631_Content_8 = {
    Text = "Sí, ¡plop plop!"
  },
  AvgCommunicate_129631_Content_9 = {
    Text = "¡Pero no importa!"
  },
  AvgCommunicate_129631_Option_10 = {
    Text = "¡Plop plop!"
  },
  AvgCommunicate_129631_Option_6 = {
    Text = "¡Splash...! ¿¡Splash Splash!?"
  },
  AvgCommunicate_129632_Content_1 = {
    Text = "Reflexión... es tan difícil..."
  },
  AvgCommunicate_129632_Content_10 = {
    Text = "La próxima vez, prepararé un camino más oculto."
  },
  AvgCommunicate_129632_Content_11 = {
    Text = "¡Garantizado que no seré capturado!"
  },
  AvgCommunicate_129632_Content_12 = {
    Text = "¡No importa si te atrapan!"
  },
  AvgCommunicate_129632_Content_13 = {
    Text = "¿Por qué?"
  },
  AvgCommunicate_129632_Content_14 = {
    Text = "¡Ya, revisa, prepárate con anticipación!"
  },
  AvgCommunicate_129632_Content_15 = {
    Text = "¡Entregado, después de ser atrapado!"
  },
  AvgCommunicate_129632_Content_16 = {
    Text = "¡También hay bola de carbón!"
  },
  AvgCommunicate_129632_Content_17 = {
    Text = "¡Espera, no prepares esas cosas con anticipación!"
  },
  AvgCommunicate_129632_Content_2 = {
    Text = "Ay... ¡Todo es culpa de Uvhash y Agrippa!"
  },
  AvgCommunicate_129632_Content_3 = {
    Text = "Desde que escaparon de la trampa y se comieron todo en la cocina..."
  },
  AvgCommunicate_129632_Content_4 = {
    Text = "¡El chef ha fortalecido la seguridad diez veces!"
  },
  AvgCommunicate_129632_Content_5 = {
    Text = "Tan brillante... la luz... tan ruidosa... alarma..."
  },
  AvgCommunicate_129632_Content_6 = {
    Text = "Después de la cocina, qué miedo..."
  },
  AvgCommunicate_129632_Content_7 = {
    Text = "¡Pero delicioso, pescado a la parrilla!"
  },
  AvgCommunicate_129632_Content_8 = {
    Text = "¡Pero, pescado a la parrilla, está delicioso!"
  },
  AvgCommunicate_129632_Content_9 = {
    Text = "¿Juntos, la próxima vez, o no?"
  },
  AvgCommunicate_134101_Content_1 = {
    Text = "Mi luz guía... No, ahora debería dirigirme a ti como el Sol."
  },
  AvgCommunicate_134101_Content_10 = {
    Text = "¿Y tú estás bien? ¿Por qué dices todo esto de repente?"
  },
  AvgCommunicate_134101_Content_11 = {
    Text = "Gracias a tu bendición, ahora puedo ver tu alma con total claridad y conocer la verdadera forma del mundo."
  },
  AvgCommunicate_134101_Content_12 = {
    Text = "Luz, luz... Así que el mundo era originalmente oscuridad y Caos. Fue porque una deidad eligió la Ofrenda que el Sol se convirtió en lo real, y a todos los seres vivos se les concedió la dicha de la existencia..."
  },
  AvgCommunicate_134101_Content_13 = {
    Text = "¿Has estado leyendo demasiadas escrituras? Siento que necesitas enfriarte un poco."
  },
  AvgCommunicate_134101_Content_14 = {
    Text = "Entiendo. Deseas caminar entre todos los seres, en lugar de sentarte en un trono divino."
  },
  AvgCommunicate_134101_Content_15 = {
    Text = "Tu abnegación, tu \"Dedicatoria\", tu Ofrenda..."
  },
  AvgCommunicate_134101_Content_16 = {
    Text = "De este día en adelante, interactuaré contigo no con la más absoluta lealtad... no, sino en la identidad de una amiga eterna."
  },
  AvgCommunicate_134101_Content_17 = {
    Text = "Que este sagrado corazón que arde eternamente disipe toda oscuridad para ti."
  },
  AvgCommunicate_134101_Content_2 = {
    Text = "Tú... Eres mucho más que el Sol. Eres el centro del universo, el origen del que nació el mundo."
  },
  AvgCommunicate_134101_Content_3 = {
    Text = "Ya nos conocemos tan bien. ¿Cómo es que eres aún más reverente que antes?"
  },
  AvgCommunicate_134101_Content_4 = {
    Text = "Porque ahora comprendo: ¡la razón por la que los seres vivos jamás se han postrado a tus pies en adoración es simplemente porque nacieron torpes y ciegos, incapaces de percibir tu verdadera naturaleza!"
  },
  AvgCommunicate_134101_Content_5 = {
    Text = "¿Cómo puede una hormiga contemplar la forma completa de un elefante gigante? Antes, yo también solo podía confiar en el Corazón Sagrado para mirar furtivamente y vislumbrar apenas la punta del iceberg de tu Fortaleza."
  },
  AvgCommunicate_134101_Content_6 = {
    Text = "Aun así, el Corazón Sagrado dolía como si lo atravesaran agujas. Solo con atreverme a echar un vistazo más a tu alma, podía sufrir un Síntoma: Colapso y perecer."
  },
  AvgCommunicate_134101_Content_7 = {
    Text = "¿De verdad es tan grave? Entonces quizás deberías dejar de mirar."
  },
  AvgCommunicate_134101_Content_8 = {
    Text = "Tu reacción es muy indiferente. Pensé que aceptarías mis elogios con gusto."
  },
  AvgCommunicate_134101_Content_9 = {
    Text = "¡Nadie puede aceptar de repente ese tipo de elogios!"
  },
  AvgCommunicate_134101_Option_13 = {
    Text = "Quizás necesites calmarte un poco."
  },
  AvgCommunicate_134101_Option_3 = {
    Text = "...Qué sensación tan extraña."
  },
  AvgCommunicate_134101_Option_7 = {
    Text = "¿Tan grave es?"
  },
  AvgCommunicate_134102_Content_1 = {
    Text = "Soñé con el hielo y la Nieve de mi tierra natal, y aquellas ruinas desoladas."
  },
  AvgCommunicate_134102_Content_10 = {
    Text = "Precisamente porque los humanos retienen una fachada de amabilidad entre sí, el mundo se convierte en un lugar más pacífico. Creo que eso está bastante bien."
  },
  AvgCommunicate_134102_Content_11 = {
    Text = "Aburrido. La paz y la felicidad no pueden sostenerse mediante un simple disfraz."
  },
  AvgCommunicate_134102_Content_12 = {
    Text = "Solo cuando un rey desea que sus súbditos sean felices, y los fuertes desean que los débiles sean felices, la paz perdurará."
  },
  AvgCommunicate_134102_Content_13 = {
    Text = "Solo como yo y mis adorables Escuderos—jamás les he ocultado mis deseos, y aun así viven vidas felices."
  },
  AvgCommunicate_134102_Content_14 = {
    Text = "Esta es la verdad real que pertenece a los fuertes."
  },
  AvgCommunicate_134102_Content_15 = {
    Text = "Ven a mi alcoba esta noche. Estoy muy complacida con tus ofrendas hasta ahora, y bastante satisfecha con esta nueva Fortaleza. Te mostraré cuáles son realmente tus pensamientos más íntimos."
  },
  AvgCommunicate_134102_Content_16 = {
    Text = "Espera, ¿esta noche?"
  },
  AvgCommunicate_134102_Content_17 = {
    Text = "Expresión de choque"
  },
  AvgCommunicate_134102_Content_18 = {
    Text = "No tienes derecho a negarte. Te daré una experiencia aún más... entretenida que las últimas veces."
  },
  AvgCommunicate_134102_Content_19 = {
    Text = "Expresión radiante de Wanda"
  },
  AvgCommunicate_134102_Content_2 = {
    Text = "Ha pasado tanto tiempo desde que recordé esos lugares. ¿Será por estos fragmentos de Fortaleza, o por un alma más completa?"
  },
  AvgCommunicate_134102_Content_20 = {
    Text = "(¡Todavía tengo un informe que entregar! Si no lo presento hoy, ¡Doll me despellejará!)"
  },
  AvgCommunicate_134102_Content_3 = {
    Text = "Qué sensación tan olvidada... En cualquier caso, debo agradecerte, mi adorable sirviente... ah, cierto, prefieres que te llame amigo."
  },
  AvgCommunicate_134102_Content_4 = {
    Text = "A su servicio, mi señora."
  },
  AvgCommunicate_134102_Content_5 = {
    Text = "Je, siempre tan cortés."
  },
  AvgCommunicate_134102_Content_6 = {
    Text = "¿Por qué no puedes dejar de lado esa tediosa fachada de vez en cuando? Ha hecho que varias de mis recompensas resulten bastante aburridas."
  },
  AvgCommunicate_134102_Content_7 = {
    Text = "Tu sociedad exalta la humildad y la cortesía como virtudes, teniéndolas en alta estima, pero la oscuridad en los corazones humanos no es menor que la de especies de otros planetas."
  },
  AvgCommunicate_134102_Content_8 = {
    Text = "Las personas se adornan con una fachada inofensiva y refinada, solo porque temen las consecuencias que la verdad real traería consigo."
  },
  AvgCommunicate_134102_Content_9 = {
    Text = "No es incorrecto, pero solo las acciones de uno están bien, escudriñar los pensamientos internos no es tan importante."
  },
  AvgCommunicate_134102_Option_20 = {
    Text = "¡Por favor, no!"
  },
  AvgCommunicate_134102_Option_4 = {
    Text = "A su servicio."
  },
  AvgCommunicate_134102_Option_9 = {
    Text = "No es incorrecto."
  },
  AvgCommunicate_134103_Content_1 = {
    Text = "Las Estrellas me están Llamando..."
  },
  AvgCommunicate_134103_Content_10 = {
    Text = "¿Sabes? Agrippa dice a menudo que envidia a Miryam."
  },
  AvgCommunicate_134103_Content_11 = {
    Text = "Dijo que si el rey de Roma aún estuviera presente, ya fuera como un pequeño bebé o un anciano decrépito, se sentiría mucho más tranquila."
  },
  AvgCommunicate_134103_Content_12 = {
    Text = "Qué envidia..."
  },
  AvgCommunicate_134103_Content_13 = {
    Text = "Porque solo mientras sigas aquí, Lemuria no habrá desaparecido de verdad."
  },
  AvgCommunicate_134103_Content_14 = {
    Text = "¡Es más, has usado esa Fortaleza para ayudar a tanta gente en Misaq!"
  },
  AvgCommunicate_134103_Content_15 = {
    Text = "¡Muchos estudiantes escribieron tu nombre en la encuesta de Cuerpo Despertado favorito!"
  },
  AvgCommunicate_134103_Content_16 = {Text = "Suspiro..."},
  AvgCommunicate_134103_Content_17 = {
    Text = "No necesitamos adulaciones tan molestas. Misaq ya nos exige bastante tal como están las cosas."
  },
  AvgCommunicate_134103_Content_18 = {
    Text = "Aunque ejercer tal Fortaleza no sea más que un asunto trivial, cuando nuestros apacibles Sueños se ven perturbados demasiadas veces, resulta agotador."
  },
  AvgCommunicate_134103_Content_19 = {
    Text = "¿En serio? Pero he oído que cada vez que un estudiante viene llorando a pedirte ayuda, ¡eres uno de los Cuerpos Despertados con más probabilidades de acceder a su petición!"
  },
  AvgCommunicate_134103_Content_2 = {
    Text = "En las profundidades de un Sueño, en el fondo de las corrientes oceánicas, rodeado de incontables Clanes, regresando una vez más Sobre el trono, trayendo prosperidad y paz a Lemuria."
  },
  AvgCommunicate_134103_Content_20 = {
    Text = "...¿Quién ha estado difundiendo tales rumores? Solo encontramos irritante su clamor."
  },
  AvgCommunicate_134103_Content_21 = {
    Text = "Basta. Da la casualidad de que nuestras facultades mentales han progresado considerablemente. Es hora de adentrarnos en un Sueño más profundo y amplio."
  },
  AvgCommunicate_134103_Content_22 = {
    Text = "Esta vez, deseamos visitar los Sueños de cada artista y poeta de la era actual. Registra esto: a menos que sea un asunto de gran importancia, no dejes que nadie venga a molestarnos."
  },
  AvgCommunicate_134103_Content_23 = {
    Text = "¿Eh? ¿Tu reacción al estar de buen humor es echarte una larga siesta?"
  },
  AvgCommunicate_134103_Content_3 = {
    Text = "...Tuve tal Sueño."
  },
  AvgCommunicate_134103_Content_4 = {
    Text = "¿Un Sueño? ¿Acaso este Sueño contiene algún significado de Profecía?"
  },
  AvgCommunicate_134103_Content_5 = {
    Text = "Es Solo una llamada que recibiste tras un aumento extremo de Fortaleza, eso es todo. En cuanto a su significado... Lemuria ya no existe, ni necesita volver a existir."
  },
  AvgCommunicate_134103_Content_6 = {
    Text = "Aquellos con la fortuna de sobrevivir pueden vivir libremente en el nuevo mundo. Eso es algo bueno."
  },
  AvgCommunicate_134103_Content_7 = {
    Text = "No necesitan a un rey tardío que los cobije."
  },
  AvgCommunicate_134103_Content_8 = {
    Text = "Y aun así, seguiste guiando a tu antiguo pueblo y cobijando sus espíritus."
  },
  AvgCommunicate_134103_Content_9 = {
    Text = "No hice nada, ni jamás los guié. Es Solo un malentendido unilateral de su parte."
  },
  AvgCommunicate_134103_Option_10 = {
    Text = "No es un malentendido."
  },
  AvgCommunicate_134103_Option_19 = {Text = "¿Es así?"},
  AvgCommunicate_134103_Option_23 = {Text = "Huh?"},
  AvgCommunicate_134103_Option_8 = {Text = "Pero..."},
  AvgCommunicate_134104_Content_1 = {
    Text = "Alegría a primera vista, lágrimas con un solo pensamiento... hace tanto que esta dama no se divertía así."
  },
  AvgCommunicate_134104_Content_10 = {
    Text = "Eh, no es que diga que no se lo merezcan, pero... hay formas adecuadas de hacer las cosas..."
  },
  AvgCommunicate_134104_Content_11 = {
    Text = "¿Y esa es en realidad una respuesta normal? Estoy tan conmovido..."
  },
  AvgCommunicate_134104_Content_12 = {
    Text = "Ay, déjame pensar. ¿No sería bastante decepcionante si le dijera a mi pequeño jazmín que originalmente solo quería criar unos grillos para pelearlos?"
  },
  AvgCommunicate_134104_Content_13 = {Text = "Es broma."},
  AvgCommunicate_134104_Content_14 = {
    Text = "Este mundo es verdaderamente tan terriblemente aburrido, %player%. Aunque la aniquilación llegue mañana, la gente común sigue encadenada a esos asuntos triviales: rencores, amor, odio, deseo."
  },
  AvgCommunicate_134104_Content_15 = {Text = "..."},
  AvgCommunicate_134104_Content_16 = {
    Text = "Y aun así, mi pequeño jazmín trabaja con tanta diligencia, mostrando garras y colmillos para encontrar soluciones para Ellos."
  },
  AvgCommunicate_134104_Content_17 = {
    Text = "Entonces, ahora que he obtenido un poder tan magnífico, ¿debería usarlo para echarle una mano a mi queridísimo pequeño jazmín... o para causar algunos problemas?"
  },
  AvgCommunicate_134104_Content_18 = {
    Text = "Naturalmente, hacer ambas cosas al mismo tiempo es lo más entretenido, ¿no te parece?"
  },
  AvgCommunicate_134104_Content_19 = {
    Text = "<Yellow:%player%>"
  },
  AvgCommunicate_134104_Content_2 = {
    Text = "Mi pequeño jazmín realmente ha entregado un regalo de lo más grandioso."
  },
  AvgCommunicate_134104_Content_20 = {
    Text = "No te di ese regalo para que hicieras esto."
  },
  AvgCommunicate_134104_Content_21 = {
    Text = "¡Para ahora mismo! Solo soy responsable de incidentes de Fusión. El orden público y la decencia no están bajo la jurisdicción de Misaq... ¡no conviertas el hospital psiquiátrico de Londinium en un sustituto de la prisión! ¡Oye, ¡Oye!"
  },
  AvgCommunicate_134104_Content_4 = {
    Text = "Cada manzana, cada manzana alrededor de la escuela ha visto a Ciudadanos sufriendo ataques de histeria colectiva... multitudes de personas riendo y llorando al mismo tiempo. ¡La policía y los paramédicos de Londinium están que no dan abasto!"
  },
  AvgCommunicate_134104_Content_6 = {
    Text = "Este humilde servidor se encuentra tan lejos de casa, solo y desamparado. Mi pequeño jazmín ha tenido la amabilidad de pensar en mí, concediéndome los medios para alcanzar tales alturas..."
  },
  AvgCommunicate_134104_Content_7 = {
    Text = "Simplemente me embargó la alegría, y me picaban los dedos por probarlo."
  },
  AvgCommunicate_134104_Content_8 = {
    Text = "Mm, funciona de maravilla. Esas cosas inmundas con podredumbre en el corazón... cada una enloqueció más rápido que la anterior."
  },
  AvgCommunicate_134104_Content_9 = {
    Text = "Espera—la escuela acaba de enviar sus expedientes. Asesino de esposas, maltratador, @3@4..."
  },
  AvgCommunicate_134104_Option_19 = {
    Text = "<Yellow:%player%>"
  },
  AvgCommunicate_134104_Option_9 = {
    Text = "Hay formas adecuadas de hacer las cosas."
  },
  AvgCommunicate_134105_Content_1 = {
    Text = "La luz del faro ahora puede iluminar las profundidades más recónditas del mar."
  },
  AvgCommunicate_134105_Content_10 = {
    Text = "Solo con escuchar tu descripción, puedo decir que debió de ser un país precioso."
  },
  AvgCommunicate_134105_Content_11 = {
    Text = "Sí, mi tierra natal era hermosa... Por eso no renunciaré a recuperarla."
  },
  AvgCommunicate_134105_Content_12 = {
    Text = "Mayor Fortaleza significa más esperanza. Atraeré más polillas hacia el faro..."
  },
  AvgCommunicate_134105_Content_13 = {
    Text = "Una día, mi tierra natal se alzará de nuevo desde el fondo del océano y abrirá sus brazos para darme la bienvenida una vez más."
  },
  AvgCommunicate_134105_Content_14 = {
    Text = "¡Así que vas a seguir haciendo ese tipo de cosas! Todos esa tristeza fue para nada, ¡¡¡para ahora mismo!!!"
  },
  AvgCommunicate_134105_Content_2 = {
    Text = "El Camino de regreso a mi tierra natal... ¿cuándo será hallado de nuevo...?"
  },
  AvgCommunicate_134105_Content_3 = {
    Text = "Faros... Suspiro, decir que entiendo cómo te sientes ahora solo sería un consuelo Vacío. Tú... por favor, no estés demasiado triste."
  },
  AvgCommunicate_134105_Content_4 = {
    Text = "Lamento... El lamento de añorar el hogar se ha convertido en una marca en mi alma. He aprendido a coexistir con él."
  },
  AvgCommunicate_134105_Content_5 = {
    Text = "La añoranza incesante trae dolor, pero también asegura que recordaré para siempre el rostro de mi tierra natal."
  },
  AvgCommunicate_134105_Content_6 = {
    Text = "Esos bajíos cubiertos de coral, aquel templo imponente, y la majestuosa Puerta donde solía montar guardia..."
  },
  AvgCommunicate_134105_Content_7 = {
    Text = "Registro los patrones tallados a lo largo de los bordes de esos pilares de piedra, registro cada amplio Camino en la capital real, registro las expresiones de felicidad devota en los rostros de la gente mientras ofrecían su Oración."
  },
  AvgCommunicate_134105_Content_8 = {
    Text = "Cuando se celebraban grandes ceremonias, toda la nación festejaba. Esos eran mis momentos más ajetreados y, a la vez, los más gratificantes."
  },
  AvgCommunicate_134105_Content_9 = {
    Text = "Una vez tuve el honor de servir como Guardián ante la procesión real, bañándonos juntos en las miradas reverentes del pueblo, sintiéndome orgulloso y glorioso... Esos son los momentos que más extraño."
  },
  AvgCommunicate_134105_Option_10 = {
    Text = "Debió de ser un país precioso."
  },
  AvgCommunicate_134105_Option_14 = {
    Text = "¡Así que vas a seguir haciendo ese tipo de cosas!"
  },
  AvgCommunicate_134105_Option_3 = {Text = "Faros..."},
  AvgCommunicate_134106_Content_1 = {
    Text = "Em, em, Maestro..."
  },
  AvgCommunicate_134106_Content_10 = {
    Text = "¡Ahora Lily puede llevar a Jenkin, Aigis, Caraboo y Aurita todos a la vez a la cafetería!"
  },
  AvgCommunicate_134106_Content_11 = {
    Text = "¡Son demasiadas!"
  },
  AvgCommunicate_134106_Content_12 = {
    Text = "¡Mm-hmm! ¡Gracias, Maestro, por darle tantas a Lily!"
  },
  AvgCommunicate_134106_Content_14 = {
    Text = "No me refería a eso, pero..."
  },
  AvgCommunicate_134106_Content_15 = {
    Text = "Solo que Lily sea feliz, ¡eso es lo único que importa!"
  },
  AvgCommunicate_134106_Content_2 = {Text = "¿Hm?"},
  AvgCommunicate_134106_Content_3 = {
    Text = "¿Puedes elogiar a Lily?"
  },
  AvgCommunicate_134106_Content_4 = {
    Text = "Buena chica, Lily. ¿Pasó algo digno de elogio?"
  },
  AvgCommunicate_134106_Content_5 = {
    Text = "¡Lily levantó un montón de Pústulas!"
  },
  AvgCommunicate_134106_Content_6 = {
    Text = "¡Las levantó súper alto!"
  },
  AvgCommunicate_134106_Content_9 = {
    Text = "Debe de ser la influencia de la Regla final..."
  },
  AvgCommunicate_134107_Content_1 = {
    Text = "Desde que comprendí la Regla final, el camino por delante se me ha vuelto mucho más claro."
  },
  AvgCommunicate_134107_Content_10 = {
    Text = "Como navegante, este es mi deber."
  },
  AvgCommunicate_134107_Content_11 = {
    Text = "Cualquiera en esa posición probablemente habría hecho lo mismo."
  },
  AvgCommunicate_134107_Content_12 = {
    Text = "El trabajo de navegación se rige por el deber y la responsabilidad, no por el afán de recibir elogios."
  },
  AvgCommunicate_134107_Content_13 = {
    Text = "Por favor, devuelvan esos regalos a los marineros."
  },
  AvgCommunicate_134107_Content_14 = {
    Text = "También es una muestra de su agradecimiento. Solo acéptalos."
  },
  AvgCommunicate_134107_Content_15 = {
    Text = "Además, si ven una luz amarilla inexplicable en el mar, por favor hagan todo lo posible por dirigir el barco hacia el Camino opuesto."
  },
  AvgCommunicate_134107_Content_16 = {
    Text = "No pregunten por qué. La academia se encargará del Primordial correspondiente lo antes posible..."
  },
  AvgCommunicate_134107_Content_2 = {
    Text = "Por el bien de las incontables almas perdidas a lo largo del camino, y también por mí mismo, ofrezco mi más sincero agradecimiento una vez más por la Revelación que me has concedido."
  },
  AvgCommunicate_134107_Content_3 = {
    Text = "No hace falta ser tan formal. Es lo que merecías, Corposant."
  },
  AvgCommunicate_134107_Content_4 = {
    Text = "¿Lo que merecía?"
  },
  AvgCommunicate_134107_Content_5 = {
    Text = "Sí, la escuela ha recibido varias cartas de agradecimiento que fueron reenviadas a través de diversos canales."
  },
  AvgCommunicate_134107_Content_6 = {
    Text = "Todos se perdieron durante sus travesías, solo para divisar un rayo de Mar de Ardora azul violáceo sobre el mástil."
  },
  AvgCommunicate_134107_Content_7 = {
    Text = "Solo tenían que seguir la guía del Mar de Ardora para llegar al puerto más cercano."
  },
  AvgCommunicate_134107_Content_8 = {
    Text = "Llamaron a esta luz la \"Luz del Santo\"."
  },
  AvgCommunicate_134107_Content_9 = {
    Text = "Además de eso, hay muchos regalos expresando gratitud, todos amontonados en la entrada de la sala de correo."
  },
  AvgCommunicate_134107_Option_5 = {
    Text = "Misaq recibió cartas de agradecimiento..."
  },
  AvgCommunicate_134108_Content_1 = {
    Text = "Tenías algo tan bueno y no se te ocurrió sacarlo antes."
  },
  AvgCommunicate_134108_Content_10 = {
    Text = "¿Acaso tienes cerebro, @2? ¡Te tomaste en serio una broma!"
  },
  AvgCommunicate_134108_Content_11 = {
    Text = "Si todos se convirtieran en mi descendencia, ¿qué haría este gran rey con todos esos electrodomésticos rotos y esos conocimientos generales raros? O sea, claro, los recuerdos se pueden conservar y todo eso."
  },
  AvgCommunicate_134108_Content_12 = {
    Text = "¿Esperas que hable solo delante de Cáscaras vacías todos los días? Ni hablar."
  },
  AvgCommunicate_134108_Content_14 = {
    Text = "Tch, me has vuelto a calar. Qué aburrido."
  },
  AvgCommunicate_134108_Content_15 = {
    Text = "Confío en que no harás eso, Agrippa. Aunque te desvíes del camino de vez en cuando, estoy seguro de que puedo reconducirte."
  },
  AvgCommunicate_134108_Content_16 = {
    Text = "Porque eres la sabia Señor del laberinto."
  },
  AvgCommunicate_134108_Content_17 = {
    Text = "Porque eres alguien importante para mí."
  },
  AvgCommunicate_134108_Content_18 = {
    Text = "¡Puaj! ¿Qué clase de cosa rara estás diciendo de repente? ¡Qué asco, qué asco, se me van a pudrir los oídos!"
  },
  AvgCommunicate_134108_Content_19 = {
    Text = "Está bien, a regañadientes dejaré de convertir a nadie en descendencia por ahora, ¡así que llévate esta tarea de aquí!"
  },
  AvgCommunicate_134108_Content_2 = {
    Text = "Jaja, ¡esta gran reina ahora es completamente libre! La noble Loba Gris Comenzará su reinado de nuevo en Misaq."
  },
  AvgCommunicate_134108_Content_3 = {
    Text = "Todo Misaq... no, todo Kadas se llenará de mi descendencia."
  },
  AvgCommunicate_134108_Content_4 = {
    Text = "¿De verdad?"
  },
  AvgCommunicate_134108_Content_5 = {
    Text = "Originalmente, para celebrar que comprendieras la Regla final, estaba preparado para hacer una excepción y ayudarte a ordenar tu dormitorio. La oficina de asuntos académicos incluso accedió a eximirte de Hace una semana de tareas."
  },
  AvgCommunicate_134108_Content_6 = {
    Text = "Pero como la noble Loba Gris planea convertir a Todos en su descendencia, supongo que nada de eso es necesario ya, ¿verdad?"
  },
  AvgCommunicate_134108_Content_7 = {
    Text = "¡Espera, espera!"
  },
  AvgCommunicate_134108_Content_9 = {
    Text = "¡No, no puedes, absolutamente no!"
  },
  AvgCommunicate_134108_Option_16 = {
    Text = "Porque eres la sabia Señor del laberinto."
  },
  AvgCommunicate_134108_Option_17 = {
    Text = "Porque eres alguien importante para mí."
  },
  AvgCommunicate_134108_Option_4 = {Text = "En serio."},
  AvgCommunicate_134109_Content_1 = {
    Text = "Miau Guardián, vi un túnel completamente oscuro..."
  },
  AvgCommunicate_134109_Content_10 = {
    Text = "Pero no percibí ninguna malicia en esos pequeños ojos. Al contrario, me sentí completamente en paz, y ahora parece que puedo Fusionarme en uno con ellos."
  },
  AvgCommunicate_134109_Content_11 = {
    Text = "¿Estás diciendo que te fusionaste con las almas de las ratas?"
  },
  AvgCommunicate_134109_Content_12 = {
    Text = "Sí, sentí que me dispersaba en muchísimos, muchísimos pedazos en un instante, correteando por tuberías sinuosas, trastos amontonados, bajo muebles bajos..."
  },
  AvgCommunicate_134109_Content_13 = {
    Text = "¿Estás pensando en tu vida anterior? Está bien, todo eso ya quedó en el pasado."
  },
  AvgCommunicate_134109_Content_14 = {
    Text = "Y entonces... ¡podría robar todo tipo de cosas fácilmente controlándolas!"
  },
  AvgCommunicate_134109_Content_15 = {
    Text = "Si hubiera tenido este tipo de habilidad en aquel entonces, ¡podría haber vaciado el banco más grande de la Zona Oeste! Jajaja, ahora soy prácticamente el rey de todos los ladrones del país... ¡no, del mundo entero! ¡Ya nadie puede detenerme!"
  },
  AvgCommunicate_134109_Content_17 = {
    Text = "Siento que ni siquiera llamar a la policía servirá esta vez. Mejor le pido a la Srta. Doll que haga la Fabricación de un dispositivo de vigilancia."
  },
  AvgCommunicate_134109_Content_2 = {
    Text = "Sin luz, sin noción del tiempo. Caminé y caminé allí completamente sola, como si hubiera estado caminando toda una vida."
  },
  AvgCommunicate_134109_Content_3 = {
    Text = "¿Estás bien? ¿Te quedaste Perdido en el espacio otra vez?"
  },
  AvgCommunicate_134109_Content_4 = {
    Text = "Caminé durante mucho, mucho tiempo, y finalmente vi algo —como un destello de luz, una voluta de humo— y luego se convirtió lentamente en marrón. Sus pequeños ojos redondos brillaban en aquel espacio completamente oscuro."
  },
  AvgCommunicate_134109_Content_5 = {
    Text = "Y luego hubo incontables pares de los mismos ojos, rodeándome, haciéndome compañía..."
  },
  AvgCommunicate_134109_Content_6 = {
    Text = "¿Una plaga de ratas?"
  },
  AvgCommunicate_134109_Content_7 = {
    Text = "Sí. Sentí que eran más que simples ratas. Parecían tener alma, igual que los niños que solía conocer en las calles. Competíamos, cooperábamos y compartíamos las mismas penurias, correteando por las calles igual que ratas."
  },
  AvgCommunicate_134109_Content_8 = {
    Text = "Quizás son las almas de muchos niños haciéndote compañía."
  },
  AvgCommunicate_134109_Content_9 = {
    Text = "¿Eh? Pero todavía le debo a Joe una pata de pollo, le debo a la pequeña Jones dos hogazas de pan, y le robé unas cuantas canicas a Johnny... ¡No habrán venido a cobrarme las deudas!"
  },
  AvgCommunicate_134109_Option_11 = {
    Text = "¿Tus sentidos se fusionaron con los suyos?"
  },
  AvgCommunicate_134109_Option_13 = {
    Text = "Todo eso ya quedó en el pasado"
  },
  AvgCommunicate_134109_Option_17 = {Text = "..."},
  AvgCommunicate_134109_Option_3 = {
    Text = "¿Estás bien?"
  },
  AvgCommunicate_134109_Option_6 = {
    Text = "¿Una plaga de ratas?"
  },
  AvgCommunicate_134109_Option_8 = {
    Text = "Quizás eran ellos."
  },
  AvgCommunicate_134110_Content_1 = {
    Text = "Ah, ah... ¡¡¡AAAAAH!!! ¡Negro, todo es negro!"
  },
  AvgCommunicate_134110_Content_10 = {
    Text = "¿No... lo ha hecho? ¿El demonio negro no ha venido?"
  },
  AvgCommunicate_134110_Content_11 = {
    Text = "Pero si estamos viviendo dentro del vientre del demonio, entonces llegará el día en que seremos Devorados por la oscuridad. ¡No podemos escapar, no podemos escapar!"
  },
  AvgCommunicate_134110_Content_12 = {
    Text = "Esto es demasiado aterrador, demasiado aterrador..."
  },
  AvgCommunicate_134110_Content_14 = {
    Text = "No tengas miedo."
  },
  AvgCommunicate_134110_Content_15 = {
    Text = "No puedo entender lo que dices, pero si el mundo realmente tiene un día destinado a la Síntoma: Destrucción, al menos yo, y Todos en Misaq, lucharemos y resistiremos hasta el último momento."
  },
  AvgCommunicate_134110_Content_16 = {
    Text = "Si la Fusión es realmente un Fin inevitable, te mantendré en el último lugar donde quede luz, y permaneceré a tu lado, hasta el Fin del mundo."
  },
  AvgCommunicate_134110_Content_17 = {Text = "...Ya veo."},
  AvgCommunicate_134110_Content_18 = {
    Text = "Nunca te extinguirás. Creo en ti."
  },
  AvgCommunicate_134110_Content_19 = {
    Text = "Gracias, Guardián."
  },
  AvgCommunicate_134110_Content_2 = {
    Text = "¡El mundo entero es negro! ¡Solo Oblivion, Solo Oblivion!"
  },
  AvgCommunicate_134110_Content_3 = {
    Text = "¡Winkle! ¡Despierta! ¡¿Otra vez con pesadillas?!"
  },
  AvgCommunicate_134110_Content_4 = {
    Text = "No, no, más técnicas de @2 personas, conocimiento, almas más fuertes, nada funciona, ¡nada! ¡Sigo sin poder migrar de nuevo!"
  },
  AvgCommunicate_134110_Content_5 = {
    Text = "Después de volverme más fuerte, es aún más fácil para la oscuridad verme. Soy demasiado llamativo. La oscuridad me alcanzará..."
  },
  AvgCommunicate_134110_Content_6 = {
    Text = "Ya no quiero volverme más fuerte. Quiero correr, huir lo más lejos que pueda. Pero si el mundo entero es negro, y toda la luz es falsa, entonces a dónde puedo ir..."
  },
  AvgCommunicate_134110_Content_7 = {
    Text = "¿Por qué, por qué esta Fortaleza me hace ver estas cosas? ¡No quiero saberlo!"
  },
  AvgCommunicate_134110_Content_8 = {
    Text = "Voy a morir, voy a morir, voy a morir otra vez. ¿Tengo que Experimentarlo de nuevo? No quiero, no quiero..."
  },
  AvgCommunicate_134110_Content_9 = {
    Text = "¡Despierta, Winkle! El mundo no se ha vuelto negro. ¡Yo sigo aquí! ¡Todos siguen aquí!"
  },
  AvgCommunicate_134110_Option_14 = {
    Text = "No tengas miedo."
  },
  AvgCommunicate_134110_Option_3 = {
    Text = "¿¡Winkle?!"
  },
  AvgCommunicate_134110_Option_9 = {Text = "¡Bígaro!"},
  AvgCommunicate_134111_Content_1 = {
    Text = "Mis alas... se han vuelto aún más grandes."
  },
  AvgCommunicate_134111_Content_10 = {
    Text = "Castor, sé que eres increíble, y tus alas también lo son. ¿Cómo lo explico...?"
  },
  AvgCommunicate_134111_Content_12 = {
    Text = "No importa, lo entiendo. Dicho esto, tu capacidad de carga también debe haber mejorado, ¿verdad?"
  },
  AvgCommunicate_134111_Content_13 = {
    Text = "Hmm, según un cálculo aproximado, el peso de una docena de personas no debería ser problema."
  },
  AvgCommunicate_134111_Content_14 = {
    Text = "Sin embargo, mis brazos no parecen capaces de cargar a tantas personas a la vez."
  },
  AvgCommunicate_134111_Content_15 = {
    Text = "Tengo una sugerencia."
  },
  AvgCommunicate_134111_Content_16 = {
    Text = "¿Qué te parece esto? Vas a entrenar la fuerza de tus brazos, ¡y así tendremos un vehículo aéreo que pueda descender del cielo en cualquier momento que lo necesitemos!"
  },
  AvgCommunicate_134111_Content_17 = {
    Text = "¿Fuerza de brazos? ¿Qué tiene eso que ver con un... vehículo aéreo? Benefactora, perdona mi ignorancia, pero no lo entiendo del todo."
  },
  AvgCommunicate_134111_Content_18 = {
    Text = "Es una misión importante."
  },
  AvgCommunicate_134111_Content_19 = {
    Text = "Solo tu capacidad de carga se mantenga, la movilidad y la velocidad de evacuación en las misiones de campo mejorarán enormemente. Castor, ¿estás dispuesto a aceptar esta misión?"
  },
  AvgCommunicate_134111_Content_2 = {
    Text = "Los Creyentes ciertamente han cantado alabanzas sobre alas que oscurecen el cielo, pero sé que lo que una vez poseí no era más que un par de alas ordinarias."
  },
  AvgCommunicate_134111_Content_20 = {
    Text = "¡Por supuesto! Sería un honor, Benefactora."
  },
  AvgCommunicate_134111_Content_21 = {
    Text = "¡Entonces es un trato! ¡Iré a buscar a Erica de inmediato para que haga una cesta de transporte personalizada!"
  },
  AvgCommunicate_134111_Content_22 = {
    Text = "Nunca más debes pensar en darle tus alas a otra persona, sin importar quién sea."
  },
  AvgCommunicate_134111_Content_3 = {
    Text = "Los que tenéis alas no tenéis ni idea de lo práctico que es tenerlas... Qué envidia..."
  },
  AvgCommunicate_134111_Content_4 = {
    Text = "Si mi salvador lo desea, recuerdo vagamente que la Iglesia de los Portadores de Luz tenía métodos para trasplantar alas. Puedo darte las mías voluntariamente. No le temo al dolor."
  },
  AvgCommunicate_134111_Content_6 = {
    Text = "No no no no, eso no será necesario. Es mejor que se queden contigo."
  },
  AvgCommunicate_134111_Content_7 = {
    Text = "Ah, ¿no quieres mis alas, salvador? Se han vuelto bastante impresionantes ahora."
  },
  AvgCommunicate_134111_Content_8 = {
    Text = "Tras comprender las leyes, cada sensación del viento fluyendo entre los huecos de mis plumas, cada fuerza de las corrientes de aire arremolinándose... todo está bajo mi control."
  },
  AvgCommunicate_134111_Content_9 = {
    Text = "No se trata de si son impresionantes o no."
  },
  AvgCommunicate_134111_Option_15 = {
    Text = "Tengo una sugerencia."
  },
  AvgCommunicate_134111_Option_18 = {
    Text = "Es una misión importante."
  },
  AvgCommunicate_134111_Option_3 = {
    Text = "Es que no lo entiendes."
  },
  AvgCommunicate_134111_Option_9 = {
    Text = "No se trata de si son impresionantes o no."
  },
  AvgCommunicate_134112_Content_1 = {
    Text = "Vaya, así que así es como se ve el mundo desde tu perspectiva."
  },
  AvgCommunicate_134112_Content_10 = {
    Text = "¿Los humanos realmente tienen tantos tipos de expresiones? Parece que yo calificaría como cara de piedra."
  },
  AvgCommunicate_134112_Content_11 = {
    Text = "No solo eso, también aprendí a reír mientras lloro, estar enfadada mientras lloro, estar enfadada mientras río, sentir miedo mientras río..."
  },
  AvgCommunicate_134112_Content_12 = {
    Text = "Solo con que combines cada expresión, se convierte en una emoción nueva. ¡A este ritmo, no pasará mucho antes de que Casiah haya dominado por completo las emociones humanas!"
  },
  AvgCommunicate_134112_Content_13 = {
    Text = "¿Quieres ver? ¿Quieres ver? Incluso \"el amor\", ese misterio sin resolver de la humanidad... ¡Casiah puede interpretarlo para ti ahora mismo!"
  },
  AvgCommunicate_134112_Content_15 = {
    Text = "¡No solo no has dominado nada, sino que tu aspecto ahora es incluso menos humano que antes! ¡¡¡Qué miedo, para ya mismo!!!"
  },
  AvgCommunicate_134112_Content_2 = {Text = "¿Qué?"},
  AvgCommunicate_134112_Content_3 = {
    Text = "No creo que el mundo a través de mis ojos tenga nada de especial, pero ¿qué viste tú?"
  },
  AvgCommunicate_134112_Content_4 = {
    Text = "Casiah vio... innumerables seres diminutos superpuestos unos sobre otros, con incontables momentos todos dentro de su \"vista\" a la vez."
  },
  AvgCommunicate_134112_Content_5 = {
    Text = "En un solo instante breve, innumerables personas estaban llorando, mientras que otras innumerables estaban riendo, ardiendo de ira, temblando de miedo..."
  },
  AvgCommunicate_134112_Content_6 = {
    Text = "Algunas personas también tenían expresiones de mucha tranquilidad. Esa emoción, según mi registro, ¿debería llamarse felicidad? Así que las emociones humanas tienen tantas, tantas diferencias sutiles..."
  },
  AvgCommunicate_134112_Content_7 = {
    Text = "¿¡Ya puedes sentir las emociones humanas!?"
  },
  AvgCommunicate_134112_Content_8 = {
    Text = "No, Casiah solo puede ver sus expresiones, sus movimientos y los colores de sus emociones."
  },
  AvgCommunicate_134112_Content_9 = {
    Text = "¡Pero Casiah es la mejor imitando! Después de ver todas las diferentes caras sonrientes y llorosas de todo el mundo a la vez, ¡Casiah ahora puede hacer 21 tipos de sonrisas y 36 tipos de expresiones de llanto para ti!"
  },
  AvgCommunicate_134112_Option_10 = {Text = "¿Tantas?"},
  AvgCommunicate_134112_Option_15 = {
    Text = "¡No has dominado absolutamente nada!"
  },
  AvgCommunicate_134112_Option_2 = {Text = "¿Qué?"},
  AvgCommunicate_134112_Option_7 = {
    Text = "¿¡Ya puedes sentir las emociones humanas!?"
  },
  AvgCommunicate_134113_Content_1 = {
    Text = "El trato contigo fue la decisión más acertada de mi carrera como Mercader."
  },
  AvgCommunicate_134113_Content_10 = {
    Text = "¡Espera, los Después son cada vez más raros!"
  },
  AvgCommunicate_134113_Content_11 = {
    Text = "Además, algo que suena tan valioso debe ser caro, ¿no? ¿Cuál es el precio del intercambio?"
  },
  AvgCommunicate_134113_Content_12 = {
    Text = "Hmm... Después de todo, es gracias a ti que obtuve un poder más conveniente para desplazarme."
  },
  AvgCommunicate_134113_Content_13 = {
    Text = "Te haré un descuento especial. En cuanto al precio, por favor ven a mi tienda para discutir los detalles. Estaré esperando tu llegada."
  },
  AvgCommunicate_134113_Content_2 = {
    Text = "Plantar una semilla y esperar a que crezca hasta convertirse en una flor, o en un árbol imponente."
  },
  AvgCommunicate_134113_Content_3 = {
    Text = "Rara vez hago negocios que requieran una espera tan larga para obtener beneficios. Afortunadamente, tal como están las cosas ahora, ya es Sin riesgo de pérdida."
  },
  AvgCommunicate_134113_Content_4 = {
    Text = "Je, je, gracias por toda la ayuda durante todo este tiempo. Me alegra no haberte decepcionado."
  },
  AvgCommunicate_134113_Content_5 = {
    Text = "Las aguas del Mar de las Mil Caras se han vuelto aún más profundas. Ha pasado mucho tiempo, y las cabezas de allí te echan mucho de menos. ¿Te gustaría hacer un Regreso a un lugar familiar?"
  },
  AvgCommunicate_134113_Content_6 = {
    Text = "Em, yo... Preferiría no hacerlo. Creo que a veces la distancia hace que el corazón se encariñe más."
  },
  AvgCommunicate_134113_Content_7 = {
    Text = "Jeje, desde luego tienes el Talento de un Mercader en lo que a elocuencia se refiere."
  },
  AvgCommunicate_134113_Content_8 = {
    Text = "Hablando de eso, mi pequeña tienda recibió hace poco algunos artículos nuevos. Bastante raros, y los he estado guardando todos para ti."
  },
  AvgCommunicate_134113_Content_9 = {
    Text = "Hay un orbe que permite alcanzar la Resonancia con la Fortaleza de Origen, un espejo que permite atisbar visiones de otro mundo mediante Espiar, y un collar que hace que la gente obedezca dócilmente."
  },
  AvgCommunicate_134113_Option_10 = {
    Text = "¡Eso es cada vez más raro!"
  },
  AvgCommunicate_134113_Option_4 = {Text = "Hehe."},
  AvgCommunicate_134113_Option_6 = {
    Text = "Preferiría no hacerlo."
  },
  AvgCommunicate_134114_Content_1 = {
    Text = "Yo... me he convertido en fuego."
  },
  AvgCommunicate_134114_Content_10 = {
    Text = "Todavía hay tanta belleza en el mundo que merece ser plasmada. Creo que ya he encontrado más Inspiración para la creación."
  },
  AvgCommunicate_134114_Content_11 = {
    Text = "De ahora en adelante, me convertiré en fuego, trayendo un ritmo más puro y natural."
  },
  AvgCommunicate_134114_Content_2 = {
    Text = "Fuego cian, danzante. Quemar, Purificar, Danza."
  },
  AvgCommunicate_134114_Content_3 = {
    Text = "Mis pecados y los pecados de los demás arderán en el fuego, y todo quedará limpio."
  },
  AvgCommunicate_134114_Content_4 = {
    Text = "Liz... ¿sigues recordando aquel fuego de entonces?"
  },
  AvgCommunicate_134114_Content_5 = {
    Text = "Mi odio ha ido siendo Quemado lentamente por el fuego, pero no tengo derecho a perdonar ese fuego en nombre de otros."
  },
  AvgCommunicate_134114_Content_6 = {
    Text = "Nunca me he arrepentido, ni huiré de los rostros en esas llamas."
  },
  AvgCommunicate_134114_Content_7 = {
    Text = "Después de llegar aquí, me diste una nueva vida. Ya no necesito ningún gran escenario, pero si tú eres el Público, creo que aún sentiría felicidad al realizar mi Danza."
  },
  AvgCommunicate_134114_Content_8 = {
    Text = "¡Déjame ser tu fan número uno y seguir viéndote bailar!"
  },
  AvgCommunicate_134114_Content_9 = {
    Text = "Mm, gracias. Después de dejar de bailar, a menudo me sentaba junto a la ventana sin hacer nada. Veía el Viento, las flores, los árboles, los pájaros y los Gatos... tantos seres vivos y toda la naturaleza rebosante del ritmo de la Danza."
  },
  AvgCommunicate_134114_Option_4 = {Text = "Liz..."},
  AvgCommunicate_134114_Option_8 = {
    Text = "¡Seguiré viéndote bailar!"
  },
  AvgCommunicate_134115_Content_1 = {
    Text = "Yo... Puedo verlo..."
  },
  AvgCommunicate_134115_Content_10 = {
    Text = "¡Eso es realmente alentador!"
  },
  AvgCommunicate_134115_Content_11 = {
    Text = "¡Me alegro por ti de que puedas ver todo esto, Miryam!"
  },
  AvgCommunicate_134115_Content_12 = {
    Text = "Por supuesto, seguiré dedicando todo al Descenso del Reino Divino."
  },
  AvgCommunicate_134115_Content_13 = {
    Text = "Pero ahora comprendo... El Reino Divino no es simplemente dos estados de Llegada completa o aniquilación total."
  },
  AvgCommunicate_134115_Content_14 = {
    Text = "Mientras rezamos por el Descenso del Reino Divino, una parte del Reino Divino ya ha llegado a nuestro lado."
  },
  AvgCommunicate_134115_Content_15 = {
    Text = "Gracias, Guardián. Me has otorgado nueva Fortaleza."
  },
  AvgCommunicate_134115_Content_16 = {
    Text = "¡Lo que he visto es la Prueba de existencia de la existencia inmortal del Reino Divino!"
  },
  AvgCommunicate_134115_Content_17 = {
    Text = "El proceso se sintió un poco raro... pero al final resultó ser un resultado decente, supongo."
  },
  AvgCommunicate_134115_Content_2 = {Text = "Qué ves?"},
  AvgCommunicate_134115_Content_3 = {
    Text = "El Reino Divino... Sí... El contorno del Reino Divino!"
  },
  AvgCommunicate_134115_Content_4 = {
    Text = "Nunca ha sido tan claro... Nunca ha sido tan... ordinario..."
  },
  AvgCommunicate_134115_Content_5 = {
    Text = "Miryam... Estás segura de que esas son tus propias palabras..."
  },
  AvgCommunicate_134115_Content_6 = {
    Text = "Veo mi tierra natal. Veo ese futuro inmortal, imperecedero."
  },
  AvgCommunicate_134115_Content_7 = {
    Text = "Pero más que eso... Veo el presente."
  },
  AvgCommunicate_134115_Content_8 = {
    Text = "Mi Señor, mis semejantes, mi Amigo cercano, mis fieles..."
  },
  AvgCommunicate_134115_Content_9 = {
    Text = "El Reino Divino siempre ha estado a mi lado... Todo lo que tengo siempre ha sido parte del Reino Divino..."
  },
  AvgCommunicate_134115_Option_10 = {
    Text = "¡Eso es realmente alentador!"
  },
  AvgCommunicate_134115_Option_17 = {
    Text = "Supongo que funciona..."
  },
  AvgCommunicate_134115_Option_2 = {Text = "¿Qué?"},
  AvgCommunicate_134115_Option_5 = {Text = "Ordinario?"},
  AvgCommunicate_134116_Content_1 = {
    Text = "Vaya, nunca esperé que llevar mi Fortaleza al límite máximo se sintiera así."
  },
  AvgCommunicate_134116_Content_10 = {Text = "Er..."},
  AvgCommunicate_134116_Content_11 = {
    Text = "Hmm, déjame ver... Ahora mismo estás pensando: \"Sinceramente, no sé cuál de los dos es más aterrador\". ¿Me equivoco?"
  },
  AvgCommunicate_134116_Content_12 = {
    Text = "¿¡¡Qué!!? ¿No dijiste que no puedes leer mi mente?"
  },
  AvgCommunicate_134116_Content_13 = {
    Text = "Qué reacción tan adorable. No leí tu mente en absoluto."
  },
  AvgCommunicate_134116_Content_14 = {
    Text = "Solo es que estás tan completamente desprevenido conmigo... que eres demasiado fácil de leer."
  },
  AvgCommunicate_134116_Content_15 = {
    Text = "¿Quieres mantener a salvo los pequeños secretos de tu corazón? Entonces esfuérzate un poco más cuando charles conmigo."
  },
  AvgCommunicate_134116_Content_2 = {
    Text = "¿Qué se siente? Tengo un mal presentimiento sobre esto..."
  },
  AvgCommunicate_134116_Content_3 = {
    Text = "¿Cómo decirlo... Básicamente, esas mentes mediocres son como diarios abiertos para mí: aburridos y expuestos de un vistazo. Es bastante tedioso, la verdad."
  },
  AvgCommunicate_134116_Content_4 = {
    Text = "¿¡Qué!? ¿Ya has dominado la Lectura de pensamientos?"
  },
  AvgCommunicate_134116_Content_5 = {
    Text = "No es para tanto. Después de todo, todavía hay bastantes personas en este mundo con espíritus resilientes y personalidades obstinadas que intentan envolver su interior en capa tras capa, negándose a dejarse leer fácilmente."
  },
  AvgCommunicate_134116_Content_6 = {
    Text = "Y luego están seres como tú, que siempre han sido enigmáticos e inescrutables."
  },
  AvgCommunicate_134116_Content_7 = {
    Text = "No hace falta ponerse nervioso. Obtener las respuestas de un examen por adelantado es tan aburrido como conocer el final de una historia de antemano, o Descubrir al culpable de un caso de asesinato demasiado pronto."
  },
  AvgCommunicate_134116_Content_8 = {
    Text = "Disfruto enormemente del proceso de guiar, especular y desprender los Capullos que envuelven el corazón, hilo a hilo."
  },
  AvgCommunicate_134116_Content_9 = {
    Text = "Sin estos juegos de ida y vuelta, ¿en qué me diferenciaría de esos charlatanes que hacen diagnósticos burdos y simplemente cortan un trozo del cerebro de alguien?"
  },
  AvgCommunicate_134116_Option_10 = {Text = "Er..."},
  AvgCommunicate_134116_Option_12 = {Text = "¿!!"},
  AvgCommunicate_134116_Option_2 = {
    Text = "¿Qué se siente?"
  },
  AvgCommunicate_134116_Option_4 = {Text = "¿Qué?!"},
  AvgCommunicate_134117_Content_1 = {
    Text = "Las rimas de los Versículos se han vuelto aún más envolventes."
  },
  AvgCommunicate_134117_Content_10 = {
    Text = "Puedo llevarte al mundo de la poesía, para vagar juntos."
  },
  AvgCommunicate_134117_Content_12 = {
    Text = "¡Eso es casi tan asombroso como la magia de palabras!"
  },
  AvgCommunicate_134117_Content_13 = {
    Text = "Entonces quiero experimentar un Espejismo de jubilación, hacerme rica y comida gourmet ilimitada. ¿Puedes llevarme allí?"
  },
  AvgCommunicate_134117_Content_14 = {
    Text = "Eso... debería ser, sí, ¡es posible! Por favor, dame un momento, necesito pensarlo con cuidado..."
  },
  AvgCommunicate_134117_Content_2 = {
    Text = "Ahora, puedo ver las emociones que surgen dentro de esos ritmos recitados, la Fortaleza reflejada detrás de esas Imágenes."
  },
  AvgCommunicate_134117_Content_3 = {
    Text = "No lo entiendo del todo, pero suena como una vista hermosa."
  },
  AvgCommunicate_134117_Content_4 = {
    Text = "Sí, la poesía es una llave para explorar la belleza. La poesía puede revelar las leyes universales del mundo y reflejar la vida tal como es en verdad."
  },
  AvgCommunicate_134117_Content_5 = {
    Text = "En la poesía, nos encontramos a nosotros mismos, encontramos la sabiduría de la Historia y la filosofía, encontramos un santuario puro para el espíritu."
  },
  AvgCommunicate_134117_Content_6 = {
    Text = "Ah, me dejé llevar hablando sola otra vez. Lo siento mucho..."
  },
  AvgCommunicate_134117_Content_7 = {
    Text = "No pasa nada. Me encanta lo apasionada que te ves cuando hablas de poesía. ¡Es muy encantador!"
  },
  AvgCommunicate_134117_Content_8 = {
    Text = "G-gracias, Guardián. En fin, ahora puedo usar Versículos para tomar prestada aún más Fortaleza de ese mundo, creando un Espejismo poético completo."
  },
  AvgCommunicate_134117_Content_9 = {
    Text = "Ya sea que desees disfrutar de la tranquilidad, la pasión o la melancolía, ya sea que quieras perseguir el aroma de las flores, las corrientes del océano o las nubes."
  },
  AvgCommunicate_134117_Option_12 = {
    Text = "Es casi como magia de palabras."
  },
  AvgCommunicate_134117_Option_3 = {
    Text = "Suena hermoso."
  },
  AvgCommunicate_134117_Option_7 = {
    Text = "No hay problema."
  },
  AvgCommunicate_134118_Content_1 = {
    Text = "De verdad le ofreces algo tan valioso a esta servidora, tú..."
  },
  AvgCommunicate_134118_Content_10 = {
    Text = "Pero, ¿de verdad puedes comer tanto? Un chef se quejó de que arrasaste con todas las reservas de mantequilla y queso, y tuve que pagar de mi bolsillo para reabastecer la cafetería."
  },
  AvgCommunicate_134118_Content_11 = {
    Text = "¿Oh? ¿Quién ha estado chismoseando a mis espaldas? ¡Que no los pille!"
  },
  AvgCommunicate_134118_Content_12 = {
    Text = "En cuanto a los pasteles, ¡no te metas en los asuntos de una dama! ¡Los que haga, me los como todos!"
  },
  AvgCommunicate_134118_Content_13 = {
    Text = "Y si no puedo terminarlos, ¡vendrás a comer conmigo!"
  },
  AvgCommunicate_134118_Content_14 = {
    Text = "¿Y–yo también tengo que comer? ¡Me voy a reventar y engordar en la flor de la vida!"
  },
  AvgCommunicate_134118_Content_15 = {
    Text = "Deja de quejarte. Después de tanta charla, aún no he mencionado tu recompensa. Esta dama será lo bastante generosa como para guardarte una porción de cada pastel que haga de ahora en adelante."
  },
  AvgCommunicate_134118_Content_16 = {
    Text = "¡Agradécelo! ¡Son obras maestras de una pastelera genial que el dinero no puede comprar!"
  },
  AvgCommunicate_134118_Content_17 = {
    Text = "Así que... ¡al final esta pastelería es solo producción propia y consumo propio!"
  },
  AvgCommunicate_134118_Content_2 = {
    Text = "Hmph, nada mal."
  },
  AvgCommunicate_134118_Content_3 = {
    Text = "¡Ahora esta dama puede hacer girar a diez... no, a cien Marchadores de Mares como peonzas a la vez! ¡Ya no necesito que nadie me salve!"
  },
  AvgCommunicate_134118_Content_4 = {
    Text = "¡La gran dama es poderosa!"
  },
  AvgCommunicate_134118_Content_5 = {
    Text = "Aunque mi vida ahora ya no requiere preocupaciones constantes, cuando se trata de Fuerza, cuanta más, mejor para sentirse segura."
  },
  AvgCommunicate_134118_Content_6 = {
    Text = "¡La que tiene los puños más grandes nunca sale perdiendo!"
  },
  AvgCommunicate_134118_Content_7 = {
    Text = "Pero usar una Fortaleza tan increíble solo para trabajar en Misaq es un desperdicio... ¡Ya lo tengo!"
  },
  AvgCommunicate_134118_Content_8 = {
    Text = "Ya que tantos tentáculos pueden trabajar de forma independiente, bien podría abrir mi propia pastelería. Conmigo sola cubriendo ocho puestos, ¡eso significaría pasteles ilimitados para siempre!"
  },
  AvgCommunicate_134118_Content_9 = {
    Text = "¿Se pueden usar así?"
  },
  AvgCommunicate_134118_Option_14 = {
    Text = "¿Hay que comer yo también?"
  },
  AvgCommunicate_134118_Option_17 = {
    Text = "Así que..."
  },
  AvgCommunicate_134118_Option_4 = {
    Text = "¡Murphy es poderosa!"
  },
  AvgCommunicate_134118_Option_9 = {
    Text = "¿Se pueden usar así?"
  },
  AvgCommunicate_134119_Content_1 = {
    Text = "Jajajaja... ¡Ajajajaja!"
  },
  AvgCommunicate_134119_Content_10 = {
    Text = "Ante un poder absoluto, la conquista es Solo un juego largo."
  },
  AvgCommunicate_134119_Content_11 = {
    Text = "Lo que te haga feliz..."
  },
  AvgCommunicate_134119_Content_12 = {
    Text = "El tiempo te traerá noticias de mi triunfo. Cuando ese día llegue, como principal contribuyente de mi nuevo reino, reservaré la tierra más fértil como tu feudo."
  },
  AvgCommunicate_134119_Content_13 = {
    Text = "O... preferirías esta polvorienta ciudad de Londinium?"
  },
  AvgCommunicate_134119_Content_2 = {
    Text = "No te habrás vuelto loca por tanta Fuerza y habrás perdido la cabeza de repente, ¿verdad?"
  },
  AvgCommunicate_134119_Content_3 = {
    Text = "Hmph hmph, como mi mayor \"Dedicatoria\" de Fuerza, puedo perdonar tu pequeña insolencia."
  },
  AvgCommunicate_134119_Content_4 = {
    Text = "Ah... el momento que tanto he esperado, ese sabor dulce y familiar, ¡esa sensación de que la sangre hierve en las venas!"
  },
  AvgCommunicate_134119_Content_5 = {
    Text = "Ahora puedo levantar icebergs sin esfuerzo y abrir las profundidades del océano."
  },
  AvgCommunicate_134119_Content_6 = {
    Text = "Ningún Líder de tribu alguna, ningún guerrero más poderoso de Los Marchadores de Mares resistiría un solo combate contra mí, y esa mujer loca ya no puede someterme tampoco."
  },
  AvgCommunicate_134119_Content_7 = {
    Text = "Pronto, conquistaré los mares, y luego conquistaré todas las tierras! Jajajaja!"
  },
  AvgCommunicate_134119_Content_8 = {
    Text = "...La confianza es algo bueno, pero no seas tan narcisista! Eso ya está al nivel de Síntoma: Delirio!"
  },
  AvgCommunicate_134119_Content_9 = {
    Text = "No sabes nada de la Fortaleza de un gigante, pequeño."
  },
  AvgCommunicate_134119_Option_11 = {
    Text = "Lo que te haga feliz..."
  },
  AvgCommunicate_134119_Option_2 = {
    Text = "¿Has perdido la cabeza?"
  },
  AvgCommunicate_134119_Option_8 = {Text = "..."},
  AvgCommunicate_134120_Content_1 = {
    Text = "Mi voz al cantar... es diferente a como era antes."
  },
  AvgCommunicate_134120_Content_10 = {
    Text = "Mm, ¡lo haré!"
  },
  AvgCommunicate_134120_Content_11 = {
    Text = "Hablando de eso, Guardián, gracias a tu aliento de antes, acepté la colaboración con la compañía musical. Ahora el primer álbum se ha publicado oficialmente, y me dicen que se está vendiendo bastante bien."
  },
  AvgCommunicate_134120_Content_12 = {
    Text = "¡Qué buena noticia! ¡Felicidades! ¿Cuántas copias se vendieron?"
  },
  AvgCommunicate_134120_Content_13 = {
    Text = "Creo que... unas cien mil copias. Pero realmente no necesito la moneda de este planeta. Ya que no hay otra forma de pagarte, ¿por qué no te doy las ganancias del álbum?"
  },
  AvgCommunicate_134120_Content_14 = {
    Text = "¡¡¡Yay!!!"
  },
  AvgCommunicate_134120_Content_2 = {
    Text = "Guardián, después de que me ayudaras a comprender la Regla final, mi voz al cantar parece haber alcanzado una Resonancia maravillosa con el Éter."
  },
  AvgCommunicate_134120_Content_3 = {
    Text = "Parece que te has vuelto más fuerte. ¡Seguro que Faint también se alegrará!"
  },
  AvgCommunicate_134120_Content_4 = {
    Text = "¿Cómo podré pagarte, Guardián? Poder tener un Reencuentro con mi hermana ya era una felicidad que mi yo del pasado jamás habría soñado, y aun así me has dado un tesoro tan preciado además de eso."
  },
  AvgCommunicate_134120_Content_5 = {
    Text = "No tengo nada a mi nombre ahora mismo, y ya no soy una estrella adorada por los fans. La única forma en que puedo pagarte es... por favor, déjame cantarte una canción."
  },
  AvgCommunicate_134120_Content_6 = {
    Text = "Tinct, ya has encontrado tu propio Camino. Si estás dispuesta a cumplir mi deseo..."
  },
  AvgCommunicate_134120_Content_7 = {
    Text = "Por favor, canta libremente, para ti misma y para mí."
  },
  AvgCommunicate_134120_Content_8 = {
    Text = "Sin complacer a nadie, sin actuar para cumplir las exigencias de nadie, Solo para tu propia felicidad."
  },
  AvgCommunicate_134120_Content_9 = {
    Text = "Mi propia... felicidad."
  },
  AvgCommunicate_134120_Option_12 = {
    Text = "Qué buena noticia."
  },
  AvgCommunicate_134120_Option_14 = {Text = "¿!!"},
  AvgCommunicate_134120_Option_3 = {
    Text = "¡Eso es maravilloso!"
  },
  AvgCommunicate_134120_Option_6 = {
    Text = "¿Alguna vez has pensado en"
  },
  AvgCommunicate_134180_Content_1 = {
    Text = "El Viento llena las velas, y las aves vuelan en formación a nuestro lado..."
  },
  AvgCommunicate_134180_Content_10 = {
    Text = "Quiero navegar por los mares para siempre jamás, junto a ti, con el Capitán, con todos."
  },
  AvgCommunicate_134180_Content_11 = {
    Text = "Vivir juntos los días soleados y los lluviosos, navegar a todo tipo de puertos, atracar en diferentes países."
  },
  AvgCommunicate_134180_Content_12 = {
    Text = "Pescar juntos, asar pescado juntos... Ah, y podríamos raspar mejillones del casco y estofar los en vino tinto."
  },
  AvgCommunicate_134180_Content_13 = {
    Text = "Vayamos a las próximas vacaciones."
  },
  AvgCommunicate_134180_Content_14 = {
    Text = "Lo he pensado durante mucho tiempo. Navegar... es cuando soy más feliz."
  },
  AvgCommunicate_134180_Content_15 = {
    Text = "Guiaré a todos lejos de cada tormenta, para que podamos seguir navegando felices juntos."
  },
  AvgCommunicate_134180_Content_16 = {
    Text = "Suena maravilloso, pero si navegáramos sin parar para siempre, ¡todos excepto los Despertados del Reino Aequor se marearían!"
  },
  AvgCommunicate_134180_Content_2 = {
    Text = "Veo la proa surcando las olas, oigo a los Marineros cantando sus salomas, siento los susurros del Viento y la lluvia."
  },
  AvgCommunicate_134180_Content_3 = {
    Text = "Ahora puedo verlo con más claridad—el rumbo que conduce a aguas claras y de Tranquilidad."
  },
  AvgCommunicate_134180_Content_4 = {
    Text = "¡Felicidades! ¡Celeste!"
  },
  AvgCommunicate_134180_Content_5 = {
    Text = "Ahora, quizás pueda cumplir de verdad los deseos de todos y guiar los barcos bajo mi protección a salvo hasta la otra orilla."
  },
  AvgCommunicate_134180_Content_6 = {
    Text = "No volveré a decepcionar a todos."
  },
  AvgCommunicate_134180_Content_7 = {
    Text = "Entonces, ¿y tu deseo? ¿Ya has decidido cuál es tu deseo?"
  },
  AvgCommunicate_134180_Content_8 = {
    Text = "Mi deseo..."
  },
  AvgCommunicate_134180_Content_9 = {
    Text = "Ya lo he decidido."
  },
  AvgCommunicate_134180_Option_13 = {
    Text = "Vayamos a las próximas vacaciones."
  },
  AvgCommunicate_134180_Option_16 = {
    Text = "Eso suena maravilloso."
  },
  AvgCommunicate_134180_Option_4 = {
    Text = "Felicidades"
  },
  AvgCommunicate_134180_Option_7 = {
    Text = "¿Y tú qué?"
  },
  AvgCommunicate_134181_Content_1 = {
    Text = "Ah... La Llamada del océano, tan suave, tan cálida."
  },
  AvgCommunicate_134181_Content_10 = {
    Text = "¿Acaso el comportamiento bruto de Rogers te dejó una sombra tan grande, o es que piensas que soy una artista tan estéril y perezosa?"
  },
  AvgCommunicate_134181_Content_11 = {
    Text = "Perfeccionar el oficio no admite atajos. Mis esculturas las tallo naturalmente con mis propias manos, cincelada a cincelada."
  },
  AvgCommunicate_134181_Content_12 = {
    Text = "Quédate tranquilo/a, no usaré ni un solo mechón de tu Cabello."
  },
  AvgCommunicate_134181_Content_13 = {
    Text = "Jaja... Quizás sea porque tus habilidades de escultura son demasiado buenas. Cada vez que veo tus obras, tengo la ilusión de estar mirando a una persona viva."
  },
  AvgCommunicate_134181_Content_14 = {
    Text = "Hmm... Bueno, ahora que mi Fortaleza ha alcanzado su punto máximo, quizás realmente podría crear una escultura que cobre vida."
  },
  AvgCommunicate_134181_Content_15 = {
    Text = "En la oscuridad de la noche, fuera de tu campo de visión, los ojos de la escultura girarían lentamente, y las comisuras de su boca se curvarían muy, muy ligeramente..."
  },
  AvgCommunicate_134181_Content_16 = {
    Text = "Cuando termine mi última obra, colocaré una justo al lado de tu cama para que te vigile en mi nombre. ¿Qué te parece?"
  },
  AvgCommunicate_134181_Content_17 = {
    Text = "¡¡¡No me atrevería a dormir nunca más en lo que me queda de vida!!!"
  },
  AvgCommunicate_134181_Content_18 = {
    Text = "Solo estaba bromeando contigo."
  },
  AvgCommunicate_134181_Content_19 = {
    Text = "Parece que realmente te aterran las historias de fantasmas tan simples. Qué adorable."
  },
  AvgCommunicate_134181_Content_2 = {
    Text = "Seguramente tú también la escuchaste, ¿verdad?"
  },
  AvgCommunicate_134181_Content_3 = {
    Text = "Nos está invitando, nos están esperando... para viajar juntos al palacio blanco puro bajo el mar."
  },
  AvgCommunicate_134181_Content_4 = {
    Text = "¿Quién? Me temo que mis oídos se han quedado sordos—no escuché nada."
  },
  AvgCommunicate_134181_Content_5 = {
    Text = "Entonces este debe ser un Beso de la musa destinado solo para mí. La belleza del océano se ha fusionado ahora con mi propia alma."
  },
  AvgCommunicate_134181_Content_6 = {
    Text = "Siempre me traes más Inspiración para mis creaciones. De verdad que te aprecio más cada día."
  },
  AvgCommunicate_134181_Content_7 = {
    Text = "¿Considerarías convertirte en mi asistente a largo plazo? No tendrías que hacer nada—solo venir a mi estudio cada día, sentarte un rato, tomar una taza de té y charlar."
  },
  AvgCommunicate_134181_Content_8 = {
    Text = "Aunque me halaga tu afecto... ¿me despertaré una mañana y descubriré que me han convertido en una escultura de piedra?"
  },
  AvgCommunicate_134181_Content_9 = {
    Text = "Jeje, ¿de verdad me ves así?"
  },
  AvgCommunicate_134181_Option_13 = {
    Text = "Tu destreza es increíble."
  },
  AvgCommunicate_134181_Option_17 = {
    Text = "¡¡¡No, por favor!!!"
  },
  AvgCommunicate_134181_Option_4 = {
    Text = "No la escuché."
  },
  AvgCommunicate_134181_Option_8 = {
    Text = "¿Me convertirán en una escultura?"
  },
  AvgCommunicate_134187_Content_1 = {
    Text = "Perrito, ¿cómo has estado últimamente?"
  },
  AvgCommunicate_134187_Content_10 = {
    Text = "No actúes precipitadamente. Pase lo que pase, el Estanque Negro te mantendrá firmemente aprisionado."
  },
  AvgCommunicate_134187_Content_11 = {
    Text = "No tienes la menor idea de qué clase de Fortaleza puede otorgarme el conocimiento."
  },
  AvgCommunicate_134187_Content_12 = {
    Text = "Estoy muy complacido con este regalo. Así que, mi queridísima estudiante, te daré un regalo a cambio."
  },
  AvgCommunicate_134187_Content_13 = {Text = "......?"},
  AvgCommunicate_134187_Content_14 = {
    Text = "Adivina. Adivina hasta dónde puedo llegar ahora."
  },
  AvgCommunicate_134187_Content_15 = {
    Text = "Adivina si tus arrogantes medidas de contención realmente pueden surtir efecto."
  },
  AvgCommunicate_134187_Content_16 = {
    Text = "Adivina si la Verdad que espié, ahora que he obtenido esta Fortaleza, será implante en la cognición de Todos."
  },
  AvgCommunicate_134187_Content_17 = {
    Text = "Esta es la tarea más importante, ¿sabes? Pronto, muy pronto, vendré a calificarla personalmente."
  },
  AvgCommunicate_134187_Content_2 = {
    Text = "Tu audacia realmente me sorprende — de verdad te atreviste a enviar un regalo de este calibre."
  },
  AvgCommunicate_134187_Content_3 = {
    Text = "¿Me creerías si te dijera que hubo un grave accidente durante el transporte de materiales raros..."
  },
  AvgCommunicate_134187_Content_5 = {
    Text = "Me subestimas, y subestimas a los Misaq."
  },
  AvgCommunicate_134187_Content_6 = {
    Text = "Estamos dispuestos a dejar que cada Cuerpo Despertado toque ese límite, porque intentaremos todos los métodos para prevenir la Síntoma: Destrucción."
  },
  AvgCommunicate_134187_Content_7 = {
    Text = "Esta es... la mayor diferencia entre esa Doll maestra, nosotros y tú. Incluso si la Síntoma: Destrucción está predestinada, jamás nos someteremos a ella."
  },
  AvgCommunicate_134187_Content_8 = {
    Text = "Ay, cómo no pude Descubrir antes que el sistema educativo de los Misaq podía producir semejantes necios."
  },
  AvgCommunicate_134187_Content_9 = {
    Text = "Afortunadamente, un necio tan lamentablemente estúpido que es difícil no sentir afecto por él."
  },
  AvgCommunicate_134187_Option_13 = {Text = "......?"},
  AvgCommunicate_134187_Option_3 = {
    Text = "Fue un accidente."
  },
  AvgCommunicate_134187_Option_5 = {
    Text = "Es mi sincera intención."
  },
  AvgCommunicate_134188_Content_1 = {
    Text = "¡Reglas, qué guay! ¡Bang—! ¡Boom—! ¡Kaboom—!"
  },
  AvgCommunicate_134188_Content_11 = {
    Text = "En ese caso, los costes de reparación de la escuela deberían bajar significativamente este mes..."
  },
  AvgCommunicate_134188_Content_12 = {
    Text = "¡Deberes malos, aparecer, Mosk, aplastar muerto!"
  },
  AvgCommunicate_134188_Content_13 = {
    Text = "¡No, no puedes contar los deberes como un enemigo también!"
  },
  AvgCommunicate_134188_Content_14 = {
    Text = "¿Mosk, Mosk?"
  },
  AvgCommunicate_134188_Content_16 = {
    Text = "Guardián, aquí Nautila. Quédate tranquilo, Mosk ha sido contenido. Los deberes y el aula están a salvo."
  },
  AvgCommunicate_134188_Content_17 = {
    Text = "Menos mal..."
  },
  AvgCommunicate_134188_Content_18 = {
    Text = "Nautila, Misaq y Mosk y yo siempre te necesitaremos."
  },
  AvgCommunicate_134188_Content_2 = {
    Text = "Recuerda la Regla N.º 1 del Código Misaq, Edición Especial Mosk: Bajo ninguna circunstancia se permite apuntar con un arma letal a nadie en Misaq."
  },
  AvgCommunicate_134188_Content_5 = {
    Text = "%player%, no te preocupes, Mosk, control, ¡puede hacer!"
  },
  AvgCommunicate_134188_Content_6 = {
    Text = "Mosk, control, remolino."
  },
  AvgCommunicate_134188_Content_7 = {
    Text = "Mosk, amigo, abracitos."
  },
  AvgCommunicate_134188_Content_8 = {
    Text = "Mosk, enemigo, ¡bang—! ¡boom—! ¡kaboom—!"
  },
  AvgCommunicate_134188_Option_2 = {
    Text = "Seguridad primero."
  },
  AvgCommunicate_134189_Content_1 = {
    Text = "Somos compañeros de armas, así que no diré gracias."
  },
  AvgCommunicate_134189_Content_2 = {
    Text = "Mi arma ha sido afilada hasta su filo más cortante—lo suficiente para cortar la garganta de un esclavista en un instante."
  },
  AvgCommunicate_134189_Content_3 = {
    Text = "El significado de la resistencia, el significado de la venganza, el significado de la batalla—aún los medito sin cesar."
  },
  AvgCommunicate_134189_Content_4 = {
    Text = "Quizás seguiré meditándolos el resto de mi vida, hasta el día en que ya no pueda mantenerme en pie."
  },
  AvgCommunicate_134189_Content_5 = {
    Text = "Al menos, ya no estoy perdida."
  },
  AvgCommunicate_134189_Content_6 = {
    Text = "Por mis compañeros de armas."
  },
  AvgCommunicate_134189_Content_7 = {
    Text = "Por los compañeros de armas. Fuiste tú quien me liberó y me dio la Resilencia para seguir adelante."
  },
  AvgCommunicate_134189_Content_8 = {
    Text = "Siempre que me necesites, cubriré sus espaldas, para Luchar juntos con ustedes."
  },
  AvgCommunicate_134189_Content_9 = {
    Text = "Sigamos luchando juntos — por la venganza que debe ser consumada, y por la emoción de la batalla en sí."
  },
  AvgCommunicate_134189_Option_6 = {
    Text = "Por los compañeros de armas."
  },
  AvgCommunicate_134201_Content_1 = {
    Text = "Guardián, he enviado una solicitud a la Oficina de Asuntos Académicos. Estaré ausente del entrenamiento durante los próximos tres días."
  },
  AvgCommunicate_134201_Content_10 = {
    Text = "Pero después de cruzar ese límite, lo comprendí."
  },
  AvgCommunicate_134201_Content_11 = {Text = "¿Qué?"},
  AvgCommunicate_134201_Content_13 = {
    Text = "Soy la hoja de la vanguardia. Es precisamente porque siempre he recorrido este Camino que pude conocer a todos ustedes, y conocerte a ti."
  },
  AvgCommunicate_134201_Content_14 = {
    Text = "Mi búsqueda asegura que nunca esté sola. Quizás nunca lleguemos, pero Solo perseveremos, podré acercar ese mundo ideal y justo un poco más, y más aún."
  },
  AvgCommunicate_134201_Content_15 = {
    Text = "Con mi cuerpo como hoja, hasta que alcancemos la utopía donde Todos puedan vivir bajo la luz."
  },
  AvgCommunicate_134201_Content_16 = {
    Text = "¡Qué gran visión, instructora Alva! ¡Te apoyaré incondicionalmente!"
  },
  AvgCommunicate_134201_Content_17 = {
    Text = "Maravilloso. En ese caso, usaré estos tres días para desarrollar un régimen de entrenamiento aún más riguroso y exigente."
  },
  AvgCommunicate_134201_Content_18 = {
    Text = "Serás la primera en probarlo. Descuida, te acompañaré durante todo el entrenamiento y mejoraré junto a todos."
  },
  AvgCommunicate_134201_Content_19 = {
    Text = "Espera, creo que podemos discutir esto un poco más..."
  },
  AvgCommunicate_134201_Content_2 = {
    Text = "¿Hubo algún problema con los materiales? ¿Estás bien? ¿Necesitas ayuda?"
  },
  AvgCommunicate_134201_Content_3 = {
    Text = "No, todo lo contrario. Todo salió bien. He experimentado un avance diferente a los anteriores."
  },
  AvgCommunicate_134201_Content_4 = {
    Text = "No lo entiendo del todo..."
  },
  AvgCommunicate_134201_Content_5 = {
    Text = "Yo... después de dejar el ejército, estuve a la deriva durante mucho tiempo."
  },
  AvgCommunicate_134201_Content_6 = {
    Text = "No sabía por qué debía luchar. Lo único que podía seguir era un sentido de la justicia del que ni siquiera estaba segura de poder alcanzar."
  },
  AvgCommunicate_134201_Content_7 = {
    Text = "Quería estar del lado de los débiles, del lado de quienes no pueden alzar la voz, del lado de quienes son tratados injustamente."
  },
  AvgCommunicate_134201_Content_8 = {
    Text = "Pero también sabía perfectamente que, sin importar cuán fuerte me volviera, siempre habría cosas ante las que sería impotente—igual que, aunque el tiempo se revirtiera, aún no podría evitar la caída de Aram."
  },
  AvgCommunicate_134201_Content_9 = {
    Text = "Instructora Alva..."
  },
  AvgCommunicate_134201_Option_2 = {
    Text = "¿Qué pasó?"
  },
  AvgCommunicate_134202_Content_1 = {
    Text = "Gracias por confiarme algo tan preciado, %player%."
  },
  AvgCommunicate_134202_Content_10 = {
    Text = "Creo que podría estar diciéndome que, además de dejar sombras en la memoria, el mundo también puede medirse con pasos."
  },
  AvgCommunicate_134202_Content_11 = {
    Text = "Si no puedo aferrarme a ellos, entonces simplemente seguiré avanzando, siempre adelante. El mundo y todos ustedes recordarán por mí."
  },
  AvgCommunicate_134202_Content_12 = {
    Text = "Incluso yo no puedo evitar sentirme entusiasmada..."
  },
  AvgCommunicate_134202_Content_13 = {
    Text = "Voy a convertirme en la mayor exploradora, la más increíble maestra mecánica. %player%, quiero extenderte formalmente la Invitación."
  },
  AvgCommunicate_134202_Content_14 = {
    Text = "Cuando llegue el día en que todo se resuelva, por favor, sal de aventura conmigo. Creemos más recuerdos preciosos en este mundo."
  },
  AvgCommunicate_134202_Content_15 = {
    Text = "Quizá ese día esté lejos, o quizá sea mañana."
  },
  AvgCommunicate_134202_Content_16 = {
    Text = "Esta invitación es válida para siempre. La recordaré, lo prometo."
  },
  AvgCommunicate_134202_Content_2 = {
    Text = "Pasé mucho, mucho tiempo absorbiéndolos... Ahora me hacen sentir como si me hubiera vuelto completa de nuevo."
  },
  AvgCommunicate_134202_Content_3 = {
    Text = "Entonces, ¿eso significa que ya no olvidarás las cosas?"
  },
  AvgCommunicate_134202_Content_4 = {
    Text = "Hmm, déjame pensar..."
  },
  AvgCommunicate_134202_Content_5 = {
    Text = "¡Jaja, sigo sin poder recordar las cosas!"
  },
  AvgCommunicate_134202_Content_6 = {
    Text = "¡¿Por qué suenas tan orgullosa de eso?!"
  },
  AvgCommunicate_134202_Content_7 = {
    Text = "Porque, aunque puede que siga olvidando muchas cosas, en el pasado y ahora, %player% siempre estará ahí para recordármelas y ayudarme a no olvidar."
  },
  AvgCommunicate_134202_Content_8 = {
    Text = "Quién soy, dónde estoy, qué debo hacer... las personas en las que más confío me lo dirán."
  },
  AvgCommunicate_134202_Content_9 = {
    Text = "Quizá por eso, tras comprender la Regla final, aunque mi memoria no ha mejorado, siento como si el mundo entero se hubiera desplegado ante mis ojos como un vasto mapa."
  },
  AvgCommunicate_134202_Option_3 = {
    Text = "¿Ha mejorado tu memoria?"
  },
  AvgCommunicate_134208_Content_1 = {
    Text = "Alguna vez creí que Solo interpretando el papel de Público podría experimentar la alegría de lo desconocido."
  },
  AvgCommunicate_134208_Content_10 = {
    Text = "No lo entiendo del todo... ¿pero suena como si debiera ser algo bueno?"
  },
  AvgCommunicate_134208_Content_11 = {
    Text = "Desde que partí de aquella puerta, esta es la mayor bendición que he encontrado."
  },
  AvgCommunicate_134208_Content_12 = {
    Text = "Guardián, esta es la sorpresa que me has dado—una que jamás podría haber previsto."
  },
  AvgCommunicate_134208_Content_13 = {
    Text = "El Destino nunca defrauda a quienes dan con generosidad."
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "No puedo tocar tus hilos, pero mientras luchas por el Destino, mi rueca girará por siempre para ti."
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "Ha pasado mucho, mucho tiempo desde la última vez que experimenté esta sensación..."
  },
  AvgCommunicate_134208_Content_3 = {
    Text = "¿Qué se siente?"
  },
  AvgCommunicate_134208_Content_4 = {Text = "Novedad."},
  AvgCommunicate_134208_Content_5 = {
    Text = "El silencioso florecer de los brotes, el entrelazarse de las palabras sobre el papel, el suave deslizar de las nubes en el Viento..."
  },
  AvgCommunicate_134208_Content_6 = {
    Text = "Y por supuesto, las personas—esos brazos extendidos, esas lágrimas cayendo, esos latidos como tambores de guerra o gotas de lluvia..."
  },
  AvgCommunicate_134208_Content_7 = {
    Text = "Veo más que antes, pero mis ojos están más bajos de lo que solían estar."
  },
  AvgCommunicate_134208_Content_8 = {
    Text = "Ya no se detienen en el cielo, Guardián. Han descendido, posándose en cada calle, junto a cada transeúnte."
  },
  AvgCommunicate_134208_Content_9 = {
    Text = "Ahora, no necesito interpretar un papel. Puedo existir verdaderamente como individuo."
  },
  AvgCommunicate_134208_Option_10 = {
    Text = "¿Eso suena como algo bueno?"
  },
  AvgCommunicate_134208_Option_3 = {
    Text = "¿Qué se siente?"
  },
  AvgCommunicate_134242_Content_1 = {
    Text = "Texto temporal"
  },
  AvgCommunicate_134245_Content_1 = {
    Text = "Parece algo muy valioso, ¿no hay problema en dárselo a Saya?"
  },
  AvgCommunicate_134245_Content_12 = {
    Text = "Resulta que este mundo también tiene su lado hermoso, aunque es un poco diferente al mundo que recuerdo."
  },
  AvgCommunicate_134245_Content_13 = {
    Text = "La forma en que está constituido, la lógica de su funcionamiento, Saya ya lo comprende por completo."
  },
  AvgCommunicate_134245_Content_14 = {
    Text = "Así que reescribir este mundo para que sea como el que recuerdo, quizás ahora podría hacerlo con mucha facilidad."
  },
  AvgCommunicate_134245_Content_16 = {
    Text = "Aunque sé que estás bromeando, por favor no hagas algo así."
  },
  AvgCommunicate_134245_Content_17 = {Text = "..."},
  AvgCommunicate_134245_Content_18 = {
    Text = "¿Por qué te has quedado callado? Es una broma, ¿verdad? ¡No guardes silencio en un momento así!"
  },
  AvgCommunicate_134245_Content_19 = {
    Text = "Oye, hace un momento solo salí un rato y observé a todos desde una nueva perspectiva..."
  },
  AvgCommunicate_134245_Content_2 = {
    Text = "Confío en Saya, así que no hay problema."
  },
  AvgCommunicate_134245_Content_20 = {
    Text = "Mientras todos los que conozco y que tratan a Saya con amabilidad sigan viviendo bien, es así."
  },
  AvgCommunicate_134245_Content_21 = {
    Text = "No sé exactamente qué está mal, pero de alguna manera siento que algo definitivamente no está del todo bien."
  },
  AvgCommunicate_134245_Content_22 = {
    Text = "¡Y además ahora seguro que tienes esa expresión de travesura cumplida en el rostro!"
  },
  AvgCommunicate_134245_Content_23 = {
    Text = "No te preocupes, me llevaré bien con todos en este mundo."
  },
  AvgCommunicate_134245_Content_24 = {
    Text = "Mmm... aunque el mundo que Saya recuerda en su memoria podría ser más interesante. ¿Vamos todos a verlo juntos? ¡Ahora debería ser posible!"
  },
  AvgCommunicate_134245_Content_25 = {
    Text = "¡Eso da aún más miedo!"
  },
  AvgCommunicate_134245_Content_3 = {
    Text = "Si puede ayudarte a comprender mejor este mundo, también debería ser de gran ayuda para la investigación sobre \"cómo detener la Disolución\"."
  },
  AvgCommunicate_134245_Content_4 = {
    Text = "Al fin y al cabo, eres realmente formidable en el aprendizaje y la investigación..."
  },
  AvgCommunicate_134245_Content_5 = {
    Text = "En realidad fue un suministro accidental... ¿pero ya es demasiado tarde para arrepentirse?"
  },
  AvgCommunicate_134245_Content_6 = {
    Text = "¿Eh? Entonces, ¿debería devolverlo? Estoy un poco indecisa."
  },
  AvgCommunicate_134245_Content_7 = {
    Text = "¿Eh? ¿Se puede devolver?"
  },
  AvgCommunicate_134245_Content_8 = {
    Text = "Mm, déjame pensar..."
  },
  AvgCommunicate_134245_Content_9 = {
    Text = "La respuesta es: no."
  },
  AvgCommunicate_134245_Option_2 = {
    Text = "No hay problema"
  },
  AvgCommunicate_134245_Option_5 = {
    Text = "Fue un accidente"
  },
  AvgCommunicate_134246_Content_1 = {
    Text = "Mi querido, amadísimo y magnífico benefactor~"
  },
  AvgCommunicate_134246_Content_10 = {
    Text = "Déjame comprobarlo."
  },
  AvgCommunicate_134246_Content_11 = {
    Text = "Déjame revisar los datos de fluctuación de tu Índice Gnóstico."
  },
  AvgCommunicate_134246_Content_12 = {
    Text = "Vaya, vaya—nuestra Caraboo realmente no mentía esta vez."
  },
  AvgCommunicate_134246_Content_13 = {
    Text = "Je je, ¿ahora sí le crees a la pobrecita Caraboo, verdad?"
  },
  AvgCommunicate_134246_Content_14 = {
    Text = "Por favor, sigue invirtiendo generosamente en mí—¡Para que pueda darle a mi querido benefactor cien, mil veces más rendimientos en el futuro!"
  },
  AvgCommunicate_134246_Content_15 = {
    Text = "¡Solo ocho más—no, cinco Fragmentos de Despertar Espiritual! ¡Y te deslumbraré de nuevo, lo prometo!"
  },
  AvgCommunicate_134246_Content_16 = {
    Text = "Eso es imposible."
  },
  AvgCommunicate_134246_Content_17 = {
    Text = "Buen intento."
  },
  AvgCommunicate_134246_Content_18 = {
    Text = "La profesora Doll me dijo que la investigación sobre el Despertar Espiritual de los Despertados ya ha alcanzado su límite. No habrá otro avance en un siglo."
  },
  AvgCommunicate_134246_Content_19 = {
    Text = "Una vez que un Despertado alcanza el Axioma Absoluto, nunca puede someterse de nuevo al ritual de la Oleada Psíquica."
  },
  AvgCommunicate_134246_Content_2 = {
    Text = "¿Qué necesitas esta vez para aparecer de repente con tanta adulación?"
  },
  AvgCommunicate_134246_Content_21 = {
    Text = "¡Jaja—debo de haberme confundido sin querer!"
  },
  AvgCommunicate_134246_Content_22 = {
    Text = "Por favor, rebobina tu memoria de esta conversación seis mensajes atrás. ¡Que tengas un día maravilloso~"
  },
  AvgCommunicate_134246_Content_3 = {
    Text = "Vaya, escúchate—¿por quién me tomas, por alguien que solo aparece cuando quiere algo?"
  },
  AvgCommunicate_134246_Content_4 = {
    Text = "Eso es exactamente lo que eres..."
  },
  AvgCommunicate_134246_Content_5 = {
    Text = "Buuuh, me has roto el corazón. Mi benefactor me juzga tan mal."
  },
  AvgCommunicate_134246_Content_6 = {
    Text = "¡En realidad he venido a traerte buenas noticias esta vez!"
  },
  AvgCommunicate_134246_Content_7 = {
    Text = "¡Tu inversión ha dado frutos—con resultados súper, súper increíbles~"
  },
  AvgCommunicate_134246_Content_8 = {
    Text = "¿Ves? Soy una nueva yo. Renacida, transformada, una persona completamente diferente~"
  },
  AvgCommunicate_134246_Content_9 = {
    Text = "¿De verdad?"
  },
  AvgCommunicate_134246_Option_10 = {
    Text = "Déjame comprobarlo."
  },
  AvgCommunicate_134246_Option_16 = {
    Text = "Eso es imposible."
  },
  AvgCommunicate_134246_Option_17 = {
    Text = "Buen intento."
  },
  AvgCommunicate_134246_Option_9 = {
    Text = "¿De verdad?"
  },
  AvgCommunicate_134247_Content_1 = {
    Text = "Texto temporal"
  },
  AvgCommunicate_134249_Content_1 = {
    Text = "Guardián..."
  },
  AvgCommunicate_134249_Content_10 = {
    Text = "Mmm... Esa sensación ha vuelto otra vez. De repente tengo calor, y sed. Mi estómago, Dentro de mi estómago,"
  },
  AvgCommunicate_134249_Content_11 = {
    Text = "Guardián, ¿estoy enferma? Mi estómago se ablanda, mi corazón se ablanda, todo se ablanda. No puedo distinguirlos, es como si me derritiera..."
  },
  AvgCommunicate_134249_Content_12 = {
    Text = "Respira hondo, Leigh. No te vas a derretir."
  },
  AvgCommunicate_134249_Content_13 = {
    Text = "Es una reacción humana normal en las relaciones íntimas. No necesitas medicina... ¡y tampoco necesitas agarrar un látigo!"
  },
  AvgCommunicate_134249_Content_14 = {
    Text = "¿Eh? ¿Ni siquiera un látigo? Qué decepción."
  },
  AvgCommunicate_134249_Content_16 = {
    Text = "...Eh, si de verdad necesitas uno, quizás ve a preguntarle a Pandia..."
  },
  AvgCommunicate_134249_Content_17 = {Text = "Jeje..."},
  AvgCommunicate_134249_Content_18 = {
    Text = "Guardián, intentaré no agacharme fuera de tu Puerta nunca más."
  },
  AvgCommunicate_134249_Content_19 = {
    Text = "Pero... ¿podrías de vez en cuando dejarme una Puerta abierta por la noche? Una ventana también serviría."
  },
  AvgCommunicate_134249_Content_2 = {
    Text = "La Carne y sangre de mi hermano y mi cuerpo son más compatibles que antes. Respiran en silencio bajo mi piel, ya no gritan constantemente para desgarrarme."
  },
  AvgCommunicate_134249_Content_20 = {
    Text = "No entraré Dentro. Solo saber que hay un Camino que me lleva a ti en cualquier momento me ayudaría a dormir más tranquila."
  },
  AvgCommunicate_134249_Content_3 = {
    Text = "El ansia de Sangre tampoco duele tanto. Antes, era como algo atascado en mi garganta—Asfixia si no bebía. Ahora parece... dispuesta a esperarme un poco."
  },
  AvgCommunicate_134249_Content_4 = {
    Text = "Esas son muy buenas noticias."
  },
  AvgCommunicate_134249_Content_5 = {
    Text = "Las noches en la escuela son tan tranquilas. La fuente salpica suavemente."
  },
  AvgCommunicate_134249_Content_6 = {
    Text = "Guardián, me has dado tantos tesoros. ¿De verdad los merezco?"
  },
  AvgCommunicate_134249_Content_7 = {
    Text = "Por supuesto que sí."
  },
  AvgCommunicate_134249_Content_8 = {
    Text = "...Siempre respondes tan rápido."
  },
  AvgCommunicate_134249_Content_9 = {
    Text = "Leigh, nos has ayudado muchísimo. Es lo mínimo que puedo hacer."
  },
  AvgCommunicate_134250_Content_1 = {
    Text = "¿No sabes cómo acaba cuando crías a una bestia salvaje?"
  },
  AvgCommunicate_134250_Content_10 = {
    Text = "A menudo me pregunto si realmente eres como aparentas en la superficie, o..."
  },
  AvgCommunicate_134250_Content_11 = {
    Text = "En realidad has estado fingiendo todo este tiempo, igual que esos amos de esclavos."
  },
  AvgCommunicate_134250_Content_12 = {
    Text = "¿Tú qué crees? No soy bueno actuando, ni tampoco soy bueno mintiendo."
  },
  AvgCommunicate_134250_Content_13 = {
    Text = "Puedes seguir tus propios sentimientos. No intentaré convencerte, ni te obligaré a hacer nada."
  },
  AvgCommunicate_134250_Content_14 = {
    Text = "Solo como dijo una vez tu otro yo, somos amigos —compañeros de armas."
  },
  AvgCommunicate_134250_Content_15 = {
    Text = "Tch, no me metas en el mismo saco que ese debilucho."
  },
  AvgCommunicate_134250_Content_16 = {
    Text = "Hace mucho que me harté de las traiciones. No necesito amigos en absoluto."
  },
  AvgCommunicate_134250_Content_17 = {
    Text = "Además, tampoco quiero ninguna de tus promesas."
  },
  AvgCommunicate_134250_Content_18 = {
    Text = "Solo proporcióname más Fortaleza, con eso basta."
  },
  AvgCommunicate_134250_Content_19 = {
    Text = "Y yo me vengaré de tus enemigos a cambio."
  },
  AvgCommunicate_134250_Content_2 = {
    Text = "Una bestia que ha crecido romperá sus cadenas y —rawr— morderá la garganta de su cuidador."
  },
  AvgCommunicate_134250_Content_20 = {
    Text = "Hasta el día en que verdaderamente me traiciones... Aunque huyas hasta los confines de la tierra, te perseguiré y te arrancaré la garganta."
  },
  AvgCommunicate_134250_Content_3 = {
    Text = "Ahora mismo, tu enlace conmigo me parece más Frágil que unas cadenas de hierro."
  },
  AvgCommunicate_134250_Content_4 = {
    Text = "¿No tienes miedo?"
  },
  AvgCommunicate_134250_Content_5 = {
    Text = "Eres libre. Nuestro enlace no pretende retenerte."
  },
  AvgCommunicate_134250_Content_6 = {
    Text = "No hay razón para tener miedo."
  },
  AvgCommunicate_134250_Content_7 = {Text = "..."},
  AvgCommunicate_134250_Content_8 = {
    Text = "Tch, palabras bonitas."
  },
  AvgCommunicate_134250_Content_9 = {
    Text = "Pero te he estado observando durante tanto tiempo, y aún no he logrado el descubrimiento de un momento en el que muestres un Defecto."
  },
  AvgCommunicate_134250_Option_12 = {
    Text = "¿Qué piensas?"
  },
  AvgCommunicate_134250_Option_5 = {Text = "Eres libre"},
  AvgCommunicate_134263_Content_1 = {
    Text = "¡¡Guardián!!"
  },
  AvgCommunicate_134263_Content_10 = {
    Text = "Por supuesto. Nunca dudé de que te harías más fuerte."
  },
  AvgCommunicate_134263_Content_11 = {Text = "..."},
  AvgCommunicate_134263_Content_12 = {
    Text = "Eres realmente alguien extraño."
  },
  AvgCommunicate_134263_Content_13 = {
    Text = "En un momento como este, ¿no deberías decir algo como \"¿Ves? Sabía que tenía buen ojo contigo\" o \"Realmente estuviste a la altura de mis expectativas\"?"
  },
  AvgCommunicate_134263_Content_14 = {
    Text = "¿Por qué estás tan tranquilo con esto?"
  },
  AvgCommunicate_134263_Content_16 = {
    Text = "Eh...porque te esforzaste tanto, hacerte más fuerte es algo natural. ¿Qué hay que decir?"
  },
  AvgCommunicate_134263_Content_17 = {
    Text = "Los 50 pavos que me devolviste hace dos años, y los 54 del año pasado... los he guardado todos."
  },
  AvgCommunicate_134263_Content_18 = {
    Text = "¿Para qué guardarlos?...solo gástalos."
  },
  AvgCommunicate_134263_Content_19 = {
    Text = "Olvídalo, no importa. Hay algo importante."
  },
  AvgCommunicate_134263_Content_2 = {
    Text = "Esos patrones se están calentando. ¡La Fortaleza del Aequor fluye bajo mi piel, mucho más claramente que antes!"
  },
  AvgCommunicate_134263_Content_20 = {
    Text = "Ve al lago ahora mismo. Te estoy esperando aquí."
  },
  AvgCommunicate_134263_Content_21 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_134263_Content_22 = {
    Text = "Lo sabrás cuando llegues."
  },
  AvgCommunicate_134263_Content_23 = {
    Text = "Está bien...entonces espérame un poco. Está lloviendo afuera ahora mismo. Necesito volver al dormitorio y buscar un paraguas primero."
  },
  AvgCommunicate_134263_Content_24 = {
    Text = "Deja de perder el tiempo. No necesitaremos paraguas para lo que viene."
  },
  AvgCommunicate_134263_Content_25 = {
    Text = "No te mojarás con la lluvia. Mis alas membranosas son lo bastante grandes."
  },
  AvgCommunicate_134263_Content_3 = {
    Text = "¡¿Tienes idea de lo que se siente?!"
  },
  AvgCommunicate_134263_Content_4 = {
    Text = "En fin, es increíblemente asombroso, más allá de las palabras. Ustedes los humanos probablemente no pueden comprenderlo."
  },
  AvgCommunicate_134263_Content_5 = {
    Text = "...Caecus, ¿estás bien?"
  },
  AvgCommunicate_134263_Content_6 = {
    Text = "Por supuesto que estoy bien. Nunca he estado mejor."
  },
  AvgCommunicate_134263_Content_7 = {
    Text = "Te lo dije hace mucho, tu inversión no sería en vano. Mi Sangre nunca me miente."
  },
  AvgCommunicate_134263_Content_8 = {Text = "Sé."},
  AvgCommunicate_134263_Content_9 = {
    Text = "...¿Eso es todo?"
  },
  AvgCommunicate_134264_Content_1 = {
    Text = "Por favor, perdóname, El mensajero pálido. No estaba lo suficientemente preparada para esto y parece que te he asustado."
  },
  AvgCommunicate_134264_Content_10 = {
    Text = "Solo pienso en esto, la paz en mi corazón supera con creces el sufrimiento de mi carne."
  },
  AvgCommunicate_134264_Content_11 = {
    Text = "Entiendo. Puede que no tenga ideales tan grandiosos. Pero aunque sea por ti, por mis amigos."
  },
  AvgCommunicate_134264_Content_12 = {
    Text = "Solo pueda alcanzar ese mundo ideal y pacífico, sin importar lo que cueste, daré lo mejor de mí."
  },
  AvgCommunicate_134264_Content_13 = {
    Text = "Gracias, Mensajero pálido."
  },
  AvgCommunicate_134264_Content_14 = {
    Text = "Que todo sufrimiento encuentre su día de disolución, y que tú y yo siempre caminemos lado a lado."
  },
  AvgCommunicate_134264_Content_15 = {
    Text = "Que la protección del Padre Dios descienda también sobre todo lo que amas."
  },
  AvgCommunicate_134264_Content_2 = {
    Text = "Uf... Me alegra que estés bien. No esperaba que la comprensión de las leyes provocara este tipo de Efecto."
  },
  AvgCommunicate_134264_Content_3 = {
    Text = "No te preocupes por mí. Esta es la misión para la que vine a este mundo."
  },
  AvgCommunicate_134264_Content_4 = {
    Text = "Antes de cruzar el umbral hacia la cima, antes de que el Padre Dios me revelara estos misterios insondables, ya me había consagrado a este Camino."
  },
  AvgCommunicate_134264_Content_5 = {
    Text = "Reunir el sufrimiento de todos los seres sobre mí, guiar todas las cosas hacia una tierra inmaculada donde el sufrimiento ya no exista... esto no es una carga. Es la gracia que me otorgó el Padre Dios."
  },
  AvgCommunicate_134264_Content_6 = {
    Text = "Siempre he sentido que cargas con demasiado. El dolor de los demás se Deshace, pero el coste..."
  },
  AvgCommunicate_134264_Content_7 = {
    Text = "Mi pálida llama, posees un corazón tierno."
  },
  AvgCommunicate_134264_Content_8 = {
    Text = "Pero no te preocupes. El sufrimiento físico es para mí lo que las Espinas son para la tierra— cuanto más profundo penetran, con más firmeza Echo raíces."
  },
  AvgCommunicate_134264_Content_9 = {
    Text = "Si tan solo un alma en este mundo aún sufre, jamás sufrirá sola. Si tan solo una no ha logrado escapar del mar de sufrimiento, jamás alcanzaré la otra orilla antes que ella."
  },
  AvgCommunicate_134264_Option_11 = {Text = "Entiendo"},
  AvgCommunicate_134264_Option_6 = {Text = "Pero..."},
  AvgCommunicate_134265_Content_1 = {
    Text = "¡Jaja, estimulante, absolutamente estimulante!"
  },
  AvgCommunicate_134265_Content_10 = {
    Text = "Pregúntale a cualquiera de mis muchachos, me conocen desde hace años. ¿Cuándo me han visto hacer algo así?"
  },
  AvgCommunicate_134265_Content_11 = {
    Text = "Ah, ahora que mi Fortaleza es aún más feroz, tendré que tener cuidado de no quemarte la próxima vez."
  },
  AvgCommunicate_134265_Content_12 = {
    Text = "Qué... ¿fuiste tú? Entonces, esas veces que me cambiaron la ropa... ¿también fuiste tú?"
  },
  AvgCommunicate_134265_Content_13 = {
    Text = "Sí, tu ropa estaba toda sucia de alcohol y comida. No podía dejarte meterte en la cama así."
  },
  AvgCommunicate_134265_Content_14 = {
    Text = "Gracias, Katie Gula."
  },
  AvgCommunicate_134265_Content_15 = {
    Text = "Pero la próxima vez, ¿podrías simplemente sacudirme para despertarme...?"
  },
  AvgCommunicate_134265_Content_16 = {
    Text = "¿Te da vergüenza? No te preocupes— mira lo cercanas que somos."
  },
  AvgCommunicate_134265_Content_17 = {
    Text = "Olvídate de algo tan trivial como cambiarte la ropa— aunque me pidieras caminar sobre fuego o escalar una montaña de cuchillas, ¡no sería ningún problema!"
  },
  AvgCommunicate_134265_Content_18 = {
    Text = "En el peor de los casos, la próxima vez te dejo que me cambies tú a mí. Justo es justo."
  },
  AvgCommunicate_134265_Content_19 = {
    Text = "...¡Nada de eso es razonable, y es tan absurdo que ni siquiera sé cómo responder!"
  },
  AvgCommunicate_134265_Content_2 = {
    Text = "Una sensación de euforia sin precedentes... ¡ahora, yo soy el Sol!"
  },
  AvgCommunicate_134265_Content_3 = {
    Text = "Pequeño, cada vez me impresionas más."
  },
  AvgCommunicate_134265_Content_4 = {
    Text = "¿Solo ahora te das cuenta? Aún queda mucho más de donde salió eso."
  },
  AvgCommunicate_134265_Content_5 = {
    Text = "¿Oh? Parece que no ha sido muy apropiado que todos te tratemos como a un pequeño."
  },
  AvgCommunicate_134265_Content_6 = {
    Text = "Hmm... de ahora en adelante, debería comenzar a llamarte grandote."
  },
  AvgCommunicate_134265_Content_7 = {
    Text = "¿Grandote? ¡Qué clase de nombre es ese! Me estás tomando el pelo otra vez con esa cara seria, ¿verdad?"
  },
  AvgCommunicate_134265_Content_8 = {
    Text = "Jajaja, no puedo evitarlo. Siempre eres el primero en caer cada vez que salimos a beber."
  },
  AvgCommunicate_134265_Content_9 = {
    Text = "Así que tengo que cargarte de vuelta al dormitorio cada vez, quitarte los zapatos, arroparte y limpiarte la cara."
  },
  AvgCommunicate_134265_Option_12 = {
    Text = "¿Eras tú?"
  },
  AvgCommunicate_134265_Option_7 = {Text = "¿?!"},
  AvgCommunicate_134267_Content_1 = {
    Text = "%player%, mi música se ha vuelto aún más perfecta."
  },
  AvgCommunicate_134267_Content_10 = {
    Text = "Mi música era como una máquina funcionando con precisión, y en su momento me ganó un lugar en la orquesta más selecta. Por supuesto, estaba orgulloso de eso."
  },
  AvgCommunicate_134267_Content_11 = {
    Text = "Él era diferente. No era apto para el Ensamble. Su música estaba destinada a brillar sola en el cielo, como el Sol o la Luna."
  },
  AvgCommunicate_134267_Content_12 = {
    Text = "Siempre lo observaba, persiguiéndolo. Solo que ya había perdido para siempre la oportunidad de comunicarme con él."
  },
  AvgCommunicate_134267_Content_13 = {
    Text = "Pero... la interpretación que ahora ha alcanzado la perfección absoluta es probablemente la mejor respuesta que puedo presentar tras toda una vida de búsqueda."
  },
  AvgCommunicate_134267_Content_14 = {
    Text = "Qué conmovedor... ¿Cómo es que tienes un pasado así? Una historia legendaria de músicos que brillan intensamente y reflejan la luz del otro..."
  },
  AvgCommunicate_134267_Content_15 = {
    Text = "Mm, Solo unas reflexiones perfectamente ordinarias. En realidad no es tan dramático."
  },
  AvgCommunicate_134267_Content_16 = {
    Text = "En cualquier caso, lo que más quiero decir es: gracias, %player%."
  },
  AvgCommunicate_134267_Content_17 = {
    Text = "De ahora en adelante, por favor permíteme seguir tocando mi flauta para ti, acompañándote hacia un sueño apacible cada noche."
  },
  AvgCommunicate_134267_Content_2 = {
    Text = "Sin tu guía, probablemente nunca habría podido dar este último paso: calibrar los errores minúsculos que antes estaban más allá de la capacidad humana para corregir."
  },
  AvgCommunicate_134267_Content_3 = {
    Text = "Ritmo perfecto, tono impecable, todo suena tan exquisito..."
  },
  AvgCommunicate_134267_Content_4 = {
    Text = "¡En efecto! ¡Nunca había escuchado una interpretación tan deliciosa!"
  },
  AvgCommunicate_134267_Content_5 = {
    Text = "Este es el resultado de la Resonancia entre música y cálculo, instrumento y cuerpo, mente y músculo."
  },
  AvgCommunicate_134267_Content_6 = {
    Text = "Por fin he demostrado que al final de este Camino árido y tedioso, también puede existir una música tan perfecta."
  },
  AvgCommunicate_134267_Content_7 = {
    Text = "¿También? ¿Qué quieres decir con eso?"
  },
  AvgCommunicate_134267_Content_8 = {
    Text = "En el pasado, tuve Una amigo cuya música era el producto de la más exquisita sensibilidad y creatividad."
  },
  AvgCommunicate_134267_Content_9 = {
    Text = "El talento que manejaba con tanta libertad le permitía improvisar composiciones únicas en cada actuación."
  },
  AvgCommunicate_134267_Option_14 = {Text = "Waaah..."},
  AvgCommunicate_134267_Option_4 = {Text = "De hecho"},
  AvgCommunicate_134267_Option_7 = {
    Text = "¿También?"
  },
  AvgCommunicate_134268_Content_1 = {
    Text = "Mi más honorable invitado, ¿cómo podré agradecerle jamás su generosidad?"
  },
  AvgCommunicate_134268_Content_10 = {
    Text = "Ya veo, entiendo. No quieres esas celebraciones vulgares. Yo también creo que no te van."
  },
  AvgCommunicate_134268_Content_11 = {
    Text = "Hay una buena idea. ¿Quizá estarías dispuesto a intentar acompañarme más allá de Necrovia para recibir a alguien que se acerca a su final?"
  },
  AvgCommunicate_134268_Content_12 = {
    Text = "Si se nos concediera tal honor, espero que tú y yo podamos recibirlos juntos, guiándolos hasta su destino final y nuevo nacido sanado. ¿Qué dices?"
  },
  AvgCommunicate_134268_Content_13 = {
    Text = "Aunque quizá no sea el mejor momento para preguntar... Supongo que al final seguirá implicando consumo, ya que es la costumbre de Necrovia."
  },
  AvgCommunicate_134268_Content_14 = {
    Text = "Hmm, yo no lo definiría como consumo. Solo como las historias que ya conoces."
  },
  AvgCommunicate_134268_Content_15 = {
    Text = "Es solo la despedida más solemne y, a la vez, más serena."
  },
  AvgCommunicate_134268_Content_16 = {
    Text = "Estaré encantado de participar, solo que me permitas saltarme ciertas partes..."
  },
  AvgCommunicate_134268_Content_17 = {
    Text = "Por supuesto, por supuesto."
  },
  AvgCommunicate_134268_Content_18 = {
    Text = "Entonces, el carruaje de Necrovia y yo estaremos esperando tu llegada fuera de la Puerta mañana por la mañana."
  },
  AvgCommunicate_134268_Content_2 = {
    Text = "Su obsequio me ha otorgado la Fuerza para servir verdadera y firmemente como Guardián de Necrovia."
  },
  AvgCommunicate_134268_Content_3 = {
    Text = "La cocina ordinaria no es digna de su ofrenda, y mi colección personal quizá no se ajuste del todo a su paladar."
  },
  AvgCommunicate_134268_Content_4 = {
    Text = "Qué dilema tan dichosamente desconcertante."
  },
  AvgCommunicate_134268_Content_5 = {
    Text = "Es usted muy amable, Doresain."
  },
  AvgCommunicate_134268_Content_6 = {
    Text = "Hemos pasado por tanto juntos. De verdad no necesitas preocuparte por esas tediosas formalidades de Tránsito."
  },
  AvgCommunicate_134268_Content_7 = {
    Text = "Oh no, no, esto no es en absoluto una mera formalidad. Estoy contemplando sinceramente cómo organizar un encuentro con un querido amigo."
  },
  AvgCommunicate_134268_Content_8 = {
    Text = "Ya has presenciado la Danza más extraordinaria de Necrovia. Cómo profundizar aún más el vínculo entre tú y nosotros... eso sí que es un desafío."
  },
  AvgCommunicate_134268_Content_9 = {
    Text = "Eh... Si quieres saber mi preferencia, humildemente espero que sea algo ordinario, sin ningún susto..."
  },
  AvgCommunicate_134268_Option_13 = {
    Text = "Supongo que"
  },
  AvgCommunicate_134268_Option_9 = {Text = "Um"},
  AvgCommunicate_134269_Content_1 = {
    Text = "Mi pequeño retoño..."
  },
  AvgCommunicate_134269_Content_10 = {
    Text = "Dentro de mi cuerpo, la Fortaleza de la \"Reproducción\" está floreciendo, nacida de haber tocado lo absoluto."
  },
  AvgCommunicate_134269_Content_11 = {
    Text = "Qué dulce, qué exuberante... Ah, me canso de hablarte a través de este diminuto bloque de metal."
  },
  AvgCommunicate_134269_Content_12 = {Text = "¿Thais?"},
  AvgCommunicate_134269_Content_13 = {
    Text = "Ven a mi lado, pequeño retoño. Ahora mismo, en este instante."
  },
  AvgCommunicate_134269_Content_14 = {
    Text = "Quiero sostener tus cálidas palmas, tocar tu suave piel..."
  },
  AvgCommunicate_134269_Content_15 = {
    Text = "Quiero abrazarte bajo la luz de la luna, igual que la noche en que hicimos nuestra promesa."
  },
  AvgCommunicate_134269_Content_16 = {
    Text = "Con mi Fortaleza cada vez más abundante, fusionándome contigo poco a poco, y dejando que tu dulce esencia me reconforte, poquito a poquito..."
  },
  AvgCommunicate_134269_Content_2 = {
    Text = "Lo que me prometiste —nuestro pacto hecho bajo la luz de la luna y a través del mar de arena— ya has comenzado a cumplirlo por mí."
  },
  AvgCommunicate_134269_Content_3 = {
    Text = "Estoy tan feliz."
  },
  AvgCommunicate_134269_Content_4 = {
    Text = "Aunque un mundo donde Todos puedan vivir en paz aún está lejos, seguiré trabajando para lograrlo."
  },
  AvgCommunicate_134269_Content_5 = {
    Text = "Desde el momento en que nos conocimos, he creído en ti."
  },
  AvgCommunicate_134269_Content_6 = {
    Text = "Eres alguien bendecido por el Destino. Tienes la Fortaleza y la determinación."
  },
  AvgCommunicate_134269_Content_7 = {
    Text = "Mi pequeño retoño, te ves tan adorable cuando te enfrentas al mundo con tanta determinación."
  },
  AvgCommunicate_134269_Content_8 = {
    Text = "Esperaré con paciencia, con fervor— Espera, espera... el día en que nuestra promesa se cumpla."
  },
  AvgCommunicate_134269_Content_9 = {
    Text = "¡Ciertamente!"
  },
  AvgCommunicate_134269_Option_12 = {Text = "¿Thais?"},
  AvgCommunicate_134269_Option_4 = {
    Text = "Seguiré esforzándome"
  },
  AvgCommunicate_134269_Option_9 = {
    Text = "¡Ciertamente!"
  },
  AvgCommunicate_134270_Content_1 = {
    Text = "No te mataré."
  },
  AvgCommunicate_134270_Content_10 = {
    Text = "Después de dejarte seco, iré a matar a Todos."
  },
  AvgCommunicate_134270_Content_11 = {
    Text = "Entonces... ¿intentaré seguir con vida todo lo que pueda?"
  },
  AvgCommunicate_134270_Content_12 = {
    Text = "Jajaja, qué respuesta tan interesante."
  },
  AvgCommunicate_134270_Content_13 = {
    Text = "Ya que pretendes usar ese frágil cuerpo tuyo para ser el Guardián del mundo entero."
  },
  AvgCommunicate_134270_Content_14 = {
    Text = "Entonces... ¿por qué tú..."
  },
  AvgCommunicate_134270_Content_15 = {Text = "...¿Y?"},
  AvgCommunicate_134270_Content_16 = {
    Text = "Hasta entonces, Solo mataré a tus enemigos."
  },
  AvgCommunicate_134270_Content_17 = {
    Text = "¡¿Así que de todas formas vas a matar?!"
  },
  AvgCommunicate_134270_Content_2 = {
    Text = "...? ¿Eh? ¿Qué se supone que diga? ¿Gracias?"
  },
  AvgCommunicate_134270_Content_3 = {
    Text = "Este mundo se volvió verdaderamente aburrido tras la caída de Roma."
  },
  AvgCommunicate_134270_Content_4 = {
    Text = "Matar, matar, matar. Nada más que pura masacre y Sangre. Sin Roma, no queda nada."
  },
  AvgCommunicate_134270_Content_5 = {
    Text = "Tu don me liberó de esas cadenas. Ahora voy a arrancar un brazo o dos, o quizás una garganta."
  },
  AvgCommunicate_134270_Content_6 = {
    Text = "Lamento decírtelo, Uvhash, pero en los tiempos modernos, matar personas sin autorización especial va contra la ley."
  },
  AvgCommunicate_134270_Content_7 = {
    Text = "Y sigo siendo tu enlazador. No Solo no puedes matarme a mí, tampoco puedes matar a nadie más."
  },
  AvgCommunicate_134270_Content_8 = {Text = "Tch."},
  AvgCommunicate_134270_Content_9 = {
    Text = "Bien. Al menos sabes mejor que todos esos amos de esclavos."
  },
  AvgCommunicate_134271_Content_1 = {
    Text = "Guar~da~se~cre~tos～ ¿Estás ocupado/a? Hay algo que quiero decirte～"
  },
  AvgCommunicate_134271_Content_10 = {Text = "¿Vacío?"},
  AvgCommunicate_134271_Content_11 = {
    Text = "Mm～ Ya sabes, esa sensación oscura y fría, la sensación de ser abandonada por todos que surge cada vez que el viento sopla a través."
  },
  AvgCommunicate_134271_Content_12 = {
    Text = "Pero ahora, todo está cálido～ y brillante～"
  },
  AvgCommunicate_134271_Content_13 = {
    Text = "Todo es gracias a %player%."
  },
  AvgCommunicate_134271_Content_14 = {
    Text = "¿Entonces esto realmente es un agradecimiento sincero?"
  },
  AvgCommunicate_134271_Content_15 = {
    Text = "Hmph～ ¡Por supuesto, puedo ser seria de vez en cuando, ¿sabes?!"
  },
  AvgCommunicate_134271_Content_16 = {
    Text = "Pero a cambio — tienes que pasar más tiempo conmigo de ahora en adelante, ¿vale?"
  },
  AvgCommunicate_134271_Content_17 = {
    Text = "Si no, usaré mis habilidades recién aprendidas para cas~ti~gar~te～ bien～"
  },
  AvgCommunicate_134271_Content_18 = {
    Text = "...¡¿De verdad así es como muestras tu agradecimiento?!"
  },
  AvgCommunicate_134271_Content_19 = {
    Text = "Oh, vaya, esta es la forma exclusiva de Pandia de expresar amor～ ¡Mua～! ¡Recuerda estar agradecido!"
  },
  AvgCommunicate_134271_Content_2 = {
    Text = "¿Qué travesura estás tramando ahora?"
  },
  AvgCommunicate_134271_Content_3 = {
    Text = "¡¿Cómo puedes decir eso?! ¡Vengo a darte las gracias sinceramente!"
  },
  AvgCommunicate_134271_Content_4 = {
    Text = "Esas cosas buenas que me diste antes... hicieron que mi cuerpo se sintiera tan caliente, tan caliente～"
  },
  AvgCommunicate_134271_Content_5 = {
    Text = "Es como si algo abrasador fluyera bajo mi piel, dulce y picante～"
  },
  AvgCommunicate_134271_Content_6 = {
    Text = "Aunque sé que no habrá efectos secundarios, ¿estás segura de que esto no es un efecto secundario..."
  },
  AvgCommunicate_134271_Content_7 = {
    Text = "¡No lo es! ¡Esta sensación es increíble! ¡Cien veces más emocionante que cualquier latigazo!"
  },
  AvgCommunicate_134271_Content_8 = {
    Text = "Y sabes qué, lo más increíble es..."
  },
  AvgCommunicate_134271_Content_9 = {
    Text = "Ese lugar vacío dentro de mi corazón... se ha llenado."
  },
  AvgCommunicate_134271_Option_14 = {Text = "Así que"},
  AvgCommunicate_134271_Option_6 = {Text = "Aunque"},
  AvgCommunicate_134272_Content_1 = {
    Text = "Amo～ ¿Cómo podría Karen pagártelo? Bebidas, limpieza, comidas—¡no dudes en darle órdenes a Karen!"
  },
  AvgCommunicate_134272_Content_10 = {
    Text = "Solo Karen quiera, la piel de Karen puede brillar con más esplendor que las gemas más caras, y resplandecer con más fulgor que las perlas más perfectas."
  },
  AvgCommunicate_134272_Content_11 = {
    Text = "Si Karen va a una Danza ahora, Karen definitivamente será el centro de atención, ya no la pequeña don nadie que a nadie le importa."
  },
  AvgCommunicate_134272_Content_12 = {
    Text = "Aunque no creo que este sea el propósito principal de Mejorar con la Regla final, pero..."
  },
  AvgCommunicate_134272_Content_13 = {
    Text = "Solo que te haga feliz, eso es lo que importa."
  },
  AvgCommunicate_134272_Content_2 = {
    Text = "Primero, ¡descartemos la comida!"
  },
  AvgCommunicate_134272_Content_3 = {
    Text = "Oh, vaya, mis habilidades domésticas están siendo cuestionadas. Karen debería estar triste por esto, pero, pero..."
  },
  AvgCommunicate_134272_Content_4 = {
    Text = "¡Tantas, tantas joyas y accesorios! Karen se siente como la gema más deslumbrante de todas. ¡Es realmente difícil para Karen sentirse triste!"
  },
  AvgCommunicate_134272_Content_5 = {
    Text = "Cálmate un poco primero. Ya casi no puedo entender lo que dices."
  },
  AvgCommunicate_134272_Content_6 = {
    Text = "Lo siento, Karen se emocionó demasiado. Después de que el Maestro ayudó a Karen a comprender esa cosa... ¿qué era, un pasador? ¿Una cinta o algo así...?"
  },
  AvgCommunicate_134272_Content_7 = {
    Text = "...Es un Axioma."
  },
  AvgCommunicate_134272_Content_8 = {
    Text = "Ah, sí, esa cosa muy cara y realmente increíble. Y entonces, Karen sintió que obtuvo una habilidad increíblemente poderosa."
  },
  AvgCommunicate_134272_Content_9 = {
    Text = "No solo ha mejorado mucho la eficiencia al hacer las tareas del hogar, sino que, lo más importante, el cuerpo de Karen brilla y resplandece."
  },
  AvgCommunicate_134272_Option_7 = {
    Text = "No es un pasador"
  },
  AvgCommunicate_134273_Content_1 = {
    Text = "%player%, mi vínculo contigo se ha hecho más profundo."
  },
  AvgCommunicate_134273_Content_10 = {
    Text = "Cosas como resultados de cálculo, preguntas de exámenes de educación general y cosas así... ¿también se pueden obtener directamente del conocimiento infinito?"
  },
  AvgCommunicate_134273_Content_11 = {Text = "..."},
  AvgCommunicate_134273_Content_12 = {
    Text = "En efecto, ya no necesitas memorizar tantas cosas con tanto esfuerzo."
  },
  AvgCommunicate_134273_Content_13 = {
    Text = "Pero creo que el significado del aprendizaje reside en el proceso de buscar el conocimiento y en el entrenamiento de la Fortaleza del pensamiento."
  },
  AvgCommunicate_134273_Content_14 = {
    Text = "Primero debes saber lo que no sabes y lo que deberías saber, antes de poder encontrar la respuesta que necesitas en el tesoro infinito."
  },
  AvgCommunicate_134273_Content_15 = {
    Text = "Está bien, entiendo. Aunque la respuesta difiere de la de Ramona, el resultado es el mismo al fin y al cabo."
  },
  AvgCommunicate_134273_Content_16 = {
    Text = "¡Estudiaré, estudiaré, ¿vale?!"
  },
  AvgCommunicate_134273_Content_17 = {
    Text = "Me alegra ver tus ganas de aprender. Sigue así. Estaré, como siempre, justo a tu lado."
  },
  AvgCommunicate_134273_Content_2 = {
    Text = "Felicidades, y gracias por tus esfuerzos. Ahora puedo reunir más fragmentos de consciencia y ocultar una existencia más completa dentro de las grietas del mundo."
  },
  AvgCommunicate_134273_Content_3 = {
    Text = "¡¿Ya puedes descender al mundo!?"
  },
  AvgCommunicate_134273_Content_4 = {
    Text = "Lamentablemente, aún no puedo revelar verdaderamente mi existencia, ni abandonar la Laguna Negra."
  },
  AvgCommunicate_134273_Content_5 = {
    Text = "Pero mi espíritu, mi Sueño, mi mirada sobre los innumerables mundos... ahora pueden existir de forma más plena, y transmitirse a ti con mayor abundancia."
  },
  AvgCommunicate_134273_Content_6 = {
    Text = "Como mínimo, ahora posees la llave del conocimiento infinito."
  },
  AvgCommunicate_134273_Content_7 = {
    Text = "¿Quieres decir que sin importar lo que pregunte, puedo obtener una respuesta?"
  },
  AvgCommunicate_134273_Content_8 = {
    Text = "Solo si existe, o puede ser demostrado."
  },
  AvgCommunicate_134273_Content_9 = {
    Text = "Jeje, por ejemplo, digo solo por ejemplo."
  },
  AvgCommunicate_134273_Option_15 = {Text = "Entiendo"},
  AvgCommunicate_134273_Option_7 = {
    Text = "¿Conocimiento infinito?"
  },
  AvgCommunicate_134274_Content_1 = {
    Text = "La semilla... se ha vuelto más completa."
  },
  AvgCommunicate_134274_Content_10 = {
    Text = "Esas escenas tan animadas todavía me resultan demasiado estresantes."
  },
  AvgCommunicate_134274_Content_11 = {
    Text = "No pasa nada. Estaré justo ahí contigo, y Tinct también."
  },
  AvgCommunicate_134274_Content_12 = {
    Text = "Por supuesto, si te sientes más cómoda estando sola, ¡apoyo tu decisión por completo!"
  },
  AvgCommunicate_134274_Content_13 = {
    Text = "Guardián... gracias, si esto es lo que tú y Tinct esperáis."
  },
  AvgCommunicate_134274_Content_14 = {
    Text = "Hmm... empecemos por adaptarnos en el rincón del fondo del aula."
  },
  AvgCommunicate_134274_Content_2 = {
    Text = "Puedo sentirlo—una Fuerza capaz de sostener mi germinación, llenando gradualmente el vacío en mi alma."
  },
  AvgCommunicate_134274_Content_3 = {
    Text = "Entonces... ¿eso significa que ya no drenarás la fuerza vital de los demás?"
  },
  AvgCommunicate_134274_Content_4 = {
    Text = "Desafortunadamente, esta habilidad innata mía no ha desaparecido."
  },
  AvgCommunicate_134274_Content_5 = {
    Text = "Sin embargo, estoy empezando a ganar control sobre esta Fuerza."
  },
  AvgCommunicate_134274_Content_6 = {
    Text = "Solo siga practicando, los Investigadores que entren en contacto conmigo ya no necesitarán llevar esos engorrosos trajes de protección."
  },
  AvgCommunicate_134274_Content_7 = {
    Text = "Ahora, existe la posibilidad de que pueda quedarme al lado de todos de forma segura."
  },
  AvgCommunicate_134274_Content_8 = {
    Text = "¡Eso es maravilloso! A partir de ahora, podrás unirte a todo tipo de actividades escolares, galas e incluso fiestas entre Cuerpos Despertados."
  },
  AvgCommunicate_134274_Content_9 = {
    Text = "F-fiestas... Creo que dominar la habilidad de llevarse bien con la gente es mucho más difícil que dominar el control sobre mis instintos."
  },
  AvgCommunicate_134274_Option_11 = {Text = "Está bien"},
  AvgCommunicate_134274_Option_3 = {
    Text = "Así que..."
  },
  AvgCommunicate_134274_Option_8 = {
    Text = "¡Eso es maravilloso!"
  },
  AvgCommunicate_134275_Content_1 = {
    Text = "Es tu privilegio ofrecer todo lo noble a la Princesa."
  },
  AvgCommunicate_134275_Content_10 = {
    Text = "...¿Gracias? ¿Acaso no estás solo intentando halagarme con regalos, para luego escuchar unas palabras de aliento de mi parte, o que cumpla alguna expectativa tuya?"
  },
  AvgCommunicate_134275_Content_11 = {
    Text = "Murphy, te hago regalos y te trato bien solo porque eres tú."
  },
  AvgCommunicate_134275_Content_12 = {
    Text = "No tiene nada que ver con que seas una princesa, la Madre divina, ni nada más. Eres mi amiga. Más allá de eso, no tengo otras expectativas."
  },
  AvgCommunicate_134275_Content_13 = {Text = "..."},
  AvgCommunicate_134275_Content_14 = {
    Text = "¡Hmph! Eso es... ¡eso es solo la misma palabrería zalamera y elocuente de siempre! ¿Crees que diciendo algo así me harás llorar?"
  },
  AvgCommunicate_134275_Content_15 = {
    Text = "¡¿Síntoma: Delirio?! ¿Qué quieres decir, amigo? Solo necesitas ser un Seguidor leal, y con eso basta."
  },
  AvgCommunicate_134275_Content_16 = {
    Text = "Qué cosa tan hiriente de decir. De verdad voy a llorar toda la noche, ¿sabes?"
  },
  AvgCommunicate_134275_Content_17 = {
    Text = "Tú... tú, ay, qué tonto tan inútil."
  },
  AvgCommunicate_134275_Content_18 = {
    Text = "Solo esta vez, así que escucha con atención."
  },
  AvgCommunicate_134275_Content_19 = {Text = "Gracias."},
  AvgCommunicate_134275_Content_2 = {
    Text = "No está nada mal."
  },
  AvgCommunicate_134275_Content_20 = {
    Text = "En cualquier caso, de ahora en adelante, ¡esta princesa tendrá más que suficiente poder para mantenerte a salvo, así que agradécelo y sigue adorándome!"
  },
  AvgCommunicate_134275_Content_3 = {
    Text = "¿No tienes nada más que decir?"
  },
  AvgCommunicate_134275_Content_4 = {
    Text = "¿Qué, acaso esta Fortaleza no me pertenecía a mí desde el principio?"
  },
  AvgCommunicate_134275_Content_5 = {
    Text = "Oh, ya veo. Quieres una recompensa, una Bendición, un puesto más alto, o quizás una identidad más distinguida?"
  },
  AvgCommunicate_134275_Content_6 = {Text = "..."},
  AvgCommunicate_134275_Content_7 = {
    Text = "¿Qué significa \"...\"? Qué molesto. No tengo interés en jugar a las adivinanzas contigo."
  },
  AvgCommunicate_134275_Content_8 = {
    Text = "Te daré una última oportunidad. Dime lo que quieres, rápido. Deja de andarte con rodeos."
  },
  AvgCommunicate_134275_Content_9 = {
    Text = "¿Es posible que, lo que quiero decir es, al menos podrías dar las gracias."
  },
  AvgCommunicate_134275_Option_16 = {
    Text = "Qué hiriente"
  },
  AvgCommunicate_134275_Option_3 = {
    Text = "¿Eso es todo?"
  },
  AvgCommunicate_134275_Option_6 = {Text = "..."},
  AvgCommunicate_134275_Option_9 = {
    Text = "¿Es posible que"
  },
  AvgCommunicate_134276_Content_1 = {
    Text = "¡Gracias, Guardián, gracias! Yo... no sé cómo expresarlo..."
  },
  AvgCommunicate_134276_Content_10 = {
    Text = "¿Algo así?"
  },
  AvgCommunicate_134276_Content_11 = {
    Text = "He oído que los colores transmiten diferentes emociones y atmósferas dentro de una pintura. Podrías crear nuevos colores según tu propia visión creativa."
  },
  AvgCommunicate_134276_Content_12 = {
    Text = "¡Oh! ¡¡Ohhh!! ¡Mezclar combinaciones de colores completamente nuevas a mi antojo!"
  },
  AvgCommunicate_134276_Content_13 = {
    Text = "¡Qué idea tan genial! Diferentes polarizaciones... diferentes texturas... ¡Ya tengo tantas ideas!"
  },
  AvgCommunicate_134276_Content_14 = {
    Text = "¡Disculpa, Guardián!"
  },
  AvgCommunicate_134276_Content_15 = {
    Text = "Tengo el presentimiento de que mi próxima pintura poseerá pinceladas aún más maravillosas."
  },
  AvgCommunicate_134276_Content_16 = {
    Text = "Quizás realmente pueda crear un reino pintado que conecte con lo desconocido. Cuando llegue ese momento, ¡definitivamente serás la primera persona en verlo!"
  },
  AvgCommunicate_134276_Content_2 = {
    Text = "Gracias por darme la oportunidad de ver la verdad real del mundo— las leyes supremas del universo, el color base en el lienzo de la realidad..."
  },
  AvgCommunicate_134276_Content_3 = {
    Text = "Ah, es tan hermoso... ¿Cómo podría mezclar un color así?"
  },
  AvgCommunicate_134276_Content_4 = {
    Text = "¿Cristal arcoíris? ¿Mithril? ¿Nácar? ¿Polvo de gusano de cristal? ¿Alas de mariposa luminosa?"
  },
  AvgCommunicate_134276_Content_5 = {
    Text = "No, no, no... Eso no se puede replicar con materiales tan mundanos y ordinarios. Piensa más, necesito pensar más..."
  },
  AvgCommunicate_134276_Content_6 = {
    Text = "¿Pickman? Parece que ya te has perdido en tu propio arte..."
  },
  AvgCommunicate_134276_Content_7 = {
    Text = "Shh, ¿cómo crees que es el verdadero color del universo? ¡Alguien tan especial como tú debe poder concederme una Inspiración única!"
  },
  AvgCommunicate_134276_Content_8 = {
    Text = "Creo que el mundo podría verse diferente a través de los ojos de cada persona."
  },
  AvgCommunicate_134276_Content_9 = {
    Text = "¡Oh! Quieres decir... seguir mi propio corazón... seguir mis sentimientos, y pintar los diferentes colores del universo..."
  },
  AvgCommunicate_134276_Option_10 = {Text = "Quizás"},
  AvgCommunicate_134276_Option_8 = {Text = "Creo"},
  AvgCommunicate_134277_Content_1 = {
    Text = "Guardián—"
  },
  AvgCommunicate_134277_Content_10 = {
    Text = "No te tendré lástima, no asumiré con condescendencia tu lógica de comportamiento. Solo espero que te diviertas en este mundo."
  },
  AvgCommunicate_134277_Content_11 = {Text = "..."},
  AvgCommunicate_134277_Content_12 = {
    Text = "Vaya, ¿quién de nosotros está más loco aquí? ¿Por una razón así, le entregarías este nivel de Fortaleza a una lunática como yo?"
  },
  AvgCommunicate_134277_Content_13 = {
    Text = "¿Será posible que mi llegada a este mundo fuera un arreglo del Destino?"
  },
  AvgCommunicate_134277_Content_15 = {
    Text = "En fin, gracias a ti, he tocado lo que me pertenece en tu mundo: mi \"límite\"."
  },
  AvgCommunicate_134277_Content_16 = {
    Text = "¡Ahora pues, date prisa y asígname una misión! No puedo esperar para ir a cortar unas cuantas cabezas y mostrarte lo que puedo hacer～"
  },
  AvgCommunicate_134277_Content_2 = {
    Text = "Una chica varada en un mundo extraño recibe un regalo costoso que puede hacerla más fuerte. ¿Sabes a qué suena eso?"
  },
  AvgCommunicate_134277_Content_3 = {
    Text = "Antes de que digas algo que se desvíe de los procesos de pensamiento humanos normales, déjame aclarar primero: eres miembro de Misaq. Nos ayudamos mutuamente. Por eso te di esos materiales."
  },
  AvgCommunicate_134277_Content_4 = {
    Text = "¿En serio? ¿No es uno de esos aburridos y rebuscados comportamientos socializados de fachada humana?"
  },
  AvgCommunicate_134277_Content_5 = {
    Text = "\"No puede volver a casa, qué lástima, mostrémosle un poco más de cariño.\""
  },
  AvgCommunicate_134277_Content_6 = {
    Text = "\"Debe ser tan difícil resolver las cosas sola, démosle un empujón.\" ¿De verdad no es una de esas razones de alta frecuencia que encontrarías en una sociedad ordinaria?"
  },
  AvgCommunicate_134277_Content_7 = {
    Text = "En primer lugar, ¡se mire como se mire, Mouchette, no tienes nada que ver con la palabra \"ordinaria\"!"
  },
  AvgCommunicate_134277_Content_8 = {
    Text = "Hmph☆hmph, esa sí que es una valoración que me gusta bastante."
  },
  AvgCommunicate_134277_Content_9 = {
    Text = "Segundo, sin importar cuál sea tu autopercepción o lo que aparentes ser en la superficie, para mí, como tú misma dijiste, \"Mouchette\" es \"Mouchette\"."
  },
  AvgCommunicate_134277_Option_7 = {
    Text = "En primer lugar"
  },
  AvgCommunicate_134278_Content_1 = {
    Text = "Gracias, querido. Me has traído tanta felicidad y me has permitido mantener mi ambición por siempre."
  },
  AvgCommunicate_134278_Content_10 = {
    Text = "Cualquier forma de gratitud que desees, puedo hacerla realidad."
  },
  AvgCommunicate_134278_Content_11 = {
    Text = "Incluso si aún no lo poseo, incluso si fueran las Estrellas y la Luna, encontraría la manera de traértelos."
  },
  AvgCommunicate_134278_Content_12 = {
    Text = "¿Lo que yo elija? ¿Cualquier cosa?"
  },
  AvgCommunicate_134278_Content_13 = {
    Text = "Cumplir la palabra es un salvoconducto indispensable en el mundo de la fama y la fortuna."
  },
  AvgCommunicate_134278_Content_14 = {
    Text = "Pues bien, me gustaría que la Señora me hiciera una promesa. En cuanto a los detalles, necesitaré algo más de tiempo para pensarlo."
  },
  AvgCommunicate_134278_Content_15 = {Text = "..."},
  AvgCommunicate_134278_Content_16 = {
    Text = "Jajajaja, qué elección tan astuta. Me gustas cada vez más."
  },
  AvgCommunicate_134278_Content_17 = {
    Text = "Por supuesto, querido/a. Tienes todo el tiempo del mundo para pensarlo."
  },
  AvgCommunicate_134278_Content_18 = {
    Text = "Si tienes tiempo, ¿por qué no vienes a mi finca esta noche? Quizás, cuando estemos solos los dos... te resulte más fácil dar con una \"buena idea\" refrescante."
  },
  AvgCommunicate_134278_Content_2 = {
    Text = "Servirla, mi señora, es un placer."
  },
  AvgCommunicate_134278_Content_3 = {
    Text = "Jeje, sensato, inteligente, valiente, leal, y con el toque justo de... belleza."
  },
  AvgCommunicate_134278_Content_4 = {
    Text = "¿Quién podría decir que no eres un perfecto...?"
  },
  AvgCommunicate_134278_Content_5 = {
    Text = "...¿Perfecto qué?"
  },
  AvgCommunicate_134278_Content_6 = {
    Text = "¿Pareces un poco nervioso?"
  },
  AvgCommunicate_134278_Content_7 = {
    Text = "Mi señora siempre lo deja a uno sin palabras."
  },
  AvgCommunicate_134278_Content_8 = {
    Text = "Algunas cosas no necesitan expresarse con palabras. Tus sentimientos durante todo este tiempo... los he recibido todos."
  },
  AvgCommunicate_134278_Content_9 = {
    Text = "Tierras, propiedades, tesoros raros, arte, y la oportunidad de conocer a tantas estrellas... con mi poder actual, todo está a mi alcance."
  },
  AvgCommunicate_134278_Option_12 = {
    Text = "¿De verdad, cualquier cosa?"
  },
  AvgCommunicate_134278_Option_14 = {
    Text = "Me gustaría una promesa suya, Señora."
  },
  AvgCommunicate_134278_Option_2 = {
    Text = "Es un placer"
  },
  AvgCommunicate_134278_Option_5 = {
    Text = "¿Perfecto?"
  },
  AvgCommunicate_134278_Option_7 = {Text = "..."},
  AvgCommunicate_134279_Content_1 = {
    Text = "Guardián, ¿sigues despierto?"
  },
  AvgCommunicate_134279_Content_10 = {
    Text = "Pero todo lo que has vertido en mí... ha convergido en un nuevo lago dentro de mí. Una incluso más vasto que ese mar."
  },
  AvgCommunicate_134279_Content_11 = {
    Text = "Me dijo: ya no hay necesidad de tener miedo."
  },
  AvgCommunicate_134279_Content_12 = {
    Text = "Entiendo que el dolor quizá nunca se deshaga por completo, pero sin importar cuántas veces haga falta, siempre te traeré de vuelta a la orilla."
  },
  AvgCommunicate_134279_Content_13 = {
    Text = "...Si mamá y papá pudieran oírte decir eso, estoy segura de que se sentirían en paz."
  },
  AvgCommunicate_134279_Content_14 = {
    Text = "Creo que... quizás están en algún lugar de ese mar, observando en quién me he convertido."
  },
  AvgCommunicate_134279_Content_15 = {
    Text = "De ahora en adelante, empuñaré esta Fuerza que se me ha otorgado y me convertiré en la marea que sirva como tu Guardián."
  },
  AvgCommunicate_134279_Content_16 = {
    Text = "Quizás... ¿estarías dispuesto/a a concederme una petición más atrevida?"
  },
  AvgCommunicate_134279_Content_17 = {
    Text = "¿Qué es? Solo que sea algo que pueda hacer, con gusto lo haré."
  },
  AvgCommunicate_134279_Content_18 = {
    Text = "Cuando el cielo se despeje, por favor, pasea conmigo junto al mar."
  },
  AvgCommunicate_134279_Content_19 = {
    Text = "Hay tanto que quiero contarte. Solo una tarde es todo lo que pido."
  },
  AvgCommunicate_134279_Content_2 = {
    Text = "Perdona si estoy interrumpiendo tu Descansar..."
  },
  AvgCommunicate_134279_Content_20 = {
    Text = "Por supuesto, no hay problema. Lo prometo."
  },
  AvgCommunicate_134279_Content_3 = {
    Text = "No, aún estoy despierto. ¿Qué ocurre?"
  },
  AvgCommunicate_134279_Content_4 = {
    Text = "Después de recibir tu regalo, caí en un profundo sueño y me sumergí en un Sueño. Soñé con aquel océano de antes, y con el atardecer fuera del Sanatorio."
  },
  AvgCommunicate_134279_Content_5 = {
    Text = "Pero esta vez... no caminé hacia el mar."
  },
  AvgCommunicate_134279_Content_6 = {
    Text = "Me quedé en la orilla, contemplando ese mar. Aún me llenaba de una sensación de paz, pero no tenía deseo alguno de avanzar."
  },
  AvgCommunicate_134279_Content_7 = {
    Text = "Si no es presuntuoso adivinar... ¿es porque esta vez tenías una razón para quedarte?"
  },
  AvgCommunicate_134279_Content_8 = {Text = "Bien."},
  AvgCommunicate_134279_Content_9 = {
    Text = "Una vez fui aplastada por el dolor. Nada podía lavar la pesadez alojada en mi garganta... nada excepto el océano, que arrastra y abraza todo."
  },
  AvgCommunicate_134279_Option_12 = {
    Text = "Nymphaea..."
  },
  AvgCommunicate_134279_Option_17 = {Text = "¿Qué?"},
  AvgCommunicate_134279_Option_7 = {Text = "Porque..."},
  AvgCommunicate_134280_Content_1 = {
    Text = "%player%, anoche tuve ese sueño otra vez."
  },
  AvgCommunicate_134280_Content_10 = {
    Text = "Quizás fue el Efecto de la Regla final."
  },
  AvgCommunicate_134280_Content_11 = {
    Text = "Sí, así que quiero decir—en nombre de todos los \"24\", gracias, %player%."
  },
  AvgCommunicate_134280_Content_12 = {
    Text = "Gracias por permitirnos escucharnos, vernos, comprendernos y aceptarnos mutuamente."
  },
  AvgCommunicate_134280_Content_13 = {
    Text = "Eso no fue obra mía."
  },
  AvgCommunicate_134280_Content_14 = {
    Text = "No, la guía y el consuelo que brindaste apaciguaron a todos los espíritus inquietos."
  },
  AvgCommunicate_134280_Content_15 = {
    Text = "Fue tu presencia la que hizo que todos los ríos convergieran en uno solo."
  },
  AvgCommunicate_134280_Content_16 = {
    Text = "\"Yo\" — todos nosotros — jamás olvidaremos tu amabilidad."
  },
  AvgCommunicate_134280_Content_2 = {
    Text = "Parecía haber regresado al pie de las montañas nevadas del lejano norte, dentro de una caverna completamente oscura."
  },
  AvgCommunicate_134280_Content_3 = {
    Text = "Incontables masas de limo, reflejando incontables sombras de \"24\"..."
  },
  AvgCommunicate_134280_Content_4 = {
    Text = "Esos... son todos tú, todos son parte de ti."
  },
  AvgCommunicate_134280_Content_5 = {Text = "Sé."},
  AvgCommunicate_134280_Content_6 = {
    Text = "En medio del Caos, me pareció escuchar a alguien decirme algo."
  },
  AvgCommunicate_134280_Content_7 = {
    Text = "La voz era difusa. No pude distinguirla con claridad..."
  },
  AvgCommunicate_134280_Content_8 = {
    Text = "Pero después de que esa persona se fue, sentí que todo el clamor a mi alrededor se asentó en calma."
  },
  AvgCommunicate_134280_Content_9 = {
    Text = "Los susurros ruidosos en mis oídos se volvieron armoniosos y naturales, como si fueran una melodía concordante..."
  },
  AvgCommunicate_134280_Option_4 = {
    Text = "Todos son tú."
  },
  AvgCommunicate_134281_Content_1 = {
    Text = "Guardián, ¿crees en el Destino?"
  },
  AvgCommunicate_134281_Content_10 = {
    Text = "...Como persona corriente, apenas puedo imaginar lo genial que se siente. Permíteme preguntar entre dientes: ¿qué se siente exactamente?"
  },
  AvgCommunicate_134281_Content_11 = {
    Text = "¿Cómo describirlo? Por ejemplo, ahora mismo tengo un poco de hambre..."
  },
  AvgCommunicate_134281_Content_12 = {
    Text = "¿? ¿Y luego?"
  },
  AvgCommunicate_134281_Content_13 = {
    Text = "Oh, perdón por la espera. Alguien acaba de llamar a la puerta: era la señorita Mason compartiendo un bizcocho recién horneado."
  },
  AvgCommunicate_134281_Content_14 = {Text = "¿¿¿???"},
  AvgCommunicate_134281_Content_15 = {
    Text = "Solo así. Y luego... tengo un poco de sed."
  },
  AvgCommunicate_134281_Content_16 = {
    Text = "¿Hm? El mayordomo del Sr. Doresain acaba de traer una invitación, diciendo que le gustaría invitarme a una Degustación de su Colección de vino tinto almacenada en un restaurante cercano."
  },
  AvgCommunicate_134281_Content_17 = {
    Text = "...Suficiente. La próxima vez, ¿podrías sentir sinceramente ganas de ayudarme con mis deberes?"
  },
  AvgCommunicate_134281_Content_18 = {
    Text = "Jajaja, como desees, %player%. Ahora eres mi mayor mecenas, patrocinador, socio e indispensable {Male=Mr.,Female=Miss} Watson."
  },
  AvgCommunicate_134281_Content_19 = {
    Text = "El Detective Afortunado, encantado de servir."
  },
  AvgCommunicate_134281_Content_2 = {
    Text = "Yo creo en el Destino, y creo que poseo el Destino más afortunado de todos."
  },
  AvgCommunicate_134281_Content_3 = {
    Text = "Alegrías inesperadas, ganancias imprevistas, bendiciones caídas del cielo — cuando estas cosas me suceden de repente, ya ni siquiera pestañeo."
  },
  AvgCommunicate_134281_Content_4 = {
    Text = "Una vez que te acostumbras al favor del Destino, todas las gratas sorpresas se vuelven insignificantes."
  },
  AvgCommunicate_134281_Content_5 = {
    Text = "Lo que acabas de decir es realmente tan envidiable como irritante."
  },
  AvgCommunicate_134281_Content_6 = {
    Text = "Espera, aún no he terminado. Conocerte es lo más afortunado entre todas mis fortunas."
  },
  AvgCommunicate_134281_Content_7 = {
    Text = "Lo que me das siempre trae nuevas sorpresas."
  },
  AvgCommunicate_134281_Content_8 = {
    Text = "Como ahora mismo — la Fortaleza que surgió con la Aparición tras comprender la Regla final ya me permite percibir con claridad cada golpe de buena suerte antes de que llegue."
  },
  AvgCommunicate_134281_Content_9 = {
    Text = "Las cosas afortunadas caen como gotas de lluvia — de una llovizna suave, ¡fush! — a un aguacero torrencial."
  },
  AvgCommunicate_134281_Option_10 = {
    Text = "¿Qué se siente?"
  },
  AvgCommunicate_134281_Option_14 = {
    Text = "<Yellow:%player%>"
  },
  AvgCommunicate_134281_Option_5 = {
    Text = "Eso es tan envidiable como irritante"
  },
  AvgCommunicate_137645_Content_1 = {Text = "Guardián."},
  AvgCommunicate_137645_Content_10 = {
    Text = "Pero con tantas patas, ¿no es un poco injusto que participes en una carrera..."
  },
  AvgCommunicate_137645_Content_11 = {
    Text = "Castor tiene alas, y Nautila también trajo Su vehículo."
  },
  AvgCommunicate_137645_Content_12 = {
    Text = "Normalmente tejo en el teatro y no soy hábil en los deportes. Sin embargo, ya he inscrito a mi Doncella."
  },
  AvgCommunicate_137645_Content_13 = {
    Text = "Es difícil imaginar por qué te interesaría algo así."
  },
  AvgCommunicate_137645_Content_14 = {
    Text = "Ver a las personas revelar una vitalidad tan vibrante y una voluntad tan tenaz en la búsqueda de un objetivo es verdaderamente algo delicioso."
  },
  AvgCommunicate_137645_Content_15 = {
    Text = "Además... me genera bastante curiosidad saber qué clase de magia posee ese pastel ofrecido como premio, para tener incluso a Tawil tan cautivado por él."
  },
  AvgCommunicate_137645_Content_16 = {
    Text = "Solo no sea algún tipo de elección que destruya un mundo, cualquier cosa vale..."
  },
  AvgCommunicate_137645_Content_17 = {
    Text = "Eh, no usarías los Hilos del destino para manipular los resultados de la competición, ¿verdad?"
  },
  AvgCommunicate_137645_Content_18 = {
    Text = "...¿Arachne?"
  },
  AvgCommunicate_137645_Content_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_137645_Content_20 = {
    Text = "Nos vemos en el Público, Guardián."
  },
  AvgCommunicate_137645_Content_3 = {
    Text = "¿Crees tú... qué tipo de Destino puede considerarse verdaderamente justo y correcto?"
  },
  AvgCommunicate_137645_Content_4 = {
    Text = "¿Justo y correcto?... Probablemente proteger los intereses de la mayoría en la mayor medida posible."
  },
  AvgCommunicate_137645_Content_5 = {
    Text = "Entonces, ¿y si — los intereses de unos pocos están destinados a ser Sacrificados? ¿Apruebas esa dirección del Destino, verdad?"
  },
  AvgCommunicate_137645_Content_6 = {
    Text = "Tú... ¿por qué preguntas esto de repente? ¡No malinterpretes lo que quiero decir!"
  },
  AvgCommunicate_137645_Content_7 = {
    Text = "Si estás a punto de hacer algo como destruir algún mundo de nuevo, por favor, piénsalo bien, ¡Arachne!"
  },
  AvgCommunicate_137645_Content_8 = {
    Text = "No hay de qué preocuparse, Guardián. Es Solo una carrera."
  },
  AvgCommunicate_137645_Content_9 = {
    Text = "Uf... me asustaste..."
  },
  AvgCommunicate_137645_Option_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_137646_Content_1 = {
    Text = "Guardián, al enterarme de que viajarías lejos para una investigación, compuse especialmente una obra para ti."
  },
  AvgCommunicate_137646_Content_10 = {
    Text = "Tu sentido para los nombres es realmente algo especial, Arachne..."
  },
  AvgCommunicate_137646_Content_11 = {
    Text = "Cada hilo hilado tiene su dueño predestinado. Cada historia, también, tiene su lector."
  },
  AvgCommunicate_137646_Content_12 = {
    Text = "Un nombre que se difunda fácilmente puede ayudar a que estas excelentes historias lleguen a más de las personas a quienes están destinadas."
  },
  AvgCommunicate_137646_Content_13 = {
    Text = "Por ejemplo, esta obra más vendida..."
  },
  AvgCommunicate_137646_Content_14 = {
    Text = "\"Guía de cocina de criaturas de Aequor\"? ¿La más vendida?"
  },
  AvgCommunicate_137646_Content_15 = {
    Text = "No me digas que Doresain compró un ejemplar para cada persona en Necrovia..."
  },
  AvgCommunicate_137646_Content_16 = {
    Text = "¿Tulu sabe algo de esto?"
  },
  AvgCommunicate_137646_Content_18 = {
    Text = "Es precisamente esta aguda perspicacia sobre el corazón humano y el Destino lo que hace que te admire de verdad."
  },
  AvgCommunicate_137646_Content_19 = {
    Text = "\"Todos aman al Guardián\"."
  },
  AvgCommunicate_137646_Content_2 = {
    Text = "Originalmente quería representar una obra de teatro para ti, pero considerando la portabilidad, la escribí como novela en su lugar."
  },
  AvgCommunicate_137646_Content_20 = {
    Text = "Por favor, lleva esta obra contigo al Partir."
  },
  AvgCommunicate_137646_Content_3 = {Text = "Eso es..."},
  AvgCommunicate_137646_Content_4 = {
    Text = "\"El Gran Guardián\"? \"La Odisea del Guardián\"? \"El Mundo del Guardián\"?"
  },
  AvgCommunicate_137646_Content_5 = {
    Text = "¡¿Qué es lo que sueles escribir!? ¿¿¿Alguien realmente lee estas cosas???"
  },
  AvgCommunicate_137646_Content_6 = {
    Text = "No subestimes tu popularidad en Misaq. Todas estas son obras extremadamente populares."
  },
  AvgCommunicate_137646_Content_7 = {
    Text = "Un Destino tan dramático naturalmente merece ser mostrado al mundo."
  },
  AvgCommunicate_137646_Content_8 = {
    Text = "En realidad, no eres solo tú. También he tejido historias sobre los Destinos de otros."
  },
  AvgCommunicate_137646_Content_9 = {
    Text = "\"Cinco años en el campo de batalla, tres años de simulaciones\", \"Cuidados postnatales para ratones\", \"La gran exposición del arte del goteo de cera\"..."
  },
  AvgCommunicate_137646_Option_3 = {Text = "Eso es..."},
  AvgCommunicate_137647_Content_1 = {
    Text = "Conectando personas a través de diferentes tiempos y espacios con hilos invisibles..."
  },
  AvgCommunicate_137647_Content_10 = {
    Text = "Lo espero con ansias, Guardián."
  },
  AvgCommunicate_137647_Content_2 = {
    Text = "La civilización humana nunca deja de sorprenderme."
  },
  AvgCommunicate_137647_Content_3 = {
    Text = "¿Sorprender?"
  },
  AvgCommunicate_137647_Content_4 = {
    Text = "¿Pero acaso estos destinos no son elegidos por tu propia mano?"
  },
  AvgCommunicate_137647_Content_5 = {
    Text = "Lo que elijo es Solo la dirección. Toda la civilización y la Historia sigue siendo creada por vosotros mismos."
  },
  AvgCommunicate_137647_Content_6 = {
    Text = "Los Hilos del destino, extendiéndose de forma natural, acabarán por Gestar nuevas creaciones de origen desconocido."
  },
  AvgCommunicate_137647_Content_7 = {
    Text = "Es al testificar todo esto, con la alegría de este textil, que soy capaz de seguir llevando esta responsabilidad."
  },
  AvgCommunicate_137647_Content_8 = {Text = "Veo..."},
  AvgCommunicate_137647_Content_9 = {
    Text = "Si hay nuevas creaciones, permíteme apreciarlas también."
  },
  AvgCommunicate_137647_Option_3 = {
    Text = "¿Sorprender?"
  },
  AvgCommunicate_140194_Content_1 = {
    Text = "Algo se siente raro. El hecho de que nadie me tenga miedo en absoluto..."
  },
  AvgCommunicate_140194_Content_10 = {
    Text = "¡No te preocupes, todos han sido muy amables conmigo! ¡Están a salvo!"
  },
  AvgCommunicate_140194_Content_11 = {
    Text = "...Probablemente. Por ahora."
  },
  AvgCommunicate_140194_Content_12 = {
    Text = "¿Por ahora? ...¡Por favor, que sea algo definitivo!"
  },
  AvgCommunicate_140194_Content_13 = {
    Text = "¡Por ahora～!"
  },
  AvgCommunicate_140194_Content_2 = {
    Text = "Doll desarrolló una feromona especial. Ahora mismo, para todos no pareces más que una chica humana corriente."
  },
  AvgCommunicate_140194_Content_4 = {
    Text = "Conveniente, supongo, pero..."
  },
  AvgCommunicate_140194_Content_5 = {
    Text = "¿Es casi un poco decepcionante no poder asustar a la gente?"
  },
  AvgCommunicate_140194_Content_6 = {Text = "......?"},
  AvgCommunicate_140194_Content_7 = {
    Text = "¿Cómo lo digo... hmm... por ejemplo, va a hacer mi \"cacería\" más difícil..."
  },
  AvgCommunicate_140194_Content_8 = {
    Text = "No he tenido problemas para encontrar comida últimamente, así que cazar no es una necesidad urgente, pero... a veces... sí..."
  },
  AvgCommunicate_140194_Content_9 = {
    Text = "A estas alturas ya casi me he acostumbrado a que todos los Cuerpos Despertados digan cosas disparatadas, pero aun así tengo que decirte... ¡Eso es algo muy peligroso de decir!"
  },
  AvgCommunicate_140195_Content_1 = {
    Text = "Solicitud de compra"
  },
  AvgCommunicate_140195_Content_10 = {
    Text = "...Y yo simplemente fingiré no estar al tanto de nada de esto. ¿De acuerdo?"
  },
  AvgCommunicate_140195_Content_2 = {
    Text = "Cuatro refrigeradores domésticos grandes... El presupuesto de la universidad no está precisamente sobrado, pero ¿para qué necesitas estos refrigeradores?"
  },
  AvgCommunicate_140195_Content_3 = {
    Text = "Si no recuerdo mal, Saya, ya solicitaste que pusieran uno en tu dormitorio el primer día que te mudaste aquí."
  },
  AvgCommunicate_140195_Content_4 = {
    Text = "Bueno, em... Nunca se sabe cuándo va a hacer falta espacio en el refrigerador..."
  },
  AvgCommunicate_140195_Content_5 = {
    Text = "Además, ya sabes, la frescura de la carne es importante..."
  },
  AvgCommunicate_140195_Content_6 = {Text = "..."},
  AvgCommunicate_140195_Content_7 = {
    Text = "Lo siento, pero no puedo aprobar más refrigeradores. Sin embargo, te pasaré los contactos de Xu y Doresain."
  },
  AvgCommunicate_140195_Content_9 = {
    Text = "Creo que te lo pasarías muy bien hablando con ellos sobre comida y recetas."
  },
  AvgCommunicate_140196_Content_1 = {Text = "¥%&#...%"},
  AvgCommunicate_140196_Content_10 = {Text = "..."},
  AvgCommunicate_140196_Content_11 = {
    Text = "¡Incorrecto! ¡Se supone que debes decir Chof Chof!"
  },
  AvgCommunicate_140196_Content_12 = {
    Text = "Al parecer, la feromona que desarrolló la Profesora Doll no funciona con la Srta. Mosk."
  },
  AvgCommunicate_140196_Content_13 = {
    Text = "Pero aun así me trata igual que siempre. Su actitud no ha cambiado en absoluto."
  },
  AvgCommunicate_140196_Content_14 = {
    Text = "Creo que es porque, em, ¿cómo lo digo..."
  },
  AvgCommunicate_140196_Content_15 = {
    Text = "...¿Quizás Mosk simplemente tiene el don de... unas habilidades sociales extraordinarias?"
  },
  AvgCommunicate_140196_Content_2 = {
    Text = "A... Abandonar. Ah, otra palabra aprendida. Hmm."
  },
  AvgCommunicate_140196_Content_3 = {Text = "?"},
  AvgCommunicate_140196_Content_4 = {
    Text = "He estado estudiando todo tipo de idiomas últimamente. ...Es fascinante."
  },
  AvgCommunicate_140196_Content_6 = {
    Text = "Además del Idioma Leo estándar, también he aprendido mucho vocabulario nuevo. Por ejemplo..."
  },
  AvgCommunicate_140196_Content_7 = {Text = "¿Glu glu?"},
  AvgCommunicate_140196_Content_8 = {
    Text = "¡Plop! ¡Plop!"
  },
  AvgCommunicate_140196_Content_9 = {
    Text = "¡Correcto!"
  },
  AvgCommunicate_140196_Option_10 = {Text = "..."},
  AvgCommunicate_140196_Option_8 = {
    Text = "¡Plop! ¡Plop!"
  },
  AvgCommunicate_141374_Content_1 = {
    Text = "Un agradecimiento tan solemne quizás resulte algo distante, pero de todo corazón, gracias, por mí mismo y por todo Ebwynnos."
  },
  AvgCommunicate_141374_Content_10 = {
    Text = "Si muestro esas cualidades, es porque así soy por naturaleza."
  },
  AvgCommunicate_141374_Content_12 = {
    Text = "No digas eso con ese tono tan orgulloso."
  },
  AvgCommunicate_141374_Content_13 = {
    Text = "Así que ayudarme a alcanzar ese límite y liberarme de su control fue realmente un gran favor."
  },
  AvgCommunicate_141374_Content_14 = {
    Text = "Muchas cosas que antes eran difíciles de lograr ya no son un problema."
  },
  AvgCommunicate_141374_Content_15 = {
    Text = "¿Aún estoy a tiempo de recuperar lo que di?"
  },
  AvgCommunicate_141374_Content_16 = {
    Text = "Cálmate, Pontos, ¡Londinium tiene un sistema legal bien establecido!"
  },
  AvgCommunicate_141374_Content_2 = {
    Text = "Ponerse tan serio de repente resulta realmente un poco extraño."
  },
  AvgCommunicate_141374_Content_3 = {
    Text = "Probablemente no sabes lo que esto significa: antes de que yo fuera lo suficientemente poderoso, Ebwynnos en realidad nunca pudo escapar del control de esa antigua presencia."
  },
  AvgCommunicate_141374_Content_4 = {
    Text = "Este es el trato que alcancé con Él. Por suerte, no alberga ninguna mala intención, e incluso podría decirse que es magnánimo."
  },
  AvgCommunicate_141374_Content_5 = {
    Text = "Sin embargo, Él no pertenece al mundo humano. Bajo su dominio, Ebwynnos se volvería aún más impredecible, y quienes viven en Ebwynnos tendrían una naturaleza aún más extrema."
  },
  AvgCommunicate_141374_Content_6 = {
    Text = "Dicho así, ¿acaso antes también eras así por la influencia de Él, y por eso eras tan, eh...?"
  },
  AvgCommunicate_141374_Content_7 = {
    Text = "Déjame adivinar, ¿quieres decir Paranoia, rencoroso o maniaco del control?"
  },
  AvgCommunicate_141374_Content_9 = {Text = "No."},
  AvgCommunicate_141374_Option_2 = {
    Text = "Es un poco extraño"
  },
  AvgCommunicate_141374_Option_6 = {Text = "¿Acaso..."},
  AvgCommunicate_143429_Content_1 = {
    Text = "Aunque estos seguidores de culto que adoran a falsos dioses son tan estúpidos que dan risa, hay que reconocer que algunos de ellos tienen bastante buen gusto."
  },
  AvgCommunicate_143429_Content_10 = {
    Text = "¡Además, ni siquiera corresponden a la época correcta!"
  },
  AvgCommunicate_143429_Content_11 = {
    Text = "Yo creo que si te dejaras influir más por ese tipo de cosas y desarrollaras más ambición, quizás reduciría considerablemente la cantidad de veces que necesitas pedir rescate durante las misiones externas."
  },
  AvgCommunicate_143429_Content_12 = {
    Text = "Por supuesto, si me llamas tío un poco más a menudo, estaré encantado de seguir cubriendo las espaldas de los pequeños sin ambición."
  },
  AvgCommunicate_143429_Content_13 = {
    Text = "...Voy a hablar con Goliath ahora mismo."
  },
  AvgCommunicate_143429_Content_14 = {
    Text = "¡Voy a añadirlas a la lista de películas prohibidas de Misaq, y que no se le ocurra recomendárselas a nadie más!"
  },
  AvgCommunicate_143429_Content_2 = {
    Text = "Hace unos días, cuando se ausentaba frecuentemente de Misaq a espaldas de Miryam, ya me quedé bastante sorprendida..."
  },
  AvgCommunicate_143429_Content_3 = {
    Text = "No estarás hablando de Goliath, ¿verdad?..."
  },
  AvgCommunicate_143429_Content_4 = {
    Text = "Bueno, en primer lugar, admiro su determinación de someterse a otros con tal de alcanzar sus propios objetivos."
  },
  AvgCommunicate_143429_Content_5 = {
    Text = "En segundo lugar, las obras que recomendó son realmente muy interesantes."
  },
  AvgCommunicate_143429_Content_6 = {
    Text = "Es difícil imaginar que Goliath frecuente el teatro."
  },
  AvgCommunicate_143429_Content_7 = {
    Text = "Me recomendó <Italic:Érase una vez en Leonia> y <Italic:El Pa▼drino> — a todos les encantaron."
  },
  AvgCommunicate_143429_Content_8 = {
    Text = "Esta noche, Ebwynnos debería estrenar \"El lobo de Lentinién\"."
  },
  AvgCommunicate_143429_Content_9 = {
    Text = "No, espera un momento, ¡Misaq no permite que aparezcan jefes de bandas criminales, ni tampoco esa cultura del lobo!"
  },
  AvgCommunicate_143429_Option_2 = {
    Text = "¿No te referirás a..."
  },
  AvgCommunicate_143430_Content_1 = {
    Text = "La sexta solicitud de traslado de residencia este mes, parece que las normas de la oficina escolar tampoco funcionan siempre."
  },
  AvgCommunicate_143430_Content_10 = {
    Text = "Ah, qué lástima."
  },
  AvgCommunicate_143430_Content_11 = {
    Text = "¿Eh?? ¡¿Eh?! ¿Por qué hay una pesadilla que sacó un juego de respuestas del examen y se sentó a empezar a escribir mi tesis?"
  },
  AvgCommunicate_143430_Content_12 = {
    Text = "Cargas con demasiado peso, aunque solo lo hayas dicho en broma, eso demuestra que deberías Relajarte un poco, pequeño."
  },
  AvgCommunicate_143430_Content_13 = {
    Text = "Solo esta vez, aunque me alegra hacerlo, intentaré no convertirme en ese tipo de padre que malcría a sus hijos."
  },
  AvgCommunicate_143430_Content_14 = {
    Text = "Ahora, abre la ventana, te llevaré a divertirte esta noche, a experimentar la diversión de olvidar la realidad sin necesidad de ir a Ebwynnos."
  },
  AvgCommunicate_143430_Content_15 = {
    Text = "......¡Genial!"
  },
  AvgCommunicate_143430_Content_3 = {
    Text = "Promedio de calificaciones, asistencia, tasa de conversión de práctica efectiva, eh, y la presión laboral que existe para la mayoría de los estudiantes ordinarios aunque no para los Guardianes."
  },
  AvgCommunicate_143430_Content_4 = {
    Text = "Incluso con la Disolución a la vuelta de la esquina, los problemas de la realidad siguen siendo aterradoramente intimidantes."
  },
  AvgCommunicate_143430_Content_5 = {
    Text = "Es normal que todos quieran escapar de la realidad, ¿por qué no me llevas también a Ebwynnos...?"
  },
  AvgCommunicate_143430_Content_6 = {
    Text = "¿Hablas en serio?"
  },
  AvgCommunicate_143430_Content_7 = {
    Text = "Si afuera de la ventana realmente hay un sonido de alas batiendo, o si llevo tres noches seguidas estudiando y estoy teniendo alucinaciones."
  },
  AvgCommunicate_143430_Content_8 = {
    Text = "La oportunidad hace al ladrón, con una oportunidad tan buena, aunque después todo Misaq viniera a buscarme problemas, estaría muy dispuesto a aceptar."
  },
  AvgCommunicate_143430_Content_9 = {
    Text = "Nonononono estaba bromeando por favor no hagas eso bajo ninguna circunstancia."
  },
  AvgCommunicate_143431_Content_1 = {
    Text = "¿Me buscabas?"
  },
  AvgCommunicate_143431_Content_10 = {
    Text = "Jajajajajaja, está bien, no pongas esa expresión."
  },
  AvgCommunicate_143431_Content_11 = {
    Text = "Conseguir su sello personal no es difícil, en cuanto a la dirección de la cena benéfica, ¿qué tal si la ponemos en Ebwynnos?"
  },
  AvgCommunicate_143431_Content_12 = {
    Text = "El siguiente paso sería que la policía nos arrestara a todos por invasión de propiedad privada."
  },
  AvgCommunicate_143431_Content_14 = {
    Text = "Está bien, qué lástima, Evadiré la situación por unos días."
  },
  AvgCommunicate_143431_Content_15 = {
    Text = "Cuando baje la guardia, quizás sería más interesante matarlo."
  },
  AvgCommunicate_143431_Content_16 = {Text = "¿¿¿!!!?"},
  AvgCommunicate_143431_Content_2 = {
    Text = "Eh, Pontos, ¿no considerarías volver a Ebwynnos por una temporada?"
  },
  AvgCommunicate_143431_Content_3 = {
    Text = "El profesor Dexter lleva exactamente dos meses sin venir a la escuela."
  },
  AvgCommunicate_143431_Content_4 = {
    Text = "Ja, esa cosa sucia y cobarde probablemente esté ahora mismo descargando su furia sobre algún desgraciado de sus subordinados."
  },
  AvgCommunicate_143431_Content_5 = {
    Text = "Tranquila, mientras no haya Regresado a su Origen, todavía no tiene la calificación para ser mi oponente."
  },
  AvgCommunicate_143431_Content_6 = {
    Text = "El problema es que hay un montón de documentos esperando su sello personal, ¡y el banquete benéfico de este año no sabe qué hacer! Conseguir que la directora Czort y la profesora Doll asistan a algo así es más difícil que hacer que vuelen Misaq por los aires."
  },
  AvgCommunicate_143431_Content_7 = {
    Text = "Si la profesora Sylvia lo preside, entonces habría que preocuparse por otras cosas..."
  },
  AvgCommunicate_143431_Content_8 = {
    Text = "Qué triste, pequeño, lo sé, en Misaq muchas personas te protegen y ya no me necesitas, y yo he hecho tanto por ti, incluso tú..."
  },
  AvgCommunicate_145234_Content_1 = {
    Text = "Se ha quedado en silencio."
  },
  AvgCommunicate_145234_Content_10 = {
    Text = "Entonces... ¿ya no quieres pelear?"
  },
  AvgCommunicate_145234_Content_11 = {
    Text = "Je, je, je, je..."
  },
  AvgCommunicate_145234_Content_12 = {
    Text = "Por supuesto que no."
  },
  AvgCommunicate_145234_Content_13 = {
    Text = "Ya no necesito el combate para callar a mi cuerpo, pero..."
  },
  AvgCommunicate_145234_Content_14 = {
    Text = "¡Ahora puedo usar mi fuerza con más libertad, y desafiar a quien quiera!"
  },
  AvgCommunicate_145234_Content_15 = {
    Text = "Creo que... te debo mi gratitud."
  },
  AvgCommunicate_145234_Content_16 = {
    Text = "Me llevaste a una cima que he anhelado durante mucho tiempo. Pero..."
  },
  AvgCommunicate_145234_Content_17 = {
    Text = "El camino de la fuerza no tiene fin. ¿Verdad, Guardián?"
  },
  AvgCommunicate_145234_Content_2 = {
    Text = "¿Silencio? ¿A qué te refieres?"
  },
  AvgCommunicate_145234_Content_3 = {
    Text = "Mi sangre ha dejado de hervir. Mis huesos, de doler. Mi hoja ya no ruge..."
  },
  AvgCommunicate_145234_Content_4 = {
    Text = "Desde el momento en que nací, nunca se detuvieron ni una sola vez."
  },
  AvgCommunicate_145234_Content_5 = {
    Text = "Ahora, todos están en silencio."
  },
  AvgCommunicate_145234_Content_6 = {
    Text = "¿Es eso algo malo?"
  },
  AvgCommunicate_145234_Content_7 = {
    Text = "¿Estás bien?"
  },
  AvgCommunicate_145234_Content_8 = {
    Text = "El ruido de antes... era solo hambre. Una desesperada comezón por no ser lo suficientemente fuerte, lo suficientemente rápido."
  },
  AvgCommunicate_145234_Content_9 = {
    Text = "Ahora ha desaparecido. Mi cuerpo se siente... saciado por primera vez."
  },
  AvgCommunicate_145234_Option_6 = {
    Text = "¿Es eso algo malo?"
  },
  AvgCommunicate_145234_Option_7 = {
    Text = "¿Estás bien?"
  },
  AvgCommunicate_146392_Content_1 = {
    Text = "¿Estás ahí?"
  },
  AvgCommunicate_146392_Content_10 = {
    Text = "Le pagué para que me dejara tomar el trabajo en su lugar."
  },
  AvgCommunicate_146392_Content_11 = {
    Text = "¿La encontraste?"
  },
  AvgCommunicate_146392_Content_12 = {
    Text = "La tengo justo enfrente. Durmiendo plácidamente."
  },
  AvgCommunicate_146392_Content_13 = {
    Text = "Estoy esperando a que despierte."
  },
  AvgCommunicate_146392_Content_14 = {
    Text = "...Tiene sentido."
  },
  AvgCommunicate_146392_Content_15 = {
    Text = "Déjame pensar en alguna forma de que pases el tiempo..."
  },
  AvgCommunicate_146392_Content_16 = {
    Text = "¡Oh, ya sé! Podrías..."
  },
  AvgCommunicate_146392_Content_17 = {
    Text = "Sus ojos están temblando… Está despertando."
  },
  AvgCommunicate_146392_Content_18 = {
    Text = "Tengo que irme."
  },
  AvgCommunicate_146392_Content_19 = {
    Text = "¿Oye? ¿Lotan?"
  },
  AvgCommunicate_146392_Content_2 = {Text = "?"},
  AvgCommunicate_146392_Content_3 = {
    Text = "¿Lotan? Pensé que no te interesaban estas cosas."
  },
  AvgCommunicate_146392_Content_4 = {
    Text = "Solo estoy aburrido. Probando este artilugio que me dio Doll."
  },
  AvgCommunicate_146392_Content_5 = {
    Text = "Podría ser útil algún día."
  },
  AvgCommunicate_146392_Content_6 = {
    Text = "¿Tú? ¿Aburrido?"
  },
  AvgCommunicate_146392_Content_7 = {
    Text = "Pensé que estabas peleando o buscando pelea."
  },
  AvgCommunicate_146392_Content_8 = {
    Text = "Hablando de eso, ¿dónde estás? No te he visto en días..."
  },
  AvgCommunicate_146392_Content_9 = {
    Text = "Escuché que Daffodil ha estado cazando alguna poderosa criatura antigua."
  },
  AvgCommunicate_146392_Option_14 = {
    Text = "...Tiene sentido."
  },
  AvgCommunicate_146392_Option_6 = {
    Text = "¿Tú? ¿Aburrido?"
  },
  AvgCommunicate_146393_Content_1 = {
    Text = "Cuernos. Dientes. Garras. Carne. Globos oculares. Tentáculos."
  },
  AvgCommunicate_146393_Content_10 = {
    Text = "Espero que tú también seas igual de duro."
  },
  AvgCommunicate_146393_Content_11 = {Text = "..."},
  AvgCommunicate_146393_Content_12 = {
    Text = "Vaya, gracias."
  },
  AvgCommunicate_146393_Content_2 = {Text = "Elige uno."},
  AvgCommunicate_146393_Content_3 = {
    Text = "¿Es algún tipo de juego de \"adivina qué te gustaría\"...?"
  },
  AvgCommunicate_146393_Content_4 = {
    Text = "Traje de vuelta al monstruo que maté la última vez."
  },
  AvgCommunicate_146393_Content_5 = {
    Text = "De todas formas no tenía dónde ponerlo, pensé que querrías un recuerdo."
  },
  AvgCommunicate_146393_Content_6 = {
    Text = "Ninguna de esas opciones suena atractiva..."
  },
  AvgCommunicate_146393_Content_7 = {
    Text = "¿Es raro que los quiera todos...?"
  },
  AvgCommunicate_146393_Content_8 = {
    Text = "Difícil elección... ¿por qué no eliges tú por mí?"
  },
  AvgCommunicate_146393_Content_9 = {
    Text = "El cuerno está bien. Aguantó tres golpes antes de romperse. Te va que ni pintado."
  },
  AvgCommunicate_146393_Option_6 = {
    Text = "Ninguna de esas opciones suena atractiva..."
  },
  AvgCommunicate_146393_Option_7 = {
    Text = "¿Es raro que los quiera todos...?"
  },
  AvgCommunicate_146394_Content_1 = {
    Text = "Tengo un problema."
  },
  AvgCommunicate_146394_Content_10 = {
    Text = "Me fui tres veces. Cada vez que lo hacía, empezaban a sacrificarse. Al parecer, creían que era algún tipo de prueba divina."
  },
  AvgCommunicate_146394_Content_11 = {
    Text = "Están todos locos."
  },
  AvgCommunicate_146394_Content_12 = {
    Text = "¿Y por qué volviste??"
  },
  AvgCommunicate_146394_Content_13 = {
    Text = "No saqué mi hoja de su cadáver."
  },
  AvgCommunicate_146394_Content_14 = {
    Text = "Ahora también la han consagrado."
  },
  AvgCommunicate_146394_Content_15 = {Text = "..."},
  AvgCommunicate_146394_Content_16 = {
    Text = "Necesito recuperar mi hoja sin que se suiciden en masa delante de mí."
  },
  AvgCommunicate_146394_Content_17 = {
    Text = "Tú entiendes a estas pequeñas criaturas débiles mejor que yo. Échame una mano."
  },
  AvgCommunicate_146394_Content_18 = {
    Text = "...Oye, ¿qué se supone que significa eso?!"
  },
  AvgCommunicate_146394_Content_2 = {
    Text = "¡Vaya, así que incluso tú te metes en líos a veces!"
  },
  AvgCommunicate_146394_Content_3 = {
    Text = "Me enteré de que había un gusano poderoso, así que lo maté."
  },
  AvgCommunicate_146394_Content_4 = {
    Text = "Después de que murió, la gente que llevaba mucho tiempo atrapada dentro del planeta bajo su enorme cuerpo salió arrastrándose."
  },
  AvgCommunicate_146394_Content_5 = {
    Text = "Me llamaron dios, me hicieron reverencias e incluso me construyeron una estatua dorada... horrible a más no poder."
  },
  AvgCommunicate_146394_Content_6 = {
    Text = "JAJAJAJAJAJA"
  },
  AvgCommunicate_146394_Content_7 = {
    Text = "Deja de reírte."
  },
  AvgCommunicate_146394_Content_8 = {
    Text = "¿Acaso no te gusta que te adoren?"
  },
  AvgCommunicate_146394_Content_9 = {
    Text = "¿Acaso no te gusta que te adoren?"
  },
  AvgCommunicate_146394_Option_6 = {Text = "JAJAJAJAJA"},
  AvgCommunicate_146394_Option_8 = {
    Text = "¿Por qué no te fuiste sin más?"
  },
  AvgCommunicate_146394_Option_9 = {
    Text = "¿Por qué no te fuiste sin más?"
  },
  AvgCommunicate_148438_Content_1 = {
    Text = "Supongo que ya lo sabes, ¿hmm?"
  },
  AvgCommunicate_148438_Content_10 = {
    Text = "Ji ji, ¡no le des tantas vueltas! Las personas que piensan demasiado se convierten en adultos aburridos y sin gracia~"
  },
  AvgCommunicate_148438_Content_11 = {
    Text = "Aunque, claro está, si el Gardian del secreto simplemente no puede evitar sentirse atraído por la Hada —si te encuentras siguiendo cada uno de mis pasos, día y noche, solo para ganarte mi verdadero afecto—, bueno, eso sería completamente comprensible~"
  },
  AvgCommunicate_148438_Content_12 = {Text = "Ugh..."},
  AvgCommunicate_148438_Content_13 = {
    Text = "Ya he dejado la manzana acaramelada más dulce de todas sobre el escritorio de tu dormitorio."
  },
  AvgCommunicate_148438_Content_14 = {
    Text = "Ahora debes, absolutamente debes, saborearla despacio, examinar cada bocado y disfrutarla tú solo~"
  },
  AvgCommunicate_148438_Content_2 = {
    Text = "¿Así que te tomaste todas esas molestias para conseguir un permiso de salida... solo para comprarle a Aigis, Ogier y Murphy unas manzanas acarameladas de edición limitada que dijeron que nunca habían probado?"
  },
  AvgCommunicate_148438_Content_3 = {
    Text = "Esos pequeños brib— ejem— esos devotos niños puede que no hayan pagado sus cuotas de membresía en su totalidad, pero desempeñan un papel absolutamente vital en la difusión de las bendiciones del Hada."
  },
  AvgCommunicate_148438_Content_4 = {
    Text = "Cuidar a mi rebaño para que difundan la buena palabra con aún más entusiasmo... pues bien, esa es solo una carga más que el Hada lleva sobre sus hombros~"
  },
  AvgCommunicate_148438_Content_5 = {
    Text = "Aunque esta vez tuvieras una buena razón, ¿por qué sigues cargándolo a MI cuenta...?"
  },
  AvgCommunicate_148438_Content_7 = {
    Text = "Oh, no te preocupes por los pequeños detalles~ Mira, los niños ya son verdaderos creyentes. Entonces, ¿cuándo vas a unirte a ellos por fin, hmm?"
  },
  AvgCommunicate_148438_Content_9 = {
    Text = "Sinceramente no puedo distinguir si de vez en cuando dejas escapar un atisbo de tu verdadero yo, o si eres simplemente una cebolla, ocultando eternamente tu verdadero objetivo bajo una capa más..."
  },
  AvgCommunicate_148439_Content_1 = {Text = "[Imagen]"},
  AvgCommunicate_148439_Content_10 = {
    Text = "[Imagen cargada correctamente]"
  },
  AvgCommunicate_148439_Content_11 = {Text = "[Imagen]"},
  AvgCommunicate_148439_Content_12 = {
    Text = "Qué... de verdad es una carta de disculpa..."
  },
  AvgCommunicate_148439_Content_13 = {
    Text = "Lo siento... Caraboo. No debí reaccionar así cuando por una vez estabas siendo sincera."
  },
  AvgCommunicate_148439_Content_14 = {
    Text = "Voy a retirar la queja que acabo de presentar ahora mismo. La que recomendaba dejarte en tierra... denegarte todas las solicitudes de salida... ¡Listo! He retirado cada queja que haya presentado contra ti."
  },
  AvgCommunicate_148439_Content_15 = {
    Text = "¡Maravilloso~ Jeje, Gardian del secreto! Creo que una vez que se retira una queja, no se puede presentar ninguna nueva contra el mismo Despertado durante todo un mes, ¿verdad?"
  },
  AvgCommunicate_148439_Content_17 = {
    Text = "Tengo un muy mal presentimiento sobre esto..."
  },
  AvgCommunicate_148439_Content_18 = {
    Text = "Oh, vamos, el Hada nunca sería tan descortés como para jugar con el sincero corazón de %player%~ Cada palabra de esa carta de disculpa era la pura verdad. Cuando regrese de mi salida, me aseguraré de traerte la manzana roja más dulce~"
  },
  AvgCommunicate_148439_Content_19 = {
    Text = "¡Espera! ¿Por qué acaba de venir Aigis a mí llorando, diciendo que aunque no tiene ni idea de qué hizo mal, espera que la perdone cuando vea la carta de disculpa?"
  },
  AvgCommunicate_148439_Content_2 = {
    Text = "Cargando..."
  },
  AvgCommunicate_148439_Content_20 = {
    Text = "¿Y que prometiste hacérsela llegar, pero que ella decidió disculparse en persona también para asegurarse de que no volviera a estar enfadada con ella?!"
  },
  AvgCommunicate_148439_Content_21 = {
    Text = "Oye, Caraboo. ¡¡CARABOO!!"
  },
  AvgCommunicate_148439_Content_3 = {Text = "?"},
  AvgCommunicate_148439_Content_4 = {
    Text = "Caraboo, ya has usado este truco una vez. Digas lo que digas, NO voy a abrir esta imagen."
  },
  AvgCommunicate_148439_Content_5 = {
    Text = "No, %player%... Lo he reflexionado de verdad. Tú, y todos en Misaq, han sido tan amables conmigo. Realmente no debería haber traído mis viejas costumbres a este hermoso lugar."
  },
  AvgCommunicate_148439_Content_6 = {
    Text = "Al fin y al cabo, nunca elegí convertirme en quien soy, no desde el principio."
  },
  AvgCommunicate_148439_Content_7 = {
    Text = "Así que me senté y te escribí una carta de disculpa como es debido, escrita a mano, cada palabra, con mi propia mano~ Pero mira tú por dónde, el Comunicador tuvo que fallar justo en ese momento..."
  },
  AvgCommunicate_148439_Content_8 = {
    Text = "Entiendo que no me creas. Solo... esperaré. El tiempo que haga falta para que vuelvas a confiar en mí..."
  },
  AvgCommunicate_148439_Content_9 = {
    Text = "...Ugh, ¿por qué me remuerde la conciencia ahora? En fin, de ninguna manera voy a..."
  },
  AvgCommunicate_148440_Content_1 = {Text = "[Imagen]"},
  AvgCommunicate_148440_Content_10 = {
    Text = "¿De qué hablas? ¡Como si fuera a devolverte algo!"
  },
  AvgCommunicate_148440_Content_11 = {Text = "Huh?"},
  AvgCommunicate_148440_Content_12 = {
    Text = "¿Ya ni siquiera finges?"
  },
  AvgCommunicate_148440_Content_13 = {
    Text = "Jejee. Servir al Hada es en sí mismo tu mayor honor. Te conducirá a un paraíso sin igual. Comparado con eso, la recompensa mundana apenas merece mención, por supuesto."
  },
  AvgCommunicate_148440_Content_14 = {
    Text = "¡Basta de todo eso! Si no transfieres el dinero pronto, el mapa se perderá para siempre..."
  },
  AvgCommunicate_148440_Content_16 = {
    Text = "Ya eché un vistazo a lo que me enviaste. Estaba claramente falsificado con alguna tecnología de Núcleo de plata de mala calidad..."
  },
  AvgCommunicate_148440_Content_17 = {
    Text = "¿Oh? ¿Lo abriste? Eso fue completamente tu propia decisión, ¿sabes?~ ¡Maravilloso! *El Hada recordará la ofrenda de %player% por siempre.*"
  },
  AvgCommunicate_148440_Content_18 = {
    Text = "Espera, ¿por qué me llega un aviso de que me acaban de descontar 1.000 Florins? ¡Ese es mi estipendio de trabajo de campo!"
  },
  AvgCommunicate_148440_Content_2 = {
    Text = "Cargando..."
  },
  AvgCommunicate_148440_Content_20 = {
    Text = "Tranquilo, tranquilo. Estás bastante bien de dinero, ¿verdad? Esta vez solo tomaré 200 Florins, como pago por la amable lección de que no deberías abrir enlaces desconocidos en tu comunicador. Agradece la misericordia del Hada, ¿hmm?"
  },
  AvgCommunicate_148440_Content_21 = {
    Text = "[Transferencia: 800 Leonian Florins]"
  },
  AvgCommunicate_148440_Content_3 = {
    Text = "[Imagen Corrupta]"
  },
  AvgCommunicate_148440_Content_4 = {
    Text = "...¿Qué enviaste?"
  },
  AvgCommunicate_148440_Content_5 = {Text = "¡Ay!"},
  AvgCommunicate_148440_Content_6 = {
    Text = "¡Estamos perdidos! Esa imagen contenía un mapa hacia el Este, obtenido con el sudor y las lágrimas de mis devotos seguidores... ¡y ahora el original se ha corrompido junto con ella! ¡Debe ser algún @2 maligno intentando impedirnos llegar al Este!"
  },
  AvgCommunicate_148440_Content_7 = {
    Text = "%player%, ¿cuántos Florins llevas encima? ¡Rápido, dámelos todos! Todavía hay una oportunidad de recuperarlo..."
  },
  AvgCommunicate_148440_Content_8 = {
    Text = "Déjame adivinar: me lo devolverás diez veces cuando llegues al Este. No nací ayer, ¿sabes?"
  },
  AvgCommunicate_148440_Content_9 = {
    Text = "Una estafa que no se adapta a los tiempos no tiene futuro."
  },
  AvgCommunicate_149803_Content_1 = {
    Text = "La misión de escolta que la academia me encomendó anteriormente ya ha concluido. ¿Hay algo que necesitéis que haga, mi señor?"
  },
  AvgCommunicate_149803_Content_10 = {
    Text = "En fin, si no quieres estar ociosa, en unos días habrá muchas actividades en la academia. ¿Te apetece ir a disfrutarlas?"
  },
  AvgCommunicate_149803_Content_11 = {
    Text = "...Si es una orden de mi señor, la obedeceré."
  },
  AvgCommunicate_149803_Content_12 = {
    Text = "Ahora voy a hacer la ronda."
  },
  AvgCommunicate_149803_Content_13 = {
    Text = "¡Espero que después realmente lo cumplas!"
  },
  AvgCommunicate_149803_Content_2 = {
    Text = "¿No piensas descansar un poco?"
  },
  AvgCommunicate_149803_Content_3 = {
    Text = "No es necesario."
  },
  AvgCommunicate_149803_Content_4 = {
    Text = "Además... no tengo derecho a disfrutar de semejante tranquilidad."
  },
  AvgCommunicate_149803_Content_5 = {
    Text = "Esa sombra oscura aún me perturba de vez en cuando al oído."
  },
  AvgCommunicate_149803_Content_6 = {
    Text = "Quizás cuando tengo trabajo entre manos, me siento más serena."
  },
  AvgCommunicate_149803_Content_7 = {
    Text = "Es todo, mi señor, no os preocupéis por ello."
  },
  AvgCommunicate_149803_Content_8 = {
    Text = "Quizás deba enseñarte la importancia de tomárselo con calma."
  },
  AvgCommunicate_149803_Content_9 = {
    Text = "Relajarse más permite combatir mejor."
  },
  AvgCommunicate_149803_Option_8 = {
    Text = "Quizás deba enseñarte la importancia de tomárselo con calma."
  },
  AvgCommunicate_149803_Option_9 = {
    Text = "Relajarse más permite combatir mejor."
  },
  AvgCommunicate_149950_Content_10 = {
    Text = "Hmm...... ¿te estás burlando de mí? ¡Este es el límite de lo que puedo controlar este cuerpo ahora mismo!"
  },
  AvgCommunicate_149950_Content_11 = {
    Text = "¿Qué pretendes hacer? ¿Seguir instigándolo y manipulándolo?"
  },
  AvgCommunicate_149950_Content_12 = {
    Text = "Si pudiera hacerlo, ya lo habría......"
  },
  AvgCommunicate_149950_Content_13 = {
    Text = "Bueno, en vez de convertirme en una hoja afilada, ser un escudo o una barrera tampoco parece tan malo......"
  },
  AvgCommunicate_149950_Content_14 = {
    Text = "En cuanto al señor en quien él confía y al que sirve —tú— tras este contacto, resultas bastante interesante."
  },
  AvgCommunicate_149950_Content_15 = {
    Text = "Ya lo entiendo, Ogier te ha influenciado a ti también, ¿verdad?"
  },
  AvgCommunicate_149950_Content_17 = {
    Text = "<Yellow:%player%>"
  },
  AvgCommunicate_149950_Content_18 = {
    Text = "Mi señor, lo siento mucho. Acabo de perder el conocimiento por unos minutos."
  },
  AvgCommunicate_149950_Content_19 = {
    Text = "Al volver en mí, vi que el comunicador estaba encendido."
  },
  AvgCommunicate_149950_Content_2 = {
    Text = "Por fin te veo......"
  },
  AvgCommunicate_149950_Content_20 = {
    Text = "Tengo la sensación de que, hace un momento, escuché de nuevo esa voz irritante después de tanto tiempo......"
  },
  AvgCommunicate_149950_Content_21 = {
    Text = "Cómo decirlo...... parece que tú y esa fuerza que llevas dentro ya podéis coexistir en bastante armonía."
  },
  AvgCommunicate_149950_Content_22 = {
    Text = "...... He leído el registro."
  },
  AvgCommunicate_149950_Content_23 = {
    Text = "Me preocupaba que Él fuera a decir palabras malvadas y agresivas como antes."
  },
  AvgCommunicate_149950_Content_24 = {
    Text = "Realmente sorprendente. Antes siempre era yo quien sufría Su erosión, pero ahora parece que se ha invertido."
  },
  AvgCommunicate_149950_Content_25 = {
    Text = "Supongo que es algo bueno. Al menos... eso significa que Lo he vencido por completo."
  },
  AvgCommunicate_149950_Content_26 = {
    Text = "Claro, ¿será acaso porque el poder de Ogier ha aumentado, que el dominio sobre esta entidad invisible ha podido alcanzar tal nivel?"
  },
  AvgCommunicate_149950_Content_27 = {
    Text = "Sí, seguramente es así. Sin duda, todos estos cambios han surgido gracias a vos."
  },
  AvgCommunicate_149950_Content_28 = {
    Text = "Además, para mí, la \"Ley Final\" que he comprendido no es solo poder..."
  },
  AvgCommunicate_149950_Content_29 = {
    Text = "También esta convicción de proteger a los demás arde en mi pecho con más fervor que nunca. Creo que ahí está la verdadera raíz de todo."
  },
  AvgCommunicate_149950_Content_3 = {
    Text = "No eres Ogier, ¿quién eres tú?"
  },
  AvgCommunicate_149950_Content_4 = {
    Text = "¡Devuelve el comunicador a su dueño!"
  },
  AvgCommunicate_149950_Content_5 = {
    Text = "Qué ridículo. Si no fuera por mi existencia, ¿cómo habría sobrevivido este niño, y cómo habría podido quedarse aquí como Despertado?"
  },
  AvgCommunicate_149950_Content_6 = {
    Text = "Tú eres...... ¿esa presencia invisible que se adhiere a él?"
  },
  AvgCommunicate_149950_Content_7 = {
    Text = "Exactamente. Vaya, Guardián del Secreto de Misaq, resulta que no me reconoces."
  },
  AvgCommunicate_149950_Content_8 = {
    Text = "Eh...... es que siempre has sido fuertemente reprimido por Ogier, así que nunca te había visto."
  },
  AvgCommunicate_149950_Option_3 = {
    Text = "No eres Ogier, ¿quién eres tú?"
  },
  AvgCommunicate_149950_Option_4 = {
    Text = "¡Devuelve el comunicador a su dueño!"
  },
  AvgCommunicate_149986_Content_1 = {
    Text = "Mi señor, he venido a hacerle una invitación."
  },
  AvgCommunicate_149986_Content_10 = {
    Text = "...Un árbol."
  },
  AvgCommunicate_149986_Content_11 = {Text = "Huh?"},
  AvgCommunicate_149986_Content_12 = {
    Text = "Quizás sea porque tengo entrenamiento profesional; sin importar cuánto caos haya, puedo mantenerme firme sobre el escenario."
  },
  AvgCommunicate_149986_Content_13 = {
    Text = "¡¿Qué demonios va a pasar en vuestra obra?!"
  },
  AvgCommunicate_149986_Content_14 = {
    Text = "No lo sé, yo solo soy un árbol."
  },
  AvgCommunicate_149986_Content_15 = {
    Text = "...Bueno, en la obra, Jenkin, que interpreta a la princesa, descenderá desde las alturas, y Lily, que interpreta al príncipe, tendrá que atraparla."
  },
  AvgCommunicate_149986_Content_16 = {
    Text = "Y Aigis, que interpreta al rey demonio, también bajará a interactuar con el público."
  },
  AvgCommunicate_149986_Content_17 = {
    Text = "Ya no tengo ganas de comentar nada sobre el reparto..."
  },
  AvgCommunicate_149986_Content_18 = {
    Text = "Pero, ¿no es eso un spoiler?"
  },
  AvgCommunicate_149986_Content_19 = {
    Text = "Porque no quiero ocultarle nada a usted."
  },
  AvgCommunicate_149986_Content_2 = {
    Text = "El club de teatro va a representar una obra de cuento de hadas, y han reunido a los Despertados menores de edad de Misaq para actuar juntos."
  },
  AvgCommunicate_149986_Content_20 = {
    Text = "Además, a juzgar por los ensayos, cada vez ocurren imprevistos distintos, así que tampoco puedo garantizar qué verá realmente mi señor."
  },
  AvgCommunicate_149986_Content_21 = {
    Text = "...Eso sí que despierta la curiosidad."
  },
  AvgCommunicate_149986_Content_22 = {
    Text = "Todas estas acciones durante la actuación conllevan cierto nivel de peligro."
  },
  AvgCommunicate_149986_Content_23 = {
    Text = "Por eso, mientras interpreto al árbol, debo estar atento a lo que ocurre tanto en el escenario como entre el público, para garantizar la seguridad de los actores y los espectadores."
  },
  AvgCommunicate_149986_Content_24 = {
    Text = "Así que en realidad fuiste a trabajar de guardaespaldas a tiempo parcial... Suena bastante agotador."
  },
  AvgCommunicate_149986_Content_25 = {
    Text = "Sí. En cualquier caso, no se preocupe. Mientras yo siga en el escenario, no permitiré que nadie más resulte herido."
  },
  AvgCommunicate_149986_Content_3 = {
    Text = "Es algo difícil de decir... yo también saldré al escenario. Espero que venga a verlo."
  },
  AvgCommunicate_149986_Content_4 = {
    Text = "¡Tengo muchas ganas de verlo!"
  },
  AvgCommunicate_149986_Content_5 = {
    Text = "Aunque, no esperaba que aceptaras participar en este tipo de actividad."
  },
  AvgCommunicate_149986_Content_6 = {
    Text = "Sí, ya no soy una niña, no es muy apropiado que participe en esto."
  },
  AvgCommunicate_149986_Content_7 = {
    Text = "Pero ellas insistieron..."
  },
  AvgCommunicate_149986_Content_8 = {
    Text = "No quería aguarles la fiesta y, además, me di cuenta de que este papel realmente solo podía interpretarlo yo."
  },
  AvgCommunicate_149986_Content_9 = {
    Text = "Entonces, ¿qué papel interpretará Ogier? ¿Un caballero?"
  },
  AvgCommunicate_149987_Content_1 = {
    Text = "Mi señor, ¿hay algún curso relacionado con el Phenómeno de erosión últimamente?"
  },
  AvgCommunicate_149987_Content_10 = {
    Text = "Qué estudioso... Si yo fuera tan dedicado como tú, seguro que tampoco tendría que preocuparme por los exámenes."
  },
  AvgCommunicate_149987_Content_11 = {
    Text = "Por favor, no me elogie así, las responsabilidades que usted carga son mucho más pesadas que las mías."
  },
  AvgCommunicate_149987_Content_12 = {
    Text = "Además, esto no es más que la tarea necesaria que debo hacer para expiar mis culpas."
  },
  AvgCommunicate_149987_Content_13 = {
    Text = "Pero aprendes muy rápido, quién sabe si Ogier tiene el potencial para convertirse en un erudito."
  },
  AvgCommunicate_149987_Content_14 = {
    Text = "Como todos piensan de pequeños, sobre el tema del futuro."
  },
  AvgCommunicate_149987_Content_15 = {
    Text = "¿Ogier ha pensado alguna vez en qué quiere hacer cuando sea mayor?"
  },
  AvgCommunicate_149987_Content_16 = {
    Text = "Usted sabe que ya me he convertido en un Despertado, así que ya no existe la posibilidad de crecer."
  },
  AvgCommunicate_149987_Content_17 = {
    Text = "¡Aun así puedes imaginar tus planes para el futuro! No seas tan pesimista."
  },
  AvgCommunicate_149987_Content_18 = {
    Text = "¿Ogier no tiene nada que quiera hacer más allá de \"proteger a los demás\"?"
  },
  AvgCommunicate_149987_Content_19 = {
    Text = "Gracias por sus palabras de aliento."
  },
  AvgCommunicate_149987_Content_2 = {
    Text = "Quiero profundizar más en el aprendizaje."
  },
  AvgCommunicate_149987_Content_20 = {
    Text = "En cuanto a otras cosas que quiera hacer... lo siento, realmente no se me ocurre nada."
  },
  AvgCommunicate_149987_Content_21 = {
    Text = "Cuando este cuerpo ya no esté manchado de pecado, entonces lo pensaré."
  },
  AvgCommunicate_149987_Content_3 = {
    Text = "Claro que sí, te llevaré conmigo después."
  },
  AvgCommunicate_149987_Content_4 = {
    Text = "Pero, ¿por qué Ogier quiere aprender sobre este tema de repente?"
  },
  AvgCommunicate_149987_Content_5 = {
    Text = "Porque hoy alguien me preguntó si el poder que me envuelve está relacionado con el D-Slime."
  },
  AvgCommunicate_149987_Content_6 = {
    Text = "Ya veo, si solo se mira la forma, realmente se parecen un poco."
  },
  AvgCommunicate_149987_Content_7 = {
    Text = "Sí, siempre me ha preocupado la naturaleza de esta entidad invisible. Quizás comprenderla lo suficiente me permita controlarla mejor."
  },
  AvgCommunicate_149987_Content_8 = {
    Text = "Aunque desde que llegué a Misaq me di cuenta de que hay muchas más existencias difíciles de comprender de lo que imaginaba..."
  },
  AvgCommunicate_149987_Content_9 = {
    Text = "Por eso decidí aprender más sobre todo lo relacionado con la corrosión, pues también es el enemigo contra el que mi señor ha luchado durante tanto tiempo."
  },
  AvgCommunicate_149988_Content_1 = {
    Text = "Ah, mi desobediente cachorrito, siempre corriendo salvajemente por el mundo."
  },
  AvgCommunicate_149988_Content_10 = {
    Text = "A nadie le importa tu William."
  },
  AvgCommunicate_149988_Content_11 = {
    Text = "Solo no olvides: eres mi cachorrito mascota personal. Cualquier amenaza a tu patética vida no es más que una pérdida de mis activos."
  },
  AvgCommunicate_149988_Content_12 = {
    Text = "Además, yo mismo elegí este mundo específico: una pequeña grieta, a salvo de la Disolución."
  },
  AvgCommunicate_149988_Content_13 = {
    Text = "Así que ten cuidado. Intenta no romperlo."
  },
  AvgCommunicate_149988_Content_2 = {
    Text = "Tu señal se está cortando de nuevo. ¿En qué páramo olvidado de Dios te has metido esta vez?"
  },
  AvgCommunicate_149988_Content_3 = {
    Text = "Estoy en el Continente del Norte Final."
  },
  AvgCommunicate_149988_Content_4 = {
    Text = "Estoy muy arriba en las tierras altas."
  },
  AvgCommunicate_149988_Content_5 = {
    Text = "Nos estamos preparando para escalar una montaña. Sinceramente, estoy un poco preocupado por mi resistencia."
  },
  AvgCommunicate_149988_Content_6 = {
    Text = "El aire es increíblemente escaso aquí arriba. Siento que me desmayaré si corro más de unos pocos pasos."
  },
  AvgCommunicate_149988_Content_7 = {
    Text = "¿Y de verdad crees que puedes escalar una montaña así? Qué cachorrito imprudente y sin cerebro, completamente ajeno a tus propios límites."
  },
  AvgCommunicate_149988_Content_8 = {
    Text = "Sé que solo estás preocupado, pero tengo cosas que necesito terminar."
  },
  AvgCommunicate_149988_Content_9 = {
    Text = "No te preocupes, el Mayor William está aquí conmigo. Estaremos bien."
  },
  AvgCommunicate_149988_Option_3 = {
    Text = "Continente del Norte Final."
  },
  AvgCommunicate_149988_Option_4 = {
    Text = "Una región de gran altitud."
  },
  AvgCommunicate_150103_Content_1 = {
    Text = "Un leve temblor se propaga por los confines del tapiz del destino."
  },
  AvgCommunicate_150103_Content_10 = {
    Text = "¿Es este otro hilo en tu tapiz del destino?"
  },
  AvgCommunicate_150103_Content_11 = {
    Text = "Sobre esto, el telar debe permanecer en silencio."
  },
  AvgCommunicate_150103_Content_12 = {
    Text = "¿Y las personas que viven en este mundo? ¿Qué les ocurre ahora?"
  },
  AvgCommunicate_150103_Content_13 = {
    Text = "Regresarán a su esencia más pura: los Núcleos de plata."
  },
  AvgCommunicate_150103_Content_14 = {
    Text = "Y el Rey Dios rescatará esos fragmentos de la lluvia interminable, reformando el mundo tras un largo y silencioso letargo."
  },
  AvgCommunicate_150103_Content_15 = {
    Text = "Este silencioso testimonio será compartido."
  },
  AvgCommunicate_150103_Content_2 = {
    Text = "El umbral crítico ha sido cruzado. La tierra prometida tan largamente buscada finalmente ha sido alcanzada."
  },
  AvgCommunicate_150103_Content_3 = {
    Text = "No puedo creerlo."
  },
  AvgCommunicate_150103_Content_4 = {
    Text = "El mundo está desapareciendo."
  },
  AvgCommunicate_150103_Content_5 = {
    Text = "El cielo se derrite, la nieve se derrumba, las cimas de las montañas se desmoronan."
  },
  AvgCommunicate_150103_Content_6 = {
    Text = "Este mundo entero... todo era falso."
  },
  AvgCommunicate_150103_Content_7 = {
    Text = "¿Lo sabías desde siempre? ¿Siempre has podido ver esto?"
  },
  AvgCommunicate_150103_Content_8 = {
    Text = "Estar fuera del gran escenario del mundo es tejer por la eternidad."
  },
  AvgCommunicate_150103_Content_9 = {
    Text = "¿Eso incluía el deseo de Caraboo? El mundo no habría desaparecido sin él."
  },
  AvgCommunicate_150103_Option_3 = {
    Text = "Puedo verlo..."
  },
  AvgCommunicate_150103_Option_4 = {
    Text = "El mundo está desapareciendo..."
  },
  AvgCommunicate_57593_Content_1 = {
    Text = "Pareja, ¿has terminado de leer los libros sobre historia y ciencias naturales que te presté la última vez?"
  },
  AvgCommunicate_57593_Content_10 = {
    Text = "Eh? ¿Realmente necesita ser tan serio...?"
  },
  AvgCommunicate_57593_Content_11 = {
    Text = "Estos son libros esenciales para investigadores. Debes memorizar algunos, incluso si tienes que hacerlo de memoria."
  },
  AvgCommunicate_57593_Content_12 = {
    Text = "Planeo tutorizarte durante una hora todos los días. Si quieres aprender más rápido, no me importa quedarme despierto toda la noche contigo."
  },
  AvgCommunicate_57593_Content_13 = {
    Text = "Más lento... mucho más lento... ¡creo que una hora es suficiente! Aprender demasiado no favorece la revisión y consolidación"
  },
  AvgCommunicate_57593_Content_14 = {
