  },
  AvgCommunicate_57594_Content_2 = {
    Text = "Recuerda enviar."
  },
  AvgCommunicate_57594_Content_3 = {
    Text = "Deja que los muertos sean muertos..."
  },
  AvgCommunicate_57594_Content_4 = {
