    Text = "Guardián, dijiste..."
  },
  AvgCommunicate_57595_Content_10 = {
    Text = "Escribiré algunos avisos de duelo y los enviaré a los dormitorios de todos; eso debería ser lo suficientemente educado."
  },
  AvgCommunicate_57595_Content_11 = {
    Text = "Está decidido. ¿Son suficientes cuarenta hojas...?"
  },
  AvgCommunicate_57595_Content_12 = {
    Text = "?! Espera, no se trata de la invitación al duelo, ¿verdad? ¡Esto es demasiado disruptivo!"
  },
  AvgCommunicate_57595_Content_13 = {
    Text = "No entiendes. Dexter me dijo que en el pasado, duelar a través de los Libros de Duelo se consideraba un acto de caballeros. ¡Aprende de ello, joven!"
  },
  AvgCommunicate_57595_Content_14 = {
