  AvgCommunicate_57897_Content_10 = {
    Text = "No hay problema, entonces queda decidido. Nos vemos en clase mañana."
  },
  AvgCommunicate_57897_Content_11 = {
    Text = "Tengo otras sesiones de entrenamiento durante las vacaciones—"
  },
  AvgCommunicate_57897_Content_12 = {Text = "Es broma."},
  AvgCommunicate_57897_Content_13 = {
    Text = "He ajustado tu plan de entrenamiento, así que descansa bien durante los próximos días."
  },
  AvgCommunicate_57897_Content_14 = {
    Text = "¿Realmente? ¡Eso es genial, gracias!"
  },
  AvgCommunicate_57897_Content_2 = {
    Text = "¿Sabes tu puntuación?"
  },
  AvgCommunicate_57897_Content_3 = {
    Text = "...Esto me está causando mucho estrés."
  },
  AvgCommunicate_57897_Content_4 = {
    Text = "Estoy aquí para felicitarte. A pesar de muchos incidentes este período, has tenido un desempeño bastante bueno hasta ahora."
  },
  AvgCommunicate_57897_Content_5 = {
    Text = "Como recompensa, he ajustado tu plan de entrenamiento. Descansa bien durante los próximos días."
  },
  AvgCommunicate_57897_Content_6 = {
    Text = "Lo siento, la regué. Voy a esforzarme durante mi descanso..."
  },
  AvgCommunicate_57897_Content_7 = {
    Text = "Vine a felicitarte. Aunque ha habido muchos incidentes este período, tu desempeño hasta ahora ha sido bastante bueno."
  },
  AvgCommunicate_57897_Content_8 = {
    Text = "Ya que pediste tomarte un tiempo libre, no me importa darte algunas clases extra después de clase para compensar tu tiempo de descanso."
