  AvgCommunicate_57898_Content_1 = {
    Text = "Te encontré."
  },
  AvgCommunicate_57898_Content_10 = {
    Text = "......Informaré a la escuela sobre esta brecha."
  },
  AvgCommunicate_57898_Content_11 = {
    Text = "Qué mal niño, pero ¿crees que esta pequeña cosa puede detenerme?"
  },
  AvgCommunicate_57898_Content_12 = {
    Text = "Siempre estaré observándote."
  },
  AvgCommunicate_57898_Content_2 = {
    Text = "¿Quién eres tú? ¿Por qué no tienes una cuenta oficial?"
  },
  AvgCommunicate_57898_Content_3 = {
    Text = "Usa tu ingenioso cerebro para adivinar."
  },
  AvgCommunicate_57898_Content_4 = {
    Text = "¿Conoces el comunicador? ¿Eres estudiante en el campus?"
  },
  AvgCommunicate_57898_Content_5 = {
    Text = "¿Por qué no, si todos todavía están dispuestos a admitirlo?"
  },
  AvgCommunicate_57898_Content_6 = {
    Text = "Eres... esa Muñeca."
  },
  AvgCommunicate_57898_Content_7 = {
    Text = "Corregir, el perro inteligente recibe una recompensa."
  },
  AvgCommunicate_57898_Content_8 = {
    Text = "...¿Alguna recompensa?"
  },
  AvgCommunicate_57898_Content_9 = {
    Text = "Recompensa por una palmadita en la cabeza. Siéntete libre de recogerla en cualquier momento en la Piscina Negra."
  },
  AvgCommunicate_57898_Option_10 = {
    Text = "Se lo informaré a la escuela."
  },
  AvgCommunicate_57898_Option_2 = {
    Text = "¿Quién eres tú?"
  },
  AvgCommunicate_57898_Option_4 = {
    Text = "¿Eres estudiante aquí?"
