  AvgCommunicate_57899_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%, ¿has visto a Jenkin?"
  },
  AvgCommunicate_57899_Content_10 = {
    Text = "Gracias, %player%."
  },
  AvgCommunicate_57899_Content_2 = {
    Text = "Ella mencionó algo sobre \"crujido de chocolate\" esta mañana y salió corriendo. No ha vuelto desde entonces."
  },
  AvgCommunicate_57899_Content_3 = {
    Text = "Estoy un poco preocupado."
  },
  AvgCommunicate_57899_Content_4 = {
    Text = "Hannah dijo que Jenkin está con ella."
  },
  AvgCommunicate_57899_Content_5 = {
    Text = "Creo que ella quería comprar un poco de chocolate como regalo para ti."
  },
  AvgCommunicate_57899_Content_6 = {Text = "¿Don?"},
  AvgCommunicate_57899_Content_7 = {
    Text = "Pero ni siquiera es un día festivo... ¿Olvidé algo?"
  },
  AvgCommunicate_57899_Content_8 = {
    Text = "Creo que a veces, los regalos no necesariamente tienen que comprarse solo durante las festividades."
  },
  AvgCommunicate_57899_Content_9 = {
    Text = "¿Es así...? Entonces prepararé algo también."
  },
  AvgCommunicate_57899_Option_4 = {
    Text = "Hannah dijo que Jenkin está con ella."
  },
  AvgCommunicate_57899_Option_8 = {
    Text = "Creo que..."
  },
  AvgCommunicate_57900_Content_1 = {Text = "¿Milord?"},
  AvgCommunicate_57900_Content_10 = {
    Text = "¡Increíble! ¿Cómo lo hiciste?"
  },
  AvgCommunicate_57900_Content_11 = {
    Text = "Espera, iré y te enseñaré."
  },
  AvgCommunicate_57900_Content_2 = {
    Text = "¿Qué pasa, Ogier?"
  },
  AvgCommunicate_57900_Content_3 = {
    Text = "¡Vaya, hay palabras!"
  },
  AvgCommunicate_57900_Content_4 = {
    Text = "Lo siento, My Lord, perdí la compostura antes."
  },
  AvgCommunicate_57900_Content_5 = {
    Text = "La señorita Muñeca acaba de enviarme un comunicador mejorado para pruebas. No esperaba que funcionara tan bien."
  },
  AvgCommunicate_57900_Content_6 = {
    Text = "Me pregunto qué más puede transmitir."
  },
  AvgCommunicate_57900_Content_7 = {
    Text = "¡También puedes enviar imágenes!"
  },
  AvgCommunicate_57900_Option_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_57901_Content_1 = {
    Text = "¿?!#¥%&*()"
  },
  AvgCommunicate_57901_Content_10 = {
    Text = "¡Ah! ¡Lo siento, Guardia!"
  },
  AvgCommunicate_57901_Content_11 = {
    Text = "Esta vez, definitivamente no olvidaré. ¡Definitivamente!"
  },
  AvgCommunicate_57901_Content_2 = {Text = "¿¿??"},
  AvgCommunicate_57901_Content_3 = {
    Text = "Lo siento, lo siento, aún no estoy muy familiarizado con el teclado."
  },
  AvgCommunicate_57901_Content_4 = {
    Text = "Está bien. Yo también me tropecé al principio cuando comencé a usarlo. Practica un par de veces más, y lo dominarás."
  },
  AvgCommunicate_57901_Content_5 = {
    Text = "Sigh, aun así, temo que ya lo olvidaré para mañana."
  },
  AvgCommunicate_57901_Content_6 = {
    Text = "Entonces, solo intenta unas cuantas veces más. ¡Debería estar bien!"
  },
  AvgCommunicate_57901_Content_7 = {
    Text = "¡Tienes razón! ¡Gracias, Alva!"
  },
  AvgCommunicate_57901_Content_8 = {
    Text = "...Eso, no soy Alva."
  },
  AvgCommunicate_57901_Content_9 = {
    Text = "Soy el Guardián."
  },
  AvgCommunicate_57901_Option_2 = {Text = "¿¿??"},
  AvgCommunicate_57901_Option_4 = {
    Text = "Practica más, y lo dominarás."
  },
  AvgCommunicate_57901_Option_6 = {
    Text = "Entonces hazlo más veces"
  },
  AvgCommunicate_57901_Option_8 = {
    Text = "No soy Alva."
  },
  AvgCommunicate_57901_Option_9 = {
    Text = "Soy el Guardián."
  },
  AvgCommunicate_57903_Content_1 = {
    Text = "Buen día, mensajero pálido."
  },
  AvgCommunicate_57903_Content_10 = {
    Text = "Debo decir que es bastante ingenioso."
  },
  AvgCommunicate_57903_Content_2 = {
    Text = "Hola, Obispo Salvador."
  },
  AvgCommunicate_57903_Content_3 = {
    Text = "Parece que has recibido el comunicador más reciente. ¿Qué piensas?"
  },
  AvgCommunicate_57903_Content_4 = {
    Text = "Es bastante interesante y conveniente. A pesar de que estamos a cientos de millas de distancia, aún podemos comunicarnos como si estuviéramos cara a cara."
  },
  AvgCommunicate_57903_Content_5 = {
    Text = "Si el mundo entero tuviera tales dispositivos, la distancia entre las personas no sería tan vasta como lo es ahora."
  },
  AvgCommunicate_57903_Content_6 = {
    Text = "Pero entiendo la singularidad de esta tecnología—sabes que transmite información al vincularse con otros espíritus, ¿verdad?"
  },
  AvgCommunicate_57903_Content_7 = {
    Text = "Solo sé que hay Plata dentro."
  },
  AvgCommunicate_57903_Content_8 = {
    Text = "¿Lo viste?"
  },
  AvgCommunicate_57903_Content_9 = {
    Text = "Así es, nuestros espíritus están conectados a la Plata, que está vinculada a las Platas en otros dispositivos similares."
  },
  AvgCommunicate_57903_Option_2 = {
    Text = "Hola, Obispo Salvador."
  },
  AvgCommunicate_57903_Option_7 = {
    Text = "Solo sé que hay Plata dentro."
  },
  AvgCommunicate_57903_Option_8 = {
    Text = "¿Lo viste?"
  },
  AvgCommunicate_57904_Content_1 = {
    Text = "Guardián, gracias por llevar el inventario al sanatorio ayer, y por favor agradece al Noble Dexter por su continuo apoyo."
  },
  AvgCommunicate_57904_Content_10 = {
    Text = "Eso es todo lo que puedo hacer por el niño."
  },
  AvgCommunicate_57904_Content_2 = {
    Text = "Esto es lo que deberíamos hacer."
  },
  AvgCommunicate_57904_Content_3 = {
    Text = "El sanatorio no habría sobrevivido sin ti."
  },
  AvgCommunicate_57904_Content_4 = {
    Text = "El decano seguramente te estará agradecido."
  },
  AvgCommunicate_57904_Content_5 = {
    Text = "Gestionando el sanatorio todo por ti mismo, has trabajado duro."
  },
  AvgCommunicate_57904_Content_6 = {
    Text = "Lo que hago no significa nada."
  },
  AvgCommunicate_57904_Content_7 = {
    Text = "Solo espero que los pacientes en el sanatorio puedan tener un momento de paz."
  },
  AvgCommunicate_57904_Content_8 = {
    Text = "Si tienes tiempo, por favor trae a Lily de vuelta más a menudo."
  },
  AvgCommunicate_57904_Content_9 = {
    Text = "Limpiaré la oficina del director y esperaré por ti."
  },
  AvgCommunicate_57904_Option_2 = {
    Text = "Esto es lo que deberíamos hacer."
  },
  AvgCommunicate_57904_Option_5 = {
    Text = "Gestionando el sanatorio todo por ti mismo, has trabajado duro."
  },
  AvgCommunicate_57905_Content_1 = {
    Text = "Ding-ding~ Recordatorio pensativo de la sirvienta Karen: ¡tu desayuno ha sido colocado en la puerta!"
  },
  AvgCommunicate_57905_Content_10 = {
    Text = "¡Déjame! ¡Karen es una sirvienta polivalente, capaz de manejar todo, desde lavandería hasta cambios de cerraduras y más!"
  },
  AvgCommunicate_57905_Content_11 = {
    Text = "¡No! ¡Mantente alejado!"
  },
  AvgCommunicate_57905_Content_12 = {
    Text = "¡No seas tímido! Estaré allí en un momento~"
  },
  AvgCommunicate_57905_Content_2 = {
    Text = "¡Tú! ¿Tomaste mi ropa?"
  },
  AvgCommunicate_57905_Content_3 = {
    Text = "Oh querido, Maestro, ¿por qué te has levantado tan temprano? ¡Tu ropa aún no está seca!"
  },
  AvgCommunicate_57905_Content_4 = {
    Text = "¿No está seco aún? ¿Lo llevaste a lavar?"
  },
  AvgCommunicate_57905_Content_5 = {
    Text = "¡Por supuesto! Una sirvienta calificada no podría permitir que su amo salga vistiendo ropa sucia y arrugada."
  },
  AvgCommunicate_57905_Content_6 = {
    Text = "Entonces pasé toda la noche despierto y lavé cada prenda de tu ropa, limpia, limpia, impecable, impecable, oh."
  },
  AvgCommunicate_57905_Content_7 = {
    Text = "¡No puedes lavar todo! ¡Deja uno para mí!"
  },
  AvgCommunicate_57905_Content_8 = {
    Text = "El Maestro aún tenía otro. Para ser honesto, realmente quería llevármelo a escondidas, pero el Maestro envuelve la manta tan ajustadamente mientras duerme que no tuve oportunidad."
  },
  AvgCommunicate_57905_Content_9 = {
    Text = "...Estoy cambiando la cerradura."
  },
  AvgCommunicate_57905_Option_11 = {
    Text = "¡No! ¡Mantente alejado!"
  },
  AvgCommunicate_57905_Option_2 = {
    Text = "¿Tomaste mi ropa?"
  },
  AvgCommunicate_57905_Option_4 = {
    Text = "¿Lo llevaste a lavar?"
  },
  AvgCommunicate_57905_Option_7 = {
    Text = "\"¡Deja uno para mí!\""
  },
  AvgCommunicate_57905_Option_9 = {
    Text = "...Estoy cambiando la cerradura."
  },
  AvgCommunicate_57906_Content_1 = {
    Text = "Ah, déjame ver qué es esta cosa buena."
  },
  AvgCommunicate_57906_Content_2 = {
    Text = "¿Está alguien extrañando mi pequeño látigo por insatisfacción?"
  },
  AvgCommunicate_57906_Content_3 = {
    Text = "No realmente..."
  },
  AvgCommunicate_57906_Content_4 = {
    Text = "No seas tímido, no ocultes los deseos más profundos de tu corazón."
  },
  AvgCommunicate_57906_Content_5 = {
    Text = "¡Ríndete a ello, libéralo, enciéndelo!"
  },
  AvgCommunicate_57906_Content_6 = {
    Text = "¡Grita de dolor!"
  },
  AvgCommunicate_57906_Content_7 = {
    Text = "Estoy apagándome ahora."
  },
  AvgCommunicate_57906_Content_8 = {
    Text = "Es raro encontrar una forma tan conveniente y privada de contactar. No tengas miedo; nadie lo sabrá."
  },
  AvgCommunicate_57906_Content_9 = {
    Text = "¡Puedes llamarme para servicio a domicilio en cualquier momento!"
  },
  AvgCommunicate_57906_Option_3 = {
    Text = "No realmente..."
  },
  AvgCommunicate_57906_Option_7 = {
    Text = "Estoy apagándome ahora."
  },
  AvgCommunicate_57907_Content_1 = {
    Text = "La señorita Muñeca preguntó si había algo que quería hacer."
  },
  AvgCommunicate_57907_Content_10 = {
    Text = "...Es una evaluación rara."
  },
  AvgCommunicate_57907_Content_11 = {
    Text = "Si realmente estás perdido, ¿qué tal empezar con lo que se te da bien?"
  },
  AvgCommunicate_57907_Content_12 = {
    Text = "Alva es bastante hábil en entrenar soldados."
  },
  AvgCommunicate_57907_Content_13 = {
    Text = "Entrenamiento, dices. Quizás... entiendo."
  },
  AvgCommunicate_57907_Content_14 = {
    Text = "Gracias, Guardián."
  },
  AvgCommunicate_57907_Content_2 = {
    Text = "I... me siento un poco confundida."
  },
  AvgCommunicate_57907_Content_3 = {
