  AvgCommunicate_57907_Content_4 = {
    Text = "Es hora de empezar a apretar...!"
  },
  AvgCommunicate_57907_Content_5 = {
    Text = "Hahaha, no realmente. Ofrecí ayuda, pero tampoco estoy seguro de lo que puedo hacer."
  },
  AvgCommunicate_57907_Content_6 = {
    Text = "He sido soldado toda mi vida, simplemente siguiendo órdenes. Incluso en Remouahe, la mayor parte del tiempo no estoy seguro de lo que debo o puedo hacer."
  },
  AvgCommunicate_57907_Content_7 = {
    Text = "De repente me dices que puedo decidirlo todo. Esta sensación... me resulta extraña."
