  },
  AvgCommunicate_57920_Option_3 = {
    Text = "Son hermosos."
  },
  AvgCommunicate_57920_Option_6 = {
    Text = "¡Estoy seguro de que puedes hacerlo!"
  },
  AvgCommunicate_57956_Content_1 = {
    Text = "He estado un poco preocupado recientemente."
  },
  AvgCommunicate_57956_Content_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_57956_Content_3 = {
    Text = "Si no te importa, ¿podrías contarme sobre ello?"
  },
  AvgCommunicate_57956_Content_4 = {
    Text = "La dama que siempre se sienta en un extraño dispositivo y bebe grandes cantidades de líquido oscuro ha estado en mi habitación durante tres días."
  },
  AvgCommunicate_57956_Content_5 = {
    Text = "Sé que teme a la oscuridad, y entiendo el dolor de nunca poder regresar a casa mientras sigo la guía, pero..."
  },
  AvgCommunicate_57956_Content_6 = {
    Text = "Ella incluso quiere seguirme al baño, lo que es bastante embarazoso."
  },
  AvgCommunicate_57956_Content_7 = {
    Text = "Hablaré con Bígaro sobre eso."
  },
  AvgCommunicate_57956_Content_8 = {
    Text = "Gracias de antemano."
  },
  AvgCommunicate_57956_Content_9 = {
    Text = "Sin embargo, por favor, asegúrate de tratarla con gentileza. Después de todo, no es su culpa."
  },
  AvgCommunicate_57956_Option_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_57956_Option_3 = {
    Text = "Si no te importa, ¿podrías contarme sobre ello?"
  },
  AvgCommunicate_57956_Option_7 = {
    Text = "Hablaré con Bígaro sobre eso."
  },
  AvgCommunicate_57957_Content_1 = {
    Text = "¿Recibiste mi regalo?"
  },
  AvgCommunicate_57957_Content_2 = {
    Text = "Debería haberlo adivinado. Eres el único que me daría esto."
  },
  AvgCommunicate_57957_Content_3 = {
    Text = "Como todo arte, la escultura también es algo muy personal."
  },
  AvgCommunicate_57957_Content_4 = {
    Text = "No todos pueden ver estas creaciones de piedra como extensiones de sí mismos, una continuación de la vida, como yo lo hago"
  },
  AvgCommunicate_57957_Content_5 = {
    Text = "Pero eres diferente, ¿no?"
  },
  AvgCommunicate_57957_Content_6 = {
    Text = "¿Querida \"Dama Sanga\"?"
  },
  AvgCommunicate_57957_Option_2 = {
    Text = "Debería haberlo adivinado."
  },
  AvgCommunicate_57958_Content_1 = {
    Text = "Disculpe, {Male=sir,Female=miss}, ¿podría concederme un momento de su tiempo?"
  },
  AvgCommunicate_57958_Content_10 = {
    Text = "No te preocupes. Para difundir la gracia de mi Señor, no me rendiré ante ninguna alma obstinada."
  },
  AvgCommunicate_57958_Content_11 = {
    Text = "Mañana a las 3 AM, sostendré una ceremonia en el Salón de Mythag para narrar las grandes hazañas de mi maestro."
  },
  AvgCommunicate_57958_Content_12 = {
    Text = "Como alguien profundamente vinculado con mi Señor, espero que el Guardián {Male=señor,Female=señorita} asista puntualmente."
  },
  AvgCommunicate_57958_Content_2 = {
    Text = "Me gustaría hablar contigo sobre nuestro joven rey y salvador—Tulu."
