  AvgCommunicate_57958_Content_3 = {
    Text = "Sacerdote Jefe, ten en cuenta tu estatus; no imites estos lemas callejeros."
  },
  AvgCommunicate_57958_Content_4 = {
    Text = "Juliette una vez me aconsejó que, para expandir a los seguidores, necesitamos adoptar un enfoque más suave y proactivo para la promoción."
  },
  AvgCommunicate_57958_Content_5 = {
    Text = "Creo que hay algo de verdad en lo que dijo."
  },
  AvgCommunicate_57958_Content_6 = {
