  AvgCommunicate_60943_Content_1 = {
    Text = "Compañero, nos falta personal para esta misión. Necesito ir a la posición avanzada antes para preparar todo, así que me temo que no podré operar contigo."
  },
  AvgCommunicate_60943_Content_10 = {
    Text = "Lo sé. Siempre piensas en todo por todos."
  },
  AvgCommunicate_60943_Content_11 = {
    Text = "Pero quizá sea hora de que aprendas a confiar en mí para cubrirte las espaldas, ¿no? Compañera."
  },
  AvgCommunicate_60943_Content_12 = {Text = "..."},
  AvgCommunicate_60943_Content_13 = {
    Text = "Tienes razón."
  },
  AvgCommunicate_60943_Content_14 = {
    Text = "Entonces contaré con tu apoyo esta vez, compañero."
  },
  AvgCommunicate_60943_Content_2 = {
    Text = "Te he redactado varios planes de contingencia para crisis. Si surge alguna emergencia, puedes consultar la sección correspondiente en el índice."
  },
  AvgCommunicate_60943_Content_3 = {
    Text = "También he solicitado Cuerpo de Gnosis de Emergencia adicional para ti. Aunque andamos cortos de personal, haré lo posible por organizar a alguien más para que te acompañe."
  },
  AvgCommunicate_60943_Content_4 = {Text = "Ramona."},
  AvgCommunicate_60943_Content_5 = {
    Text = "Sé que estás preocupado por mí. Gracias por todo lo que has hecho."
  },
  AvgCommunicate_60943_Content_6 = {
    Text = "Pero ya no soy esa persona débil y desorientada que era cuando me inscribí. Puedo con esto."
  },
  AvgCommunicate_60943_Content_7 = {
    Text = "Por supuesto que confío en tus habilidades, es solo que..."
  },
  AvgCommunicate_60943_Content_8 = {
    Text = "Lo siento, estoy acostumbrada a hacer Proyecciones de todo. Si no estoy ahí, no puedo evitar pensar en las peores posibilidades."
  },
  AvgCommunicate_60943_Content_9 = {
    Text = "No puedo aceptar que podría fallar en prevenir el peor desenlace..."
