  AvgCommunicate_66973_Content_1 = {
    Text = "Guardián, muchas gracias por sugerir que mi hermana y yo fuéramos juntas a la reunión."
  },
  AvgCommunicate_66973_Content_10 = {
    Text = "Qué adorable, ver a mi hermana sonrojarse así."
  },
  AvgCommunicate_66973_Content_11 = {
    Text = "Mm, la relación entre ustedes hermanas es realmente profunda"
  },
  AvgCommunicate_66973_Content_12 = {
    Text = "Por supuesto. Mi hermana siempre será la persona más importante para mí, y seguiré cuidándola por siempre."
  },
  AvgCommunicate_66973_Content_13 = {
    Text = "Parece que en las próximas reuniones, será mi turno de guiar a mi hermana."
  },
  AvgCommunicate_66973_Content_14 = {
    Text = "Si tienes la oportunidad, Guardián, ¡deberías venir a unirte a nosotros también!"
  },
  AvgCommunicate_66973_Content_15 = {
    Text = "¡No hay problema!"
  },
  AvgCommunicate_66973_Content_2 = {
    Text = "¡De nada! ¡Encantado de ayudar!"
  },
  AvgCommunicate_66973_Content_3 = {
    Text = "Antes siempre dependía de mi hermana, y ella siempre se mostraba fuerte frente a mí—incluso un poco dura."
  },
  AvgCommunicate_66973_Content_4 = {
    Text = "Nunca esperé que se pusiera tan nerviosa en ese tipo de situación. Jamás había visto a mi hermana tan tímida."
  },
  AvgCommunicate_66973_Content_5 = {
    Text = "¿Hm? Siempre pensé que Faint tenía ese tipo de personalidad reservada."
  },
  AvgCommunicate_66973_Content_6 = {
    Text = "No, en realidad mi hermana tiene una personalidad muy decidida, ¡y es bastante determinada!"
  },
  AvgCommunicate_66973_Content_7 = {
    Text = "Cada vez que me sentía perdida y Frágil, siempre era mi hermana quien me aconsejaba. Siempre me acariciaba la cabeza y calmaba mis emociones con dulzura."
  },
  AvgCommunicate_66973_Content_8 = {
    Text = "Ya veo, eso es algo que no habría esperado."
  },
  AvgCommunicate_66973_Content_9 = {
    Text = "Pero ahora que ya no enfrentamos una crisis de supervivencia, mi hermana por fin puede hacer amigos delante de los demás."
  },
  AvgCommunicate_66973_Option_11 = {
    Text = "Vaya, el vínculo entre ustedes como hermanas es realmente profundo..."
  },
  AvgCommunicate_66973_Option_15 = {
    Text = "¡No hay problema!"
  },
  AvgCommunicate_66973_Option_2 = {
