  AvgCommunicate_66975_Content_1 = {
    Text = "¡¡Guardián!! ¡Mi mundo, mi vida, todo se ha derrumbado! Buaaaah—"
  },
  AvgCommunicate_66975_Content_10 = {
    Text = "Eso suena bastante bien."
  },
  AvgCommunicate_66975_Content_11 = {
    Text = "Hmph, Karen apretó los dientes, vació todos sus ahorros para comprar esos adornos y los usó todos."
  },
  AvgCommunicate_66975_Content_12 = {
    Text = "Hmm... ¿No pesan mucho para llevarlas encima?"
  },
  AvgCommunicate_66975_Content_13 = {
    Text = "Pero entonces, cuando Karen fue a atender a la Señora Sorel, ¡la Señora echó un solo vistazo y dijo que todas esas gemas eran falsas! ¡¡Eran falsificaciones!!"
  },
  AvgCommunicate_66975_Content_14 = {
    Text = "¿Cómo pudo pasar esto? ¿Cuánto dinero te estafó?"
  },
  AvgCommunicate_66975_Content_15 = {
    Text = "¡Un total de 500 Colmillos de Leo!!"
  },
  AvgCommunicate_66975_Content_16 = {
    Text = "¡¡¡Hay que estar loca para pensar que con quinientas se compra algo auténtico!!! ¿¿Qué pasó con esos años de reserva??"
  },
  AvgCommunicate_66975_Content_17 = {
    Text = "E–es que a Karen le gustan tanto las cosas brillantes que, cada vez que Karen consigue dinero, todo se va en comprar cosas brillantes, así que Karen no ha ahorrado mucho..."
  },
  AvgCommunicate_66975_Content_18 = {
    Text = "No importa... De todos modos, si simplemente te gustan las piedras brillantes, estas piedras son lo suficientemente brillantes, y la artesanía es lo suficientemente exquisita."
  },
  AvgCommunicate_66975_Content_19 = {
    Text = "Comparado con comprar las auténticas, en realidad te has ahorrado una fortuna. ¿Por qué disgustarse?"
  },
  AvgCommunicate_66975_Content_2 = {
    Text = "¿? ¿Qué pasó?"
  },
  AvgCommunicate_66975_Content_20 = {
    Text = "Vaya, eso tiene mucho sentido."
  },
  AvgCommunicate_66975_Content_21 = {
    Text = "¡Karen siente de inmediato que salió ganando! ¡Gracias, Maestro!"
  },
  AvgCommunicate_66975_Content_3 = {
    Text = "¡Daffodil, esa mujer traidora! ¡Le sacó a Karen toda la Reserva por la que trabajó tan duro durante años!"
  },
  AvgCommunicate_66975_Content_4 = {
    Text = "¿Daffodil te estafó el dinero? ¿Qué fuiste a comprarle?"
  },
  AvgCommunicate_66975_Content_5 = {
    Text = "Todo fue porque Karen estaba suspirando por los precios de joyas y accesorios en una revista, y esa malvada mujer justo la pilló haciéndolo."
  },
  AvgCommunicate_66975_Content_6 = {
    Text = "Le dijo a Karen que tenía un lote de joyería con gemas en oferta especial. Nadie las quería porque los diseños estaban pasados de moda, pero serían perfectas para el estilo vintage de Karen..."
  },
  AvgCommunicate_66975_Content_7 = {
