  },
  AvgCommunicate_66975_Content_8 = {
    Text = "¿Qué tiene de malo? A Karen simplemente le encantan esas piedritas brillantes..."
  },
  AvgCommunicate_66975_Content_9 = {
    Text = "La mala mujer le mostró a Karen esas gemas, y cada una era más deslumbrante que la anterior. ¡El corazón de Karen fue capturado al instante!"
