  AvgCommunicate_66977_Content_12 = {
    Text = "¿Qué? ¿Qué pasa, Guardián?"
  },
  AvgCommunicate_66977_Content_13 = {
    Text = "Es un laxante... Necesito usar el baño de inmediato..."
  },
  AvgCommunicate_66977_Content_14 = {
