  },
  AvgCommunicate_66977_Content_6 = {
    Text = "Recuerdo vagamente que ella añadió algo mientras hacía galletas... De todos modos, ¿te sientes mal ahora mismo?"
  },
  AvgCommunicate_66977_Content_7 = {
    Text = "Ahora que lo mencionas, de repente me siento terrible por todo..."
