  },
  AvgCommunicate_66977_Content_9 = {
    Text = "¡Improbable! A ella simplemente le gustan las bromas y no es tan malvada."
  },
  AvgCommunicate_66977_Option_11 = {
    Text = "Espera, aguanta, olvídalo..."
  },
  AvgCommunicate_66977_Option_13 = {
    Text = "Es un laxante..."
  },
  AvgCommunicate_66977_Option_2 = {
    Text = "Uh, ¿cierto?"
  },
  AvgCommunicate_66977_Option_4 = {
    Text = "¿Qué? ¿No lo hiciste tú?"
  },
  AvgCommunicate_66977_Option_7 = {
    Text = "Ahora que lo mencionas, de repente me siento terrible por todo..."
  },
  AvgCommunicate_66978_Content_1 = {
    Text = "¡Hola! ¡Ayúdame! ¡Estoy enredado en la manta!"
  },
  AvgCommunicate_66978_Content_10 = {
    Text = "Esta es la tarea doméstica más simple. Realmente has perdido el contacto con la vida."
  },
  AvgCommunicate_66978_Content_11 = {
    Text = "Hmph... Trataré a los esclavos con más gentileza de ahora en adelante. ¡Ahora, ve a buscarme algunos que sean diligentes!"
  },
  AvgCommunicate_66978_Content_12 = {
    Text = "¡Ya te he dicho, Roma ha caído!"
  },
  AvgCommunicate_66978_Content_13 = {
    Text = "¡Debes estar soñando en esta sociedad respetuosa de la ley!"
  },
  AvgCommunicate_66978_Content_14 = {
    Text = "¡No me importa! ¡No me importa! ¡Prefiero morir que hacer estas tareas todos los días!"
  },
  AvgCommunicate_66978_Content_15 = {
    Text = "Je, no solo tareas, sino también deberes."
  },
  AvgCommunicate_66978_Content_16 = {
    Text = "¡Te arrojaré al laberinto para alimentar a mis crías!"
  },
  AvgCommunicate_66978_Content_2 = {
    Text = "¿Mordido por qué??"
  },
  AvgCommunicate_66978_Content_3 = {
    Text = "¡Es toda tu culpa por no asignarme sirvientes! ¿Quién hubiera pensado que esta maldita sábana sería tan difícil de cambiar?"
  },
  AvgCommunicate_66978_Content_4 = {
    Text = "No importa cuánto intenté, no pude resolverlo, y en mi frustración, ¡terminé peleando con la manta!"
  },
  AvgCommunicate_66978_Content_5 = {Text = "..."},
  AvgCommunicate_66978_Content_6 = {
    Text = "¿Por qué estás ahí parado? ¡Apresúrate y ayúdame! ¡No puedo salir!"
  },
  AvgCommunicate_66978_Content_7 = {
    Text = "A veces me pregunto cómo alguien como tú ha logrado sobrevivir tanto tiempo."
  },
  AvgCommunicate_66978_Content_8 = {
    Text = "Estas son tareas para esclavos. ¿Por qué son tan difíciles...?"
  },
  AvgCommunicate_66978_Content_9 = {
    Text = "¿Hicieron esos esclavos esto todos los días? ¡Imposible! ¿Cómo lo lograron?"
  },
  AvgCommunicate_66978_Option_10 = {
    Text = "Esta es la tarea doméstica más simple. Realmente has perdido el contacto con la vida."
  },
  AvgCommunicate_66978_Option_12 = {
    Text = "¡Ya te he dicho, Roma ha caído!"
  },
  AvgCommunicate_66978_Option_13 = {
    Text = "¡Debes estar soñando en esta sociedad respetuosa de la ley!"
  },
  AvgCommunicate_66978_Option_15 = {
    Text = "Je, no solo tareas, sino también deberes."
  },
  AvgCommunicate_66978_Option_2 = {
    Text = "¿Mordido por qué??"
  },
  AvgCommunicate_66978_Option_5 = {Text = "..."},
  AvgCommunicate_66978_Option_7 = {
    Text = "A veces me pregunto cómo alguien como tú ha logrado sobrevivir tanto tiempo."
  },
  AvgCommunicate_66979_Content_1 = {
    Text = "Guardián, el pastel que acabas de enviar a Black Pool... era un pastel de cumpleaños para esa persona, la empleada veterana que se encarga de la Fabricación de las Llaves de plata, ¿verdad?"
  },
  AvgCommunicate_66979_Content_10 = {
    Text = "Ja, ya entiendo. ¡Te traeré otra porción enseguida!"
  },
  AvgCommunicate_66979_Content_11 = {Text = "Gracias."},
  AvgCommunicate_66979_Content_2 = {
    Text = "¡Sí! Sabíamos que no comerías nada, pero todos querían que participaras en la diversión, así que te lo enviamos."
  },
  AvgCommunicate_66979_Content_3 = {
    Text = "Gracias por el amable gesto. Por favor, transmite mis Bendiciones de cumpleaños en mi nombre, y... ¿podrían enviar otra porción de pastel?"
  },
  AvgCommunicate_66979_Content_4 = {
    Text = "¿Eh? ¡¿De verdad te lo comiste?!"
  },
  AvgCommunicate_66979_Content_5 = {
    Text = "Un impulso del momento. Esa persona ha trabajado conmigo durante muchos años y nunca ha cometido un solo error."
  },
  AvgCommunicate_66979_Content_6 = {
    Text = "Aunque poseo conocimiento infinito y comprendo todos los principios, yo... en realidad nunca había comido pastel antes."
  },
  AvgCommunicate_66979_Content_7 = {
    Text = "Ya veo, ¿entonces quieres decir que solo conocías el pastel en teoría?"
  },
  AvgCommunicate_66979_Content_8 = {
    Text = "Sí, conocía todos los componentes de este pastel, y que la experiencia de su sabor debería ser dulce con el aroma de ricas grasas animales."
  },
  AvgCommunicate_66979_Content_9 = {
    Text = "Pero nunca imaginé que un pastel pudiera saber tan dulce y aromático..."
  },
  AvgCommunicate_66979_Option_10 = {
    Text = "Ja, ya entiendo."
  },
  AvgCommunicate_66979_Option_2 = {
    Text = "...¡Está bien!"
  },
  AvgCommunicate_66979_Option_4 = {
    Text = "¿Eh? ¡¿De verdad te lo comiste?!"
  },
  AvgCommunicate_66979_Option_7 = {
    Text = "Ya veo, ¿entonces quieres decir que solo conocías el pastel en teoría?"
  },
  AvgCommunicate_66980_Content_1 = {
    Text = "Disculpe, ¿para qué se utiliza esta intrincada caja mecánica?"
  },
  AvgCommunicate_66980_Content_10 = {
    Text = "¡Deja de investigar! No es importante. Si se rompe, ¡será muy caro!"
  },
  AvgCommunicate_66980_Content_11 = {
    Text = "Está bien, ¿entonces para qué se usa esta caja?"
  },
  AvgCommunicate_66980_Content_12 = {
    Text = "Este es el comunicador emitido por la escuela para comunicación remota. También se puede utilizar para pedir ayuda en situaciones peligrosas."
  },
  AvgCommunicate_66980_Content_13 = {
    Text = "Veo, qué invención tan interesante. Gracias, Guardián."
  },
  AvgCommunicate_66980_Content_14 = {
    Text = "¿Realmente recuerdas quién soy?"
  },
  AvgCommunicate_66980_Content_15 = {
    Text = "Recuerdo. Prometí que no olvidaría."
  },
  AvgCommunicate_66980_Content_16 = {
    Text = "¡Eres %player%, mi amigo!"
  },
  AvgCommunicate_66980_Content_2 = {
    Text = "? ¿Olvidaste todo?"
  },
  AvgCommunicate_66980_Content_3 = {
    Text = "¿Olvidado? No puedo recordar de dónde vino esta caja."
  },
  AvgCommunicate_66980_Content_4 = {
    Text = "Pero vi los registros de chat. Creo que lo he usado antes, pero olvidé cómo."
  },
  AvgCommunicate_66980_Content_5 = {
    Text = "¿Cómo lo estás usando ahora?!"
  },
  AvgCommunicate_66980_Content_6 = {Text = "Hehe."},
  AvgCommunicate_66980_Content_7 = {
    Text = "¡No te rías de mí por tener miedo!"
  },
  AvgCommunicate_66980_Content_8 = {
    Text = "Lo desarmé y lo volví a ensamblar, y ahora tengo una comprensión general de cómo funciona."
  },
  AvgCommunicate_66980_Content_9 = {
    Text = "Aunque los principios que operan por dentro son muy complejos, aún no los he entendido completamente. Puede que requieran más investigación."
  },
  AvgCommunicate_66980_Option_10 = {
    Text = "¡Deja de investigar! No es importante. Si se rompe, ¡será muy caro!"
  },
  AvgCommunicate_66980_Option_12 = {
    Text = "Este es el comunicador emitido por la escuela."
  },
  AvgCommunicate_66980_Option_14 = {
    Text = "¿Realmente recuerdas quién soy?"
  },
  AvgCommunicate_66980_Option_2 = {
    Text = "? ¿Olvidaste todo?"
  },
  AvgCommunicate_66980_Option_5 = {
    Text = "¿Cómo lo estás usando ahora?!"
  },
  AvgCommunicate_66980_Option_7 = {
    Text = "¡No te rías de mí por tener miedo!"
  },
  AvgCommunicate_66981_Content_1 = {
    Text = "Guardián, ¿cuáles son tus pensamientos sobre las emociones humanas?"
  },
  AvgCommunicate_66981_Content_10 = {
    Text = "¿Y qué pasa contigo? Como Cuerpo Intelectual, ¿no se supone que debes ser absolutamente racional?"
  },
  AvgCommunicate_66981_Content_11 = {
    Text = "Eres perceptivo, Guardián, lo cual es una razón por la que siempre he tratado de minimizar mi contacto con el mundo."
  },
  AvgCommunicate_66981_Content_12 = {
    Text = "Cuando me distancio del mundo y evito mantener vínculos demasiado cercanos con los humanos, me mantengo claro y independiente."
  },
  AvgCommunicate_66981_Content_13 = {
    Text = "Es como si nunca hubiera probado la dulzura del pastel, no estaría pensando constantemente en ello en mi mente."
  },
  AvgCommunicate_66981_Content_14 = {
    Text = "Veo... Entonces, ¿quieres comer algunos pasteles pequeños ahora?"
  },
  AvgCommunicate_66981_Content_15 = {
    Text = "No es una necesidad, pero si te resulta conveniente, te estaría muy agradecido."
  },
  AvgCommunicate_66981_Content_2 = {
    Text = "¡Qué tema tan profundo desde el principio!"
  },
  AvgCommunicate_66981_Content_3 = {
    Text = "Emociones... todos las tienen, después de todo, solo somos humanos."
  },
  AvgCommunicate_66981_Content_4 = {
    Text = "Exactamente, los humanos existen confiando en su carne, y las emociones surgen de reacciones instintivas."
  },
  AvgCommunicate_66981_Content_5 = {
    Text = "La mayoría de las elecciones humanas están influenciadas por emociones en lugar de pensamiento racional, lo que requiere contención y esfuerzo."
  },
  AvgCommunicate_66981_Content_6 = {
    Text = "De verdad, mantener una racionalidad absoluta en todo momento parece posible solo para la Muñeca Maestra."
  },
  AvgCommunicate_66981_Content_7 = {
    Text = "No, la Muñeca tampoco puede hacerlo. Aún tiene vínculos emocionales y tomará grandes riesgos al tomar decisiones."
  },
  AvgCommunicate_66981_Content_8 = {
    Text = "¿Es así como es? ¿Son todas las personas así, incluyendo a esos individuos retorcidos y locos?"
  },
  AvgCommunicate_66981_Content_9 = {
    Text = "Sí, las elecciones extremas están más impulsadas por las emociones."
  },
  AvgCommunicate_66981_Option_10 = {
    Text = "¿Y qué pasa contigo? Como Cuerpo Intelectual, ¿no se supone que debes ser absolutamente racional?"
  },
  AvgCommunicate_66981_Option_14 = {
    Text = "Veo... Entonces, ¿quieres comer algunos pasteles pequeños ahora?"
  },
  AvgCommunicate_66981_Option_2 = {
    Text = "¡Qué tema tan profundo desde el principio!"
  },
  AvgCommunicate_66981_Option_6 = {
    Text = "De verdad, mantener una racionalidad absoluta en todo momento parece posible solo para la Muñeca Maestra."
  },
  AvgCommunicate_66981_Option_8 = {
    Text = "¿Es así como es? ¿Son todas las personas así, incluyendo a esos individuos retorcidos y locos?"
  },
  AvgCommunicate_66982_Content_1 = {
    Text = "Guardián, te estoy dando la oportunidad de ganarte mi favor."
  },
  AvgCommunicate_66982_Content_10 = {
    Text = "Ya que estás, ¿por qué no me vendes a mí también?"
  },
  AvgCommunicate_66982_Content_11 = {
    Text = "¡¿Cómo voy a comprar uno de esos caprichos de la alta sociedad que ni con dinero se consiguen?!"
  },
  AvgCommunicate_66982_Content_12 = {
    Text = "¡No me importa! Busca la manera. Ese conejito también debe estar deseando venir conmigo."
  },
  AvgCommunicate_66982_Content_13 = {
    Text = "Ya he pensado en un nombre para ella: ¡Ivy!"
  },
  AvgCommunicate_66982_Content_14 = {
    Text = "Tomará el té conmigo, junto con Jenny y Oliver."
  },
  AvgCommunicate_66982_Content_15 = {
    Text = "Está bien, está bien, está bien. Déjame ir a suplicarle a la Señora Sorel, y sin duda la traeré de vuelta para tu pequeña reunión."
  },
  AvgCommunicate_66982_Content_16 = {
    Text = "Hehe, ¡eso es más como debe ser!"
  },
  AvgCommunicate_66982_Content_2 = {
    Text = "¿Quieres cupcakes de edición limitada otra vez?"
  },
  AvgCommunicate_66982_Content_3 = {
    Text = "¡¿Acaso lo único que hago a tus ojos es comer?!"
  },
  AvgCommunicate_66982_Content_4 = {
    Text = "Bueno, ¿qué más..."
  },
  AvgCommunicate_66982_Content_5 = {
    Text = "Hmph, el pastel también está bien, pero esta vez no se trata de comida."
  },
  AvgCommunicate_66982_Content_6 = {
    Text = "Vi en una revista que trajiste de tu última salida que los Grandes Almacenes de Londinium acaban de lanzar una nueva línea de muñecos de peluche artesanales."
  },
  AvgCommunicate_66982_Content_7 = {
    Text = "¡Dentro hay un muñeco de conejito especial negro y rosa!"
  },
  AvgCommunicate_66982_Content_8 = {
    Text = "¡Prácticamente tiene mi nombre escrito por todas partes! La revista dice que es una especie de pieza de maestro artesano. ¡Date prisa y cómpralo para mí!"
  },
  AvgCommunicate_66982_Content_9 = {
    Text = "¿De maestro artesano?"
  },
  AvgCommunicate_66982_Option_10 = {
    Text = "Ya que estás, ¿por qué no me vendes a mí también?"
  },
  AvgCommunicate_66982_Option_15 = {
    Text = "Está bien, está bien, está bien..."
  },
  AvgCommunicate_66982_Option_2 = {
    Text = "¿Quieres cupcakes de edición limitada otra vez?"
  },
  AvgCommunicate_66982_Option_4 = {
    Text = "Bueno, ¿qué más..."
  },
  AvgCommunicate_66982_Option_9 = {
    Text = "¿De maestro artesano?"
  },
  AvgCommunicate_66983_Content_1 = {
    Text = "Hey, no necesitas traerme pasteles estos días."
  },
  AvgCommunicate_66983_Content_10 = {
    Text = "Y con una deslumbrante variedad de ingredientes, puedes añadir tanto como quieras—¡es absolutamente delicioso!"
  },
  AvgCommunicate_66983_Content_11 = {
    Text = "¡Ese es el punto clave! ¿No sería abrumador agregar más?"
  },
  AvgCommunicate_66983_Content_12 = {
    Text = "No entenderías—¡mis nuevas creaciones han ganado elogios interminables de esos chefs!"
  },
  AvgCommunicate_66983_Content_13 = {
    Text = "La producción comenzó ayer, y ya está en los estantes de la cafetería. ¡Hay muchas personas haciendo fila!"
  },
  AvgCommunicate_66983_Content_14 = {
    Text = "Así que fuiste tú quien hizo esos nuevos mini pasteles que todos se apresuraron a comprar ayer!"
  },
  AvgCommunicate_66983_Content_15 = {
    Text = "Hahahahaha, ¿soy increíble o no? ¡Llámame genio!"
  },
  AvgCommunicate_66983_Content_16 = {Text = "¡Genius!"},
  AvgCommunicate_66983_Content_17 = {
    Text = "Pero de repente me di cuenta de que los pasteles caseros podrían saber mejor. Mantener esto de ahora en adelante no es una mala idea."
  },
  AvgCommunicate_66983_Content_18 = {
    Text = "Qué encantador, la joven finalmente ha experimentado la alegría del trabajo."
  },
  AvgCommunicate_66983_Content_2 = {
    Text = "¿Qué vi? ¿Qué te impactó?"
  },
  AvgCommunicate_66983_Content_3 = {
    Text = "¿Qué ataque? ¡Estoy perfectamente bien!"
  },
  AvgCommunicate_66983_Content_4 = {
    Text = "¿Quién eres tú?"
  },
  AvgCommunicate_66983_Content_5 = {
    Text = "Sigh, solo es que me he cansado de los pequeños pasteles de la cafetería últimamente, ¡y esos chefs vacíos de cabeza no tienen intención de introducir nuevos!"
  },
  AvgCommunicate_66983_Content_6 = {
    Text = "De verdad, nadie tiene tanto anhelo por pasteles como tú..."
  },
  AvgCommunicate_66983_Content_7 = {
    Text = "Es toda su culpa por ser tan incompetentes, así que entré en la cocina y les pedí que me enseñaran a hornear un pastel."
  },
  AvgCommunicate_66983_Content_8 = {
    Text = "¿Eh? ¿Tú, cocinando?"
  },
  AvgCommunicate_66983_Content_9 = {
    Text = "¡Sorpresa! Entonces descubrí que hacer un pastel no es difícil en absoluto. ¡Simplemente soy una natural!"
  },
  AvgCommunicate_66983_Option_11 = {
    Text = "¡Ese es el punto clave! ¿No sería abrumador agregar más?"
  },
  AvgCommunicate_66983_Option_14 = {
    Text = "Así que fuiste tú quien hizo esos nuevos mini pasteles que todos se apresuraron a comprar ayer!"
  },
  AvgCommunicate_66983_Option_16 = {Text = "¡Genius!"},
  AvgCommunicate_66983_Option_18 = {
    Text = "Qué encantador, la joven finalmente ha experimentado la alegría del trabajo."
  },
  AvgCommunicate_66983_Option_2 = {
    Text = "¿Qué vi? ¿Qué te impactó?"
  },
  AvgCommunicate_66983_Option_4 = {
    Text = "¿Quién eres tú?"
  },
  AvgCommunicate_66983_Option_6 = {
    Text = "De verdad, nadie anhela pasteles como tú..."
  },
  AvgCommunicate_66983_Option_8 = {
    Text = "¿Eh? ¿Tú, cocinando?"
  },
  AvgCommunicate_66984_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%, me he encontrado con un pequeño problema, ?me echarías una mano?"
  },
  AvgCommunicate_66984_Content_10 = {
    Text = "Pero le dije que ya tengo pareja de baile."
  },
  AvgCommunicate_66984_Content_11 = {
    Text = "En realidad, solo ahora vengo a buscar a mi encantadora pareja de baile."
  },
  AvgCommunicate_66984_Content_12 = {
    Text = "Creo que {Male=he,Female=she} no soportaría dejarme asistir al baile completamente sola, ?verdad?"
  },
  AvgCommunicate_66984_Content_13 = {
    Text = "¿Qué dices?"
  },
  AvgCommunicate_66984_Content_14 = {
    Text = "El honor es mío, mi señora."
  },
  AvgCommunicate_66984_Content_15 = {
    Text = "Parece que será mejor que repase mis pasos de baile y mi etiqueta, no vaya a ser que pise los pies de mi señora."
  },
  AvgCommunicate_66984_Content_16 = {
    Text = "Siempre eres tan confiable y considerado, mi Caballero."
  },
  AvgCommunicate_66984_Content_2 = {
    Text = "¿Qué ha dejado a la Sra. Sorel perpleja?"
  },
  AvgCommunicate_66984_Content_3 = {
    Text = "Estoy todo oídos."
  },
  AvgCommunicate_66984_Content_4 = {
    Text = "Dentro de unos días, asistiré a una cena con baile. Ya sabes, de esas en las que un montón de gente pretenciosa y quisquillosa pasa el rato junta."
  },
  AvgCommunicate_66984_Content_5 = {
    Text = "Lo molesto es que un tipo completamente maleducado ha estado acosándome últimamente. También asistirá al baile y me ha invitado a ser su pareja a los cuatro vientos."
  },
  AvgCommunicate_66984_Content_6 = {
    Text = "Qué molestia. ?Quiere que me encargue de él, mi señora?"
  },
  AvgCommunicate_66984_Content_7 = {
    Text = "Jejeje, cada vez se te da mejor bromear."
  },
  AvgCommunicate_66984_Content_8 = {
    Text = "Desafortunadamente, eso aún no es una opción. El mundo de los adultos es así de problemático. Sin embargo, ya he rechazado su invitación."
  },
  AvgCommunicate_66984_Content_9 = {
    Text = "?Entonces no está el asunto resuelto?"
  },
  AvgCommunicate_66984_Option_14 = {
    Text = "El honor es mío, mi señora."
  },
  AvgCommunicate_66984_Option_2 = {
    Text = "¿Qué ha dejado a la Sra. Sorel perpleja?"
  },
  AvgCommunicate_66984_Option_3 = {
    Text = "Estoy todo oídos."
  },
  AvgCommunicate_66984_Option_6 = {
    Text = "Qué molestia. ?Quiere que me encargue de él, mi señora?"
  },
  AvgCommunicate_66984_Option_9 = {
    Text = "?Entonces no está el asunto resuelto?"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "Mi pequeño Caballero, gracias a tu ayuda en la Danza de la última vez, logré librarme de esa persona espantosa."
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "¿Un deseo? Entonces deseo que la hermosa Señora Sorel comparta una suntuosa cena a la luz de las velas conmigo."
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "Solo tú y yo, sin necesidad de atender a nadie más."
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "Como desees, pequeño astuto."
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "¿Qué te gustaría comer? Dime, y lo saborearé junto a ti."
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "Esto realmente pone a prueba la imaginación de alguien como yo que come en la cafetería todos los días. Bueno, entonces déjame hacer la prueba — lo que más le guste comer a la señora."
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "Jeje, qué criatura tan encantadora eres."
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "Entonces, esperaré tu visita en mi residencia."
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "Para agradecerte tu amabilidad y generosidad, me gustaría hacer algo por ti como muestra de mi gratitud."
  },
  AvgCommunicate_66985_Content_3 = {
    Text = "Es usted muy amable, Señora Sorel. Creía que nuestra relación ya había superado la necesidad de dar las gracias."
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "En efecto, no me gusta expresar gratitud con palabras. La mayoría de las veces, son Solo cortesías vacías."
  },
  AvgCommunicate_66985_Content_5 = {
    Text = "Sin embargo, una oportunidad de hacerme cualquier petición... ¿de verdad no te interesa?"
  },
  AvgCommunicate_66985_Content_6 = {
    Text = "Vaya, ¿cualquier petición? Si esos nobles caballeros se enteraran, se morirían de envidia."
  },
  AvgCommunicate_66985_Content_7 = {
    Text = "Tú siempre mereces un trato especial de mi parte."
  },
  AvgCommunicate_66985_Content_8 = {
    Text = "Ahora sí que me has dejado sin saber qué decir. Qué difícil decidir... Si me lanzara a lo grande y pidiera una mansión, ¿lo descubriría la escuela..."
  },
  AvgCommunicate_66985_Content_9 = {
    Text = "No te preocupes, yo me encargo de todo. Siéntete libre de pedir tu deseo."
  },
  AvgCommunicate_66985_Option_10 = {
    Text = "¿Un deseo?"
  },
  AvgCommunicate_66985_Option_14 = {
    Text = "Entonces déjame hacer la Prueba — lo que más le guste comer a mi Señora."
  },
  AvgCommunicate_66985_Option_3 = {
    Text = "Es usted muy amable, Señora Sorel."
  },
  AvgCommunicate_66985_Option_6 = {
    Text = "¡Vaya, ¿alguna solicitud?"
  },
  AvgCommunicate_66985_Option_8 = {
    Text = "Ahora sí que me has dejado sin saber qué decir..."
  },
  AvgCommunicate_66986_Content_1 = {
    Text = "Lotan y yo acabamos de tener un combate. Fue un empate."
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "Ajaja... No creo que tenga tantos pensamientos distractores, así que paso por ahora..."
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "Entonces tú también eres fuerte."
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "Lamentablemente, siempre hay alguien pescando junto a esa cascada. Es un poco ruidoso."
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "Una vez salí de la cascada e intenté pedirle que bajara el ruido. Se asustó tanto que me lanzó su pescado a la cara y salió corriendo."
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "Me pregunto si volverá la próxima vez."
  },
  AvgCommunicate_66986_Content_15 = {
    Text = "Hmm... No creo que lo haga..."
  },
  AvgCommunicate_66986_Content_2 = {
    Text = "¿Qué pasó entre ustedes dos?"
  },
  AvgCommunicate_66986_Content_3 = {
    Text = "No se pelearon, ¿verdad?"
  },
  AvgCommunicate_66986_Content_4 = {
    Text = "No, Solo un combate de práctica entre guerreros."
  },
  AvgCommunicate_66986_Content_5 = {
    Text = "Antes, ella dijo que mi forma de pelear no era lo suficientemente pura. Creo que ahora lo entiendo."
  },
  AvgCommunicate_66986_Content_6 = {
    Text = "Encontré una forma de volverme más puro. El yo actual es más fuerte."
  },
  AvgCommunicate_66986_Content_7 = {
    Text = "Eso es bueno, pero ¿qué método usas para volverte más puro?"
  },
  AvgCommunicate_66986_Content_8 = {
    Text = "Ponte Debajo de una cascada y deja que el agua se lleve tus pensamientos distractores."
  },
  AvgCommunicate_66986_Content_9 = {
    Text = "Es muy efectivo. ¿Quieres ir juntos?"
  },
  AvgCommunicate_66986_Option_10 = {
    Text = "Ajaja... No creo que tenga tantos pensamientos distractores, así que paso por ahora..."
  },
  AvgCommunicate_66986_Option_15 = {
    Text = "Hmm... No creo que lo haga..."
  },
  AvgCommunicate_66986_Option_2 = {
    Text = "¿Qué pasó entre ustedes dos?"
  },
  AvgCommunicate_66986_Option_3 = {
    Text = "No se pelearon, ¿verdad?"
  },
  AvgCommunicate_66986_Option_7 = {
    Text = "Eso es bueno, pero ¿qué método usas para volverte más puro?"
  },
  AvgCommunicate_66987_Content_1 = {
    Text = "Guardián, ¿conoces alguna receta con pescado?"
  },
  AvgCommunicate_66987_Content_10 = {
    Text = "Qué amable y gentil anciana."
  },
  AvgCommunicate_66987_Content_11 = {
    Text = "Mm. Así que quiero aprender a cocinar pescado también. La próxima vez, seré yo quien cocine para ella."
  },
  AvgCommunicate_66987_Content_12 = {
    Text = "¡Qué conmovedor! ¡Tienes que hacerlo sin falta! ¡Voy a interrogar al cocinero de la cafetería por ti ahora mismo!"
  },
  AvgCommunicate_66987_Content_13 = {Text = "Gracias."},
  AvgCommunicate_66987_Content_2 = {
    Text = "¿Recetas¿? ¿Vas a cocinar?"
  },
  AvgCommunicate_66987_Content_3 = {
    Text = "Mm, después de que asusté al pescador la última vez, ha habido tranquilidad cerca de la cascada durante bastante tiempo."
  },
  AvgCommunicate_66987_Content_4 = {
    Text = "Recientemente, una anciana ha estado viniendo aquí a pescar. Nunca hace ruido, así que nunca me dejé ver."
  },
  AvgCommunicate_66987_Content_5 = {
    Text = "Después, una vez, encendió un fuego y estaba asando el pescado que había atrapado."
  },
  AvgCommunicate_66987_Content_6 = {
    Text = "El olor era tan bueno que mi estómago hizo un pequeño ruido, y ella me descubrió."
  },
  AvgCommunicate_66987_Content_7 = {
    Text = "¿Eh? ¿También la asustaste?"
  },
  AvgCommunicate_66987_Content_8 = {
    Text = "No, me invitó a comer el pescado asado juntas. Estaba delicioso."
  },
  AvgCommunicate_66987_Content_9 = {
    Text = "Después empezó a traer una ollita cuando venía a pescar, luego preparaba sopa de pescado y la compartía conmigo."
  },
  AvgCommunicate_66987_Option_10 = {
    Text = "Qué amable y gentil anciana."
  },
  AvgCommunicate_66987_Option_12 = {
    Text = "¡Qué conmovedor! ¡Tienes que hacerlo sin falta! ¡Voy a interrogar al cocinero de la cafetería por ti ahora mismo!"
  },
  AvgCommunicate_66987_Option_2 = {
    Text = "¿Recetas¿? ¿Vas a cocinar?"
  },
  AvgCommunicate_66987_Option_7 = {
    Text = "¿Eh? ¿También la asustaste?"
  },
  AvgCommunicate_66988_Content_1 = {
    Text = "Hace poco recibí una buena suma de dinero, pero casi muero en el proceso. Por suerte, la diosa de la fortuna siempre me concede su Bendición."
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "Pero cuando empezamos a pelear, la trampa que había puesto se activó accidentalmente y le dio a él en su lugar."
  },
  AvgCommunicate_66988_Content_11 = {Text = "Huh?"},
  AvgCommunicate_66988_Content_12 = {
    Text = "Incluso le apliqué control de Sangre de emergencia, que es la única razón por la que seguía vivo cuando lo llevé a la comisaría."
  },
  AvgCommunicate_66988_Content_13 = {
    Text = "La policía me dio una recompensa. El convicto volvió a prisión, y escuché que le van a cambiar la sentencia a cadena perpetua."
  },
  AvgCommunicate_66988_Content_14 = {
    Text = "Solo le quedaban unos pocos años antes de poder salir. ¿Por qué tuvo que hacer algo tan estúpido... *suspiro*..."
  },
  AvgCommunicate_66988_Content_15 = {
    Text = "Dificultad para decir quién está peor, si tú o él..."
  },
  AvgCommunicate_66988_Content_16 = {
    Text = "Pero espera, ¿no vinieron ayer mismo personas de la Apuesta Lavka a buscarte para cobrarte una deuda? ¿Qué pasó con el dinero de tu recompensa?"
  },
  AvgCommunicate_66988_Content_17 = {
    Text = "Ajaja... Bueno, mi suerte es limitada, al fin y al cabo. Si la gasto toda por adelantado, es inevitable que pierda unas cuantas manos en la mesa..."
  },
  AvgCommunicate_66988_Content_18 = {
    Text = "Al oír eso, de repente me siento mucho mejor respecto a las cosas."
  },
  AvgCommunicate_66988_Content_2 = {
    Text = "¿Qué pasó??"
  },
  AvgCommunicate_66988_Content_3 = {
    Text = "Sabes, normalmente acepto encargos de detective fuera. Mi tasa de éxito resolviendo casos es tan alta que siempre he tenido mucha demanda."
  },
  AvgCommunicate_66988_Content_4 = {
    Text = "Pero, por otro lado, esos criminales que he enviado a prisión me detestan profundamente."
  },
  AvgCommunicate_66988_Content_5 = {
    Text = "Bueno, al fin y al cabo, perdieron de las formas más desconcertantes."
  },
  AvgCommunicate_66988_Content_6 = {
    Text = "Hace un par de días, un convicto se fugó de prisión y vigiló la Apuesta Lavka que frecuento durante días, hasta que finalmente me atrapó."
  },
  AvgCommunicate_66988_Content_7 = {
    Text = "¿¡Estaba ahí para vengarse de ti?!"
  },
  AvgCommunicate_66988_Content_8 = {
    Text = "Así es. Me siguió durante mucho tiempo y finalmente me acorraló en un callejón."
  },
  AvgCommunicate_66988_Content_9 = {
    Text = "Había colocado trampas en el callejón de antemano, con la intención de matarme."
  },
  AvgCommunicate_66988_Option_11 = {Text = "Huh?"},
  AvgCommunicate_66988_Option_15 = {
    Text = "Dificultad para decir quién está peor, si tú o él..."
  },
  AvgCommunicate_66988_Option_18 = {
    Text = "Al oír eso, de repente me siento mucho mejor respecto a las cosas."
  },
  AvgCommunicate_66988_Option_2 = {
    Text = "¿Qué pasó??"
  },
  AvgCommunicate_66988_Option_5 = {
    Text = "Bueno, al fin y al cabo, perdieron de las formas más desconcertantes."
  },
  AvgCommunicate_66988_Option_7 = {
    Text = "¿¡Estaba ahí para vengarse de ti?!"
  },
  AvgCommunicate_66989_Content_1 = {
    Text = "Guardián, he terminado de compilar los protocolos de gestión de crisis para Investigadores que me consultaste."
  },
  AvgCommunicate_66989_Content_10 = {
    Text = "Puede que sea más atenta a tus necesidades que esa Ramona, pero no lo olvides— yo también fui ella."
  },
  AvgCommunicate_66989_Content_11 = {
    Text = "Si quieres engañarme, vas a necesitar más práctica."
  },
  AvgCommunicate_66989_Content_12 = {
    Text = "Ay... ¡Mi sinceridad fue desperdiciada con la persona equivocada!"
  },
  AvgCommunicate_66989_Content_13 = {
    Text = "Entonces, sobre esos deberes— digo, esa pregunta— ¡al menos dame una pista de cómo abordarla!"
  },
  AvgCommunicate_66989_Content_14 = {Text = "¿Ramona?"},
  AvgCommunicate_66989_Content_15 = {Text = "Ramona—"},
  AvgCommunicate_66989_Content_2 = {
    Text = "¡Maravilloso! Sabía que eras la más confiable."
  },
  AvgCommunicate_66989_Content_3 = {
    Text = "Gracias, pero podrías preguntarle este tipo de cosas a la Ramona de tu propio mundo con la misma facilidad. ¿Por qué vienes a mí?"
  },
  AvgCommunicate_66989_Content_4 = {
    Text = "Ya sabes cómo es— esa Ramona siempre se ha tomado todo tan en serio. Si voy a preguntarle directamente, seguro que me hará pensar por mi cuenta."
  },
  AvgCommunicate_66989_Content_5 = {
    Text = "¡Pero la cuestión es esta! ¡Creo que el aprendizaje avanza más rápido mediante la discusión mutua y el intercambio de ideas!"
  },
  AvgCommunicate_66989_Content_6 = {
    Text = "¡Entendido!"
  },
  AvgCommunicate_66989_Content_7 = {
    Text = "Así que me estás pidiendo que te ayude a terminar los deberes."
  },
  AvgCommunicate_66989_Content_8 = {Text = "¿?!"},
  AvgCommunicate_66989_Content_9 = {
    Text = "E-eso no es para nada, cómo va a ser, ajaja..."
  },
  AvgCommunicate_66989_Option_12 = {
    Text = "Ay... ¡Mi sinceridad fue desperdiciada con la persona equivocada!"
  },
  AvgCommunicate_66989_Option_2 = {
    Text = "¡Maravilloso! Sabía que eras la más confiable."
  },
  AvgCommunicate_66989_Option_4 = {
    Text = "Ya sabes cómo es..."
  },
  AvgCommunicate_66989_Option_8 = {Text = "¿?!"},
  AvgCommunicate_66990_Content_1 = {
    Text = "Guardián, los nombres de todos son tan difíciles de escribir. ¡No puedo recordar quiénes son esos personajes!"
  },
  AvgCommunicate_66990_Content_10 = {
    Text = "Luego, ¡entonces lo cambiaré! No debes decirlo"
  },
  AvgCommunicate_66990_Content_11 = {
    Text = "Está bien, está bien, ¿cuáles son los nombres de Aigis y Lily?"
  },
  AvgCommunicate_66990_Content_12 = {
    Text = "Por supuesto, sus nombres son Aigis y Lily. Son amigas. ¡Las amigas no pueden tener el mismo nombre!"
  },
  AvgCommunicate_66990_Content_13 = {
    Text = "Así que, ¿por qué me llaman el Guardián..."
  },
  AvgCommunicate_66990_Content_14 = {
    Text = "¿No es más o menos lo mismo? ¡No seas tacaño! ¡Ayúdame a pensar en nombres en clave para los demás!"
  },
  AvgCommunicate_66990_Content_15 = {
    Text = "Creo que es más fiable encontrar primero a alguien que te enseñe a leer y escribir."
  },
  AvgCommunicate_66990_Content_2 = {
    Text = "Bueno, en efecto es un poco desafiante para ti. ¿Qué tal dejar que Ramona te dé una lección de alfabetización?"
  },
  AvgCommunicate_66990_Content_3 = {
    Text = "¡De ninguna manera! ¿Y qué si soy del West Side? ¿No puedes aceptar a alguien que no puede leer?"
  },
  AvgCommunicate_66990_Content_4 = {
    Text = "No lo hice... ¡Tú lo sacaste primero!"
  },
  AvgCommunicate_66990_Content_5 = {
    Text = "Hmph, un asunto tan trivial no podría engañar a un maestro ladrón como yo."
  },
  AvgCommunicate_66990_Content_6 = {
    Text = "He decidido darle a todos un nombre en clave para poder anotarlo."
  },
  AvgCommunicate_66990_Content_7 = {
    Text = "¿Por ejemplo?"
  },
  AvgCommunicate_66990_Content_8 = {
    Text = "Por ejemplo, robots, caracoles marinos, una noble roja, una persona de cabello rosa, ¡aún no he pensado en tantos!"
  },
  AvgCommunicate_66990_Content_9 = {
    Text = "¡Pshaw, esa es la \"Dama Roja\"! Y si la Muñeca escucha este apodo..."
  },
  AvgCommunicate_66990_Option_11 = {
    Text = "Está bien, está bien, ¿cuáles son los nombres de Aigis y Lily?"
  },
  AvgCommunicate_66990_Option_13 = {
    Text = "Así que, ¿por qué me llaman el Guardián..."
  },
  AvgCommunicate_66990_Option_15 = {
    Text = "Creo que es más fiable encontrar primero a alguien que te enseñe a leer y escribir."
  },
  AvgCommunicate_66990_Option_2 = {
    Text = "Bueno, en efecto es un poco difícil para ti..."
  },
  AvgCommunicate_66990_Option_4 = {
    Text = "No lo hice... ¡Tú lo sacaste primero!"
  },
  AvgCommunicate_66990_Option_7 = {
    Text = "¿Por ejemplo?"
  },
  AvgCommunicate_66990_Option_9 = {
    Text = "¡Pshaw, esa es la \"Dama Roja\"! Y si la Muñeca escucha este apodo..."
  },
  AvgCommunicate_66991_Content_1 = {
    Text = "¡¡Guardián Gato!! marrón ha desaparecido. ¿Lo has visto?"
  },
  AvgCommunicate_66991_Content_10 = {
    Text = "Supongo que es todo lo que podemos hacer por ahora... Gracias, Guardián."
  },
  AvgCommunicate_66991_Content_11 = {
    Text = "¿Ahora me vienes con formalidades? Déjame vestirme y salgo... Espera un momento."
  },
  AvgCommunicate_66991_Content_12 = {
    Text = "¿Por qué hay una cola que me resulta familiar en mi montón de ropa...?"
  },
  AvgCommunicate_66991_Content_13 = {
    Text = "¿¡marrón?! ¿¡marrón está en tu casa?!"
  },
  AvgCommunicate_66991_Content_14 = {
    Text = "Sí, puedes dejar de buscar. Además, se enredó en mi camisa, y tiene uno de mis calcetines en la boca y no lo suelta. ¿Tienes idea de qué va eso?"
  },
  AvgCommunicate_66991_Content_15 = {
    Text = "E-eso es definitivamente solo una manía de rata. ¡No tiene nada que ver conmigo!"
  },
  AvgCommunicate_66991_Content_16 = {
    Text = "En el peor de los casos, te compro un par de calcetines nuevos."
  },
  AvgCommunicate_66991_Content_2 = {
    Text = "¿marrón? ¿No está siempre contigo?"
  },
  AvgCommunicate_66991_Content_3 = {
    Text = "La mayor parte del tiempo, sí, pero a veces sale a robar... *ejem* a cazar cosas. Normalmente vuelve en medio día, ¡pero ya llevo un día entero sin verlo!"
  },
  AvgCommunicate_66991_Content_4 = {
    Text = "No te asustes. Déjame ayudarte a pensar en algo. ¿A dónde suele ir normalmente?"
  },
  AvgCommunicate_66991_Content_5 = {
    Text = "Va a la cocina más que a ningún sitio, pero esos tontos nunca podrían atrapar a marrón."
  },
  AvgCommunicate_66991_Content_6 = {
    Text = "También podría ir a los laboratorios a buscar cositas Brillantes, pero ya los revisé todos. Ni rastro de marrón por ninguna parte."
  },
  AvgCommunicate_66991_Content_7 = {
    Text = "...Vaya, vaya. Así que esa es la explicación de las piezas que desaparecen misteriosamente en los laboratorios."
  },
  AvgCommunicate_66991_Content_8 = {
    Text = "Ya he recorrido el campus varias veces. ¿Será posible que... que se lo haya comido ese maldito Gato de la escuela?"
  },
  AvgCommunicate_66991_Content_9 = {
    Text = "Hmm, ese Gato de la escuela probablemente no tiene ese tipo de gustos... Mira, voy a preparar ahora mismo un lote de carteles de Revelación de rata perdida y los colgaré por todo el campus. ¡Si todos ayudan a buscar, seguro que lo encontramos!"
  },
  AvgCommunicate_66991_Option_11 = {
    Text = "¿Ahora me vienes con formalidades? Déjame vestirme y salgo... Espera un momento."
  },
  AvgCommunicate_66991_Option_14 = {
    Text = "Sí, puedes dejar de buscar. Además..."
  },
  AvgCommunicate_66991_Option_2 = {
    Text = "¿marrón? ¿No está siempre contigo?"
  },
  AvgCommunicate_66991_Option_4 = {
    Text = "No te asustes. Déjame ayudarte a pensar en algo. ¿A dónde suele ir normalmente?"
  },
  AvgCommunicate_66991_Option_7 = {
    Text = "...Vaya, vaya. Así que esa es la explicación de las piezas que desaparecen misteriosamente en los laboratorios."
  },
  AvgCommunicate_66991_Option_9 = {
    Text = "Hmm, ese Gato de la escuela probablemente no tiene ese tipo de gustos..."
  },
  AvgCommunicate_66992_Content_1 = {
    Text = "Guardián, ya he cumplido el deseo que pediste la última vez."
  },
  AvgCommunicate_66992_Content_10 = {
    Text = "Para mantener el número de tareas sin cambios, se lo asigné a Ramona."
  },
  AvgCommunicate_66992_Content_11 = {
    Text = "No te preocupes, ella no se dio cuenta."
  },
  AvgCommunicate_66992_Content_12 = {
    Text = "No te preocupes, ella definitivamente se dio cuenta..."
  },
  AvgCommunicate_66992_Content_13 = {
    Text = "¡Oh no, alguien está tocando..."
  },
  AvgCommunicate_66992_Content_14 = {
    Text = "Celeste, deseo de nuevo. ¡Sálvame ahora!"
  },
  AvgCommunicate_66992_Content_15 = {
    Text = "¡Entendido! He anotado tu deseo y vendré de inmediato."
  },
  AvgCommunicate_66992_Content_16 = {
    Text = "Olvídalo, ya es demasiado tarde. ¡Primero contacta a la enfermería por mí!!!"
  },
  AvgCommunicate_66992_Content_2 = {
    Text = "Así que esta tarea completada en mi escritorio, ¿la trajiste aquí?"
  },
  AvgCommunicate_66992_Content_3 = {
    Text = "Sí, tu deseo es despertar y encontrar tus tareas ya completadas."
  },
  AvgCommunicate_66992_Content_4 = {
    Text = "Creo que podría haber dicho eso... ¡Pero esta tarea lleva el nombre de Ramona!"
  },
  AvgCommunicate_66992_Content_5 = {
    Text = "De nada. He investigado, y Ramona actualmente tiene las mejores calificaciones en tareas."
  },
  AvgCommunicate_66992_Content_6 = {
    Text = "¿Es esta una pregunta educada?!"
  },
  AvgCommunicate_66992_Content_7 = {
    Text = "¡Nuestra escritura es completamente diferente!"
  },
  AvgCommunicate_66992_Content_8 = {
    Text = "Olvídalo... Antes de que Ramona se dé cuenta, debería poder devolverla a tiempo."
  },
  AvgCommunicate_66992_Content_9 = {
    Text = "Espera, ¿dónde está mi cuaderno de tareas original?"
  },
  AvgCommunicate_66992_Option_12 = {
    Text = "No te preocupes, ella definitivamente se dio cuenta..."
  },
  AvgCommunicate_66992_Option_16 = {
    Text = "Olvídalo, ya es demasiado tarde. ¡Primero contacta a la enfermería por mí!!!"
  },
  AvgCommunicate_66992_Option_2 = {
    Text = "Así que esta tarea completada en mi escritorio, ¿la trajiste aquí?"
  },
  AvgCommunicate_66992_Option_4 = {
    Text = "Creo que podría haber dicho eso... ¡Pero esta tarea lleva el nombre de Ramona!"
  },
  AvgCommunicate_66992_Option_6 = {
    Text = "¿Es esta una pregunta educada?!"
  },
  AvgCommunicate_66992_Option_7 = {
    Text = "¡Nuestra escritura es completamente diferente!"
  },
  AvgCommunicate_66993_Content_1 = {
    Text = "Guardián, ¿puedo preguntar... cuándo tendrías tiempo para reunirte conmigo?"
  },
  AvgCommunicate_66993_Content_10 = {
    Text = "¡No puedo esperar! ¿De qué color piensas tejerme el suéter?"
  },
  AvgCommunicate_66993_Content_11 = {
    Text = "Creo que los suéteres rojos o blancos se ven bien. ¿Qué color quiere el Guardián?"
  },
  AvgCommunicate_66993_Content_12 = {Text = "¡Rojo!"},
  AvgCommunicate_66993_Content_13 = {Text = "¡Blanco!"},
  AvgCommunicate_66993_Content_14 = {
    Text = "¡Entendido, Aigis recuerda! ¡Haré lo mejor que pueda!"
  },
  AvgCommunicate_66993_Content_2 = {
    Text = "Ah, ¡por supuesto! Si estás ocupado, prestarme tu ropa personal estará bien"
  },
  AvgCommunicate_66993_Content_3 = {
    Text = "¿Ropa interior? ¿Para qué es esto?"
  },
  AvgCommunicate_66993_Content_4 = {
    Text = "Sí, así es. Recientemente, aprendí a tejer con la Hermana Mason, y hice bufandas y gorros para Lily y Jenkin."
  },
  AvgCommunicate_66993_Content_5 = {
    Text = "¡Vaya, impresionante!"
  },
  AvgCommunicate_66993_Content_6 = {
    Text = "No, es todo muy simple..."
  },
  AvgCommunicate_66993_Content_7 = {
    Text = "Pero ahora soy lo suficientemente hábil para tejer cosas más complejas, así que quiero tejer un suéter para el Guardián"
  },
  AvgCommunicate_66993_Content_8 = {
    Text = "Para el suéter, necesito tomar las medidas del Guardián. Por supuesto, si el Guardián no lo necesita, ¡entonces no hay problema!"
  },
  AvgCommunicate_66993_Content_9 = {
    Text = "¿Cómo podría ser eso? Si Aigis está pensando en mí, estoy más que feliz."
  },
  AvgCommunicate_66993_Option_12 = {Text = "¡Rojo!"},
  AvgCommunicate_66993_Option_13 = {Text = "¡Blanco!"},
  AvgCommunicate_66993_Option_3 = {
    Text = "¿Ropa interior? ¿Para qué es esto?"
  },
  AvgCommunicate_66993_Option_5 = {
