  },
  AvgCommunicate_66995_Content_4 = {
    Text = "Cortar con las tonterías. Ve a deshacerte de esa mujer llamada Lotan."
  },
  AvgCommunicate_66995_Content_5 = {
    Text = "Esa lunática me ha estado persiguiendo durante un mes entero."
  },
  AvgCommunicate_66995_Content_6 = {
    Text = "Y no importa cuánto pelee contra ella, simplemente no cae. ¡Me está volviendo loca!"
  },
  AvgCommunicate_66995_Content_7 = {
    Text = "Vaya, parece que tus habilidades son realmente impresionantes."
  },
  AvgCommunicate_66995_Content_8 = {
    Text = "Lotan rara vez encuentra una oponente que pueda seguir luchando contra Ella indefinidamente. Debe de estar muy complacida."
  },
  AvgCommunicate_66995_Content_9 = {
    Text = "Hmph, los halagos no te llevarán a ningún lado."
