  AvgCommunicate_66996_Content_1 = {
    Text = "Mitag es un lugar tan aburrido."
  },
  AvgCommunicate_66996_Content_10 = {
    Text = "Entonces te deseo que encuentres lo que buscas. Si alguna vez quieres volver, las puertas de Misaq siempre estarán abiertas para ti."
  },
  AvgCommunicate_66996_Content_2 = {
    Text = "Un montón de autoproclamados justos, manteniendo encerradas a un montón de bestias con collar."
  },
  AvgCommunicate_66996_Content_3 = {
    Text = "Realmente no sé por qué esa otra yo está dispuesta a participar en sus aburridos jueguitos. Pero pensándolo bien, considerando lo débil que es, todo tiene sentido."
  },
  AvgCommunicate_66996_Content_4 = {
    Text = "Nunca has sido protegida con determinación por nadie, así que naturalmente no comprendes los sentimientos y el significado de ser una guardiana."
  },
  AvgCommunicate_66996_Content_5 = {
    Text = "Helot es una guerrera excepcional. Simplemente eligió aceptar la calidez y la ayuda que otros le ofrecieron."
  },
  AvgCommunicate_66996_Content_6 = {
    Text = "Ja, como quieran. Si ella está dispuesta a llevar un collar, que se quede aquí."
  },
  AvgCommunicate_66996_Content_7 = {
    Text = "Me voy. Quedarme aquí más tiempo solo hará que una guerrera se vuelva torpe."
  },
  AvgCommunicate_66996_Content_8 = {
    Text = "Está bien, supongo que no responderías ni aunque te preguntara adónde vas."
  },
  AvgCommunicate_66996_Content_9 = {
    Text = "Dondequiera que pueda obtener fuerza, allí iré."
  },
  AvgCommunicate_66996_Option_10 = {
