  AvgCommunicate_66997_Content_1 = {
    Text = "Oye, escuché que Murphy no ha estado asistiendo a clase últimamente. ¿Qué está pasando?"
  },
  AvgCommunicate_66997_Content_10 = {
    Text = "Por supuesto, solo recupéralo."
  },
  AvgCommunicate_66997_Content_11 = {
    Text = "Hola, ¿es esto la policía? Alguien está a punto de cometer un crimen nuevamente."
  },
  AvgCommunicate_66997_Content_12 = {
    Text = "Está bien, lo compraré, ¿de acuerdo? Persona entrometida."
  },
  AvgCommunicate_66997_Content_13 = {
    Text = "Recuerda, te estoy observando. Si intentas algo divertido con Murphy... Hmph."
  },
  AvgCommunicate_66997_Content_2 = {
    Text = "Ella comió demasiados pastelitos y le dio dolor de estómago. Pero, ¿por qué no le preguntas a ella misma?"
  },
  AvgCommunicate_66997_Content_3 = {
    Text = "Suficiente charla. ¿Hiciste algo? Vi que seguiste comprándole pasteles."
  },
  AvgCommunicate_66997_Content_4 = {
    Text = "¿Qué tiene que ver conmigo? Ella misma no pudo resistir el viejo pastel del día anterior"
  },
  AvgCommunicate_66997_Content_5 = {
    Text = "No, ¿qué tiene que ver esto contigo?"
  },
  AvgCommunicate_66997_Content_6 = {
    Text = "No te atreverías."
  },
  AvgCommunicate_66997_Content_7 = {
    Text = "Hmph, ¿qué tiene de especial un par de pasteles? Encontraré un chef que los haga para ella todos los días."
  },
  AvgCommunicate_66997_Content_8 = {
    Text = "¿Realmente piensas que eres su padre, verdad? Nunca esperé que tuvieras un lado tan paternal."
  },
  AvgCommunicate_66997_Content_9 = {
    Text = "Espera, ¿cómo vas a encontrar al chef?"
  },
  AvgCommunicate_66997_Option_11 = {
    Text = "Hola, ¿es esto la policía? Alguien está a punto de cometer un crimen nuevamente."
  },
  AvgCommunicate_66997_Option_2 = {
