  AvgCommunicate_66998_Content_1 = {
    Text = "El Camino del fuerte es verdaderamente un Camino solitario."
  },
  AvgCommunicate_66998_Content_10 = {
    Text = "Dificultad para saber si hiciste algo bueno o malo ahí..."
  },
  AvgCommunicate_66998_Content_11 = {
    Text = "Hmph, Solo hice lo que se supone que hacen los fuertes."
  },
  AvgCommunicate_66998_Content_12 = {
    Text = "El bajo mundo de aquí se ha vuelto un poco aburrido. ¿Qué debería hacer ahora..."
  },
  AvgCommunicate_66998_Content_13 = {
    Text = "Sea lo que sea que estés planeando, me aseguraré de decirle a la policía que te vigile."
  },
  AvgCommunicate_66998_Content_2 = {
    Text = "¿Camino? ¿Qué hiciste? No me digas que estás en la comisaría otra vez."
  },
  AvgCommunicate_66998_Content_3 = {
    Text = "Ja, como si esos tontos pudieran retenerme alguna vez."
  },
  AvgCommunicate_66998_Content_4 = {
    Text = "Después de lo que pasó la última vez, ahora he conquistado con éxito la mitad del bajo mundo de Londinium."
  },
  AvgCommunicate_66998_Content_5 = {
    Text = "Lástima que las bandas de aquí son mucho más débiles que mis compatriotas Filisteos de antaño. Nunca llegarán a nada grande."
  },
  AvgCommunicate_66998_Content_6 = {
    Text = "¿¿Bandas?? ¿Qué clase de cosas fuera de la ley has estado haciendo?"
  },
  AvgCommunicate_66998_Content_7 = {
    Text = "Qué, si acabar con las bandas cuenta como infringir la ley, entonces no quedaría una sola persona buena en este mundo."
  },
  AvgCommunicate_66998_Content_8 = {
    Text = "Si me preguntas, Misaq o esa oficina de policía o como se llame todavía me debe una medalla de Honor Noble."
  },
  AvgCommunicate_66998_Content_9 = {
    Text = "Ahora que los he sometido a todos a golpes, ¿no has notado que la seguridad pública de la ciudad ha mejorado?"
  },
  AvgCommunicate_66998_Option_10 = {
    Text = "Dificultad para saber si hiciste algo bueno o malo ahí..."
  },
  AvgCommunicate_66998_Option_13 = {
