  AvgCommunicate_66999_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%, hace poco la Universidad de Misag me invitó a ayudar a grabar la música de transición entre clases."
  },
  AvgCommunicate_66999_Content_10 = {
    Text = "Si hay algo especial, probablemente esté rebosante de mis sentimientos por protegerte."
  },
  AvgCommunicate_66999_Content_11 = {
    Text = "Siempre he tenido un poco de problemas para levantarme. ¡Quizás algo de música revitalizante facilitaría las cosas!"
  },
  AvgCommunicate_66999_Content_12 = {
    Text = "Emocionante, ¿no? Entiendo."
  },
  AvgCommunicate_66999_Content_13 = {
    Text = "Aunque creo que dormir lo suficiente y de calidad es más importante, dadas las muchas responsabilidades que tienes, estar ocupado es inevitable."
  },
  AvgCommunicate_66999_Content_14 = {
    Text = "Espero que esta marcha te traiga poder."
  },
  AvgCommunicate_66999_Content_2 = {
    Text = "En la grabación, el Profesor Muñeca también mencionó que la escuela había desarrollado un nuevo tipo de grabadora. Es pequeña, con calidad de audio clara, e incluso puede ser llevada durante las misiones, con funciones de grabación y reproducción."
  },
  AvgCommunicate_66999_Content_3 = {
    Text = "Cuando lo vi, pensé en ti. Si es necesario, puedo grabar la pieza musical que te gusta para ti."
  },
  AvgCommunicate_66999_Content_4 = {
    Text = "Aunque no estoy a tu lado, habrá música que consuele tu alma."
  },
  AvgCommunicate_66999_Content_5 = {
    Text = "Hameln... ¡Estoy profundamente conmovido!"
  },
  AvgCommunicate_66999_Content_6 = {
    Text = "Todo es parte de mi deber. Entonces, ¿hay algo que te gustaría escuchar?"
  },
  AvgCommunicate_66999_Content_7 = {
    Text = "Hablando de eso, siempre duermo bien cada vez que tocas la canción de cuna."
  },
  AvgCommunicate_66999_Content_8 = {
    Text = "¿Qué tiene de especial esta melodía?"
  },
  AvgCommunicate_66999_Content_9 = {
    Text = "¿Este? Ya veo."
  },
  AvgCommunicate_66999_Option_11 = {
    Text = "Música para ayudar a despertarse"
  },
  AvgCommunicate_66999_Option_5 = {
    Text = "Hameln... ¡Estoy profundamente conmovido!"
  },
  AvgCommunicate_66999_Option_7 = {
    Text = "Música que ayuda a dormir"
  },
  AvgCommunicate_67000_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%. Recientemente he compuesto una nueva pieza y me gustaría invitarte a escucharla y dar tu opinión cuando tengas tiempo libre."
  },
  AvgCommunicate_67000_Content_10 = {
    Text = "Ah, tales requisitos son de hecho duros. Mis disculpas por no considerar esto a fondo."
  },
  AvgCommunicate_67000_Content_11 = {
    Text = "Quizás la próxima vez tocaré a tu lado y registraré cuidadosamente tu sueño."
  },
  AvgCommunicate_67000_Content_12 = {
    Text = "Espero que mi vigilancia te traiga paz en cada sueño."
  },
  AvgCommunicate_67000_Content_2 = {
    Text = "Eres demasiado amable, Hameln. Como un amateur sin experiencia, apenas estoy calificado para criticar tu trabajo."
  },
  AvgCommunicate_67000_Content_3 = {
    Text = "No, no te menosprecies; tus sugerencias son mi mayor fuente de motivación."
  },
  AvgCommunicate_67000_Content_4 = {
    Text = "¿Es realmente tan exagerado? Sin embargo, debo admitir vergonzosamente, siempre me quedo dormido mientras escucho tus nuevas composiciones..."
  },
  AvgCommunicate_67000_Content_5 = {
    Text = "Tu música es hermosa y ejecutada a la perfección, sin embargo, siempre me hace caer en un sueño instantáneamente. Tal vez realmente carezca de talento musical."
  },
  AvgCommunicate_67000_Content_6 = {
    Text = "No, esto es exactamente lo que quiero."
  },
  AvgCommunicate_67000_Content_7 = {
    Text = "Traer un sueño pacífico es mi misión y deber."
  },
  AvgCommunicate_67000_Content_8 = {
    Text = "Más bien, por favor describe en detalle los sentimientos que diferentes piezas te traen, así como la calidad de tu sueño, cuánto tiempo te lleva conciliar el sueño y la duración de tu sueño."
  },
  AvgCommunicate_67000_Content_9 = {Text = "Huh?"},
  AvgCommunicate_67000_Option_2 = {
    Text = "Realmente eres demasiado educado."
  },
  AvgCommunicate_67000_Option_4 = {
    Text = "¿Es realmente tan exagerado?"
  },
  AvgCommunicate_67000_Option_9 = {Text = "Huh?"},
  AvgCommunicate_67001_Content_1 = {
    Text = "Guardián, ¿estos zapatos de Danza nuevos en mi Puerta son tuyos?"
  },
  AvgCommunicate_67001_Content_10 = {
    Text = "No, para nada. Los zapatos de danza que me regalaste me Inspiran en cuerpo y alma."
  },
  AvgCommunicate_67001_Content_11 = {
    Text = "Saber que alguien espera con tantas ganas mi Danza, lo tomaré como motivación para seguir esforzándome y bailando."
  },
  AvgCommunicate_67001_Content_2 = {
    Text = "Ajaja, ¿fue tan obvio? ¿Pensé que no había dejado ninguna pista?"
  },
  AvgCommunicate_67001_Content_3 = {
    Text = "En Misaq, realmente no hay muchas personas que se fijen en mí y sean tan consideradas con los demás."
  },
  AvgCommunicate_67001_Content_4 = {
    Text = "Siempre he estado agradecida por todo lo que has hecho por mí. Gracias, Guardián."
  },
  AvgCommunicate_67001_Content_5 = {
    Text = "Ahora me estás haciendo sonrojar... En realidad, noté que los zapatos de danza que usaste en tu última actuación estaban algo desgastados, así que pensé en regalarte un par nuevo."
  },
  AvgCommunicate_67001_Content_6 = {
    Text = "Ah, en efecto, esos zapatos de danza me han acompañado durante mucho tiempo. Pero para un Bailarín, unos zapatos más nuevos no son necesariamente mejores."
  },
  AvgCommunicate_67001_Content_7 = {
    Text = "¿Eh? ¿Por qué?"
  },
  AvgCommunicate_67001_Content_8 = {
    Text = "Un par de zapatos de danza debe pasar por incontables horas de uso para adaptarse gradualmente a los pies. El desgaste de los zapatos suele reflejar la forma de los hábitos propios del Bailarín."
  },
  AvgCommunicate_67001_Content_9 = {
    Text = "Ya veo, parece que mis buenas intenciones fueron contraproducentes."
  },
  AvgCommunicate_67001_Option_2 = {
    Text = "Ajaja, ¿fue tan obvio? ¿Pensé que no había dejado ninguna pista?"
  },
  AvgCommunicate_67001_Option_5 = {
