  },
  AvgCommunicate_67001_Option_7 = {
    Text = "¿Eh? ¿Por qué?"
  },
  AvgCommunicate_67001_Option_9 = {
    Text = "Ya veo, parece que mis buenas intenciones fueron contraproducentes."
  },
  AvgCommunicate_67002_Content_1 = {
    Text = "Guardián, ¿esta invitación para actuar la enviaste tú?"
  },
  AvgCommunicate_67002_Content_10 = {
    Text = "Me has convencido, Guardián."
  },
  AvgCommunicate_67002_Content_11 = {
    Text = "Me prepararé bien. Gracias."
