  },
  AvgCommunicate_67002_Content_4 = {
    Text = "No requiere... ¿frente a nadie?"
  },
  AvgCommunicate_67002_Content_5 = {
    Text = "Así es. Hemos preparado una pantalla para ti, con equipo de iluminación colocado detrás."
  },
  AvgCommunicate_67002_Content_6 = {
    Text = "Cuando bailes detrás de la pantalla, la gente solo verá una sombra danzante. No podrán ver cómo luces."
  },
  AvgCommunicate_67002_Content_7 = {
    Text = "Tu actuación representa la Danza en sí misma, no a ti."
  },
  AvgCommunicate_67002_Content_8 = {
    Text = "La Danza en sí misma..."
  },
  AvgCommunicate_67002_Content_9 = {
    Text = "Liz, por favor, lleva la belleza de la Danza a todos. Esto es Solo un tributo puro a la belleza."
  },
  AvgCommunicate_67002_Option_3 = {
    Text = "Lo sé, y por eso esta actuación no requiere que bailes frente a nadie."
  },
  AvgCommunicate_67002_Option_5 = {
