  },
  AvgCommunicate_67003_Content_1 = {
    Text = "Guardián, hay una tarea personal que me gustaría encomendarte."
  },
  AvgCommunicate_67003_Content_10 = {
    Text = "Entiendo, pero ¿no sé nada sobre reparaciones mecánicas? Las piezas de un títere deben ser muy delicadas."
  },
  AvgCommunicate_67003_Content_11 = {
    Text = "Los cuerpos que hay allí están todos sin usar, así que no se necesitan reparaciones complejas."
  },
  AvgCommunicate_67003_Content_12 = {
    Text = "Solo necesitas aplicar algo de aceite para máquinas y mover las articulaciones un poco."
  },
  AvgCommunicate_67003_Content_13 = {
    Text = "Los cuerpos de títere pueden ser bastante pesados. Si de verdad no puedes cargarlos, puedes pedirle a Ramona o a Ogier que te acompañen."
