  },
  AvgCommunicate_67003_Content_5 = {
    Text = "Bien. Varios de mis experimentos han alcanzado recientemente etapas críticas. Llevo bastante tiempo viviendo en el laboratorio y simplemente no puedo ausentarme."
  },
  AvgCommunicate_67003_Content_6 = {
