  },
  AvgCommunicate_67003_Option_2 = {
    Text = "¿Una tarea personal?"
  },
  AvgCommunicate_67003_Option_4 = {
    Text = "¡Encantado de ayudar!"
  },
  AvgCommunicate_67003_Option_8 = {
    Text = "¿Un almacén de muñecas?"
