  AvgCommunicate_67006_Content_1 = {
    Text = "Encuentro que, aunque el progreso tecnológico y el desarrollo empresarial siguen siendo monótonos, han surgido muchos nuevos tipos de almohadas."
  },
  AvgCommunicate_67006_Content_10 = {
    Text = "Ese vendedor le dijo a Yu que Yu era un probador de sueño nato e insistió en que Yu probara almohadas para ellos a largo plazo."
  },
  AvgCommunicate_67006_Content_11 = {
    Text = "¿Te están haciendo trabajar? Si Miryam se entera, podría matarlos."
  },
  AvgCommunicate_67006_Content_12 = {
    Text = "Quería rechazarlo, pero dijo que los durmientes de prueba podrían llevarse todos los nuevos productos a casa gratis para probar."
  },
  AvgCommunicate_67006_Content_13 = {
    Text = "Al ver su sinceridad, acepté."
  },
  AvgCommunicate_67006_Content_14 = {
    Text = "Nunca esperé que fueras sobornado por una almohada... Quiero decir, qué rey tan amable."
  },
  AvgCommunicate_67006_Content_2 = {
    Text = "El otro día, pasé por el gran almacén en Londinium y vi que estaban promocionando una serie de nuevas almohadas."
  },
  AvgCommunicate_67006_Content_3 = {
    Text = "Solo miré dos veces, y el vendedor me arrastró para probar una cama de muestra. Qué grosero."
  },
  AvgCommunicate_67006_Content_4 = {
    Text = "Uh, realmente se parece a su estilo de ventas."
  },
  AvgCommunicate_67006_Content_5 = {
    Text = "Pero la llamada almohada de nubes es efectivamente extraordinariamente suave. No es como el plumón o el algodón; no puedo averiguar de qué está hecha."
  },
  AvgCommunicate_67006_Content_6 = {
    Text = "¿Probablemente algunos productos industriales? Cosas que definitivamente no existían en los viejos tiempos."
  },
  AvgCommunicate_67006_Content_7 = {
    Text = "Todo es porque la almohada era demasiado cómoda. Me sentí somnoliento y realmente me quedé dormido allí—qué vergonzoso."
  },
  AvgCommunicate_67006_Content_8 = {
    Text = "¿Es realmente tan cómodo?!"
  },
  AvgCommunicate_67006_Content_9 = {
