  AvgCommunicate_67007_Content_1 = {
    Text = "Maestro, hoy Aigis nos contó a mí y a Jenkin sobre los juguetes de la Casa de pobres."
  },
  AvgCommunicate_67007_Content_10 = {
    Text = "No, Guardián, por favor no escuches a Jenkin. Mi muñeca está perfectamente bien, ¡no hace falta comprar una nueva!"
  },
  AvgCommunicate_67007_Content_11 = {
    Text = "Está bien, está bien, está bien, ¡compraremos todo, todo!"
  },
  AvgCommunicate_67007_Content_12 = {
    Text = "Guardián, el comunicador acaba de ser arrebatado y se cayó al suelo. Parece que se desprendieron algunas piezas."
  },
  AvgCommunicate_67007_Content_13 = {
    Text = "¿Podemos comprar uno nuevo de esto también?"
  },
  AvgCommunicate_67007_Content_14 = {Text = "¿Eh???"},
  AvgCommunicate_67007_Content_2 = {
    Text = "Dijo que hay un juguete llamado tangram, hecho de siete piezas planas como bloques que se pueden organizar en muchos patrones y también encajar de vuelta en un gran marco cuadrado."
  },
  AvgCommunicate_67007_Content_3 = {
    Text = "Jenkin dijo que podríamos hacer uno de papel, pero después de pensarlo juntos durante mucho tiempo, todavía no pudimos descifrar cómo es el tangram."
  },
  AvgCommunicate_67007_Content_4 = {
    Text = "Guardián, ¿alguna vez has visto cómo es un tangram?"
  },
  AvgCommunicate_67007_Content_5 = {
    Text = "He visto uno antes, pero ahora que lo mencionas, también he olvidado exactamente cómo es..."
  },
  AvgCommunicate_67007_Content_6 = {
    Text = "No te preocupes. Como adulta, tengo un superpoder especial — el poder del dinero. Los llevaré a todos a comprar juguetes ahora mismo."
  },
  AvgCommunicate_67007_Content_7 = {
    Text = "¡Gracias, Guardián! ¡Iré a decirle a Jenkin y a Aigis!"
  },
  AvgCommunicate_67007_Content_8 = {
    Text = "¡Oye, Guardián, Aigis dijo que también hay un juguete llamado cubo de Rubik con muchos cuadritos que puedes girar y girar! ¡También queremos eso!"
  },
  AvgCommunicate_67007_Content_9 = {
    Text = "¡Y la muñeca de Aigis también está vieja, así que tienes que comprarle una nueva!"
  },
  AvgCommunicate_67007_Option_11 = {
    Text = "Está bien, está bien, está bien, ¡compraremos todo, todo!"
  },
  AvgCommunicate_67007_Option_14 = {Text = "¿Eh???"},
  AvgCommunicate_67007_Option_5 = {
    Text = "He visto uno antes, pero ahora que lo mencionas, también he olvidado exactamente cómo es..."
  },
  AvgCommunicate_67008_Content_1 = {
    Text = "*suspiro*..."
  },
  AvgCommunicate_67008_Content_10 = {
    Text = "Para alguien tan inútil como yo, ¿no sería mejor simplemente rendirse y encontrar una tumba para esperar la muerte?"
  },
  AvgCommunicate_67008_Content_11 = {
    Text = "¡No tiene que ser tan extremo!"
  },
  AvgCommunicate_67008_Content_12 = {
    Text = "Siempre he sentido que no era tu culpa. Fuiste engañado por quienes te vendieron remedios; simplemente aprovecharon tus sentimientos de desesperación."
  },
  AvgCommunicate_67008_Content_13 = {
    Text = "Tu cuerpo no es incapaz de romper a través; ¡simplemente está envenenado y enfermo!"
  },
  AvgCommunicate_67008_Content_14 = {
    Text = "¿Es así? Lo que dijiste parece tener sentido."
  },
  AvgCommunicate_67008_Content_15 = {
    Text = "¡¿No he estado diciendo esto todo el tiempo!!"
  },
  AvgCommunicate_67008_Content_16 = {
    Text = "Así que estoy enfermo, mi despertar aún tiene esperanza"
  },
  AvgCommunicate_67008_Content_17 = {
    Text = "Mm-hmm... Así es, solo necesitas concentrarte en recuperarte."
  },
  AvgCommunicate_67008_Content_18 = {
    Text = "Entiendo, gracias, Guardián."
  },
  AvgCommunicate_67008_Content_19 = {
    Text = "Entonces... ¿puedes prestarme cincuenta para ver a un médico?"
  },
  AvgCommunicate_67008_Content_2 = {
