  AvgCommunicate_67012_Content_3 = {
    Text = "Mm... Si acaso pasas por el centro, tienes algo de tiempo y es conveniente, ¿podrías traerme un nuevo ovillo de hilo?"
  },
  AvgCommunicate_67012_Content_4 = {
    Text = "Quiero remendar la muñeca, y el vestido, y la ropa de todos. La capa de Jenkin también se está desgastando un poco..."
  },
  AvgCommunicate_67012_Content_5 = {
    Text = "¿No son suficientes los ovillos? Lo recordaré. ¿Qué color quieres?"
  },
  AvgCommunicate_67012_Content_6 = {
    Text = "¿Qué tal si te llevo a comprar ropa nueva? Invitemos a Jenkin y Lily."
  },
  AvgCommunicate_67012_Content_7 = {
    Text = "No, ¡no es necesario! Mis ropas aún son utilizables. Sería un desperdicio..."
  },
  AvgCommunicate_67012_Content_8 = {
    Text = "¿Cómo podría ser un desperdicio, Aigis? No hay necesidad de ser tan cauteloso. Todos estamos felices de cumplir tus deseos."
  },
  AvgCommunicate_67012_Content_9 = {
    Text = "La financiación diaria de Mythag es más que suficiente. Nadie te abandonará de nuevo, ¿entiendes?"
  },
  AvgCommunicate_67012_Option_11 = {Text = "Bien."},
  AvgCommunicate_67012_Option_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_67012_Option_5 = {
    Text = "¿No son suficientes los ovillos? Lo recordaré. ¿Qué color quieres?"
  },
  AvgCommunicate_67012_Option_8 = {
    Text = "¿Cómo podría ser un desperdicio?"
  },
  AvgCommunicate_67013_Content_1 = {
    Text = "Guardián, ¡Ayúdame! ¡Siento como si hormigas me recorrieran todo el cuerpo!"
  },
  AvgCommunicate_67013_Content_10 = {
    Text = "Vacía los sacos de boxeo de la sala de entrenamiento y métete dentro. Registro: no hagas ni un ruido."
  },
  AvgCommunicate_67013_Content_11 = {
    Text = "Dios mío, Guardián, ¡eres el mejor!"
  },
  AvgCommunicate_67013_Content_2 = {
    Text = "...¿Qué te pasa? Si estás enfermo, puedes ir a la enfermería."
  },
  AvgCommunicate_67013_Content_3 = {
    Text = "Yo, no lo sé, siento que apenas puedo respirar..."
  },
  AvgCommunicate_67013_Content_4 = {
    Text = "¿Tan grave? ¿Dónde estás? ¿Llamo a un Médico tratante de inmediato?"
  },
  AvgCommunicate_67013_Content_5 = {
    Text = "Estoy en... estoy en tu Puerta, ¡por favor, solo dame una paliza! ¡Llevo tres días sin que me peguen! ¡Me siento fatal!"
  },
  AvgCommunicate_67013_Content_6 = {Text = "..."},
  AvgCommunicate_67013_Content_7 = {Text = "..."},
  AvgCommunicate_67013_Content_8 = {
    Text = "Ya contacté a los Vigilantes y te conseguí un nuevo trabajo. Ellos te llevarán."
  },
  AvgCommunicate_67013_Content_9 = {
    Text = "¿Qué trabajo?"
  },
  AvgCommunicate_67013_Option_10 = {
    Text = "Vacía los sacos de boxeo de la sala de entrenamiento y métete dentro. Registro: no hagas ni un ruido."
  },
  AvgCommunicate_67013_Option_2 = {
    Text = "...¿Qué te pasa? Si estás enfermo, puedes ir a la enfermería."
  },
  AvgCommunicate_67013_Option_4 = {
    Text = "¿Tan grave? ¿Dónde estás? ¿Llamo a un Médico tratante de inmediato?"
  },
  AvgCommunicate_67013_Option_6 = {Text = "..."},
  AvgCommunicate_67013_Option_7 = {Text = "..."},
  AvgCommunicate_67014_Content_1 = {
    Text = "Guardián, a veces me pregunto si todo lo que he hecho ha satisfecho verdaderamente a mi rey"
  },
  AvgCommunicate_67014_Content_10 = {
    Text = "Pero creo que lo único que los dioses pueden sentir es la devota y apasionada dedicación de sus seguidores."
  },
  AvgCommunicate_67014_Content_11 = {
    Text = "Así que tal vez lo que hiciste no es la parte más importante; lo que importa es el corazón que pusiste en ello. Después de todo, Tulu nunca te detuvo, ¿verdad?"
  },
  AvgCommunicate_67014_Content_12 = {
    Text = "Nunca esperé ser iluminado por un escéptico como tú. Tus palabras me han dejado una profunda impresión. Gracias."
  },
  AvgCommunicate_67014_Content_2 = {
    Text = "¿Es el camino que he elegido realmente el correcto?"
  },
  AvgCommunicate_67014_Content_3 = {
    Text = "Nunca esperé que reflexionaras sobre ti mismo un día."
  },
  AvgCommunicate_67014_Content_4 = {
    Text = "Porque yo, también, me siento confundido, cansado y desalentado. Si todo lo que hago es correcto, ¿por qué el Rey no me ha respondido?"
  },
  AvgCommunicate_67014_Content_5 = {
    Text = "Aunque no soy tan devoto como tú, creo que lo que los seguidores hacen por Dios no es necesariamente lo que Dios necesita."
  },
  AvgCommunicate_67014_Content_6 = {
    Text = "¿Qué dijiste?"
  },
  AvgCommunicate_67014_Content_7 = {
    Text = "Hola, ¡hey, no te apresures! Aún no he terminado de hablar."
  },
  AvgCommunicate_67014_Content_8 = {
    Text = "La diferencia entre mortales y dioses es similar a la que existe entre hormigas y humanos. No creo que los humanos puedan comprender completamente las necesidades de los dioses."
  },
  AvgCommunicate_67014_Content_9 = {
    Text = "Hormigas... Quizás tienes razón."
  },
  AvgCommunicate_67014_Option_10 = {
    Text = "Pero creo que..."
  },
  AvgCommunicate_67014_Option_3 = {
    Text = "Nunca esperé que reflexionaras sobre ti mismo un día."
  },
  AvgCommunicate_67014_Option_5 = {
    Text = "Aunque mi fe no es tan devota como la tuya..."
  },
  AvgCommunicate_67014_Option_7 = {
    Text = "Hola, ¡hey, no te apresures! Aún no he terminado de hablar."
  },
  AvgCommunicate_67015_Content_1 = {
    Text = "Guardián, las charlas que di en el campus y los panfletos promocionales que imprimí han sido muy bien recibidos."
  },
  AvgCommunicate_67015_Content_10 = {
    Text = "¿La señorita Sanga? Rara vez la veo a Ella. He oído que es una escultora excepcional."
  },
  AvgCommunicate_67015_Content_11 = {
    Text = "Si ella está dispuesta a esculpir para mi Señor, sería perfecto; el Reino Divino la protegerá."
  },
  AvgCommunicate_67015_Content_2 = {
    Text = "Han desarrollado sentimientos de reverencia hacia mi gran Señor. Algunos de los fieles me dijeron que desean obtener estatuillas en miniatura del Señor, para poder Liberar su Oración y adorar cómodamente en su habitación."
  },
  AvgCommunicate_67015_Content_3 = {
    Text = "Creo que tienen razón. ¿Dónde podría encontrar un artesano para hacer un lote Personalizado de esas estatuillas?"
  },
  AvgCommunicate_67015_Content_4 = {
    Text = "¿Estatuillas en miniatura? Algo no me cuadra..."
  },
  AvgCommunicate_67015_Content_5 = {
    Text = "¿Qué pasa? Estas estatuillas requieren una artesanía muy fina. ¿De verdad no hay artesanos así en Misaq?"
  },
  AvgCommunicate_67015_Content_6 = {
    Text = "No es realmente por los artesanos... es Solo que tengo la sensación de que no quieren esas estatuillas para Oración y adoración..."
  },
  AvgCommunicate_67015_Content_7 = {
    Text = "Imposible. He presenciado su Fervor por mi Señor de primera mano. Incluso se preocupan por cada detalle de las preferencias y la vida diaria del Señor."
  },
  AvgCommunicate_67015_Content_8 = {
    Text = "Eso Solo demuestra lo que digo... Da igual, lo que te haga feliz."
  },
  AvgCommunicate_67015_Content_9 = {
    Text = "Le preguntaré a Sanga si está dispuesta a hacer este lote de estatuillas."
  },
  AvgCommunicate_67015_Option_4 = {
    Text = "¿Estatuillas en miniatura? Algo no me cuadra..."
  },
  AvgCommunicate_67015_Option_6 = {
    Text = "No es realmente por los artesanos..."
  },
  AvgCommunicate_67015_Option_8 = {
    Text = "Eso Solo demuestra lo que digo... Da igual, lo que te haga feliz."
  },
  AvgCommunicate_67016_Content_1 = {
    Text = "Suspiro, Guardián, he venido a confesar mi negligencia ante ti y el Señor Dexter, y espero recibir su perdón."
  },
  AvgCommunicate_67016_Content_10 = {
    Text = "Ejem, es bastante desafortunado, pero no es tu culpa. No te culpes."
  },
  AvgCommunicate_67016_Content_11 = {
    Text = "No, todo esto fue por mi descuido. Haré una autocrítica pública y reforzaré la gestión del día a día."
  },
  AvgCommunicate_67016_Content_2 = {
    Text = "Debido a mi mala gestión personal, dos pacientes del Sanatorio fueron gravemente envenenados. Afortunadamente, ya están fuera de peligro tras un tratamiento de emergencia."
  },
  AvgCommunicate_67016_Content_3 = {
    Text = "¿Eh? ¿Qué pasó?"
  },
  AvgCommunicate_67016_Content_4 = {
    Text = "Bueno, detrás del Sanatorio hay un pequeño estanque que poca gente suele visitar."
  },
  AvgCommunicate_67016_Content_5 = {
    Text = "Conoces mi afición por el agua. En los días laborales ajetreados, me escabullía silenciosamente al estanque por la noche y disfrutaba de un momento de Tranquilidad en el mundo submarino."
  },
  AvgCommunicate_67016_Content_6 = {
    Text = "Mm... Eso es comprensible. El trabajo siempre es estresante, después de todo."
  },
  AvgCommunicate_67016_Content_7 = {
    Text = "Quizás porque fui demasiadas veces, las Toxinas de mi cuerpo se fueron esparciendo gradualmente en el estanque y en los peces que vivían allí."
  },
  AvgCommunicate_67016_Content_8 = {
    Text = "Originalmente este estanque no estaba en el área de actividades de los pacientes, pero hace dos días, dos pacientes glotones se escaparon al estanque para pescar y asar los peces para comerlos."
  },
  AvgCommunicate_67016_Content_9 = {
    Text = "Para cuando el Personal médico los Descubrió, ya estaban echando espuma por la boca y se habían desplomado en el suelo..."
  },
  AvgCommunicate_67016_Option_10 = {
    Text = "Ejem, es bastante desafortunado, pero no es tu culpa. No te culpes."
  },
  AvgCommunicate_67016_Option_3 = {
    Text = "¿Eh? ¿Qué pasó?"
  },
  AvgCommunicate_67016_Option_6 = {
    Text = "Mm... Eso es comprensible. El trabajo siempre es estresante, después de todo."
  },
  AvgCommunicate_67017_Content_1 = {
    Text = "Guardián, un invitado que visitaba Misaq escuchó por casualidad mi canto durante un ensayo."
  },
  AvgCommunicate_67017_Content_10 = {
    Text = "Amas cantar, amas actuar... ¿por qué no dejar que más personas escuchen tu voz?"
  },
  AvgCommunicate_67017_Content_11 = {
    Text = "Amarlo... Ahora lo entiendo. Gracias, Guardián."
  },
  AvgCommunicate_67017_Content_12 = {
    Text = "Intentaré brillar una vez más en este planeta."
  },
  AvgCommunicate_67017_Content_2 = {
    Text = "Ahora me invitan a colaborar con su compañía para lanzar algunos discos. ¿Debería aceptar?"
  },
  AvgCommunicate_67017_Content_3 = {
    Text = "¡Creo que deberías! Si no recuerdo mal, solías ser una cantante famosa, ¿verdad?"
  },
  AvgCommunicate_67017_Content_4 = {
    Text = "Sí, mis canciones fueron una vez las más populares en Wild Star, pero la mayor parte del tiempo, solo era para comerciar con la nobleza."
  },
  AvgCommunicate_67017_Content_5 = {
    Text = "Ahora que he recuperado a mi hermana, ya no necesito nada más."
  },
  AvgCommunicate_67017_Content_6 = {
    Text = "Entonces, ¿qué hay de ti? ¿Sigues sintiéndote feliz cuando cantas?"
  },
  AvgCommunicate_67017_Content_7 = {
    Text = "Feliz... Supongo que soy feliz. Después de todo, cantar es lo solo que sé hacer."
  },
  AvgCommunicate_67017_Content_8 = {
    Text = "No, Tinct, nadie seguiría practicando canto todos los días si no lo amara de verdad."
  },
  AvgCommunicate_67017_Content_9 = {
    Text = "Aferrarse a lo que amas es solo algo natural."
  },
  AvgCommunicate_67017_Option_3 = {
    Text = "¡Creo que deberías! Si no recuerdo mal, solías ser una cantante famosa, ¿verdad?"
  },
  AvgCommunicate_67017_Option_6 = {
    Text = "Entonces, ¿qué hay de ti? ¿Sigues sintiéndote feliz cuando cantas?"
  },
  AvgCommunicate_67017_Option_8 = {
    Text = "Nadie seguiría practicando canto todos los días si no lo amara de verdad."
  },
  AvgCommunicate_67018_Content_1 = {
    Text = "El mensajero pálido, quería contactarte específicamente para informarte de que visitaré Misaq pronto."
  },
  AvgCommunicate_67018_Content_2 = {
    Text = "Mi visita anterior parece haber sido de cierta ayuda para todos, y me han invitado a volver para charlar con todos en el auditorio."
  },
  AvgCommunicate_67018_Content_3 = {
    Text = "Si resulta que tienes algo de tiempo libre, espero que podamos vernos en el campus."
  },
  AvgCommunicate_67018_Content_4 = {
    Text = "¡Me encantaría!"
  },
  AvgCommunicate_67018_Content_5 = {
    Text = "Maravilloso. Reservaré tiempo solo para ti, para escuchar todo lo que quieras contarme."
  },
  AvgCommunicate_67018_Content_6 = {
    Text = "¿Solo nosotros dos?"
  },
  AvgCommunicate_67018_Content_7 = {
    Text = "Sí. Después de todo, esto no es un servicio de adoración— Solo un encuentro entre amigos, ¿no es así?"
  },
  AvgCommunicate_67018_Content_8 = {
    Text = "No hay problema. Te haré un recorrido por los lugares de interés de Misaq. ?Quizás te gustaría probar la cafetería de los Cuerpos Despertados?"
  },
  AvgCommunicate_67018_Content_9 = {
    Text = "Seguiré tus planes. Estoy deseando que llegue el momento."
  },
  AvgCommunicate_67018_Option_4 = {
    Text = "¡Me encantaría!"
  },
  AvgCommunicate_67018_Option_6 = {
    Text = "¿Solo nosotros dos?"
  },
  AvgCommunicate_67018_Option_8 = {
    Text = "¡No hay problema!"
  },
  AvgCommunicate_67019_Content_1 = {
    Text = "Mensajero pálido, el distrito del Santuario celebrará una gran misa pronto."
  },
  AvgCommunicate_67019_Content_10 = {
    Text = "Tu corazón sincero me llena de tanta calidez. Entonces no me negaré más."
  },
  AvgCommunicate_67019_Content_11 = {
    Text = "Ven cuando tengas tiempo libre y ayúdame con algo de limpieza y decoración sencillas."
  },
  AvgCommunicate_67019_Content_12 = {
    Text = "No hay problema, ¡nos vemos entonces!"
  },
  AvgCommunicate_67019_Content_13 = {
    Text = "Gracias una vez más, mensajero pálido. Que el Padre Dios vigile El Camino de la Mecha ante ti."
  },
  AvgCommunicate_67019_Content_2 = {
    Text = "Yo presidiré la ceremonia, compartiendo las enseñanzas del Padre Dios."
  },
  AvgCommunicate_67019_Content_3 = {
    Text = "Creyentes de Londinium y las áreas circundantes asistirán. Si te interesa, eres bienvenido a unirte a esta celebración eucarística también."
  },
  AvgCommunicate_67019_Content_4 = {
    Text = "¡Me encantaría! Pero con tantos creyentes que atender, los preparativos para esta misa deben ser todo un desafío."
  },
  AvgCommunicate_67019_Content_5 = {
    Text = "Siempre eres tan atento, amable y considerado con los demás."
  },
  AvgCommunicate_67019_Content_6 = {
    Text = "En efecto, asegurarse de que todos estén debidamente acomodados y puedan sentir la gracia del Padre Dios requiere una gran cantidad de preparativos."
  },
  AvgCommunicate_67019_Content_7 = {
    Text = "Pero no te preocupes. Tengo una amplia Experiencia presidiendo la Misa y puedo manejar bien estos asuntos triviales."
  },
  AvgCommunicate_67019_Content_8 = {
    Text = "Ninguna cantidad de Experiencia te da manos extra. Si es posible, ¡déjame venir temprano y ayudarte!"
  },
  AvgCommunicate_67019_Content_9 = {
    Text = "Después de todo, para un evento tan grandioso, cuanto más minuciosos sean los preparativos, mejor."
  },
  AvgCommunicate_67019_Option_12 = {
    Text = "No hay problema, ¡nos vemos entonces!"
  },
  AvgCommunicate_67019_Option_4 = {
    Text = "¡Me encantaría!"
  },
  AvgCommunicate_67019_Option_8 = {
    Text = "Si es posible, ¡déjame venir temprano y ayudarte!"
  },
  AvgCommunicate_67020_Content_1 = {
    Text = "Ay, desde que Misaq emitió esa orden de restricción, ya no vienen linduras a hacerme compañía."
  },
  AvgCommunicate_67020_Content_10 = {
    Text = "Muy bien, entonces tendré que rezar para que el Sol se ponga rápido."
  },
  AvgCommunicate_67020_Content_11 = {
    Text = "Ah, ya estoy deseando que llegue la luz de luna de esta noche."
  },
  AvgCommunicate_67020_Content_2 = {
    Text = "Diciendo que sin tu acompañamiento, nadie más tiene permitido verme."
  },
  AvgCommunicate_67020_Content_3 = {
    Text = "Tú, oh tú, dime... ¿acaso te pusiste celoso/a y me denunciaste ante la escuela?"
  },
  AvgCommunicate_67020_Content_4 = {
    Text = "Tú fuiste quien primero embrujó a estudiantes para que bebieran cosas extrañas..."
  },
  AvgCommunicate_67020_Content_5 = {
    Text = "Eso era claramente un regalo de amor. ¿De verdad soy tan despreciable a tus ojos?"
  },
  AvgCommunicate_67020_Content_6 = {
    Text = "Cada día te espero en soledad, y aun así es como me ves..."
  },
  AvgCommunicate_67020_Content_7 = {
    Text = "¡Para! Lo entiendo, vendré a visitarte más seguido."
  },
  AvgCommunicate_67020_Content_8 = {
    Text = "Qué criatura tan considerada. Pero quiero verte a cada momento—ahora mismo—no quiero esperar ni un segundo."
  },
  AvgCommunicate_67020_Content_9 = {
    Text = "Esta noche, ¡iré esta noche, de acuerdo!"
  },
  AvgCommunicate_67020_Option_4 = {
    Text = "Tú fuiste quien primero embrujó a estudiantes para que bebieran cosas extrañas..."
  },
  AvgCommunicate_67020_Option_7 = {
    Text = "¡Para! Lo entiendo, vendré a visitarte más seguido."
  },
  AvgCommunicate_67020_Option_9 = {
    Text = "Esta noche, ¡iré esta noche, de acuerdo!"
  },
  AvgCommunicate_67021_Content_1 = {
    Text = "Guardián, perdona las molestias. ¿Tienes algo de tiempo libre recientemente?"
  },
  AvgCommunicate_67021_Content_10 = {
    Text = "Así que, ?me estás preguntando si podría ir contigo?"
  },
  AvgCommunicate_67021_Content_11 = {
    Text = "Mm, ?estaría bien?"
  },
  AvgCommunicate_67021_Content_12 = {
    Text = "!Por supuesto! !Parece que será muy divertido!"
  },
  AvgCommunicate_67021_Content_13 = {
    Text = "!Gracias, Guardián! Tenerte conmigo me hace sentir mucho más tranquila."
  },
  AvgCommunicate_67021_Content_14 = {
    Text = "Escuché que los poemas escritos en el momento tienen la posibilidad de ganar un premio. Si tengo la suerte de conseguir uno, te lo daré como regalo de agradecimiento."
  },
  AvgCommunicate_67021_Content_2 = {
    Text = "¿Qué ocurre? Es raro que vengas a buscarme por tu cuenta."
  },
  AvgCommunicate_67021_Content_3 = {
    Text = "Bueno, hay una feria de poesía próximamente en Londinium. Se venderán muchos libros nuevos y antiguos, y muchos poetas asistirán para intercambiar ideas."
  },
  AvgCommunicate_67021_Content_4 = {
    Text = "Los organizadores también me invitaron a montar un puesto para compartir mi colección de poesía."
  },
  AvgCommunicate_67021_Content_5 = {
    Text = "Su invitación fue tan amable que acepté sin darme cuenta, pero..."
  },
  AvgCommunicate_67021_Content_6 = {
    Text = "Pero, ?ir a atender un puesto sola te pone demasiado nerviosa?"
  },
  AvgCommunicate_67021_Content_7 = {
    Text = "Mm... Siempre me entiendes."
  },
  AvgCommunicate_67021_Content_8 = {
    Text = "Pero no quiero echarme atrás en algo que ya acepté, y el evento parece muy interesante. Escuché que incluso hay una cadena de escritura colaborativa en vivo."
  },
  AvgCommunicate_67021_Content_9 = {
    Text = "Así que..."
  },
  AvgCommunicate_67021_Option_10 = {
    Text = "Así que, ?me estás preguntando si podría ir contigo?"
  },
  AvgCommunicate_67021_Option_12 = {
    Text = "!Por supuesto! !Parece que será muy divertido!"
  },
  AvgCommunicate_67021_Option_2 = {
    Text = "¿Qué ocurre? Es raro que vengas a buscarme por tu cuenta."
  },
  AvgCommunicate_67021_Option_6 = {
    Text = "Pero, ?ir a atender un puesto sola te pone demasiado nerviosa?"
  },
  AvgCommunicate_67022_Content_1 = {
    Text = "Guardián, por fin se me ha ocurrido una buena forma de dormir en paz."
  },
  AvgCommunicate_67022_Content_10 = {
    Text = "¡Eso ya es una gran molestia para los demás!"
  },
  AvgCommunicate_67022_Content_11 = {
    Text = "¡Solo piensa en ello como una pieza de arte decorativa! ¡No ronco cuando duermo!"
  },
  AvgCommunicate_67022_Content_12 = {
    Text = "Espera, no me digas que la persona en quien confías soy yo."
  },
  AvgCommunicate_67022_Content_13 = {
    Text = "¡Por supuesto! El Guardián más amable, más confiable y más poderoso de Misaq — ¡no hay nadie más adecuado para esto que tú!"
  },
  AvgCommunicate_67022_Content_14 = {
    Text = "Planeo mover la Esfera del Sueño esta noche. Si quieres, incluso puedo charlar contigo antes de dormir～"
  },
  AvgCommunicate_67022_Content_15 = {Text = "Keeper?"},
  AvgCommunicate_67022_Content_16 = {Text = "Keeper??"},
  AvgCommunicate_67022_Content_2 = {
    Text = "¡Felicidades! ¿Cuál es el método?"
  },
  AvgCommunicate_67022_Content_3 = {
    Text = "Diseñé una esfera de sueño que mantiene su interior iluminado durante toda la noche. Así no hacen falta luces potentes y se asegura de que no haya puntos ciegos con sombras cerca."
  },
  AvgCommunicate_67022_Content_4 = {
    Text = "Suena genial. Ahora por fin puedes dejar de irrumpir en las habitaciones de los demás todos los días y que te echen a patadas."
  },
  AvgCommunicate_67022_Content_5 = {
    Text = "¡No! Para prevenir cualquier mal funcionamiento de la Esfera de Sueño y evitar peligros externos, necesito colocar la Esfera de Sueño en algún lugar donde haya gente alrededor."
  },
  AvgCommunicate_67022_Content_6 = {
    Text = "? ¿Quieres poner este trasto en la habitación de otra persona?"
  },
  AvgCommunicate_67022_Content_7 = {
    Text = "¡Exacto! Le entregaré el botón de reinicio de emergencia de la Esfera de Sueño a alguien de confianza. ¡Así nada puede salir mal!"
  },
  AvgCommunicate_67022_Content_8 = {
    Text = "Además, mi costumbre de dormir con la luz encendida ya no molestará a nadie. Es absolutamente perfecto."
  },
  AvgCommunicate_67022_Content_9 = {
    Text = "¡Perfecto mis pies!"
  },
  AvgCommunicate_67022_Option_10 = {
    Text = "¡Eso ya es una gran molestia para los demás!"
  },
  AvgCommunicate_67022_Option_12 = {
    Text = "Espera, no me digas que la persona en quien confías soy yo."
  },
  AvgCommunicate_67022_Option_2 = {
    Text = "¡Felicidades! ¿Cuál es el método?"
  },
  AvgCommunicate_67022_Option_4 = {
    Text = "Suena bastante bien."
  },
  AvgCommunicate_67022_Option_6 = {
    Text = "? ¿Quieres poner este trasto en la habitación de otra persona?"
  },
  AvgCommunicate_67022_Option_9 = {
    Text = "¡Perfecto mis pies!"
  },
  AvgCommunicate_67023_Content_1 = {
    Text = "Guardián, últimamente no paro de ver manchas extrañas delante de los ojos, y siempre estoy mareada, con palpitaciones, opresión en el pecho, zumbidos en los oídos... !?Me voy a morir?!"
  },
  AvgCommunicate_67023_Content_10 = {
    Text = "No, no lo entiendes. Esa oscuridad está en todas partes. No importa dónde esté, ¡me encontrará! No puedo dormir, no puedo cerrar los ojos..."
  },
  AvgCommunicate_67023_Content_11 = {
    Text = "Eh... entonces, ¿por qué no contratas a alguien para que Solo te deje inconsciente? Así perderías el conocimiento y no sentirías miedo."
  },
  AvgCommunicate_67023_Content_12 = {
    Text = "¿Eh? Lo que dices en realidad tiene algo de sentido."
  },
  AvgCommunicate_67023_Content_13 = {
    Text = "Ya que el Síntoma: Destrucción llegará de todos modos, mejor dejarme morir en paz en la más dichosa ignorancia..."
  },
  AvgCommunicate_67023_Content_14 = {
    Text = "¡Solo es quedar inconsciente, estás muy lejos de morir!"
  },
  AvgCommunicate_67023_Content_15 = {
    Text = "Gracias, Guardián. Entonces te encomendaré esta tarea a ti, en quien más confío."
  },
  AvgCommunicate_67023_Content_16 = {
    Text = "......¡¡Tenía que abrir mi bocota!!"
  },
  AvgCommunicate_67023_Content_2 = {
    Text = "Eh, dado tu horario de sueño, probablemente te has estado acostando demasiado tarde. Te sugeriría irte a dormir más temprano."
  },
  AvgCommunicate_67023_Content_3 = {
    Text = "?Qué? ?Este cuerpo también ha llegado a su límite...?"
  },
  AvgCommunicate_67023_Content_4 = {
    Text = "!Pero enfrentarme a esa oscuridad aterradora me mataría igual!"
  },
  AvgCommunicate_67023_Content_5 = {
    Text = "Agh, maldición. Sufrimiento prolongado o un final rápido, ser o no ser — cómo se supone que elija..."
  },
  AvgCommunicate_67023_Content_6 = {
    Text = "!?No es un poco exagerado?! !Lo has elevado a filosofía!"
  },
  AvgCommunicate_67023_Content_7 = {
    Text = "Pero en realidad nunca te ha pasado nada malo por dormir. Ese terror es solo tu imaginación. Creo que deberías probar la desensibilización."
  },
  AvgCommunicate_67023_Content_8 = {
    Text = "¿Desensibilización?"
  },
  AvgCommunicate_67023_Content_9 = {
    Text = "Por ejemplo, quizás podrías Comenzar intentando echarte una siesta. Durante el día, al menos los Alrededores están iluminados, así que deberías sentirte segura."
