  AvgCommunicate_67024_Content_1 = {
    Text = "¡Tachán, la clase de magia de Casiah ya ha comenzado!"
  },
  AvgCommunicate_67024_Content_10 = {
    Text = "Entonces, ¿por qué dijiste eso?"
  },
  AvgCommunicate_67024_Content_11 = {
    Text = "Oh, estas son las habilidades exclusivas del Maestro Casiah. Por supuesto, no puedes aprenderlas."
  },
  AvgCommunicate_67024_Content_12 = {
    Text = "Pero la Maestra Casiah puede enseñarte a hacer tus manos ágiles. De esta manera, cuando te encuentres con cuerdas que no se pueden desatar o cerraduras que no se pueden abrir, ¡también dominarás las técnicas de apertura de cerraduras y robo!"
  },
  AvgCommunicate_67024_Content_13 = {
    Text = "¡Aún enseñando cosas extrañas!"
  },
  AvgCommunicate_67024_Content_14 = {
    Text = "¡No uses palabras extrañas a la ligera!"
  },
  AvgCommunicate_67024_Content_15 = {
    Text = "Tsk, ¿los estudiantes de la Muñeca también causan tantos problemas? Qué molestia. Ser maestro realmente no es divertido."
  },
  AvgCommunicate_67024_Content_16 = {
    Text = "Aunque la Sra. Muñeca es realmente trabajadora, ¡especialmente no quiero que me desagrades!"
  },
  AvgCommunicate_67024_Content_2 = {
    Text = "¿Qué estás tramando de nuevo??"
  },
  AvgCommunicate_67024_Content_3 = {
    Text = "¿Qué? ¡Esta vez estoy dando una conferencia seriamente por invitación de la escuela!"
  },
  AvgCommunicate_67024_Content_4 = {
    Text = "Doll me dijo que intentar ser un maestro me permitiría experimentar la sensación de educación y legado."
  },
  AvgCommunicate_67024_Content_5 = {
    Text = "Puede que sea un poco difícil de entender, pero de ahora en adelante, ¡por favor llámame Maestro Casiah!"
  },
  AvgCommunicate_67024_Content_6 = {
    Text = "Uh, Casiah... Profesor. ¡Entiendo aún menos que tú!"
  },
  AvgCommunicate_67024_Content_7 = {
    Text = "¿Qué? ¡Los trucos de magia del maestro Casiah son increíblemente secretos! Como la recuperación remota, atravesar objetos o el robo en la pared..."
  },
  AvgCommunicate_67024_Content_8 = {
    Text = "¡Las cosas se están volviendo cada vez más extrañas, verdad!"
  },
  AvgCommunicate_67024_Content_9 = {
    Text = "...¡No puedes aprender estas cosas!"
  },
  AvgCommunicate_67024_Option_10 = {
    Text = "Entonces, ¿por qué dijiste eso?"
  },
  AvgCommunicate_67024_Option_13 = {
    Text = "¡Aún enseñando cosas extrañas!"
  },
  AvgCommunicate_67024_Option_14 = {
