  AvgCommunicate_67025_Content_1 = {
    Text = "El efecto del reciente entrenamiento militar con perros superó mis expectativas."
  },
  AvgCommunicate_67025_Content_10 = {
    Text = "¡¡¡Por favor, asegúrate de guardarme un lugar!!!"
  },
  AvgCommunicate_67025_Content_2 = {
    Text = "Incluso los estudiantes que no participaron en el entrenamiento físico están viniendo a mí para inscribirse en clases. Estoy realmente sorprendido por el entusiasmo de todos."
  },
  AvgCommunicate_67025_Content_3 = {
    Text = "Después de todo, ¡nadie puede resistirse a un cachorro esponjoso!!!"
  },
  AvgCommunicate_67025_Content_4 = {
    Text = "De verdad, para fomentar el trabajo en equipo entre los estudiantes, he elegido cachorros juveniles."
  },
  AvgCommunicate_67025_Content_5 = {
    Text = "Aunque adoro a estos pequeños tanto como todos los demás, requieren mucho más cuidado y entrenamiento que los perros adultos."
  },
  AvgCommunicate_67025_Content_6 = {
    Text = "Ahora que el número de inscritos ha aumentado, también necesita aumentar el número de cachorros, y realmente se está volviendo difícil de manejar para mí."
  },
  AvgCommunicate_67025_Content_7 = {
    Text = "Es simple. Si el Instructor Alva da la orden, más personas estarán dispuestas a inscribirse para cuidar a los cachorros. Para entonces, puede que ni siquiera haya suficientes cachorros para todos."
  },
  AvgCommunicate_67025_Content_8 = {
    Text = "¿Sugieres que reclutemos algunos voluntarios? Esa es una buena idea."
  },
  AvgCommunicate_67025_Content_9 = {
    Text = "Entonces iré y preguntaré al Decano Czort para que apruebe este asunto más tarde. Si todo sale bien, los estudiantes también podrán ver más cachorros."
