  },
  AvgCommunicate_67025_Option_3 = {
    Text = "Después de todo, ¡nadie puede resistirse a un cachorro esponjoso!!!"
  },
  AvgCommunicate_67025_Option_7 = {
    Text = "Esto es demasiado simple."
