  AvgCommunicate_67026_Content_1 = {
    Text = "Guardián, ¿tienes alguna sugerencia para mejorar los recientes cursos de entrenamiento de investigadores?"
  },
  AvgCommunicate_67026_Content_10 = {
    Text = "Además, los perros militares bien entrenados pueden asistir a los soldados excelentemente en varias tareas. Quizás podamos aplicar esto a las misiones de investigadores y explorar más a fondo las posibilidades."
  },
  AvgCommunicate_67026_Content_11 = {
    Text = "Impresionante, perros."
  },
  AvgCommunicate_67026_Content_12 = {
    Text = "Exactamente, ¿significa esto que estarás más dispuesta a asistir al entrenamiento ahora?"
  },
  AvgCommunicate_67026_Content_13 = {
    Text = "¡Instructor Alva! ¡Estoy dispuesto!"
  },
  AvgCommunicate_67026_Content_2 = {
    Text = "La sugerencia es: \"El entrenamiento fue bien. No hay necesidad de entrenar la próxima vez...\""
