  AvgCommunicate_67026_Content_3 = {
    Text = "¿Dices que el contenido del entrenamiento es desagradable?"
  },
  AvgCommunicate_67026_Content_4 = {
    Text = "Justo es una broma. Principalmente porque el contenido del entrenamiento físico es demasiado aburrido, realmente no hay motivación..."
  },
  AvgCommunicate_67026_Content_5 = {
    Text = "Mm, ya veo. Parece que el problema clave sigue siendo el interés."
  },
  AvgCommunicate_67026_Content_6 = {
