  AvgCommunicate_67027_Content_1 = {
    Text = "Guardián, ¿por qué ya no viene nadie de Mitag a mí para hacer deseos?"
  },
  AvgCommunicate_67027_Content_10 = {
    Text = "En lugar de hacer un deseo, es más como si todos estuvieran esperando suerte y bendiciones."
  },
  AvgCommunicate_67027_Content_11 = {
    Text = "Incluso si los deseos no pueden hacerse realidad de inmediato, mantenerlos en nuestros corazones trae consuelo y anticipación."
  },
  AvgCommunicate_67027_Content_12 = {
    Text = "Los deseos que no pueden cumplirse de inmediato... ¿de verdad son tan valiosos?"
  },
  AvgCommunicate_67027_Content_13 = {
    Text = "Creo que entiendo. A partir de mañana, daré mis bendiciones a todos en la fuente de la escuela."
  },
  AvgCommunicate_67027_Content_14 = {
    Text = "¡Espera, por qué la fuente de la escuela?"
  },
  AvgCommunicate_67027_Content_15 = {
    Text = "He oído que los pozos de los deseos son populares en muchos lugares, así que si convierto la fuente de la escuela en un pozo de los deseos, todos podrán venir a buscar la Bendición."
  },
  AvgCommunicate_67027_Content_16 = {
    Text = "Parece lógico, ¡pero aún se siente extraño!"
  },
  AvgCommunicate_67027_Content_2 = {
    Text = "Mm... Quizás porque todos en Mythag son pragmáticos."
  },
  AvgCommunicate_67027_Content_3 = {
    Text = "Frente a innumerables peligros cada día, mi espíritu se ha vuelto lo suficientemente estable como para no depender de desear soluciones."
  },
  AvgCommunicate_67027_Content_4 = {
    Text = "...Parece que sigo siendo demasiado inútil."
  },
  AvgCommunicate_67027_Content_5 = {
    Text = "No, ¡no! De hecho, no todos descreen completamente de estas cosas."
  },
  AvgCommunicate_67027_Content_6 = {
    Text = "Si el deseo es abstracto y a largo plazo, todos aún disfrutan participar en la diversión y hacer un deseo."
  },
  AvgCommunicate_67027_Content_7 = {Text = "¿Es así?"},
  AvgCommunicate_67027_Content_8 = {
    Text = "No entiendo del todo. ¿Cuáles son los deseos abstractos y a largo plazo?"
