  AvgCommunicate_67028_Content_1 = {
    Text = "Hola, {Male=Mr.,Female=Miss} Guardián del secreto. Perdona que te moleste de nuevo después de tanto tiempo."
  },
  AvgCommunicate_67028_Content_10 = {
    Text = "Eso es genial. Elegiré un momento conveniente para visitarte."
  },
  AvgCommunicate_67028_Content_11 = {
    Text = "Mantengámoslo en secreto de Lily por ahora. Quiero sorprenderla."
  },
  AvgCommunicate_67028_Content_2 = {
    Text = "Recientemente, obtuve inesperadamente dos hermosos peces de oro rojo."
  },
  AvgCommunicate_67028_Content_3 = {
    Text = "Afortunadamente, bajo mi cuidado, lograron poner muchos huevos, y ahora han eclosionado en incontables pececitos."
  },
  AvgCommunicate_67028_Content_4 = {
    Text = "Eso es realmente bonito. Recuerdo que te encanta el pescado."
  },
  AvgCommunicate_67028_Content_5 = {
    Text = "Sí, tengo un profundo apego al mundo submarino."
  },
  AvgCommunicate_67028_Content_6 = {
    Text = "Los peces, la hierba marina y el coral en el agua son un lugar cálido y acogedor en mi Memoria."
  },
  AvgCommunicate_67028_Content_7 = {
    Text = "Lo siento, me distraje. Quería preguntarte si estás interesado en tener algunos peces de colores"
  },
  AvgCommunicate_67028_Content_8 = {
    Text = "La forma en que mueven sus aletas en el agua es tan linda. Si Lily los viera, probablemente le encantaría."
  },
  AvgCommunicate_67028_Content_9 = {
    Text = "¡Por supuesto! Podemos ponerlos en mi habitación y la de Lily."
  },
  AvgCommunicate_67028_Option_4 = {
    Text = "Eso es realmente bonito. Recuerdo que te encanta el pescado."
  },
  AvgCommunicate_67028_Option_9 = {
    Text = "¡Por supuesto! Podemos ponerlos en mi habitación y la de Lily."
  },
  AvgCommunicate_67029_Content_1 = {
    Text = "Oh vaya, Guardián, ¿me estabas buscando?"
  },
  AvgCommunicate_67029_Content_10 = {
    Text = "Así que Casiah tuvo una gran idea: ¡empezar a investigar a partir de los animales! ¡Eso lo hace mucho más fácil!"
  },
  AvgCommunicate_67029_Content_11 = {
    Text = "...¿Y donde están esos pollos ahora?"
  },
  AvgCommunicate_67029_Content_12 = {
    Text = "¡La habitación de Casiah ahora bulle con muchos pollitos recién nacidos! ¡Está animada todos los días!"
  },
  AvgCommunicate_67029_Content_13 = {
    Text = "¡Devuelve la cafetería correctamente!!"
  },
  AvgCommunicate_67029_Content_14 = {
    Text = "Oh, separar cruelmente a estas madres y niños, ¡qué despiadado! ¡Tú que careces de amor materno!"
  },
  AvgCommunicate_67029_Content_15 = {
    Text = "¿Por qué siento afecto maternal hacia los pollos!"
  },
  AvgCommunicate_67029_Content_16 = {
    Text = "Y realmente no quiero que me llames frío de corazón"
  },
  AvgCommunicate_67029_Content_2 = {
    Text = "Exactamente, Casiah, alguien informó que después de tu espectáculo de magia improvisado en la cafetería de la escuela ayer, tres gallinas y veinte huevos desaparecieron del almacenamiento."
  },
  AvgCommunicate_67029_Content_3 = {
    Text = "¿Qué? ¿Hay algo así? Casiah no lo sabía."
  },
  AvgCommunicate_67029_Content_4 = {
    Text = "¡Deja de hacerte la tonta! ¡Todos te vieron conjurar un montón de gallinas!"
  },
  AvgCommunicate_67029_Content_5 = {
    Text = "Oh, parece que sí. Esos pollos pueden haberse volado por su cuenta."
  },
  AvgCommunicate_67029_Content_6 = {
    Text = "Quizás han perdido su camino en el interminable mundo de los sombreros. ¡Qué patético!"
  },
  AvgCommunicate_67029_Content_7 = {
    Text = "Si no comienzas a considerar decir la verdad, contactaré a la Dama del narciso para que gestione a sus empleados."
  },
  AvgCommunicate_67029_Content_8 = {
    Text = "Está bien, está bien, ¡no tienes sentido del humor en absoluto!"
  },
  AvgCommunicate_67029_Content_9 = {
    Text = "¡Casiah ha estado investigando \"amor maternal\" recientemente, pero hay muy pocas referencias entre los Despertados!"
  },
  AvgCommunicate_67029_Option_11 = {
    Text = "...¿Y donde están esos pollos ahora?"
  },
  AvgCommunicate_67029_Option_13 = {
    Text = "¡Devuelve la cafetería correctamente!!"
  },
  AvgCommunicate_67029_Option_15 = {
    Text = "¿Por qué siento afecto maternal hacia los pollos!"
  },
  AvgCommunicate_67029_Option_16 = {
    Text = "Y realmente no quiero que me llames frío de corazón"
  },
  AvgCommunicate_67029_Option_2 = {
    Text = "¡Sí, claro!"
  },
  AvgCommunicate_67029_Option_4 = {
    Text = "¡Deja de hacerte la tonta! ¡Todos te vieron conjurar un montón de gallinas!"
  },
  AvgCommunicate_67029_Option_7 = {
    Text = "Si no comienzas a pensar en decir la verdad..."
  },
  AvgCommunicate_67030_Content_1 = {
    Text = "Ay, Maestro, ¿por qué crees que ninguno de los pastelitos que Karen prepara con tanto esmero se vende?"
  },
  AvgCommunicate_67030_Content_10 = {
    Text = "¡¡La de los gustos peculiares eres tú!!"
  },
  AvgCommunicate_67030_Content_11 = {
    Text = "Ay, emprender un negocio es tan difícil. Parece que necesito vender algo diferente. ¿Qué tal si preparo algunas bebidas esta vez?"
  },
  AvgCommunicate_67030_Content_12 = {
    Text = "¡¡¡Para, deja de infligir tus creaciones a todo el mundo!!!"
  },
  AvgCommunicate_67030_Content_2 = {
    Text = "La última vez que pusimos un puesto en el campus, ¡Murphy hasta los escupió al suelo! Si no hubiera corrido lo suficientemente rápido, ¡me habría dado una paliza!"
  },
  AvgCommunicate_67030_Content_3 = {
    Text = "Solo qué tan mal sabrán..."
  },
  AvgCommunicate_67030_Content_4 = {
    Text = "¡Pero yo los probé y me parecieron deliciosos!"
  },
  AvgCommunicate_67030_Content_5 = {
    Text = "¿Cómo preparas exactamente tus pastelitos?"
  },
  AvgCommunicate_67030_Content_6 = {
    Text = "Seleccioné las mejores arañas secas y lampreas frescas, las herví en una olla grande y luego las mezclé con la masa..."
  },
  AvgCommunicate_67030_Content_7 = {
    Text = "Espera... ¡Ugh, me están dando náuseas solo de escucharlo!!"
  },
  AvgCommunicate_67030_Content_8 = {
    Text = "¿¡Eso es siquiera comestible!?"
  },
  AvgCommunicate_67030_Content_9 = {
    Text = "¡Pero sabe muy bien! ¿De verdad todos tienen gustos tan peculiares...?"
