  AvgCommunicate_67031_Content_10 = {
    Text = "¿Es posible que haya una etiqueta en ello?"
  },
  AvgCommunicate_67031_Content_11 = {
    Text = "¿Qué etiqueta? No puedo entenderlo."
  },
  AvgCommunicate_67031_Content_12 = {
    Text = "¿Ignoraste completamente tu clase básica de lengua??"
  },
  AvgCommunicate_67031_Content_13 = {
    Text = "¡Argh, qué molesto! ¿Por qué el maestro del laberinto tiene que estudiar!"
  },
  AvgCommunicate_67031_Content_14 = {
    Text = "¡Tráeme algunos sirvientes para atenderme!"
  },
  AvgCommunicate_67031_Content_15 = {
    Text = "Despierta, Roma ha caído."
  },
  AvgCommunicate_67031_Content_16 = {
    Text = "Vivimos en una sociedad gobernada por el estado de derecho."
  },
  AvgCommunicate_67031_Content_17 = {
    Text = "No me importa. Si no puedes encontrarlo, entonces ¡me sirves tú mismo!"
  },
  AvgCommunicate_67031_Content_18 = {
    Text = "Entonces, más vale que sigas usando limpiador facial para cepillarte los dientes."
  },
  AvgCommunicate_67031_Content_19 = {
    Text = "¡te arrojaré al laberinto para alimentar a mi descendencia!!!"
  },
  AvgCommunicate_67031_Content_2 = {
    Text = "¿Qué pasa contigo??"
  },
  AvgCommunicate_67031_Content_3 = {
    Text = "La última vez que mencionaste, el polvo dental no estaba en la pequeña caja redonda, sino en una tira larga."
  },
  AvgCommunicate_67031_Content_4 = {
    Text = "¿Por qué usé la larga? ¡Ahora mi boca se siente tan amarga! ¡Tan picante y amarga!!"
  },
  AvgCommunicate_67031_Content_5 = {
    Text = "Uh... No debería saber así."
  },
  AvgCommunicate_67031_Content_6 = {
    Text = "Espera, ¿de qué color es la tira larga a la que te refieres?"
  },
  AvgCommunicate_67031_Content_7 = {
    Text = "¿Qué pasa con el azul?"
  },
  AvgCommunicate_67031_Content_8 = {
    Text = "Es para lavarte la cara. La pastilla dental es verde..."
  },
  AvgCommunicate_67031_Content_9 = {
    Text = "¿Qué? ¿Por qué nadie me lo dijo? ¿Fue deliberado?"
  },
