  },
  AvgCommunicate_67032_Content_1 = {
    Text = "Cachorro, hace tanto frío en el Pozo Negro. Siento que mi fuerza vital se agota cada día."
  },
  AvgCommunicate_67032_Content_10 = {
    Text = "¿Qué pasa si digo que he conseguido aflojar un poco el dispositivo que me atrapa?"
  },
  AvgCommunicate_67032_Content_11 = {
    Text = "?! Estoy viniendo ahora."
  },
  AvgCommunicate_67032_Content_2 = {
    Text = "Si no vienes a verme pronto, podría disolverme en D-baba un día."
  },
  AvgCommunicate_67032_Content_3 = {
    Text = "...No caeré más en tus trucos."
  },
  AvgCommunicate_67032_Content_4 = {
    Text = "¿No es natural preocuparse por el mentor? ¿Cómo puede considerarse eso una estafa?"
  },
  AvgCommunicate_67032_Content_5 = {
    Text = "Aún extraño cómo solías holgazanear en clase y preocuparte porque pudiera atraparte."
  },
  AvgCommunicate_67032_Content_6 = {
    Text = "Cuando intentas atraparme, tu expresión justa pero ingenua es bastante linda."
  },
  AvgCommunicate_67032_Content_7 = {
    Text = "No digas más, o apagaré el comunicador."
  },
  AvgCommunicate_67032_Content_8 = {
    Text = "Sigh, qué cruel. ¿No puedes verme de ninguna manera?"
  },
  AvgCommunicate_67032_Content_9 = {
    Text = "¿Qué piensas?"
  },
  AvgCommunicate_67032_Option_11 = {
    Text = "?! Estoy viniendo ahora."
  },
  AvgCommunicate_67032_Option_3 = {
    Text = "...No caeré más en tus trucos."
  },
  AvgCommunicate_67032_Option_7 = {
    Text = "No digas más, o apagaré el comunicador."
  },
  AvgCommunicate_67032_Option_9 = {
    Text = "¿Qué piensas?"
  },
  AvgCommunicate_67033_Content_1 = {
    Text = "Ah, Watson, la vida es tan aburrida."
  },
  AvgCommunicate_67033_Content_10 = {
    Text = "¿No me digas que realmente perdiste contra él?"
  },
  AvgCommunicate_67033_Content_11 = {
    Text = "No, eso no. Ninguno de los dos estaba dispuesto a ceder. Las apuestas subían cada vez más y a ambos se nos inyectaban los ojos."
  },
  AvgCommunicate_67033_Content_12 = {
    Text = "Entonces, en su emoción, el viejo mostró un Defecto, y Descubrí que en realidad había estado haciendo trampa todo el tiempo."
  },
  AvgCommunicate_67033_Content_13 = {
    Text = "?Entonces has estado empatando en victorias y derrotas con un tramposo todo este tiempo?"
  },
  AvgCommunicate_67033_Content_14 = {
    Text = "Sí, fue muy decepcionante. Lo que es aún más indignante es que el viejo montó en cólera por la humillación y se lanzó sobre mí para pelear."
  },
  AvgCommunicate_67033_Content_15 = {
    Text = "¡De hecho sospechaba que yo era un tramposo igual que él! Qué insulto."
  },
  AvgCommunicate_67033_Content_16 = {
    Text = "Al final, el personal de la Apuesta Lavka nos echó a los dos. Todavía me duele el trasero por la caída. Qué mala suerte."
  },
  AvgCommunicate_67033_Content_17 = {
    Text = "No sé por qué, pero no consigo sentir ninguna compasión..."
  },
  AvgCommunicate_67033_Content_2 = {
    Text = "? Seguro que has vuelto a apostar. ?Has vuelto a desplumar a todos?"
  },
  AvgCommunicate_67033_Content_3 = {
    Text = "¡Esta vez no, de verdad! Solo iba a la Apuesta Lavka a divertirme un poco como siempre... ejem."
  },
  AvgCommunicate_67033_Content_4 = {
    Text = "No pasa nada, continúa."
  },
  AvgCommunicate_67033_Content_5 = {
    Text = "Déjame escuchar el resto de tus excusas."
  },
  AvgCommunicate_67033_Content_6 = {
    Text = "Suspiro, y entonces hoy de repente me encontré con un oponente que podía igualarme."
  },
  AvgCommunicate_67033_Content_7 = {
    Text = "Después de unirme a esa mesa, estuve Casi empatado en victorias y derrotas con ese viejo de aspecto modesto."
  },
  AvgCommunicate_67033_Content_8 = {
    Text = "Eso sí que es sorprendente. Para poder ganarle a tu suerte, debe ser un verdadero experto."
  },
  AvgCommunicate_67033_Content_9 = {
    Text = "¡Eso mismo pensé yo! Así que reuní toda mi concentración y seguí apostando con él. ¡Hasta me senté derecho!"
  },
  AvgCommunicate_67033_Option_10 = {
    Text = "¿No me digas que realmente perdiste contra él?"
  },
  AvgCommunicate_67033_Option_13 = {
    Text = "?Entonces has estado empatando en victorias y derrotas con un tramposo todo este tiempo?"
