  AvgCommunicate_67034_Content_1 = {
    Text = "Guardián, hola."
  },
  AvgCommunicate_67034_Content_10 = {
    Text = "¿En serio? Entonces, ¿cómo explicas este examen reprobado? Cometer errores en material tan básico... Creo que te gustaría copiar las respuestas correctas cien veces."
  },
  AvgCommunicate_67034_Content_11 = {
    Text = "¿¡Cien veces?! No, por favor... ¡Espera, casi olvido que eres Erica!"
  },
  AvgCommunicate_67034_Content_12 = {
    Text = "¿¡Por qué insultaste de forma tan realista?! ¿¡Lo hiciste a propósito?! ¡¡Voy a dejar una mala reseña!!"
  },
  AvgCommunicate_67034_Content_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Content_14 = {
    Text = "Entendido. Cambiando simulación de personalidad a: Ramona."
  },
  AvgCommunicate_67034_Content_15 = {
    Text = "Compañero, un profesor acaba de decirme que al parecer no entregaste una de tus tareas."
  },
  AvgCommunicate_67034_Content_16 = {
    Text = "¿Eh? ¿En serio? Tengo el registro claro de haber hecho todas mis tareas..."
  },
  AvgCommunicate_67034_Content_17 = {
    Text = "¿Cuándo vas a corregir esa costumbre descuidada tuya?"
  },
  AvgCommunicate_67034_Content_18 = {
    Text = "Olvídalo. Solo ven a mi dormitorio todos los días a partir de ahora. Te supervisaré hasta que termines tus tareas diarias antes de que te vayas. Ah, y nada de buscar respuestas ni referencias."
  },
  AvgCommunicate_67034_Content_19 = {
    Text = "¿¡Qué?! ¡¡De ninguna manera!! ¿¡Cómo se supone que haga la tarea sin referencias?!"
  },
  AvgCommunicate_67034_Content_2 = {
    Text = "Estás invitado/a a probar el último sistema de simulación de personalidad. Este sistema, cuando las misiones lo requieran, suplantará las comunicaciones en nombre de miembros no disponibles, predecirá su lógica de comportamiento y más."
  },
  AvgCommunicate_67034_Content_20 = {
    Text = "Espera... ¡Casi olvido que eres Erica! ¿¡Me asustaste a propósito?! ¡¡Voy a dejar una mala reseña!!"
  },
  AvgCommunicate_67034_Content_21 = {
    Text = "Entendido. Se ha recibido tu opinión de uso. Evaluación preliminar: simulación aprobada."
  },
  AvgCommunicate_67034_Content_22 = {
    Text = "Espero verte de nuevo en la próxima prueba del sistema."
  },
  AvgCommunicate_67034_Content_3 = {
    Text = "Por favor, comparte tus comentarios y sugerencias una vez que hayas terminado la prueba."
  },
  AvgCommunicate_67034_Content_4 = {
    Text = "¿Qué clase de cosa rara es esta?"
  },
  AvgCommunicate_67034_Content_5 = {
    Text = "Puedes elegir uno de los siguientes dos personajes iniciales para experimentar la simulación de personalidad: Doll, Ramona."
  },
  AvgCommunicate_67034_Content_6 = {Text = "Doll."},
  AvgCommunicate_67034_Content_7 = {
    Text = "Entendido. Cambiando simulación de personalidad a: Doll."
  },
  AvgCommunicate_67034_Content_8 = {
    Text = "Guardián, ya salieron los resultados de tu último examen. Espero que seas consciente de lo que has estado haciendo últimamente."
  },
  AvgCommunicate_67034_Content_9 = {
    Text = "¿Eh? Yo... He estado entregando todas mis tareas a tiempo últimamente. Solo me quedé dormido en clase un par de veces, eso es todo..."
  },
  AvgCommunicate_67034_Option_11 = {
    Text = "¿¡Cien veces?! No, por favor..."
  },
  AvgCommunicate_67034_Option_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Option_16 = {
    Text = "¿Eh? ¿En serio? Tengo el registro claro de haber hecho todas mis tareas..."
  },
  AvgCommunicate_67034_Option_19 = {
