  },
  AvgCommunicate_67034_Option_4 = {
    Text = "¿Qué clase de cosa rara es esta?"
  },
  AvgCommunicate_67034_Option_6 = {Text = "Doll."},
  AvgCommunicate_67034_Option_9 = {Text = "Huh?"},
  AvgCommunicate_67035_Content_1 = {
    Text = "¡Querido Guardián! ¡Por favor, ayúdame!"
  },
  AvgCommunicate_67035_Content_10 = {
    Text = "¡¿Cómo puede ser eso un trabajo?!"
  },
  AvgCommunicate_67035_Content_11 = {
    Text = "Bueno... Las sesiones de entrenamiento de Alva se han centrado últimamente en entrenar a los cachorros para Buscar enemigos."
  },
  AvgCommunicate_67035_Content_12 = {
    Text = "Si no te importa que te muerdan los perros, puedes ir a Jugar de villana allí."
  },
  AvgCommunicate_67035_Content_13 = {
    Text = "¿Qué? ¿Estás diciendo que adorables cachorros pueden Morderme ferozmente?"
  },
  AvgCommunicate_67035_Content_14 = {
    Text = "¡Me apunto! ¡Eres la mejor, Guardián!"
  },
  AvgCommunicate_67035_Content_2 = {
    Text = "No hay regaños, no hay peleas y no hay quedarse en la habitación."
  },
  AvgCommunicate_67035_Content_3 = {
    Text = "¡Oh, vamos, esta vez de verdad no estaba en la Puerta de tu habitación!"
  },
  AvgCommunicate_67035_Content_4 = {
    Text = "Gracias a tu ayuda la última vez, pasé mucho tiempo golpeando felizmente el saco de arena en la sala de entrenamiento. Se sintió como estar en casa—nunca había sido tan feliz antes."
  },
  AvgCommunicate_67035_Content_5 = {
    Text = "Mm... de nada. Solo estés feliz, eso me basta."
  },
  AvgCommunicate_67035_Content_6 = {
    Text = "Ay, pero me han Descubierto hace poco de todas formas. No tengo ni idea de cómo Uvhash se dio cuenta de que era yo la que estaba Dentro."
  },
  AvgCommunicate_67035_Content_7 = {
    Text = "Después de que todos descubrieran que era yo la que estaba Dentro del Saco terrero, todos me lanzaron Maldiciones."
  },
  AvgCommunicate_67035_Content_8 = {
    Text = "Aunque esa parte fue bastante divertida, ya no puedo disfrazarme de Saco terrero."
  },
  AvgCommunicate_67035_Content_9 = {
    Text = "¿Qué hago? ¡Estar desempleada es horrible, Guardián! ¡Por favor, búscame otro trabajo así!"
  },
  AvgCommunicate_67035_Option_10 = {
    Text = "¡¿Cómo puede ser eso un trabajo?!"
  },
  AvgCommunicate_67035_Option_2 = {
    Text = "No hay regaños, no hay peleas y no hay quedarse en la habitación."
  },
  AvgCommunicate_67035_Option_5 = {
    Text = "Mm... de nada. Solo estés feliz, eso me basta."
  },
  AvgCommunicate_67036_Content_1 = {
    Text = "¡Guardián! ¡Mi última modificación ha sido un éxito!"
  },
  AvgCommunicate_67036_Content_10 = {
    Text = "De esa manera no tendré que preocuparme por olvidar revisar mi diario otra vez y perder mis recuerdos anteriores."
  },
  AvgCommunicate_67036_Content_11 = {
    Text = "¡Gran idea! Pero, ¿no solías no preocuparte tanto por ser olvidadiza?"
  },
  AvgCommunicate_67036_Content_12 = {
    Text = "Es cierto, pero ahora no quiero olvidar a mis amigos."
  },
  AvgCommunicate_67036_Content_13 = {
    Text = "¡Me aseguraré de recordarte, Guardián!"
  },
  AvgCommunicate_67036_Content_2 = {
    Text = "¡Felicidades! ¿Hablas de tu Nautilus? Además, me sorprende que aún me recuerdes."
  },
  AvgCommunicate_67036_Content_3 = {
    Text = "No, hablo de esta pequeña caja de chat."
  },
  AvgCommunicate_67036_Content_4 = {
    Text = "? Eso se llama comunicador, ¿y qué exactamente modificaste¿?"
  },
  AvgCommunicate_67036_Content_5 = {
    Text = "Ahora puedo configurar lo que he escrito para que se envíe con una Latencia, y puedo controlar el tiempo de Latencia yo misma."
  },
  AvgCommunicate_67036_Content_6 = {
    Text = "Por ejemplo, el primer mensaje que Solo te envié en realidad fue escrito hace cinco minutos como prueba."
  },
  AvgCommunicate_67036_Content_7 = {
    Text = "¡¿Eso es increíble?! Parece que podrías configurar Eventos de seguimiento con antelación durante las misiones, y activar planes de respaldo también sería muy conveniente."
  },
  AvgCommunicate_67036_Content_8 = {
    Text = "Ah, no he pensado en ello tanto como todos ustedes."
  },
  AvgCommunicate_67036_Content_9 = {
    Text = "Solo estaba pensando, si me envío lo que recuerdo hoy a mí misma mañana, entonces no lo olvidaré."
  },
  AvgCommunicate_67036_Option_11 = {
    Text = "¡Gran idea! Pero, ¿no solías no preocuparte tanto por ser olvidadiza?"
  },
  AvgCommunicate_67036_Option_2 = {
    Text = "¡Felicidades! ¿Hablas de tu Nautilus? Además, me sorprende que aún me recuerdes."
  },
  AvgCommunicate_67036_Option_4 = {
    Text = "? Eso se llama comunicador, ¿y qué exactamente modificaste¿?"
  },
  AvgCommunicate_67036_Option_7 = {
    Text = "¡¿Eso es increíble?!"
  },
  AvgCommunicate_67037_Content_1 = {
    Text = "Guardián, recientemente encontré un juego de poesía muy interesante."
  },
  AvgCommunicate_67037_Content_10 = {Text = "Frío."},
  AvgCommunicate_67037_Content_11 = {Text = "Muerte."},
  AvgCommunicate_67037_Content_12 = {Text = "Cantando."},
  AvgCommunicate_67037_Content_13 = {Text = "Amor."},
  AvgCommunicate_67037_Content_14 = {
    Text = "Melancolía."
  },
  AvgCommunicate_67037_Content_15 = {Text = "Fragancia."},
  AvgCommunicate_67037_Content_16 = {
    Text = "Hmm, creo que es suficiente. Déjame intentar tejerlas en un verso."
  },
  AvgCommunicate_67037_Content_17 = {
    Text = "El amor del ruiseñor por la luna florece noche tras noche en su melodiosa garganta, pero la luna permanece siempre tan fría."
  },
  AvgCommunicate_67037_Content_18 = {
    Text = "Cantó y cantó, hasta que la espina de la rosa le atravesó el pecho."
  },
  AvgCommunicate_67037_Content_19 = {
    Text = "Aquel canto se desvaneció con el flujo carmesí de la muerte, dejando solo la rosa, solo la rosa exhalando una fragancia melancólica."
  },
  AvgCommunicate_67037_Content_2 = {
    Text = "¿Qué tipo de juego?"
  },
  AvgCommunicate_67037_Content_20 = {
    Text = "¡Hermoso! ¡Bravo! ¡No esperaba menos de ti!"
  },
  AvgCommunicate_67037_Content_21 = {
    Text = "Es... es solo algo que improvisé en el momento. No es nada especial..."
  },
  AvgCommunicate_67037_Content_22 = {
    Text = "Si este verso es hermoso, entonces la mitad de su belleza la creaste tú."
  },
  AvgCommunicate_67037_Content_3 = {
    Text = "Todos se turnan para decir una Imagen, y después de varias rondas, todas las Imágenes se combinan para formar un Versículo."
  },
  AvgCommunicate_67037_Content_4 = {
    Text = "Está lleno de la belleza de las colisiones aleatorias, ¿no crees? ¿Te gustaría probarlo conmigo?"
  },
  AvgCommunicate_67037_Content_5 = {
    Text = "¡Suena muy divertido! ¡A jugar, a jugar!"
  },
  AvgCommunicate_67037_Content_6 = {
    Text = "Entonces empiezo yo. Rosa."
  },
  AvgCommunicate_67037_Content_7 = {Text = "Florecer."},
  AvgCommunicate_67037_Content_8 = {Text = "Ruiseñor."},
  AvgCommunicate_67037_Content_9 = {Text = "Luna."},
