  AvgCommunicate_67038_Content_1 = {
    Text = "Guardián, la estatua de Tulu que me pediste hacer para Miryam ha sido entregada a tu habitación."
  },
  AvgCommunicate_67038_Content_10 = {
    Text = "Su comprensión de Tulu es incluso menor que mi comprensión de ti; qué incompetente."
  },
  AvgCommunicate_67038_Content_11 = {
    Text = "¡Suficiente, no digas eso! No dejes que ella lo vea."
  },
  AvgCommunicate_67038_Content_12 = {
    Text = "De todos modos, gracias por tu arduo trabajo. Déjame pensar cómo decirle a Miryam..."
  },
  AvgCommunicate_67038_Content_2 = {
    Text = "Lo vi, pero esta imagen... ¿no es un poco demasiado linda?"
  },
  AvgCommunicate_67038_Content_3 = {
    Text = "¿Así es como se ve Tulu? ¿Me estrangulará Miryam...?"
  },
  AvgCommunicate_67038_Content_4 = {
    Text = "¿Qué? ¿También eres un devoto seguidor del joven rey?"
  },
  AvgCommunicate_67038_Content_5 = {
    Text = "A mis ojos, él era solo un niño, obligado a soportar una corona y cadenas impuestas por otros."
  },
  AvgCommunicate_67038_Content_6 = {
    Text = "¿No crees que su aspecto somnoliento y perezoso todos los días es adorable? Me recuerda al gato de pelo largo que tenía de niña."
  },
  AvgCommunicate_67038_Content_7 = {
    Text = "Es cierto, aquellos que deseen la estatua quedarán satisfechos..."
  },
  AvgCommunicate_67038_Content_8 = {
    Text = "La única mala noticia podría ser el nacimiento de un mundo donde solo Miryam sufre..."
  },
  AvgCommunicate_67038_Content_9 = {
    Text = "Eso solo significa que ella es una sacerdotisa ciega que no entiende a su propio Dios."
  },
  AvgCommunicate_67038_Option_11 = {
    Text = "¡Suficiente, no digas eso! No dejes que ella lo vea."
  },
  AvgCommunicate_67038_Option_2 = {
    Text = "Lo vi, pero esta imagen... ¿no es un poco demasiado linda?"
  },
  AvgCommunicate_67038_Option_7 = {
    Text = "Es cierto, aquellos que deseen la estatua quedarán satisfechos..."
  },
  AvgCommunicate_67039_Content_1 = {
    Text = "Querido Guardián, ¿recibiste mi última obra?"
  },
  AvgCommunicate_67039_Content_10 = {
    Text = "Tantos halagos de repente... me estás haciendo sonrojar..."
  },
  AvgCommunicate_67039_Content_11 = {
    Text = "No hay por qué ser tímido. Siempre has sido mi musa. Cuando tengas tiempo, ¿vendrías a visitar mi estudio?"
  },
  AvgCommunicate_67039_Content_12 = {
    Text = "Hay tantas obras que deseo completar. Necesito trazar cuidadosamente los contornos de tu alma."
  },
  AvgCommunicate_67039_Content_13 = {
    Text = "Estaré aquí en La Vigilia esperándote, aguardando a que me concedas más Inspiración."
  },
  AvgCommunicate_67039_Content_2 = {
    Text = "Esto es... ¿yo, dormido?"
  },
  AvgCommunicate_67039_Content_3 = {
    Text = "Según mi Inspiración, eres tú, sumergiéndote en un hermoso Sueño."
  },
  AvgCommunicate_67039_Content_4 = {
    Text = "¿Obtener una felicidad ciega y falsa, o un descenso lúcido y doloroso?"
  },
  AvgCommunicate_67039_Content_5 = {
    Text = "Una elección imposible es siempre una cuestión de arte y filosofía."
  },
  AvgCommunicate_67039_Content_6 = {
    Text = "¿No puedo tener una felicidad que sea lúcida y real a la vez?"
  },
  AvgCommunicate_67039_Content_7 = {
    Text = "Jeje, qué codicioso eres."
  },
  AvgCommunicate_67039_Content_8 = {
    Text = "Nada es perfecto. Quizás ni siquiera la escultura pueda capturar la perfección."
  },
  AvgCommunicate_67039_Content_9 = {
    Text = "Pero siempre puedes recorrer El Camino de la Mecha en busca de esa felicidad. Ahí es donde reside tu encanto."
  },
  AvgCommunicate_67039_Option_10 = {
    Text = "Tantos halagos de repente... me estás haciendo sonrojar..."
  },
  AvgCommunicate_67039_Option_2 = {
    Text = "Esto es... ¿yo, dormido?"
  },
  AvgCommunicate_67039_Option_6 = {
    Text = "¿No puedo tener una felicidad que sea lúcida y real a la vez?"
  },
  AvgCommunicate_67040_Content_1 = {
    Text = "Oh, cariño, ¿qué te pareció nuestro dulce momento juntos la última vez? ¿Lo has estado saboreando cada día desde entonces?"
  },
  AvgCommunicate_67040_Content_10 = {
    Text = "Solo dilo, ¿qué tramas esta vez..."
  },
  AvgCommunicate_67040_Content_11 = {
    Text = "No estés tan tenso, si ya nos llevamos tan bien～"
  },
  AvgCommunicate_67040_Content_12 = {
    Text = "Confía en mí, sígueme, y te llevaré a placeres completamente nuevos."
  },
  AvgCommunicate_67040_Content_13 = {
    Text = "Esta vez, ¿te gustaría experimentar de primera mano cómo se usan las velas y los pequeños látigos?"
  },
  AvgCommunicate_67040_Content_14 = {
    Text = "Te enseñaré todo, mano a mano, poco a poco, cariño."
  },
  AvgCommunicate_67040_Content_2 = {
    Text = "¿Qué momento juntos?"
  },
  AvgCommunicate_67040_Content_3 = {
    Text = "No recuerdo."
  },
  AvgCommunicate_67040_Content_4 = {
    Text = "¡Qué crueldad! Y eso que fui tan delicada contigo la última vez～"
  },
  AvgCommunicate_67040_Content_5 = {
    Text = "Te aconsejo que midas tus palabras..."
  },
  AvgCommunicate_67040_Content_6 = {
    Text = "Hmph, hacerte el tonto no te servirá de nada, ¡porque ya he usado cera para hacer un Registro de cada contorno, cada curva, cada forma tuya!"
  },
  AvgCommunicate_67040_Content_7 = {
    Text = "Tengo muchas ganas de mostrárselo a todos～"
  },
  AvgCommunicate_67040_Content_8 = {
    Text = "?! ¿No te atreverás?"
  },
  AvgCommunicate_67040_Content_9 = {
    Text = "Oh, vaya, eso depende de cómo me trate mi cielito～ Soy muy Frágil, ¿sabes?～"
  },
  AvgCommunicate_67040_Option_10 = {
    Text = "Solo dilo, ¿qué tramas esta vez..."
  },
  AvgCommunicate_67040_Option_2 = {
    Text = "¿Qué momento juntos?"
  },
  AvgCommunicate_67040_Option_3 = {
    Text = "No recuerdo."
  },
  AvgCommunicate_67040_Option_5 = {
    Text = "Te aconsejo que midas tus palabras..."
  },
  AvgCommunicate_67040_Option_8 = {
    Text = "?! ¿No te atreverás?"
  },
  AvgCommunicate_67041_Content_1 = {
    Text = "Maestro, estabas haciéndome gestos hace un momento. ¿Querías decir que deseabas contactarme?"
  },
  AvgCommunicate_67041_Content_10 = {
    Text = "Ay, necesito enseñarte a identificar a las malas mujeres en la escuela y conseguirte algunas medidas de precaución de inmediato."
  },
  AvgCommunicate_67041_Content_11 = {
    Text = "Escúchame—aléjate de su Puerta ahora mismo. Cuanto más lejos vayas, mejor. Solo dile Después que yo te llamé."
  },
  AvgCommunicate_67041_Content_12 = {
    Text = "P-pero ya se lo prometí a Lady Pandia. No puedo faltar a mi palabra."
  },
  AvgCommunicate_67041_Content_13 = {
    Text = "No os preocupéis, mi señor. ¡Hay Fortaleza suficiente para protegerme!"
  },
  AvgCommunicate_67041_Content_14 = {
    Text = "Tú, yo... Olvídalo. Si insistes en quedarte ahí, haz Registro de esto—nunca entres en su habitación."
  },
  AvgCommunicate_67041_Content_15 = {
    Text = "¡Por supuesto! ¡Jamás entraría en la habitación de una dama!"
  },
  AvgCommunicate_67041_Content_16 = {
    Text = "No importa lo que ella diga, no entres. Llámame si pasa algo. ¡Ah, y hagas lo que hagas, no huelas sus velas!"
  },
  AvgCommunicate_67041_Content_17 = {
    Text = "Lo recordaré, mi señor. Pero, ¿por qué no puedo oler las velas?"
  },
  AvgCommunicate_67041_Content_18 = {
    Text = "No preguntes... Son lecciones duras pagadas con mi Sangre y lágrimas en tu nombre..."
  },
  AvgCommunicate_67041_Content_2 = {
    Text = "Así es. ¿Por qué has estado parado frente a la Puerta de Pandia?"
  },
  AvgCommunicate_67041_Content_3 = {
    Text = "Ah, Pandia me lo pidió. Dijo que tenía algo muy importante que atender y quería que yo fuera el Guardián de su puerta."
  },
  AvgCommunicate_67041_Content_4 = {
    Text = "¿Algo importante? ¡No te creas sus tonterías! Sus supuestos asuntos... Olvídalo, ¡seguro que te ha engañado!"
  },
  AvgCommunicate_67041_Content_5 = {
    Text = "¿Eh? Pero su expresión de hace un momento era tan solemne, y me estaba tomando de la mano con tanta sinceridad..."
  },
  AvgCommunicate_67041_Content_6 = {
    Text = "Déjame adivinar—te tomó de la mano y te llamó el Caballero más confiable y gentil."
  },
  AvgCommunicate_67041_Content_7 = {
    Text = "¡¿Cómo lo sabéis, mi señor?!"
  },
  AvgCommunicate_67041_Content_8 = {
    Text = "Ogier, ¡nunca confíes en las palabras de una mala mujer! ¡Te tendrá comiendo de su mano!"
  },
  AvgCommunicate_67041_Content_9 = {
    Text = "Mm, solo siento que nadie tiene malas intenciones..."
  },
  AvgCommunicate_67041_Option_10 = {
    Text = "Necesito enseñarte a identificar a las malas mujeres en la escuela, y rápido..."
  },
  AvgCommunicate_67041_Option_14 = {
    Text = "Olvídalo..."
  },
  AvgCommunicate_67041_Option_16 = {
    Text = "No importa lo que diga, no entres. Llámame si algo sucede."
  },
  AvgCommunicate_67041_Option_18 = {
    Text = "No preguntes... Son lecciones duras pagadas con mi Sangre y lágrimas en tu nombre..."
  },
  AvgCommunicate_67041_Option_2 = {
    Text = "Así es. ¿Por qué has estado parado frente a la Puerta de Pandia?"
  },
  AvgCommunicate_67041_Option_4 = {
    Text = "¿Algo importante? ¡No te creas sus tonterías!"
  },
  AvgCommunicate_67041_Option_6 = {
    Text = "Déjame adivinar—te tomó de la mano y te llamó el Caballero más confiable y gentil."
  },
  AvgCommunicate_67041_Option_8 = {
    Text = "Ogier, ¡nunca confíes en las palabras de una mala mujer!"
  },
  AvgCommunicate_67042_Content_1 = {
    Text = "Din don, tienes un precioso regalo esperando a que lo recojas～"
  },
  AvgCommunicate_67042_Content_10 = {
    Text = "Huele bien, es un aroma muy peculiar, pero ¿por qué me estoy sintiendo un poco mareado/a..."
  },
  AvgCommunicate_67042_Content_11 = {
    Text = "Quizás ya te has enamorado de mí. Así que he bajado tal como pediste."
  },
  AvgCommunicate_67042_Content_12 = {
    Text = "¿Por qué no traes la vela del amor y sales a pasar un rato de calidad conmigo～"
  },
  AvgCommunicate_67042_Content_13 = {
    Text = "Me engañaste..."
  },
  AvgCommunicate_67042_Content_14 = {
    Text = "¿Cómo va a ser? Esto es un dulce contrato de mutuo consentimiento."
  },
  AvgCommunicate_67042_Content_2 = {
    Text = "¿Te refieres a esta caja rara en la puerta que solo tiene el nombre del destinatario?"
  },
  AvgCommunicate_67042_Content_3 = {
    Text = "Entonces puedes venir a reciclarla en el cubo de basura de abajo en la residencia ahora mismo."
  },
  AvgCommunicate_67042_Content_4 = {
    Text = "¡No seas tan cruel! Al menos échale un vistazo, ¡solo un vistazo!"
  },
  AvgCommunicate_67042_Content_5 = {
    Text = "No querrás que tu puerta se llene de mis regalos todos los días, ¿verdad?"
  },
  AvgCommunicate_67042_Content_6 = {
    Text = "Está bien, le echo un vistazo y luego vienes a recogerlo de la basura."
  },
  AvgCommunicate_67042_Content_7 = {
    Text = "¿Qué es esto... una vela rosa?"
  },
  AvgCommunicate_67042_Content_8 = {
    Text = "¡Es una vela del amor hecha especialmente! La temperatura a la que se derrite es juuusto la ideal～"
  },
  AvgCommunicate_67042_Content_9 = {
    Text = "¿Qué te parece? Huélela... ¿a que huele de maravilla y te dan ganas de olerla otra vez, y otra vez..."
  },
  AvgCommunicate_67042_Option_10 = {
    Text = "Huele bien, es un aroma muy peculiar, pero ¿por qué me estoy sintiendo un poco mareado/a..."
  },
  AvgCommunicate_67042_Option_13 = {
    Text = "Me engañaste..."
  },
  AvgCommunicate_67042_Option_2 = {
    Text = "¿Te refieres a esta caja rara en la puerta que solo tiene el nombre del destinatario?"
  },
  AvgCommunicate_67042_Option_6 = {
    Text = "Está bien, le echo un vistazo y luego vienes a recogerlo de la basura."
  },
  AvgCommunicate_67043_Content_1 = {
    Text = "Después de pasar tanto tiempo en Misaq, de repente me descubro echando de menos la luna sobre el desierto."
  },
  AvgCommunicate_67043_Content_10 = {
    Text = "Ven, creemos nuevos recuerdos juntos — entre las flores, a través de los campos abiertos, para ver el océano y los valles, las ciudades y el campo."
  },
  AvgCommunicate_67043_Content_11 = {
    Text = "Quiero dejar recuerdos nuestros en cada lugar hermoso. Te quedarás a mi lado, ¿verdad?"
  },
  AvgCommunicate_67043_Content_2 = {
    Text = "¿Así que tú también sientes nostalgia?"
  },
  AvgCommunicate_67043_Content_3 = {
    Text = "Más que nostalgia, quizás solo estoy rememorando los recuerdos que una vez compartí con otras personas — esas emociones intensas."
  },
  AvgCommunicate_67043_Content_4 = {
    Text = "No esperaba que fueras tan sentimental."
  },
  AvgCommunicate_67043_Content_5 = {
    Text = "¿Qué? ¿Crees que soy del tipo despreocupado y sin corazón? No, recuerdo a cada persona, cada recuerdo cálido y dulce."
  },
  AvgCommunicate_67043_Content_6 = {
    Text = "Incluidos los que tengo contigo."
  },
  AvgCommunicate_67043_Content_7 = {
    Text = "¿Debería sentirme honrado o celoso?"
  },
  AvgCommunicate_67043_Content_8 = {
    Text = "Me encanta verte así de nervioso/a. Qué adorable."
  },
  AvgCommunicate_67043_Content_9 = {
    Text = "Aunque los días pasados merecen ser saboreados, la alegría de esta noche es la más preciada de todas."
  },
  AvgCommunicate_67043_Option_2 = {
    Text = "¿Así que tú también sientes nostalgia?"
  },
  AvgCommunicate_67043_Option_4 = {
    Text = "No esperaba que fueras tan sentimental."
  },
  AvgCommunicate_67043_Option_7 = {
    Text = "¿Debería sentirme honrado o celoso?"
  },
  AvgCommunicate_67044_Content_1 = {
    Text = "Últimamente he estado diseñando un lote de accesorios para adornar mi colección."
  },
  AvgCommunicate_67044_Content_10 = {
    Text = "Si te apetece, por favor acepta estos collares que he seleccionado cuidadosamente. Esta vez son un regalo."
  },
  AvgCommunicate_67044_Content_11 = {
    Text = "Si encuentras uno que te guste después de probártelos, por favor asegúrate de decírmelo."
  },
  AvgCommunicate_67044_Content_12 = {
    Text = "Aunque tu cráneo aún no me pertenezca, con solo verte llevándolo puesto sería suficiente para alegrarme."
  },
  AvgCommunicate_67044_Content_2 = {
    Text = "Hay bastantes estilos entre los que elegir y me está costando decidirme, así que quería pedirte consejo."
  },
  AvgCommunicate_67044_Content_3 = {
    Text = "¿Colección?"
  },
  AvgCommunicate_67044_Content_4 = {
    Text = "No te refieres a..."
  },
  AvgCommunicate_67044_Content_5 = {
    Text = "Ah, mis preciados cráneos, por supuesto."
  },
  AvgCommunicate_67044_Content_6 = {
    Text = "He revisado muchas revistas de moda y diseños de joyerías."
  },
  AvgCommunicate_67044_Content_7 = {
    Text = "Todos los tipos de collares tienen su propio encanto, e incluso hay estilos de gargantilla poco convencionales. Es una elección tan difícil."
  },
  AvgCommunicate_67044_Content_8 = {
    Text = "Hmm... Creo que tu colección merece los accesorios más únicos."
  },
  AvgCommunicate_67044_Content_9 = {
    Text = "¿De verdad? Oírte decir eso me hace muy feliz."
  },
  AvgCommunicate_67044_Option_3 = {
    Text = "¿Colección?"
  },
  AvgCommunicate_67044_Option_4 = {
    Text = "No te refieres a..."
  },
  AvgCommunicate_67044_Option_8 = {
    Text = "Hmm... Creo que tu colección merece los accesorios más únicos."
  },
  AvgCommunicate_67045_Content_1 = {
    Text = "Ay, el negocio de mi pequeña tienda ha ido mal últimamente. Hace mucho que no encuentro una cabeza que me satisfaga."
  },
  AvgCommunicate_67045_Content_10 = {
    Text = "Si vosotros dos cooperarais para cazar a algunos grandes criminales buscados, podríais incluso crear una leyenda de justicieros urbanos que castigan el mal."
  },
  AvgCommunicate_67045_Content_11 = {
    Text = "No es mala sugerencia, pero un tipo tan astuto no es fácil de engañar."
  },
  AvgCommunicate_67045_Content_12 = {
    Text = "Ahora que lo pienso, esa peculiar cabeza suya valdría mucho la pena añadirla a mi Colección. Qué lástima que no haya oportunidad de hacer un intercambio. Qué pena."
  },
  AvgCommunicate_67045_Content_13 = {
    Text = "Espero que Ryker no esté estornudando ahora mismo..."
  },
  AvgCommunicate_67045_Content_2 = {
    Text = "Hmm... Las cabezas son, en efecto, algo que no puedes ir a comprar así como así."
  },
  AvgCommunicate_67045_Content_3 = {
    Text = "Así que recientemente llegué a un acuerdo de cooperación con el Comité de revisión. Les ayudo a rastrear fugitivos y, a cambio, me proporcionan en secreto las cabezas de los criminales ejecutados."
  },
  AvgCommunicate_67045_Content_4 = {
    Text = "Una persona viva a cambio de la cabeza de un muerto... es un buen trato para ambas partes."
  },
  AvgCommunicate_67045_Content_5 = {
    Text = "¿Eh? Nunca habría pensado que el Comité de revisión aceptaría ese tipo de cooperación."
  },
  AvgCommunicate_67045_Content_6 = {
    Text = "Por supuesto, no es una cooperación oficial, pero siempre hay gente espabilada en todas partes."
  },
  AvgCommunicate_67045_Content_7 = {
    Text = "También intenté contactar con la policía de Londinium, pero parece que confían más en ese detective con cabeza de perro."
  },
  AvgCommunicate_67045_Content_8 = {
    Text = "Como alguien se me adelantó en el negocio, no tuve más remedio que buscar en otra parte."
  },
  AvgCommunicate_67045_Content_9 = {
    Text = "Hmm... Aunque no creo que a Ryker le importe mucho ese negocio tampoco."
  },
  AvgCommunicate_67045_Option_13 = {
    Text = "Espero que Ryker no esté estornudando ahora mismo..."
  },
  AvgCommunicate_67045_Option_2 = {
    Text = "Hmm... Las cabezas son, en efecto, algo que no puedes ir a comprar así como así."
  },
  AvgCommunicate_67045_Option_5 = {
    Text = "¿Eh? Nunca habría pensado que el Comité de revisión aceptaría ese tipo de cooperación."
  },
  AvgCommunicate_67045_Option_9 = {
    Text = "Hmm... Aunque no creo que a Ryker le importe mucho ese negocio tampoco."
  },
  AvgCommunicate_67046_Content_1 = {
    Text = "¡Mi lord! ¡La yegua de sangre caliente llamada Copo de Nieve en el establo está a punto de dar a luz!"
  },
  AvgCommunicate_67046_Content_10 = {
    Text = "¡La idea de haber estado involucrado en el crecimiento de Pony desde una edad temprana me emociona!"
  },
  AvgCommunicate_67046_Content_11 = {
    Text = "¿Así que comenzar a criar caballos desde una edad tan temprana?"
  },
  AvgCommunicate_67046_Content_12 = {
    Text = "¡Un caballo es el compañero más cercano del caballero! Cuanta más confianza haya entre ellos, mejor."
  },
  AvgCommunicate_67046_Content_13 = {
    Text = "Siempre he querido tener un caballo que criara desde potrillo"
  },
  AvgCommunicate_67046_Content_14 = {
    Text = "Puedo ver que realmente estás esperando con ansias."
  },
  AvgCommunicate_67046_Content_15 = {
    Text = "Si tengo tiempo entonces, iré y te ayudaré."
  },
  AvgCommunicate_67046_Content_16 = {
    Text = "También tengo curiosidad por saber qué tipo de patrón tendrá el pony."
  },
  AvgCommunicate_67046_Content_17 = {
    Text = "¡Estaré bien preparado!"
  },
  AvgCommunicate_67046_Content_2 = {
    Text = "Recuerdo que ese semental era de un negro puro. Tengo curiosidad por el color de su descendencia—¿quizás negro y blanco?"
  },
  AvgCommunicate_67046_Content_3 = {
    Text = "Podrían parecerse a las rayas de una cebra."
  },
  AvgCommunicate_67046_Content_4 = {
    Text = "Entonces, ¿hay esta posibilidad? Eso es verdaderamente asombroso..."
  },
  AvgCommunicate_67046_Content_5 = {
    Text = "¡Jaja, es solo una broma! Es peligroso creer todo lo que dicen los demás."
  },
  AvgCommunicate_67046_Content_6 = {
    Text = "¡Iré más cuidado la próxima vez! Pero si es por ti, mi señor, no hay necesidad de sospechar"
  },
  AvgCommunicate_67046_Content_7 = {
    Text = "Ugh, que luz deslumbrante..."
  },
  AvgCommunicate_67046_Content_8 = {
    Text = "¿Cuál es este sentimiento de culpa..."
  },
  AvgCommunicate_67046_Content_9 = {
    Text = "Hmm? Por cierto, mi señor, planeo aprender algo de conocimiento relevante y entregar la Nieve personalmente."
  },
  AvgCommunicate_67046_Option_11 = {
    Text = "¿Así que comenzar a criar caballos desde una edad tan temprana?"
  },
  AvgCommunicate_67046_Option_14 = {
    Text = "Puedo ver que realmente estás esperando con ansias."
  },
  AvgCommunicate_67046_Option_3 = {
    Text = "Podrían parecerse a las rayas de una cebra."
  },
  AvgCommunicate_67046_Option_5 = {
    Text = "Haha, ¡solo estaba bromeando!"
  },
  AvgCommunicate_67046_Option_7 = {
    Text = "Ugh, que luz deslumbrante..."
  },
  AvgCommunicate_67046_Option_8 = {
    Text = "¿Cuál es este sentimiento de culpa..."
  },
  AvgCommunicate_67047_Content_1 = {
    Text = "Guardián, me gustaría pedirte un favor."
  },
  AvgCommunicate_67047_Content_10 = {
    Text = "Contigo a su lado, seguro que se sentirá más tranquila y podrá Relajarse."
  },
  AvgCommunicate_67047_Content_11 = {
    Text = "Yo voy con Ella... Entiendo."
  },
  AvgCommunicate_67047_Content_12 = {
    Text = "Entonces te lo encargo. Muchas gracias, Guardián."
  },
  AvgCommunicate_67047_Content_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_67047_Content_3 = {
    Text = "¿Podrías llevar a Tinct a algunas reuniones para que pueda hacer nuevos amigos?"
  },
  AvgCommunicate_67047_Content_4 = {
    Text = "Desde nuestro Reencuentro, se ha aferrado a mí todos los días, completamente aislada del mundo exterior."
  },
  AvgCommunicate_67047_Content_5 = {
    Text = "Aunque yo también valoro nuestro Reencuentro, no quiero mantenerla completamente atada a mi lado."
  },
  AvgCommunicate_67047_Content_6 = {
    Text = "Eso no es difícil, pero ¿has considerado cómo se siente Tinct al respecto?"
  },
  AvgCommunicate_67047_Content_7 = {
    Text = "Conozco a Ella... pero no puede seguir negándose a acercarse a Todos solo por mi bien."
  },
  AvgCommunicate_67047_Content_8 = {
    Text = "Quizás tú tampoco necesitas alejarla de forma tan tajante."
  },
  AvgCommunicate_67047_Content_9 = {
    Text = "¿Qué tal si os llevo a ti y a Tinct juntos a una reunión? Me aseguraré de que se tomen las precauciones adecuadas."
  },
  AvgCommunicate_67047_Option_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_67047_Option_6 = {
    Text = "Eso no es difícil, pero ¿has considerado cómo se siente Tinct al respecto?"
  },
  AvgCommunicate_67047_Option_8 = {
    Text = "Quizás tú tampoco necesitas alejarla de forma tan tajante."
  },
  AvgCommunicate_67048_Content_1 = {
    Text = "Guardián, gracias por tu sugerencia la última vez."
  },
  AvgCommunicate_67048_Content_10 = {
    Text = "Parece que la que necesita mejorar soy yo, la hermana mayor."
  },
  AvgCommunicate_67048_Content_2 = {
    Text = "Desde que Tinct y yo fuimos juntas a esa reunión, Tinct se ha enamorado de charlar con sus nuevas amigas."
  },
  AvgCommunicate_67048_Content_3 = {
    Text = "De nada. Verlas felices a las dos me hace feliz a mí también."
  },
  AvgCommunicate_67048_Content_4 = {
    Text = "Mm... Fue la primera vez que me di cuenta de que, cuando está completamente libre de cargas, Tinct es una niña muy sociable."
  },
  AvgCommunicate_67048_Content_5 = {
    Text = "Sigue quedándose cerca de mí cada vez, incluyéndome en las conversaciones de vez en cuando."
  },
  AvgCommunicate_67048_Content_6 = {
    Text = "Pero hacía tanto tiempo que no la veía sonreír tan felizmente rodeada de otras personas."
  },
  AvgCommunicate_67048_Content_7 = {
    Text = "¡Eso es maravilloso!"
  },
  AvgCommunicate_67048_Content_8 = {
    Text = "Ay, es solo que, comparado con su Elación, yo sigo encontrando estas frecuentes ocasiones sociales un poco agotadoras."
  },
  AvgCommunicate_67048_Content_9 = {
    Text = "Después de cada reunión, necesito Descansar bien dentro de mi caparazón un rato antes de poder recuperarme."
  },
  AvgCommunicate_67048_Option_3 = {
    Text = "De nada. Verlas felices a las dos me hace feliz a mí también."
  },
  AvgCommunicate_67048_Option_7 = {
    Text = "¡Eso es maravilloso!"
  },
  AvgCommunicate_67049_Content_1 = {
    Text = "Keeper, ¿me buscabas?"
  },
  AvgCommunicate_67049_Content_10 = {
    Text = "¡Claramente intentas engañar a la gente para que haga sacrificios al océano de nuevo!"
  },
  AvgCommunicate_67049_Content_11 = {
    Text = "Por supuesto que no, eso fueron solo accidentes. Descansando por siempre en su tierra natal, sus almas encontrarán la salvación."
  },
  AvgCommunicate_67049_Content_12 = {
    Text = "¡Has dejado completamente el acto! ¡Suspensión! ¡Suspéndelo de inmediato!!"
  },
  AvgCommunicate_67049_Content_2 = {
    Text = "Exactamente, te hice gestionar el tráfico de Mitag recientemente. ¿Cómo te fue?"
  },
  AvgCommunicate_67049_Content_3 = {
    Text = "Me siento genial. Guiar a los perdidos siempre ha sido mi deber, mi destino y mi propósito."
  },
  AvgCommunicate_67049_Content_4 = {
    Text = "Guiado por mi luz, el tráfico de Mythag fluye más suavemente que nunca."
  },
  AvgCommunicate_67049_Content_5 = {
    Text = "Oh, ¿de verdad? Entonces, ¿por qué todas estas quejas?"
  },
  AvgCommunicate_67049_Content_6 = {
    Text = "Imposible, mi guía no puede estar equivocada."
  },
  AvgCommunicate_67049_Content_7 = {
    Text = "Déjame ver, distribuyendo volantes durante la luz roja, leyendo anuncios, incluyendo..."
  },
  AvgCommunicate_67049_Content_8 = {
    Text = "¿Tour de Buceo de Tesoro de Naufragio? ¿Grupo de Vacaciones de Crucero de Lujo? ¿Pesca en el Mar y Festín de Cocina?"
  },
  AvgCommunicate_67049_Content_9 = {
    Text = "¿Hay algún problema? El mar es tan encantador. Creo que todos deberían acercarse a él."
  },
  AvgCommunicate_67049_Option_10 = {
    Text = "¡Claramente intentas engañar a la gente para que haga sacrificios al océano de nuevo!"
  },
  AvgCommunicate_67049_Option_12 = {
    Text = "¡Has dejado completamente el acto! ¡Suspensión! ¡Suspéndelo de inmediato!!"
  },
  AvgCommunicate_67049_Option_2 = {
    Text = "Exactamente, te hice gestionar el tráfico de Mitag recientemente. ¿Cómo te fue?"
  },
  AvgCommunicate_67049_Option_5 = {
    Text = "Oh, ¿de verdad? Entonces, ¿por qué todas estas quejas?"
  },
  AvgCommunicate_67049_Option_7 = {
    Text = "Déjame ver, distribuyendo volantes durante la luz roja, leyendo anuncios, incluyendo..."
  },
  AvgCommunicate_67050_Content_1 = {
    Text = "Guardián, ¿qué es este aviso que me prohíbe salir de noche? No creo haber hecho nada que viole las reglas."
  },
  AvgCommunicate_67050_Content_10 = {
    Text = "Tranquilo. En fin, solo procura Descansar bien esta noche."
  },
  AvgCommunicate_67050_Content_11 = {
    Text = "Si quieres, Después puedo sugerirle a la escuela que te pongan a cargo de la orientación del tráfico en los Caminos de la escuela."
  },
  AvgCommunicate_67050_Content_2 = {Text = "Verás..."},
  AvgCommunicate_67050_Content_3 = {
    Text = "Varias veces antes, cuando deambulabas por el campus en mitad de la noche, desde lejos parecías un ojo flotante. Asustaste a los estudiantes que caminaban por el Camino nocturno."
  },
  AvgCommunicate_67050_Content_4 = {
    Text = "Absurdo. Mi resplandor siempre ha sido una luz guía para los perdidos. ¿Cómo podría resultar aterrador?"
  },
  AvgCommunicate_67050_Content_5 = {
    Text = "Los estudiantes que lo reportaron dijeron que cuando te dabas cuenta de su presencia, de repente te acercabas hacia ellos."
  },
  AvgCommunicate_67050_Content_6 = {
    Text = "Los asustaste tanto que no paraban de correr, pero tú seguías persiguiéndolos."
  },
  AvgCommunicate_67050_Content_7 = {
    Text = "La noche estaba completamente oscura. Solo esperaba guiarlos por el Camino correcto."
  },
  AvgCommunicate_67050_Content_8 = {
    Text = "Magnífica guía. Por favor, no lo hagas más."
  },
  AvgCommunicate_67050_Content_9 = {
    Text = "Ellos... incluso ellos... ninguno de ustedes, Todos, entiende mi deber..."
  },
  AvgCommunicate_67050_Option_10 = {
    Text = "Tranquilo. En fin, solo procura Descansar bien esta noche."
  },
  AvgCommunicate_67050_Option_2 = {Text = "Verás..."},
  AvgCommunicate_67050_Option_5 = {
    Text = "Los estudiantes que lo reportaron dijeron que cuando te dabas cuenta de su presencia, de repente te acercabas hacia ellos."
  },
  AvgCommunicate_67050_Option_8 = {
    Text = "Magnífica guía. Por favor, no lo hagas más."
  },
  AvgCommunicate_67051_Content_1 = {
    Text = "De repente he perdido el interés en las peleas simples."
  },
  AvgCommunicate_67051_Content_10 = {
    Text = "¿Tan rápido? Entonces debes tener un verdadero Talento para ello. ¿Ya has jugado contra alguien?"
  },
  AvgCommunicate_67051_Content_11 = {
    Text = "Sí, llamé a la Puerta de cada Cuerpo Despertado. Aunque no todos aceptaron Jugar."
  },
  AvgCommunicate_67051_Content_12 = {
    Text = "¡¡Así que solo encontraste una nueva forma de molestar a todos!!"
  },
  AvgCommunicate_67051_Content_13 = {
    Text = "Eso no importa... ¿Y cómo va tu Registro?"
  },
  AvgCommunicate_67051_Content_14 = {
    Text = "Hasta ahora Solo he vencido a Aurita, ¡pero estoy segura de que Solo siga practicando, Solo me haré más fuerte!"
  },
  AvgCommunicate_67051_Content_2 = {
    Text = "?? ¡Sea quien sea, bájate de Lotan ahora mismo!"
  },
  AvgCommunicate_67051_Content_3 = {
    Text = "¿De qué hablas? Hace poco descubrí un tipo de batalla más interesante."
  },
  AvgCommunicate_67051_Content_4 = {Text = "¿Qué es?"},
  AvgCommunicate_67051_Content_5 = {
    Text = "¡Ajedrez! Dexter me habló de él. Dijo que todos los verdaderos maestros de artes marciales son hábiles en el ajedrez."
  },
  AvgCommunicate_67051_Content_6 = {
    Text = "Solo percibiendo las intenciones de tu oponente y anticipando sus movimientos puedes lograr la victoria en el tablero."
  },
  AvgCommunicate_67051_Content_7 = {
    Text = "Solo aprenda ajedrez, ¡seguro que alcanzaré el siguiente nivel en combate!"
  },
  AvgCommunicate_67051_Content_8 = {
    Text = "Algo no suena bien en eso... pero al menos el resultado es bueno."
  },
  AvgCommunicate_67051_Content_9 = {
    Text = "Llevo Hace una semana estudiando ajedrez, ¡y siento que lo he dominado por completo!"
  },
  AvgCommunicate_67051_Option_10 = {
    Text = "¿Tan rápido?"
  },
  AvgCommunicate_67051_Option_12 = {
    Text = "¡¡Así que solo encontraste una nueva forma de molestar a todos!!"
  },
  AvgCommunicate_67051_Option_2 = {
    Text = "?? ¡Sea quien sea, bájate de Lotan ahora mismo!"
  },
  AvgCommunicate_67051_Option_4 = {Text = "¿Qué es?"},
  AvgCommunicate_67051_Option_8 = {
    Text = "Algo no suena bien en eso... pero al menos el resultado es bueno."
  },
  AvgCommunicate_67052_Content_1 = {Text = "Hambre."},
  AvgCommunicate_67052_Content_10 = {
    Text = "Karen, dijo que hay un tipo de, embutido, hecho con Sangre, sabroso."
  },
  AvgCommunicate_67052_Content_11 = {
    Text = "Quiero comerlo."
  },
  AvgCommunicate_67052_Content_12 = {
    Text = "Entonces pídele a Ella que te lo prepare."
  },
  AvgCommunicate_67052_Content_13 = {
    Text = "Ella no puede. Hazlo tú para mí."
  },
  AvgCommunicate_67052_Content_14 = {
    Text = "? Ella ni siquiera sabe hacerlo, ¿por qué iba a saber yo?"
  },
  AvgCommunicate_67052_Content_15 = {
    Text = "Tu Sangre, sabrosa, Liberar una gota."
  },
  AvgCommunicate_67052_Content_16 = {Text = "Por favor."},
  AvgCommunicate_67052_Content_17 = {
    Text = "...Estoy arriesgando mi vida solo para comerme a ti."
  },
  AvgCommunicate_67052_Content_18 = {
    Text = "Está bien, ya que me lo suplicas, lo investigaré."
  },
  AvgCommunicate_67052_Content_2 = {
    Text = "Lo sabía. No te has vuelto adicta a beber mi Sangre, ¿verdad?"
  },
  AvgCommunicate_67052_Content_3 = {
    Text = "Mm, pero si bebes demasiado, morirás."
  },
  AvgCommunicate_67052_Content_4 = {
    Text = "Gracias por preocuparte tanto por si vivo o muero. ¿Quién fue la que se dejó llevar tanto bebiendo mi Sangre que terminó peleando conmigo la última vez?"
  },
  AvgCommunicate_67052_Content_5 = {
    Text = "Está deliciosa, de verdad."
  },
  AvgCommunicate_67052_Content_6 = {
    Text = "Olvídalo. En fin, no bebas de la mía esta vez. Ya estoy al borde de la anemia."
  },
  AvgCommunicate_67052_Content_7 = {
    Text = "Pero el hospital ha estado diciendo que su banco de Sangre anda bajo últimamente, así que no pueden darnos nada extra. Qué fastidio."
  },
  AvgCommunicate_67052_Content_8 = {Text = "Morcilla."},
  AvgCommunicate_67052_Content_9 = {Text = "¿Qué?"},
  AvgCommunicate_67052_Option_12 = {
    Text = "Entonces pídele a Ella que te lo prepare."
  },
  AvgCommunicate_67052_Option_14 = {
