  },
  AvgCommunicate_67052_Option_4 = {
    Text = "Gracias por preocuparte tanto por si vivo o muero."
  },
  AvgCommunicate_67052_Option_6 = {
    Text = "Olvídalo. En fin, no bebas de la mía esta vez. Ya estoy al borde de la anemia."
  },
  AvgCommunicate_67052_Option_9 = {Text = "¿Qué?"},
  AvgCommunicate_67053_Content_1 = {
    Text = "Vaya, vaya, perrito, vi que acabas de llevarle un pastel a Tawil."
  },
  AvgCommunicate_67053_Content_10 = {
    Text = "Después de todo, cuando me siento sola, estas Puertas Selladas siempre tienden a aflojarse un poco..."
  },
  AvgCommunicate_67053_Content_11 = {
    Text = "¡Tú! Yo— ¡está bien, ya voy ahora mismo!"
  },
  AvgCommunicate_67053_Content_2 = {
    Text = "Ahora tienes favoritos, sin traerle uno siquiera a tu querida mentora. Qué descorazonador."
  },
  AvgCommunicate_67053_Content_3 = {
    Text = "Como si pudieras comerlo, ¿no?"
  },
  AvgCommunicate_67053_Content_4 = {
    Text = "Pues adelante, desconsuélate."
  },
  AvgCommunicate_67053_Content_5 = {
    Text = "Aunque mi cuerpo no necesite comer, mi espíritu sigue necesitando mucho el cariño de mi perrito."
  },
  AvgCommunicate_67053_Content_6 = {
    Text = "Si dejarlo aquí sería un desperdicio, verte comerlo frente a mí tampoco estaría mal."
  },
  AvgCommunicate_67053_Content_7 = {
    Text = "Puedo imaginar la textura y el sabor de esa dulce crema, cómo se desliza desde la punta de tu lengua por tu garganta..."
  },
  AvgCommunicate_67053_Content_8 = {
    Text = "¿? Parece que lo tienes todo planeado, pero ¿cuándo acepté yo esto?"
  },
  AvgCommunicate_67053_Content_9 = {
    Text = "Pensé que eventualmente aprenderías a portarte bien, pero sigues siendo adorablemente tonto."
  },
  AvgCommunicate_67053_Option_11 = {
    Text = "¡Tú! Yo— ¡está bien, ya voy ahora mismo!"
  },
  AvgCommunicate_67053_Option_3 = {
    Text = "Como si pudieras comerlo, ¿no?"
  },
  AvgCommunicate_67053_Option_4 = {
