  AvgCommunicate_67054_Content_1 = {
    Text = "Ah, ¡Guardián! ¡La habitación de Aurita está completamente inundada!"
  },
  AvgCommunicate_67054_Content_2 = {
    Text = "¿Qué está pasando??"
  },
  AvgCommunicate_67054_Content_3 = {
    Text = "Justo ahora, Aurita quería jugar con sus amigos y saltó al acuario—¡splash!—"
  },
  AvgCommunicate_67054_Content_4 = {
    Text = "¡Aurita es demasiado grande, el tanque es demasiado pequeño, y toda el agua se exprime!"
  },
  AvgCommunicate_67054_Content_5 = {
    Text = "Uh, es algo que eres capaz de hacer. Sin problema, estoy en camino."
  },
  AvgCommunicate_67054_Content_6 = {
    Text = "Suspira, Aurita quiere un enorme acuario, súper grande, ¡tan grande como una habitación entera!"
  },
  AvgCommunicate_67054_Content_7 = {
    Text = "¡De esta manera, Aurita y sus amigos pueden jugar juntos todos los días!"
  },
  AvgCommunicate_67054_Content_8 = {
    Text = "El sueño es hermoso, ¡pero la escuela no tiene fondos para construir un acuario!"
  },
  AvgCommunicate_67054_Content_9 = {
    Text = "Sigh—¡Vaya, algo tan grande como media habitación también puede funcionar!"
  },
  AvgCommunicate_67054_Option_2 = {
    Text = "¿Qué está pasando??"
  },
  AvgCommunicate_67054_Option_5 = {
    Text = "Uh, es algo que eres capaz de hacer. Sin problema, estoy en camino."
  },
  AvgCommunicate_67054_Option_8 = {
    Text = "El sueño es hermoso, ¡pero la escuela no tiene fondos para construir un acuario!"
  },
  AvgCommunicate_67055_Content_1 = {
    Text = "Guardián, ¿por qué no se mueve el compañero que traímos de la playa"
  },
  AvgCommunicate_67055_Content_2 = {
    Text = "¿Está enfermo o deprimido mi compañero...?"
  },
  AvgCommunicate_67055_Content_3 = {
    Text = "¿Puede el Guardián ayudar a sus compañeros?"
  },
  AvgCommunicate_67055_Content_4 = {
    Text = "Mm... Mi pareja debe estar extrañando el mar."
  },
  AvgCommunicate_67055_Content_5 = {
    Text = "Vino del mar. ¿Deberíamos devolverlo al mar juntos?"
  },
  AvgCommunicate_67055_Content_6 = {
    Text = "De esta manera... entiendo. Mi compañero está sintiendo nostalgia."
  },
  AvgCommunicate_67055_Content_7 = {
    Text = "Aurita extraña el mar, pero Aurita también ama la escuela. Ahora, Aurita tiene dos hogares."
  },
  AvgCommunicate_67055_Content_8 = {
    Text = "¡Vamos! ¡Llevemos a nuestro amigo a casa! Luego podemos regresar juntos, de vuelta a nuestra escuela"
  },
  AvgCommunicate_67055_Option_4 = {
    Text = "Mm... Mi pareja debe estar extrañando el mar."
  },
  AvgCommunicate_67056_Content_1 = {
    Text = "Disculpe, he estado pensando por mucho tiempo y me gustaría preguntarle..."
  },
  AvgCommunicate_67056_Content_10 = {
    Text = "¿Es así...? Eso es genial."
  },
  AvgCommunicate_67056_Content_11 = {
    Text = "Estoy contento de haber podido ayudar."
  },
  AvgCommunicate_67056_Content_12 = {
    Text = "No tienes que apresurarte cada vez. Estaría feliz de charlar contigo y tomar una taza de té."
  },
  AvgCommunicate_67056_Content_13 = {
    Text = "No... no pertenezco aquí. Quedarme sería un apego, lo cual es dañino para ti, para mí, e incluso para el tiempo y el espacio."
  },
  AvgCommunicate_67056_Content_14 = {
    Text = "Luego, al menos concédeme un momento para despedirme, para que siempre tenga tiempo de decirte adiós."
  },
  AvgCommunicate_67056_Content_15 = {
    Text = "...Está bien."
  },
  AvgCommunicate_67056_Content_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_67056_Content_3 = {
    Text = "¿Cómo crees que respondo a tu invocación?"
  },
  AvgCommunicate_67056_Content_4 = {
    Text = "Aunque siempre atiendo tu llamada y me pongo en marcha en el primer momento."
  },
  AvgCommunicate_67056_Content_5 = {
    Text = "Pero me preocupa que pueda haber algunas desviaciones durante el proceso de cruzar el tiempo y el espacio, y si hay un retraso en el tiempo..."
  },
  AvgCommunicate_67056_Content_6 = {
    Text = "La idea de que estés en peligro por esto me hace sentir inquieto."
  },
  AvgCommunicate_67056_Content_7 = {Text = "Ramona..."},
  AvgCommunicate_67056_Content_8 = {
    Text = "Nada, siempre llegas justo a tiempo."
  },
  AvgCommunicate_67056_Content_9 = {
    Text = "Saber que siempre estás detrás de mí me da tranquilidad."
  },
  AvgCommunicate_67056_Option_12 = {
    Text = "En realidad, no tienes que salir corriendo cada vez..."
  },
  AvgCommunicate_67056_Option_14 = {
    Text = "Luego, al menos concédeme un momento para decir adiós."
  },
  AvgCommunicate_67056_Option_2 = {
    Text = "¿Qué pasa?"
  },
  AvgCommunicate_67056_Option_7 = {Text = "Ramona..."},
  AvgCommunicate_67057_Content_1 = {
    Text = "Guardián, hola."
  },
  AvgCommunicate_67057_Content_10 = {
    Text = "Lo siento, no puedo buscar las tareas de otras personas para ti. Dicho comportamiento constituye plagio y viola las normas escolares y la ética social."
  },
  AvgCommunicate_67057_Content_11 = {
    Text = "Si tienes alguna otra pregunta o necesitas ayuda, no dudes en decírmelo. Te proporcionaré información positiva y constructiva."
  },
  AvgCommunicate_67057_Content_12 = {
    Text = "Ay, por favor... Entonces, ¿al menos puedes buscar en la base de datos las respuestas a las preguntas de la tarea, o algún material relacionado?"
  },
  AvgCommunicate_67057_Content_13 = {
    Text = "Lo siento, no puedo buscar las respuestas de las tareas para ti. Dicho comportamiento constituye trampa y viola las normas escolares y la ética social."
  },
  AvgCommunicate_67057_Content_14 = {
    Text = "Si tienes alguna otra pregunta o necesitas ayuda, no dudes en decírmelo. Te proporcionaré información positiva y constructiva."
  },
  AvgCommunicate_67057_Content_15 = {
    Text = "¡Qué sistema más inútil, es demasiado recto! ¡Apágalo! ¡Apágalo! ¡Voy a dejar una mala reseña!"
  },
  AvgCommunicate_67057_Content_16 = {
    Text = "Tu opinión ha sido recibida. Esperamos verte de nuevo una vez que se hayan realizado las mejoras."
  },
  AvgCommunicate_67057_Content_2 = {
    Text = "Estás invitado a probar el nuevo sistema de consulta inteligente. Por favor, comparte tus comentarios y sugerencias después de la prueba."
  },
  AvgCommunicate_67057_Content_3 = {
    Text = "Puedes intentar decirme: ¿Qué tiempo hace hoy?"
  },
  AvgCommunicate_67057_Content_4 = {
    Text = "¿Qué tiempo hace hoy?"
  },
  AvgCommunicate_67057_Content_5 = {
    Text = "Londinium hoy: lluvia ligera pasando a parcialmente nublado, temperaturas entre 18 y 25 grados Celsius, viento del suroeste de fuerza 2 a 3. Se recomienda llevar un paraguas al salir."
  },
  AvgCommunicate_67057_Content_6 = {
    Text = "¿Eso es impresionante? Déjame pensar... ¿Puedes buscar mi próximo horario de clases?"
  },
  AvgCommunicate_67057_Content_7 = {
    Text = "Se te ha enviado por separado un horario de clases organizado. Se han encontrado tres tareas con entregas pendientes. Por favor, ten en cuenta las fechas límite de entrega."
  },
  AvgCommunicate_67057_Content_8 = {
    Text = "Uf, tenías que mencionar lo único que no quería escuchar..."
  },
  AvgCommunicate_67057_Content_9 = {
    Text = "Ah, cierto, ¿puedes buscar las tareas que han entregado otras personas? Solo quiero usarlas como una pequeña referencia..."
  },
  AvgCommunicate_67057_Option_12 = {
    Text = "Ay, por favor..."
  },
  AvgCommunicate_67057_Option_15 = {
    Text = "¡Qué sistema más inútil, es demasiado recto! ¡Apágalo! ¡Apágalo! ¡Voy a dejar una mala reseña!"
  },
  AvgCommunicate_67057_Option_4 = {
    Text = "¿Qué tiempo hace hoy?"
  },
  AvgCommunicate_67057_Option_6 = {
    Text = "¿Eso es impresionante? Déjame pensar... ¿Puedes buscar mi próximo horario de clases?"
  },
  AvgCommunicate_67057_Option_8 = {
    Text = "Uf, tenías que mencionar lo único que no quería escuchar..."
  },
  AvgCommunicate_70486_Content_1 = {
    Text = "Escuché que..."
  },
  AvgCommunicate_70486_Content_10 = {
    Text = "Ramona, de hecho, fue llevada al Pozo Negro, pero sabes, ese es un lugar al que no puedes ir..."
  },
  AvgCommunicate_70486_Content_11 = {
    Text = "Ten la seguridad, ¡traeré a Ramona de vuelta completamente intacta!"
  },
  AvgCommunicate_70486_Content_12 = {
    Text = "Gracias por informarme. Sin embargo, me temo que tengo que decepcionarte esta vez."
  },
  AvgCommunicate_70486_Content_13 = {
    Text = "Por favor, entiende los sentimientos de un padre."
  },
  AvgCommunicate_70486_Content_14 = {
    Text = "Las cosas que haré en el futuro, espero que puedas perdonarme."
  },
  AvgCommunicate_70486_Content_15 = {
    Text = "¡La Charca Negra es extremadamente peligrosa ahora; tu fuerza espiritual no puede sobrevivir en la Charca Negra!"
  },
  AvgCommunicate_70486_Content_16 = {
    Text = "¡Por favor, no actúes apresuradamente, profesor Dexter!"
  },
  AvgCommunicate_70486_Content_17 = {
    Text = "¿Profesor Dexter?"
  },
  AvgCommunicate_70486_Content_18 = {
    Text = "¿¡Profesor Dexter?!..."
  },
  AvgCommunicate_70486_Content_2 = {
    Text = "Ramona, ¿te llevaron al Pozo Negro?"
  },
  AvgCommunicate_70486_Content_3 = {
    Text = "Es mi culpa por no haberla protegido..."
  },
  AvgCommunicate_70486_Content_4 = {
    Text = "No es tu responsabilidad. No necesitas culparte, Guardián."
  },
  AvgCommunicate_70486_Content_5 = {
    Text = "Mientras escoltaba al Decano Czort, se encontró con Herbert......"
  },
  AvgCommunicate_70486_Content_6 = {
    Text = "No es una reunión, Guardián."
  },
  AvgCommunicate_70486_Content_7 = {
    Text = "Herbert está aquí por Ramona."
  },
  AvgCommunicate_70486_Content_8 = {
    Text = "Solo quiero saber ahora si la llevaron al Pozo Negro."
  },
  AvgCommunicate_70486_Content_9 = {
    Text = "No quiero ocultar nada, Profesor Dexter."
  },
  AvgCommunicate_70486_Option_15 = {
    Text = "¡Por favor, no seas impulsivo!"
  },
  AvgCommunicate_70486_Option_3 = {
    Text = "Es mi culpa por no haberla protegido..."
  },
  AvgCommunicate_70486_Option_5 = {
    Text = "Mientras escoltaba al Decano Czort, se encontró con Herbert......"
  },
  AvgCommunicate_70486_Option_9 = {Text = "Sí..."},
  AvgCommunicate_70487_Content_1 = {
    Text = "¿Cómo va la recuperación de ese debilucho?"
  },
  AvgCommunicate_70487_Content_10 = {Text = "..."},
  AvgCommunicate_70487_Content_11 = {
    Text = "No me gusta ella, ni tampoco me gustas tú. Pero detesto aún más a esa montaña nevada tan engreída, así como a aquellos que quieren usarme y traicionarme."
  },
  AvgCommunicate_70487_Content_12 = {
    Text = "Eso es todo."
  },
  AvgCommunicate_70487_Content_2 = {
    Text = "Después de regresar de la Montaña de Nieve, recibió sanación, y sus heridas sanaron muy bien."
  },
  AvgCommunicate_70487_Content_3 = {
    Text = "Escuché sobre la montaña nevada de otra versión de ti."
  },
  AvgCommunicate_70487_Content_4 = {
    Text = "Gracias, Helot. Fuiste tú quien nos ayudó."
  },
  AvgCommunicate_70487_Content_5 = {
    Text = "¿Gracias? Qué palabra tan débil."
  },
  AvgCommunicate_70487_Content_6 = {
    Text = "Solo busco el poder de la Montaña de Nieve. No tiene nada que ver con ayudarte."
  },
  AvgCommunicate_70487_Content_7 = {
    Text = "Las vidas de un grupo de hormigas no me conciernen."
  },
  AvgCommunicate_70487_Content_8 = {
    Text = "En la montaña nevada, tuviste la oportunidad de matar otra versión de ti mismo, ya sea para devorar el poder de la montaña nevada solo o permitir que la montaña nevada nos devorara."
  },
  AvgCommunicate_70487_Content_9 = {
    Text = "Pero no lo hiciste, ¿cierto?"
  },
  AvgCommunicate_70487_Option_3 = {
    Text = "Gracias por contarme sobre la Montaña de Nieve."
  },
  AvgCommunicate_70487_Option_8 = {
    Text = "Pero elegiste no matar otra versión de ti mismo."
  },
  AvgCommunicate_70488_Content_1 = {
    Text = "Capitán, el cuerpo ha estado debilitándose..."
  },
  AvgCommunicate_70488_Content_10 = {
    Text = "Guardián, haré todo lo posible para asistirte."
  },
  AvgCommunicate_70488_Content_11 = {
    Text = "Si hay una oportunidad, por favor salva al capitán."
  },
  AvgCommunicate_70488_Content_12 = {
    Text = "Esto es... mi deseo."
  },
  AvgCommunicate_70488_Content_2 = {
    Text = "¿Puedo preguntar, hay alguna forma de ayudarlo?"
  },
  AvgCommunicate_70488_Content_3 = {
    Text = "Esto puede ser difícil, Celeste."
  },
  AvgCommunicate_70488_Content_4 = {
    Text = "Incluso para los Investigadores, vincularse a los Despertadores es una carga tremenda."
  },
  AvgCommunicate_70488_Content_5 = {
    Text = "Además, el Capitán Elton es simplemente una persona ordinaria en este aspecto."
  },
  AvgCommunicate_70488_Content_6 = {
    Text = "Que haya podido mantener un vínculo contigo durante tanto tiempo ya es un milagro."
  },
  AvgCommunicate_70488_Content_7 = {
    Text = "Pero por favor, ten la seguridad de que definitivamente encontraré una manera de ayudarte."
  },
  AvgCommunicate_70488_Content_8 = {
    Text = "Lo que Miryam puede hacer, Mythag ciertamente también puede hacerlo."
  },
  AvgCommunicate_70488_Content_9 = {
    Text = "Las personas me hacen deseos, pero soy impotente para ayudar a los que me rodean..."
  },
  AvgCommunicate_70488_Option_3 = {
    Text = "Esto puede ser difícil, pero Mythag seguramente encontrará una manera."
  },
  AvgCommunicate_70489_Content_1 = {
    Text = "Lo siento por la interrupción, pálido Ojo Ciego."
  },
  AvgCommunicate_70489_Content_10 = {
    Text = "Mi contacto contigo se basa puramente en un interés personal."
  },
  AvgCommunicate_70489_Content_11 = {
    Text = "Después de ocuparme de los asuntos actuales, realmente espero tener la oportunidad de reunirme contigo en privado."
  },
  AvgCommunicate_70489_Content_12 = {
    Text = "Para hablar contigo sobre tu pasado y tu futuro."
  },
  AvgCommunicate_70489_Content_13 = {
    Text = "Por supuesto, siempre que puedas sobrevivir a estos Eventos."
  },
  AvgCommunicate_70489_Content_14 = {
    Text = "Te deseo lo mejor, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgCommunicate_70489_Content_15 = {
    Text = "¿Mi futuro?"
  },
  AvgCommunicate_70489_Content_16 = {
    Text = "¿Qué quieres decir?"
  },
  AvgCommunicate_70489_Content_17 = {Text = "..."},
  AvgCommunicate_70489_Content_18 = {
    Text = "¿Clementine?"
  },
  AvgCommunicate_70489_Content_2 = {
    Text = "Eres tú... Perfecto momento. Aún tengo muchas cosas que quiero preguntarte."
  },
  AvgCommunicate_70489_Content_3 = {
    Text = "¿Qué nos hiciste en el asilo?"
  },
  AvgCommunicate_70489_Content_4 = {
    Text = "Como dije, algunos trucos en campos especializados."
  },
  AvgCommunicate_70489_Content_5 = {
    Text = "Puede permitirme irme y dejar que todos ustedes duerman bien."
  },
  AvgCommunicate_70489_Content_6 = {
    Text = "Has mencionado el término \"Ojo Ciego\" más de una vez. ¿Qué significa realmente?"
  },
  AvgCommunicate_70489_Content_7 = {
    Text = "¡Shh, esto no es algo que debas saber ahora mismo!"
  },
  AvgCommunicate_70489_Content_8 = {
    Text = "¡Confía en mí, lo sabrás — cuando llegue el momento adecuado!"
  },
  AvgCommunicate_70489_Content_9 = {
    Text = "En cualquier caso, no pretendo hacer daño, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgCommunicate_70489_Option_15 = {
    Text = "¿Mi futuro?"
  },
  AvgCommunicate_70489_Option_2 = {
    Text = "¿Eres... el psicólogo?!"
  },
  AvgCommunicate_70489_Option_3 = {
    Text = "¿Qué nos hiciste en el asilo?"
  },
  AvgCommunicate_70489_Option_6 = {
    Text = "¿Qué significa exactamente \"Ojo Ciego\"?"
  },
  AvgCommunicate_70490_Content_1 = {
    Text = "Cuando el Cuerpo artificial se autodestruyó, dejé a Herbert un pequeño trozo de Plata con capacidades de grabación y transmisión de información."
  },
  AvgCommunicate_70490_Content_10 = {
    Text = "Exactamente igual que el símbolo que dibujaste en tu sueño."
  },
  AvgCommunicate_70490_Content_11 = {
    Text = "¿Qué es exactamente ese símbolo?"
  },
  AvgCommunicate_70490_Content_12 = {
    Text = "Iglesia de la luz del templo."
  },
  AvgCommunicate_70490_Content_13 = {
    Text = "En realidad son ellos..."
  },
  AvgCommunicate_70490_Content_14 = {
    Text = "La Asociación de Escultores, Elvos... la figura de la linterna ya ha aparecido antes."
  },
  AvgCommunicate_70490_Content_15 = {
    Text = "Los verdaderos enemigos de Mitag se están acercando a nosotros."
  },
  AvgCommunicate_70490_Content_16 = {
    Text = "Prepárate, %player%."
  },
  AvgCommunicate_70490_Content_2 = {
    Text = "Gracias a la codicia de Herbert, este pequeño dispositivo aún logró reunir bastante información."
  },
  AvgCommunicate_70490_Content_3 = {
    Text = "¡Tan poderoso, Profesor Muñeca!"
  },
  AvgCommunicate_70490_Content_4 = {
    Text = "Solo es que no fue lo suficientemente cauteloso."
  },
  AvgCommunicate_70490_Content_5 = {
    Text = "Un autodenominado genio cuya arrogancia lo hará bajar la guardia."
  },
  AvgCommunicate_70490_Content_6 = {
    Text = "¿Planeaste este movimiento desde hace mucho?!"
  },
  AvgCommunicate_70490_Content_7 = {
    Text = "Incluso manipulando cuerpos artificiales, salir es bastante problemático."
  },
  AvgCommunicate_70490_Content_8 = {
    Text = "Si no puedo obtener nada, más vale que disfrute del té de la tarde en el salón."
  },
  AvgCommunicate_70490_Content_9 = {
    Text = "En resumen, la información más crucial en la inteligencia reunida es un símbolo."
  },
  AvgCommunicate_70490_Option_11 = {
    Text = "¿Qué es exactamente ese símbolo?"
  },
  AvgCommunicate_70490_Option_3 = {
    Text = "¡Tan poderoso, Profesor Muñeca!"
  },
  AvgCommunicate_70490_Option_6 = {
    Text = "¿Planeaste este movimiento desde hace mucho?!"
  },
  AvgCommunicate_70491_Content_1 = {
    Text = "La primera tarea de campo después de asumir el papel de Guardián ha terminado."
  },
  AvgCommunicate_70491_Content_10 = {
    Text = "Nunca esperé que mi primera misión oficial en el campo involucrara esto."
  },
  AvgCommunicate_70491_Content_11 = {
    Text = "Porque tú eres el Guardián."
  },
  AvgCommunicate_70491_Content_12 = {
    Text = "Muchos se han ido, pero más han sido salvados gracias a ti."
  },
  AvgCommunicate_70491_Content_13 = {
    Text = "Estamos en el camino correcto."
  },
  AvgCommunicate_70491_Content_14 = {
    Text = "Tienes razón, Ramona."
  },
  AvgCommunicate_70491_Content_15 = {
    Text = "Más personas son salvadas gracias a nosotros."
  },
  AvgCommunicate_70491_Content_16 = {
    Text = "Caminaremos por este camino todo el camino."
  },
  AvgCommunicate_70491_Content_17 = {
    Text = "¡Ciertamente!"
  },
  AvgCommunicate_70491_Content_2 = {
    Text = "Felicidades."
  },
  AvgCommunicate_70491_Content_3 = {
    Text = "Nunca esperé que mi primera misión oficial en el campo involucrara esto."
  },
  AvgCommunicate_70491_Content_4 = {
    Text = "Pero independientemente, tuvimos éxito."
  },
  AvgCommunicate_70491_Content_5 = {
    Text = "Estamos en el camino correcto."
  },
  AvgCommunicate_70491_Content_6 = {
    Text = "Eso es correcto, Guardián."
  },
  AvgCommunicate_70491_Content_7 = {
    Text = "Caminaremos por este camino todo el camino."
  },
  AvgCommunicate_70491_Content_8 = {
    Text = "No siento que haya completado nada con éxito, Ramona."
  },
  AvgCommunicate_70491_Content_9 = {
    Text = "Senior Anderson, Sarah, Aigis..."
  },
  AvgCommunicate_70491_Option_14 = {
    Text = "Tienes toda la razón..."
  },
  AvgCommunicate_70491_Option_3 = {
    Text = "Hay muchos remordimientos, pero estamos en el camino correcto."
  },
  AvgCommunicate_70491_Option_8 = {
    Text = "El problema está temporalmente resuelto, pero algunos arrepentimientos nunca pueden ser remediados."
  },
  AvgCommunicate_70492_Content_1 = {
    Text = "Recientemente quiero celebrar un evento conmemorativo, pero me faltan peces vivos y barcos."
  },
  AvgCommunicate_70492_Content_10 = {
    Text = "Dado que estás al tanto de mi pasado, también deberías conocer mi respuesta."
  },
  AvgCommunicate_70492_Content_11 = {
    Text = "Si tuviera otra oportunidad, todavía haría lo que solía hacer."
  },
  AvgCommunicate_70492_Content_12 = {
    Text = "El pasado, el presente y el futuro. El Sumo Sacerdote de Lemuria nunca se arrepiente."
  },
  AvgCommunicate_70492_Content_13 = {
    Text = "I... nunca tuve otra opción, Guardián."
  },
  AvgCommunicate_70492_Content_2 = {
    Text = "¿Puede Mythag pedir prestado algo por un tiempo? Garantizo, como el Alto Sacerdote de Lemuria, que será devuelto a tiempo."
  },
  AvgCommunicate_70492_Content_3 = {
    Text = "No hay problema. Te ayudaré a comunicarte con la escuela, y el comité escolar debería aprobarlo."
  },
  AvgCommunicate_70492_Content_4 = {
    Text = "¿Son estos artículos para tu familia o para Deborah?"
  },
  AvgCommunicate_70492_Content_5 = {
    Text = "...¿Lo sabes todo?"
  },
  AvgCommunicate_70492_Content_6 = {
    Text = "Según las costumbres de Lemuria, debes enviar saludos a tus seres queridos fallecidos usando peces vivos y barcos."
  },
  AvgCommunicate_70492_Content_7 = {
    Text = "Todavía no puedes olvidarlos. Aún los amas profundamente."
  },
  AvgCommunicate_70492_Content_8 = {
    Text = "Así que... ¿te arrepientes, Miria?"
  },
  AvgCommunicate_70492_Content_9 = {Text = "..."},
  AvgCommunicate_70492_Option_3 = {
    Text = "No hay problema."
  },
  AvgCommunicate_70492_Option_4 = {
    Text = "¿Es para tu familia, o está preparado para Deborah?"
  },
  AvgCommunicate_70492_Option_8 = {
    Text = "¿Te arrepientes?"
  },
  AvgCommunicate_70493_Content_1 = {
    Text = "He terminado de leer tu testamento."
  },
  AvgCommunicate_70493_Content_10 = {
    Text = "También narraré con orgullo tus hazañas a otros hasta... el día en que mi Memoria sufra Disolución."
  },
  AvgCommunicate_70493_Content_11 = {
    Text = "Pero mientras recito mi testamento, en este momento, el arrepentimiento consume todos mis pensamientos."
  },
  AvgCommunicate_70493_Content_12 = {
    Text = "Dijiste que eras un cobarde. Dijiste que nunca querrías abandonarnos."
  },
  AvgCommunicate_70493_Content_13 = {
    Text = "Pero al final, aún caminaste por este camino."
  },
  AvgCommunicate_70493_Content_14 = {
    Text = "Madre se ha ido. Tú también te has ido."
  },
  AvgCommunicate_70493_Content_15 = {
    Text = "No me importan las mentiras que dices. Ojalá pudieras seguir engañándome un poco más. Un año, un mes..."
  },
  AvgCommunicate_70493_Content_16 = {
    Text = "Incluso si es solo por un día, las palabras que quedan sin decir al menos tienen la oportunidad de ser expresadas..."
  },
  AvgCommunicate_70493_Content_17 = {
    Text = "Estoy realmente asustado, %player%."
  },
  AvgCommunicate_70493_Content_18 = {
    Text = "Tengo miedo de que un día olvidaré tu rostro y tu nombre."
  },
  AvgCommunicate_70493_Content_19 = {
    Text = "Tengo miedo de que un día, desaparecerás completamente de mi memoria..."
  },
  AvgCommunicate_70493_Content_2 = {
    Text = "Intenté recitar esas palabras en un tono reconfortante, como deseabas."
  },
  AvgCommunicate_70493_Content_20 = {
    Text = "Pero, sabes, no soy el tipo de persona que se rinde fácilmente."
  },
  AvgCommunicate_70493_Content_21 = {
    Text = "No puedo creer que simplemente podrías desvanecerte así."
  },
  AvgCommunicate_70493_Content_22 = {
    Text = "No importa cuánto espere, estaré aquí, recordando. Hasta el día en que despiertes del Pozo Negro, abras esa puerta y regreses a este campus."
  },
  AvgCommunicate_70493_Content_23 = {
    Text = "Cuando llegue ese momento, te contaré todo lo que sucedió mientras estabas ausente, así como esas palabras no pronunciadas, una por una..."
  },
  AvgCommunicate_70493_Content_24 = {
    Text = "Sé que ahora debes estar muy cansado, demasiado cansado para responder... Está bien, descansa bien."
  },
  AvgCommunicate_70493_Content_25 = {
    Text = "Te estoy esperando... %player%."
  },
  AvgCommunicate_70493_Content_3 = {
    Text = "Hice mi mejor esfuerzo. Pero no puedo hacerlo, %player%..."
  },
  AvgCommunicate_70493_Content_4 = {
    Text = "La tumba clave está llena de gente; no puedo ver a nadie."
  },
  AvgCommunicate_70493_Content_5 = {
    Text = "El mundo entero ha caído en silencio. Solo queda el sonido de la lluvia, solo tú y yo."
  },
  AvgCommunicate_70493_Content_6 = {
    Text = "Cuando esa puerta se cerró frente a mí y esas palabras se desplazaron línea por línea ante mis ojos, lo único que sentí fue arrepentimiento."
  },
  AvgCommunicate_70493_Content_7 = {
    Text = "Lamento haber inculcado esos ideales de Investigador en ti, lamento haberte enseñado ese Conocimiento de Investigación, lamento haberte alejado de Akut..."
  },
  AvgCommunicate_70493_Content_8 = {
    Text = "Sé que no debería pensar de esta manera."
  },
  AvgCommunicate_70493_Content_9 = {
    Text = "Soy un Investigador. Tú salvaste nuestro mundo de la Disolución. Debería sentirme aliviado por ti."
  },
  AvgCommunicate_70494_Content_1 = {
    Text = "Buen día, Guardián de Mitag."
  },
  AvgCommunicate_70494_Content_10 = {
    Text = "Escuché que Mitag ha producido un Guardián excepcional."
  },
  AvgCommunicate_70494_Content_11 = {
    Text = "No debería entrometerme, pero simplemente no puedo contener mi curiosidad y deseo de verte en persona."
  },
  AvgCommunicate_70494_Content_12 = {
    Text = "No me decepcionaste, %player%."
  },
  AvgCommunicate_70494_Content_13 = {
    Text = "¿Qué exactamente piensas hacer?"
  },
  AvgCommunicate_70494_Content_14 = {
    Text = "Si tengo la oportunidad, me gustaría invitarlo a mi laboratorio como invitado."
  },
  AvgCommunicate_70494_Content_15 = {
    Text = "Un Guardián que puede enlazar a innumerables Despertadores... Los secretos sobre ti me intrigan enormemente."
  },
  AvgCommunicate_70494_Content_16 = {
    Text = "Si traes a los miembros de la Asociación de Escultores para confesar a Mitag, la cooperación podría ser digna de considerar."
  },
  AvgCommunicate_70494_Content_17 = {
    Text = "Heh... Pensé que me regañarías."
  },
  AvgCommunicate_70494_Content_18 = {
    Text = "Eres más interesante de lo que imaginaba."
  },
  AvgCommunicate_70494_Content_19 = {
    Text = "Los días venideros son largos, y en el futuro, tendremos muchas oportunidades para comunicarnos."
  },
  AvgCommunicate_70494_Content_2 = {
    Text = "Eres tú... Herbert Rosenthal..."
  },
  AvgCommunicate_70494_Content_20 = {
    Text = "Espero con ansias, %player%."
  },
  AvgCommunicate_70494_Content_3 = {
    Text = "Oh, parece que alguien ya me ha presentado a ti."
  },
  AvgCommunicate_70494_Content_4 = {
    Text = "En realidad, me ahorró muchos problemas."
  },
  AvgCommunicate_70494_Content_5 = {
    Text = "Las Comunicaciones de Plata requieren un enlace bidireccional. ¿Cómo te pusiste en contacto conmigo?"
  },
  AvgCommunicate_70494_Content_6 = {Text = "Hmm..."},
  AvgCommunicate_70494_Content_7 = {
    Text = "Para aquellos afortunados que participan en el desarrollo, la tecnología de comunicación de Plata no tiene secretos."
  },
  AvgCommunicate_70494_Content_8 = {
    Text = "¿Eres el desarrollador de Comunicación de Plata?"
  },
  AvgCommunicate_70494_Content_9 = {
    Text = "Las viejas historias se pueden discutir con calma cuando tengamos tiempo."
  },
  AvgCommunicate_70494_Option_13 = {
    Text = "¿Qué exactamente piensas hacer?"
  },
  AvgCommunicate_70494_Option_16 = {
    Text = "A menos que confieses a Mythag"
  },
  AvgCommunicate_70494_Option_2 = {
    Text = "Herbert Rosenthal..."
  },
  AvgCommunicate_70494_Option_5 = {
    Text = "¿Cómo te pusiste en contacto conmigo?"
  },
  AvgCommunicate_70495_Content_1 = {
    Text = "Los restos de Anderson han sido destruidos por la asociación de escultores y no pueden ser reconstruidos en una figura humana completa."
  },
  AvgCommunicate_70495_Content_10 = {
    Text = "Quizás, algún día lo haremos..."
  },
  AvgCommunicate_70495_Content_11 = {
    Text = "¿Sentirás miedo, Sr. William?"
  },
  AvgCommunicate_70495_Content_12 = {Text = "..."},
  AvgCommunicate_70495_Content_13 = {
    Text = "Quizás alguien puede trascender la vida y la muerte, pero no yo."
  },
  AvgCommunicate_70495_Content_14 = {
    Text = "Tengo miedo todo el tiempo, %player%."
  },
  AvgCommunicate_70495_Content_15 = {
    Text = "Pero nunca he visto ningún rastro de miedo en ti."
  },
  AvgCommunicate_70495_Content_16 = {
    Text = "Porque no tengo tiempo. Porque la Disolución está justo frente a mí."
  },
  AvgCommunicate_70495_Content_17 = {
    Text = "Muchos han perecido, pero yo todavía vivo."
  },
  AvgCommunicate_70495_Content_18 = {
    Text = "Si es miedo o recuerdo, el Investigador de Mythag no tiene derecho a detenerse por esto."
  },
  AvgCommunicate_70495_Content_19 = {Text = "..."},
  AvgCommunicate_70495_Content_2 = {
    Text = "Esos Silvers extraídos por la fuerza también han sido casi completamente destruidos."
  },
  AvgCommunicate_70495_Content_20 = {
    Text = "Ha llegado una nueva tarea."
  },
  AvgCommunicate_70495_Content_21 = {
    Text = "Sobreviviremos, %player%. Hasta el día en que se resuelva la Disolución."
  },
  AvgCommunicate_70495_Content_3 = {
    Text = "Buscamos en el laboratorio del asilo y solo lo encontramos."
  },
  AvgCommunicate_70495_Content_4 = {
    Text = "Llave de plata, ID L-1463, pertenece al Investigador Anderson—una vez le perteneció."
  },
  AvgCommunicate_70495_Content_5 = {
    Text = "¿Qué hará la escuela con esta llave de plata...?"
  },
  AvgCommunicate_70495_Content_6 = {
    Text = "Reciclar, colocar en la <Charca negra> para rehacer, y luego distribuir a los nuevos <Investigators> en la <ceremonia de la tumba clave> del próximo año."
  },
  AvgCommunicate_70495_Content_7 = {
    Text = "Acompañará al nuevo Investigador, dirigiéndose constantemente a los lugares más peligrosos."
  },
  AvgCommunicate_70495_Content_8 = {
    Text = "Hasta que ese investigador dimita o muera."
  },
  AvgCommunicate_70495_Content_9 = {
    Text = "Quizás, algún día lo haremos..."
  },
  AvgCommunicate_70495_Option_10 = {
    Text = "¿Sentirás miedo?"
  },
  AvgCommunicate_70495_Option_15 = {
    Text = "Nunca he sentido tu miedo."
  },
  AvgCommunicate_70495_Option_5 = {
    Text = "¿Qué hará la escuela con esta llave de plata...?"
  },
  AvgCommunicate_70495_Option_9 = {
    Text = "¿Terminaremos como Anderson?"
  },
  AvgCommunicate_70496_Content_1 = {
    Text = "El ritual de estas personas Aram... es realmente impactante."
  },
  AvgCommunicate_70496_Content_10 = {
    Text = "¿Soy ese tipo de persona?"
  },
  AvgCommunicate_70496_Content_11 = {
    Text = "Solo estaba preguntando casualmente, ¿por qué tan tenso?"
  },
  AvgCommunicate_70496_Content_12 = {
    Text = "Hacer esto te convertirá en un libro abierto en la mesa de cartas. Tu fortaleza mental necesita mejorar, Guardián."
  },
  AvgCommunicate_70496_Content_13 = {
    Text = "En resumen, los secretos de este desierto son probablemente mucho más complejos de lo que anticipamos."
  },
  AvgCommunicate_70496_Content_14 = {
    Text = "La investigación posterior requiere una precaución extra."
  },
  AvgCommunicate_70496_Content_2 = {
    Text = "Pensaba que aceptarías la invitación de esa mujer de Aram."
  },
  AvgCommunicate_70496_Content_3 = {Text = "..."},
  AvgCommunicate_70496_Content_4 = {
    Text = "¿Qué tipo de imagen tengo verdaderamente en tu corazón..."
  },
  AvgCommunicate_70496_Content_5 = {
    Text = "Nunca esperé que Ryker, quien suele ser tan encantador, también tuviera cosas que no podía aceptar."
  },
  AvgCommunicate_70496_Content_6 = {
    Text = "No hay historias con flores y vino, solo los deseos más primitivos y salvajes."
  },
  AvgCommunicate_70496_Content_7 = {
    Text = "Este tipo de ritual, de hecho, no es de mi agrado."
  },
  AvgCommunicate_70496_Content_8 = {
    Text = "Hablando de eso, no aceptaste ninguna invitación extraña, ¿verdad?"
  },
  AvgCommunicate_70496_Content_9 = {
    Text = "Cuando... por supuesto que no... ¡cómo podría ser!"
  },
  AvgCommunicate_70496_Option_2 = {
    Text = "Pensaba que aceptarías la invitación de esa mujer aram"
  },
  AvgCommunicate_70496_Option_5 = {
    Text = "No esperaba que hubiera cosas que tú tampoco pudieras aceptar."
  },
  AvgCommunicate_70496_Option_9 = {
    Text = "Cuando... por supuesto que no... ¡cómo podría ser!"
  },
  AvgCommunicate_70497_Content_1 = {
    Text = "¡Hola, Guardián del Secreto {Male=señor,Female=señorita}!"
  },
  AvgCommunicate_70497_Content_2 = {
    Text = "¿Te divertiste jugando con los juguetes de Juliette?"
  },
  AvgCommunicate_70497_Content_3 = {
    Text = "¿Eres... ¡el topo?!"
  },
  AvgCommunicate_70497_Content_4 = {
    Text = "Pensé que habrías averiguado quién soy antes. Qué pena."
  },
  AvgCommunicate_70497_Content_5 = {
    Text = "Pero está bien; después de todo, es solo el juego final."
  },
  AvgCommunicate_70497_Content_6 = {
    Text = "Ahora, el juego está a punto de terminar."
  },
  AvgCommunicate_70497_Content_7 = {
    Text = "Antes de que llegue la destrucción destinada, solo tengo curiosidad por una cosa."
  },
  AvgCommunicate_70497_Content_8 = {
    Text = "¿Puede la eterna verdad del Caos, el audaz Guardián de quien hablamos sin vergüenza, Mitag, el valiente Salvador, realmente enfrentarlo con coraje?"
  },
  AvgCommunicate_70497_Option_3 = {
    Text = "¿Eres... ¡el topo?!"
  },
  AvgCommunicate_70498_Content_1 = {
    Text = "No soy un comerciante tonto, pero tras una cuidadosa consideración, parece que he hecho un trato perdedor..."
  },
  AvgCommunicate_70498_Content_10 = {
    Text = "Siempre estar alerta ante las mentiras es una cualidad básica de un empresario calificado."
  },
  AvgCommunicate_70498_Content_11 = {
    Text = "¿Así que esa era en verdad la verdadera cara de la señora Davendale?"
  },
  AvgCommunicate_70498_Content_12 = {
    Text = "No hay costo más caro que la realidad, pequeño Guardián."
  },
  AvgCommunicate_70498_Content_13 = {
    Text = "Gracias, Lady Narciso."
  },
  AvgCommunicate_70498_Content_14 = {
    Text = "Lo que acabo de decir fue una broma. Sé lo que significa para alguien como tú revelar su verdadero yo."
  },
  AvgCommunicate_70498_Content_15 = {
    Text = "Este es un regalo precioso, y lo atesoraré bien."
  },
  AvgCommunicate_70498_Content_16 = {
    Text = "No pienses que puedes despreciarme con solo unas pocas palabras, pequeña."
  },
  AvgCommunicate_70498_Content_17 = {
    Text = "A cambio, ¿no deberías darme también un regalo?"
  },
  AvgCommunicate_70498_Content_18 = {
    Text = "¿Me han descubierto...?"
  },
  AvgCommunicate_70498_Content_19 = {
    Text = "Señora Davendale, ¿qué desea?"
  },
  AvgCommunicate_70498_Content_2 = {Text = "¿Qué?"},
  AvgCommunicate_70498_Content_20 = {
    Text = "Desde que ya has visto mi verdadera forma, ¿cuándo estarás listo para mostrarme tu verdadero yo?"
  },
  AvgCommunicate_70498_Content_21 = {
    Text = "¿Mi verdadero yo? ¿Qué significa eso...? No lo entiendo del todo, Lady Narciso."
  },
  AvgCommunicate_70498_Content_22 = {
    Text = "Parece que Mythag no te ha dicho nada todavía..."
  },
  AvgCommunicate_70498_Content_23 = {
    Text = "El momento aún no ha llegado. No te preocupes."
  },
  AvgCommunicate_70498_Content_24 = {
    Text = "Recuerda nuestro trato de hoy, pequeño."
  },
  AvgCommunicate_70498_Content_25 = {
    Text = "Espero con ansias el día en que reveles tu verdadero rostro."
  },
  AvgCommunicate_70498_Content_3 = {
    Text = "¿No has ya obtenido la cabeza que deseabas?"
  },
  AvgCommunicate_70498_Content_4 = {
    Text = "Ese vibrante mar de materia gris se ha convertido en otra pieza apreciada en tu colección."
  },
  AvgCommunicate_70498_Content_5 = {
    Text = "De verdad, era una hermosa cabeza; este intercambio no puede considerarse una pérdida."
  },
  AvgCommunicate_70498_Content_6 = {
    Text = "Sin embargo, el costo que he pagado todavía es un poco demasiado alto."
  },
  AvgCommunicate_70498_Content_7 = {
    Text = "Solo me diste un vistazo de tu verdadera forma..."
  },
  AvgCommunicate_70498_Content_8 = {
    Text = "Y si realmente así es como te ves, es difícil de decir."
  },
  AvgCommunicate_70498_Content_9 = {
    Text = "Hehe... No está mal, pequeño."
  },
  AvgCommunicate_70498_Option_11 = {
    Text = "¿Entonces... esa sí era la verdadera cara de la señora Davendale?"
  },
  AvgCommunicate_70498_Option_13 = {
    Text = "Gracias, Lady Narciso."
  },
  AvgCommunicate_70498_Option_18 = {
    Text = "¿Me han descubierto...?"
  },
  AvgCommunicate_70498_Option_2 = {
    Text = "¿No hemos ya obtenido la cabeza?"
  },
  AvgCommunicate_70498_Option_21 = {
    Text = "¿Mi verdadero yo? ¿Qué significa eso...?"
  },
  AvgCommunicate_70498_Option_7 = {
    Text = "Acabo de vislumbrar tu verdadera forma..."
  },
  AvgCommunicate_70499_Content_1 = {
    Text = "Eliminando a los disidentes, se ha liberado de las restricciones de Longbel y del Contrato. Sin estos obstáculos, en solo unas pocas semanas, se ha convertido en la cazadora más feroz en el mundo empresarial de Londinium."
  },
  AvgCommunicate_70499_Content_10 = {
    Text = "No te preocupes, profesor Dexter. No te dejaremos hacer cosas tan peligrosas la próxima vez... Quiero decir, intentaremos no hacerlo."
  },
  AvgCommunicate_70499_Content_11 = {
    Text = "La existencia escondida dentro de la conciencia de Sorel parece llamarse \"N\". ¿Sabes algo sobre él?"
  },
  AvgCommunicate_70499_Content_12 = {
    Text = "No muy claro. Suena como un estafador o un loco, probablemente ambos."
  },
  AvgCommunicate_70499_Content_13 = {
    Text = "Pero no importa cuán atroz, al menos este tipo tiene gusto. Se puede notar por su canto."
  },
  AvgCommunicate_70499_Content_14 = {
    Text = "La próxima vez que haya una oportunidad, debemos conocernos mejor. Quizás incluso podamos compartir una bebida o dos."
  },
  AvgCommunicate_70499_Content_15 = {
    Text = "...Por supuesto, en un entorno seguro. El caballero anciano ya no puede soportar ningún susto."
  },
  AvgCommunicate_70499_Content_2 = {
    Text = "Creo que no pasará mucho tiempo antes de que toda la tierra de Londinium lleve su apellido."
  },
  AvgCommunicate_70499_Content_3 = {
    Text = "La Dama Sorel, qué persona tan fascinante. Afortunadamente, Mitag está de su lado."
  },
  AvgCommunicate_70499_Content_4 = {
    Text = "Le debo este asunto a su ayuda, Profesor Dexter."
  },
  AvgCommunicate_70499_Content_5 = {
    Text = "Gracias por ayudar a sacar al sospechoso; de lo contrario, habría tomado mucho más tiempo resolver este asunto."
  },
  AvgCommunicate_70499_Content_6 = {
    Text = "Cumpliendo simplemente con los deberes de un caballero."
  },
  AvgCommunicate_70499_Content_7 = {
    Text = "La propuesta hecha por Ramona, este anciano padre mío no tiene derecho a rechazarla."
  },
  AvgCommunicate_70499_Content_8 = {
    Text = "Sin embargo, si algo como esto vuelve a suceder la próxima vez, espero que puedas actuar un poco más rápido."
  },
  AvgCommunicate_70499_Content_9 = {
    Text = "¡No esperes hasta que el cuchillo de ese tipo esté a solo cinco centímetros de mi cuello para aparecer; es realmente aterrador!"
  },
  AvgCommunicate_70499_Option_10 = {
    Text = "No habrá una próxima vez... Haré todo lo posible."
  },
  AvgCommunicate_70499_Option_11 = {
    Text = "¿Sabes sobre \"N\"?"
  },
  AvgCommunicate_70499_Option_4 = {
    Text = "Gracias por ayudar a atraer al sospechoso"
  },
  AvgCommunicate_70500_Content_1 = {
    Text = "La conversación en el café fue bastante agradable, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgCommunicate_70500_Content_10 = {
    Text = "Luego, si esta situación ocurre de nuevo, ¿aún dispararías al verdadero yo para salvar a otros? ¿Lo harías?"
  },
  AvgCommunicate_70500_Content_11 = {
    Text = "Hmm... por supuesto."
  },
  AvgCommunicate_70500_Content_12 = {
    Text = "Quédate tranquilo/a, {Male=Mr.,Female=Miss} Guardián. La fortuna seguirá sonriéndome."
  },
  AvgCommunicate_70500_Content_13 = {
    Text = "En ese momento, mi arma definitivamente no tenía balas."
  },
  AvgCommunicate_70500_Content_14 = {Text = "70% no."},
  AvgCommunicate_70500_Content_2 = {
    Text = "Es un honor ser testigo del pasado de un jugador."
  },
  AvgCommunicate_70500_Content_3 = {
    Text = "Mi parte favorita es cuando el jugador arriesga todo y les roban su Alma."
  },
  AvgCommunicate_70500_Content_4 = {
    Text = "¡Ja... hay victorias y derrotas, así es la vida."
  },
  AvgCommunicate_70500_Content_5 = {
    Text = "Mira, ¿no hemos obtenido una ventaja esta vez?"
  },
  AvgCommunicate_70500_Content_6 = {
    Text = "¿Así que el tiro que me diste también fue una jugada?"
  },
  AvgCommunicate_70500_Content_7 = {
    Text = "¿Cómo puede ser eso? Estoy un 70% seguro de mi juicio."
  },
  AvgCommunicate_70500_Content_8 = {
    Text = "¿Qué pasa con el 30% restante?"
  },
  AvgCommunicate_70500_Content_9 = {
    Text = "No hay un 30% restante. 70% es igual a 100%."
  },
  AvgCommunicate_70500_Option_2 = {
    Text = "Es un honor ser testigo del pasado de un jugador."
  },
  AvgCommunicate_70500_Option_6 = {
    Text = "¿Así que el disparo que me hicieron también fue una apuesta?"
  },
  AvgCommunicate_70500_Option_8 = {
    Text = "¿Qué pasa con el 30% restante?"
  },
  AvgCommunicate_70501_Content_1 = {
    Text = "¿Te parece bonito?"
  },
  AvgCommunicate_70501_Content_10 = {
    Text = "Pero... la historia que cuenta ese conjunto de esculturas es demasiado cruel."
  },
  AvgCommunicate_70501_Content_11 = {
    Text = "Lo has entendido, Guardián..."
  },
  AvgCommunicate_70501_Content_12 = {
    Text = "Toda la creación es cruel."
  },
  AvgCommunicate_70501_Content_14 = {
    Text = "Si fuera yo, creo que encontraría el proceso de esa creación increíblemente arduo..."
  },
  AvgCommunicate_70501_Content_15 = {
    Text = "Pero tú eres diferente, Sanga. Entiendo tu elección."
  },
  AvgCommunicate_70501_Content_16 = {
    Text = "Una obra como \"La Dama Coral Caída\" es el significado que persigues."
  },
  AvgCommunicate_70501_Content_17 = {
    Text = "Lo espero con ansias—ver esa \"crueldad\" florecer una vez más en las líneas que tallas."
  },
  AvgCommunicate_70501_Content_18 = {Text = "..."},
  AvgCommunicate_70501_Content_19 = {
    Text = "Pensé que serías como esos ignorantes y me sugerirías que mi arte fuera más \"normal\"."
  },
  AvgCommunicate_70501_Content_2 = {
    Text = "¿Qué... tu cara?"
  },
  AvgCommunicate_70501_Content_20 = {
    Text = "Estas palabras significan mucho para mí... Gracias, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgCommunicate_70501_Content_21 = {
    Text = "Como recompensa, déjame contarte un pequeño secreto: cuando entraste en Soñar, yo estaba justo a tu lado."
  },
  AvgCommunicate_70501_Content_22 = {
    Text = "Todas esas expresiones desprevenidas tuyas—tallé cada una de ellas. Fieles · a · la · realidad."
  },
  AvgCommunicate_70501_Content_23 = {
    Text = "Cuando tengas tiempo, ven a visitar mi pequeño salón de exposiciones~"
  },
  AvgCommunicate_70501_Content_24 = {
    Text = "¡Sanga! Te daré cincuenta Colmillos de Leo, así que por favor deshazte de esas Esculturas..."
  },
  AvgCommunicate_70501_Content_25 = {
    Text = "Lo que llamaste arte vívido pero \"cruel\". ¿No es así, Guardián?"
  },
  AvgCommunicate_70501_Content_3 = {
    Text = "La escultura que viste en el Sueño, por supuesto."
  },
  AvgCommunicate_70501_Content_4 = {
    Text = "Las líneas de la carne son naturalmente armoniosas, pero carecen de la belleza eterna de la quietud, y les falta tema y visión creativa... difícilmente comparables a las obras escultóricas."
  },
  AvgCommunicate_70501_Content_5 = {
    Text = "Muy pocas personas han visto esa serie de esculturas ahora. Me gustaría conocer tu valoración..."
  },
  AvgCommunicate_70501_Content_6 = {
    Text = "¿Qué... tus esculturas?"
  },
  AvgCommunicate_70501_Content_7 = {
    Text = "Por supuesto. Muy pocas personas han visto esa serie de esculturas ahora. Me gustaría conocer tu valoración..."
  },
  AvgCommunicate_70501_Content_8 = {
    Text = "Esa es la serie de esculturas más hermosa que he visto en mi vida."
  },
  AvgCommunicate_70501_Content_9 = {
    Text = "Aunque las líneas están inmóviles, capturan un dinamismo y una vitalidad que ni siquiera los seres vivos poseen."
  },
  AvgCommunicate_70501_Option_14 = {
    Text = "Entiendo tu elecció"
  },
  AvgCommunicate_70501_Option_2 = {Text = "¿Tu cara?"},
  AvgCommunicate_70501_Option_24 = {Text = "¡No!!!"},
  AvgCommunicate_70501_Option_6 = {
    Text = "¿Tus esculturas?"
  },
  AvgCommunicate_70501_Option_8 = {
    Text = "Hermosas... y crueles."
  },
  AvgCommunicate_70502_Content_1 = {
    Text = "Aburrido. Aburrido, aburrido, aburrido..."
  },
  AvgCommunicate_70502_Content_10 = {
    Text = "Londinium no permite la esclavitud, este lugar es bárbaro."
  },
  AvgCommunicate_70502_Content_11 = {
    Text = "No tengo más remedio que escucharte y mangonearlos Dentro del laberinto."
  },
  AvgCommunicate_70502_Content_12 = {
    Text = "¡La forma en que lucharon en la arena era exactamente como lo que había visto antes!"
  },
  AvgCommunicate_70502_Content_13 = {
    Text = "Así que el Laberinto se usa para este propósito..."
  },
  AvgCommunicate_70502_Content_14 = {
    Text = "Así es, ¡así es! ¡Qué fascinante!"
  },
  AvgCommunicate_70502_Content_15 = {
    Text = "Vamos, ¡vayamos a echar un vistazo! ¡Este es el más alto honor!"
  },
  AvgCommunicate_70502_Content_16 = {
    Text = "No es imposible; aprender más sobre historia no es algo malo..."
  },
  AvgCommunicate_70502_Content_17 = {
    Text = "A Uvhash probablemente le gustará tu arena. ¿Por qué no invitarlo también?"
  },
  AvgCommunicate_70502_Content_18 = {
    Text = "¡¡¡No! ¡¡¡Mantén a ese demonio bien lejos!!!"
  },
  AvgCommunicate_70502_Content_2 = {
    Text = "¡Atrapada en este lugar dejado de la mano de Dios todos los días, estoy harta!"
  },
  AvgCommunicate_70502_Content_3 = {
    Text = "He reconstruido mi laberinto, ¡una arena completa construida según mis recuerdos!"
  },
  AvgCommunicate_70502_Content_4 = {
    Text = "¡Vamos a divertirnos juntos! ¡Ahora mismo!"
  },
  AvgCommunicate_70502_Content_5 = {
    Text = "¿Cuándo cambiarás ese tono que usas para ordenar a los esclavos...?"
  },
  AvgCommunicate_70502_Content_6 = {
    Text = "Hmph, ¿qué hay para cambiar en eso?"
  },
  AvgCommunicate_70502_Content_7 = {
    Text = "¡Ya he cedido diez mil veces! Ahora solo mando a esos esclavos en el Laberinto."
  },
  AvgCommunicate_70502_Content_8 = {
    Text = "¿No temes recordar esas cosas ahora?"
  },
  AvgCommunicate_70502_Content_9 = {
    Text = "De verdad. ¡¿Qué hay que temer?!"
  },
  AvgCommunicate_70502_Option_16 = {
    Text = "Entonces también llamaré a Uvhash."
  },
  AvgCommunicate_70502_Option_5 = {
    Text = "¿Cuándo cambiarás tu tono..."
  },
  AvgCommunicate_70502_Option_8 = {
    Text = "¿No temes recordar esas cosas ahora?"
  },
  AvgCommunicate_70503_Content_1 = {
    Text = "El incidente que ocurrió en la iglesia... Si no hubieras estado allí, más personas inocentes habrían sido dañadas..."
  },
  AvgCommunicate_70503_Content_10 = {
    Text = "Pero ahora, ella es la líder actual de la Iglesia de la Luz del Templo."
  },
  AvgCommunicate_70503_Content_11 = {
    Text = "¿Qué? ¿El líder de la iglesia de la luz del templo?! ¡¡¡?!!"
  },
  AvgCommunicate_70503_Content_12 = {
    Text = "En el ámbito religioso, la Iglesia de la Luz del Templo es el mayor enemigo de su iglesia... ¿Cómo es posible que su alumno...?"
  },
  AvgCommunicate_70503_Content_13 = {
    Text = "Una larga historia, Mensajero."
  },
  AvgCommunicate_70503_Content_14 = {
    Text = "Ella trabajó una vez conmigo por la causa del Dios Padre, dedicando todo lo que teníamos a los pueblos del Dios Padre."
  },
  AvgCommunicate_70503_Content_15 = {
    Text = "Pero, como puedes ver, no es tan fácil para los desobedientes apartarse del Dios Padre. Esas atrocidades y prejuicios no pueden ser disueltos solo con algunas Bendiciones."
  },
  AvgCommunicate_70503_Content_16 = {
    Text = "Debido a las tribulaciones que soporté, ella emprendió un camino del que sería difícil regresar."
  },
  AvgCommunicate_70503_Content_17 = {
    Text = "Así que así es..."
  },
  AvgCommunicate_70503_Content_18 = {
    Text = "Entiendo. Al igual que lo que sucedió antes en la iglesia, aquellos que no cambiaron por tus buenas acciones causaron su transformación..."
  },
  AvgCommunicate_70503_Content_19 = {
    Text = "El Padre Dios nos enseñó una vez que las cosas en este mundo no siempre son blanco y negro. Las buenas acciones a veces también pueden ser un error."
  },
  AvgCommunicate_70503_Content_2 = {
    Text = "En nombre de la Iglesia y de los inocentes sobrevivientes, expreso mi más sincero agradecimiento a ti, el Mensajero Pálido."
  },
  AvgCommunicate_70503_Content_20 = {
    Text = "He dedicado todo a las víctimas, pero olvidé que mi estudiante también es uno de ellos."
  },
  AvgCommunicate_70503_Content_21 = {
    Text = "La iglesia y mis creencias pueden haber salvado a muchas personas, pero no lograron salvarla."
  },
  AvgCommunicate_70503_Content_22 = {
    Text = "No soy un profesor calificado, Mensajero."
  },
  AvgCommunicate_70503_Content_23 = {
    Text = "Continuaré caminando por el camino del Padre Dios. Pero me pregunto si alguna vez tendré la oportunidad de compensar este arrepentimiento hacia esa estudiante..."
  },
  AvgCommunicate_70503_Content_3 = {
    Text = "De nada, obispo Salvador. Es parte de mi deber."
  },
  AvgCommunicate_70503_Content_4 = {
    Text = "Obispo, respecto a su pasado, hay una pregunta que me gustaría hacerle..."
  },
  AvgCommunicate_70503_Content_5 = {
    Text = "Habla sin reservas, Enviado."
  },
  AvgCommunicate_70503_Content_6 = {
    Text = "Mi pasado estará abierto a cada persona bajo la protección del Padre Dios."
  },
  AvgCommunicate_70503_Content_7 = {
    Text = "Cuando me conecté contigo, aparte de Sophia, vi a una mujer teniendo una conversación contigo."
  },
  AvgCommunicate_70503_Content_8 = {
    Text = "Ese recuerdo ocupa una gran parte de tu Espíritu... ¿Están todos muy familiarizados con él?"
  },
  AvgCommunicate_70503_Content_9 = {
    Text = "De hecho, muy familiar. Una vez, ella fue mi estudiante más destacada."
  },
  AvgCommunicate_70503_Option_11 = {
    Text = "¿El líder de la iglesia de la luz del templo?!"
  },
  AvgCommunicate_70503_Option_17 = {
    Text = "Así que así es..."
  },
  AvgCommunicate_70503_Option_3 = {
    Text = "Está todo lo que debería hacer."
  },
  AvgCommunicate_70503_Option_7 = {
    Text = "¿Quién es la última mujer que apareció en tu memoria?"
  },
  AvgCommunicate_70504_Content_1 = {
    Text = "¿Tuviste una agradable estancia anoche, querido huésped?"
  },
  AvgCommunicate_70504_Content_10 = {
    Text = "Ten la seguridad, he llegado a un acuerdo con cierto caballero y no llevaré a cabo acciones desmesuradas."
  },
  AvgCommunicate_70504_Content_11 = {
    Text = "La integridad es muy importante para un comerciante."
  },
  AvgCommunicate_70504_Content_12 = {
    Text = "Además, no tienes menos secretos que yo, ¿verdad?"
  },
  AvgCommunicate_70504_Content_13 = {
    Text = "¿Cuál es mi secreto? ¿A qué se refiere?"
  },
  AvgCommunicate_70504_Content_14 = {
    Text = "Ahora no es el momento. Pero ten la seguridad de que el comercio relacionado con el nuevo Secreto comenzará pronto."
  },
  AvgCommunicate_70504_Content_15 = {
    Text = "El viento y la nieve en el camino son más feroces de lo que imaginas."
  },
  AvgCommunicate_70504_Content_16 = {
    Text = "Mientras haya tiempo, disfruta del calor de la chimenea, pequeño."
  },
  AvgCommunicate_70504_Content_2 = {
    Text = "Un pequeño negocio tan acogedor es muy raro de encontrar en días con viento y nieve. Muchas gracias por tu amabilidad, señora Davendale."
  },
  AvgCommunicate_70504_Content_3 = {
    Text = "Pero parece que tu tienda oculta muchos secretos."
  },
  AvgCommunicate_70504_Content_4 = {
    Text = "Esos coleccionables probablemente no son tan simples como parecen."
  },
  AvgCommunicate_70504_Content_5 = {
    Text = "Observación muy aguda. Sin embargo, indagar en los secretos de los demás no es un comportamiento caballeroso"
  },
  AvgCommunicate_70504_Content_6 = {
    Text = "Lo siento, señora Narciso."
  },
  AvgCommunicate_70504_Content_7 = {
    Text = "Vinimos a este lugar desconocido para una Investigación, y primero necesitamos asegurar nuestra seguridad."
  },
  AvgCommunicate_70504_Content_8 = {
    Text = "Espero que puedas entender."
  },
  AvgCommunicate_70504_Content_9 = {
    Text = "Por supuesto. Si uno pudiera dormirse imprudentemente en la casa de un extraño, entonces la educación de Mythag para los Guardianes es evidentemente insuficiente."
  },
  AvgCommunicate_70504_Option_13 = {
    Text = "¿Mi secreto?"
  },
  AvgCommunicate_70504_Option_2 = {
    Text = "Parece que hay muchos secretos aquí."
  },
  AvgCommunicate_70504_Option_6 = {
    Text = "Lo siento, pero necesito asegurar la seguridad de la operación."
  },
  AvgCommunicate_70505_Content_1 = {
    Text = "Miriam, era la sumo sacerdote en la que más confiaba."
  },
  AvgCommunicate_70505_Content_10 = {
    Text = "Asumo la responsabilidad de los Marinero."
  },
  AvgCommunicate_70505_Content_11 = {
    Text = "Nadie podría haber previsto el desarrollo de la situación; esto no debería llamarse un crimen."
  },
  AvgCommunicate_70505_Content_12 = {
    Text = "Lo que hiciste fue la mejor elección en ese momento."
  },
  AvgCommunicate_70505_Content_13 = {
    Text = "No es tu culpa, Tulu."
  },
  AvgCommunicate_70505_Content_14 = {
    Text = "Quizás. Pero tú personalmente resolviste este asunto."
  },
  AvgCommunicate_70505_Content_15 = {
    Text = "Nadie podría haber previsto el giro de los acontecimientos."
  },
  AvgCommunicate_70505_Content_16 = {
    Text = "Incluso si hubo errores, los has corregido."
  },
  AvgCommunicate_70505_Content_17 = {
    Text = "Has cumplido tu deber como el Rey de Lemuria, Tulu."
  },
  AvgCommunicate_70505_Content_18 = {Text = "..."},
  AvgCommunicate_70505_Content_19 = {
    Text = "Palabras de consuelo algo torpes, pero las acepto."
  },
  AvgCommunicate_70505_Content_2 = {
    Text = "Ella y yo una vez trajimos un breve período de prosperidad a Lemuria."
  },
  AvgCommunicate_70505_Content_20 = {
    Text = "Necesito descansar ahora."
  },
  AvgCommunicate_70505_Content_21 = {
    Text = "Cuando sea necesario, despertaré."
  },
  AvgCommunicate_70505_Content_22 = {
    Text = "Mi deber no radica solo en Lemuria, sino también en Mitag."
  },
  AvgCommunicate_70505_Content_3 = {
    Text = "Ella y los súbditos de Lemuria creen que yo restauraré la gloria del Reino de Dios en Limoria."
  },
  AvgCommunicate_70505_Content_4 = {
    Text = "Pero... eso es una mentira, ¿verdad?"
  },
  AvgCommunicate_70505_Content_5 = {
    Text = "En el sueño, recibí una revelación."
  },
  AvgCommunicate_70505_Content_6 = {
    Text = "El final de Lemuria es inevitable."
  },
  AvgCommunicate_70505_Content_7 = {
    Text = "Desde el principio hasta el final, Lemuria ha estado viviendo en mentiras."
  },
  AvgCommunicate_70505_Content_8 = {
    Text = "Uní Lemuria y Miryam con mentiras."
  },
  AvgCommunicate_70505_Content_9 = {
    Text = "Nunca imaginé que esta mentira llevaría a tales consecuencias muchos años después."
  },
  AvgCommunicate_70505_Option_11 = {
    Text = "Nadie podría haberlo previsto; esto no debería llamarse un pecado."
  },
  AvgCommunicate_70505_Option_14 = {
    Text = "El problema ha sido resuelto por tus propias manos."
  },
  AvgCommunicate_70505_Option_4 = {
    Text = "Pero... eso es una mentira, ¿verdad?"
  },
  AvgCommunicate_70506_Content_1 = {
    Text = "Tu cuerda no está bien atada."
  },
  AvgCommunicate_70506_Content_10 = {
    Text = "Además, matar es meramente un medio, no el objetivo."
  },
  AvgCommunicate_70506_Content_11 = {
    Text = "Deberías pensar más en tus propios asuntos."
  },
  AvgCommunicate_70506_Content_12 = {
    Text = "Lo que quiero hacer no es de tu incumbencia."
  },
  AvgCommunicate_70506_Content_13 = {
    Text = "Tienes un as bajo la manga."
  },
  AvgCommunicate_70506_Content_14 = {
    Text = "Ese enano... seguramente volverá loca a Miryam, jaja."
  },
  AvgCommunicate_70506_Content_15 = {
    Text = "Haz tu mejor esfuerzo, Guardián de Mythag."
  },
  AvgCommunicate_70506_Content_16 = {
    Text = "Tengo curiosidad por ver hasta dónde puedes llevar a mi respetado Sumo Sacerdote."
  },
  AvgCommunicate_70506_Content_2 = {
    Text = "Ten cuidado de no ser notado."
  },
  AvgCommunicate_70506_Content_3 = {
    Text = "Todavía eres útil para mí ahora; no quiero que mueras demasiado pronto."
  },
  AvgCommunicate_70506_Content_4 = {
    Text = "¿Quieres salvar a Murphy?"
  },
  AvgCommunicate_70506_Content_5 = {
    Text = "¿Parezco alguien con un corazón amable?"
  },
  AvgCommunicate_70506_Content_6 = {
    Text = "Deberías pensar más en tus propios asuntos."
  },
  AvgCommunicate_70506_Content_7 = {
    Text = "Lo que quiero hacer no es de tu incumbencia."
  },
  AvgCommunicate_70506_Content_8 = {
    Text = "¿Quieres matar a Miryam?"
  },
  AvgCommunicate_70506_Content_9 = {
    Text = "Esa loca no es tan fácil de matar."
  },
  AvgCommunicate_70506_Option_4 = {
    Text = "¿Quieres salvar a Murphy?"
  },
  AvgCommunicate_70506_Option_8 = {
    Text = "¿Quieres matar a Miryam?"
  },
  AvgCommunicate_70507_Content_1 = {
    Text = "I... me siento un poco cansada..."
  },
  AvgCommunicate_70507_Content_10 = {
    Text = "El dolor dentro de ti... también desaparecerá a partir de este momento."
  },
  AvgCommunicate_70507_Content_11 = {
    Text = "Tan amable, Mitag..."
  },
  AvgCommunicate_70507_Content_12 = {
    Text = "Hmm, no quiero pensar. No pensaré en nada más."
  },
  AvgCommunicate_70507_Content_13 = {
    Text = "He tomado una decisión, Guardián."
  },
  AvgCommunicate_70507_Content_14 = {
    Text = "¿Qué has deducido?"
  },
  AvgCommunicate_70507_Content_15 = {Text = "Nada..."},
  AvgCommunicate_70507_Content_16 = {
    Text = "El pequeño pastel de Mitag, me llevarás a probarlo, ¿verdad?"
  },
  AvgCommunicate_70507_Content_17 = {
    Text = "No te preocupes, Murphy. ¡Definitivamente te traeré de vuelta!"
  },
  AvgCommunicate_70507_Content_2 = {
    Text = "¿Murphy, la situación ha empeorado de nuevo?!"
  },
  AvgCommunicate_70507_Content_3 = {
    Text = "Estamos abordando el problema en la Sala de Poder y regresaremos en breve"
  },
  AvgCommunicate_70507_Content_4 = {
    Text = "Siento ganas de comer algunos pastelitos..."
  },
  AvgCommunicate_70507_Content_5 = {
    Text = "Una vez, alguien me hacía pasteles pequeños todos los días, pero después de embarcarme en el barco, no he tenido más."
  },
  AvgCommunicate_70507_Content_6 = {
    Text = "Miryam ha cambiado. Goliat ha cambiado. También esos Marinero han cambiado."
  },
  AvgCommunicate_70507_Content_7 = {
    Text = "Solo te he conocido recientemente, pero eres los únicos que me ayudarán y estarán a mi lado..."
  },
  AvgCommunicate_70507_Content_8 = {
    Text = "Deberías descansar y no pensar en estas cosas, Murphy."
  },
  AvgCommunicate_70507_Content_9 = {
    Text = "Cuando llegues a Mythag, lo que quieras comer estará disponible en abundancia."
  },
  AvgCommunicate_70507_Option_14 = {
    Text = "¿Lo has pensado bien?"
  },
  AvgCommunicate_70507_Option_17 = {
    Text = "¡Ciertamente!"
  },
  AvgCommunicate_70507_Option_2 = {Text = "¿Murphy?!"},
  AvgCommunicate_70507_Option_8 = {
    Text = "No pienses en estas cosas por ahora"
  },
  AvgCommunicate_70508_Content_1 = {
    Text = "Gracias por el asunto relacionado con el museo de cera."
  },
  AvgCommunicate_70508_Content_10 = {
    Text = "¡Felicidades, has resuelto completamente este asunto!"
  },
  AvgCommunicate_70508_Content_11 = {
    Text = "Cuando estabas en la escuela, tu capacidad general no era la ideal."
  },
  AvgCommunicate_70508_Content_12 = {
    Text = "Pero en estos dos Eventos, demostraste una Habilidad excepcionalmente excelente."
  },
  AvgCommunicate_70508_Content_13 = {
    Text = "Incluso sin un talento único en Poder espiritual, sigues siendo un Investigador excepcional."
  },
  AvgCommunicate_70508_Content_14 = {
    Text = "Es una bendición colaborar con un camarada así."
  },
  AvgCommunicate_70508_Content_15 = {
    Text = "Tú también, el Sénior William."
  },
  AvgCommunicate_70508_Content_16 = {
    Text = "¡Es un honor luchar a tu lado!"
  },
  AvgCommunicate_70508_Content_2 = {
    Text = "No es necesario decir eso, Señor William."
  },
  AvgCommunicate_70508_Content_3 = {
    Text = "Debería ser yo quien te agradezca..."
  },
  AvgCommunicate_70508_Content_4 = {
    Text = "Sin ti, probablemente no habríamos podido salir de ese museo de cera a salvo."
  },
  AvgCommunicate_70508_Content_5 = {
    Text = "¡Realmente un investigador legendario de Mythag!"
  },
  AvgCommunicate_70508_Content_6 = {Text = "..."},
  AvgCommunicate_70508_Content_7 = {
    Text = "Estas palabras, dirigidas a un investigador que casi falla, pueden interpretarse fácilmente como sarcasmo."
  },
  AvgCommunicate_70508_Content_8 = {
    Text = "Lo que dije es verdad!"
  },
  AvgCommunicate_70508_Content_9 = {
    Text = "En resumen."
  },
  AvgCommunicate_70508_Option_15 = {Text = "Igualmente"},
  AvgCommunicate_70508_Option_2 = {
    Text = "¡Realmente un investigador legendario!"
  },
  AvgCommunicate_70508_Option_3 = {
    Text = "Debería ser yo quien te agradezca."
  },
  AvgCommunicate_70508_Option_8 = {
    Text = "¡Soy sincero!"
  },
  AvgCommunicate_70509_Content_1 = {
    Text = "Guardián..."
  },
  AvgCommunicate_70509_Content_10 = {
    Text = "Ella está en batalla. Luchando sin cesar..."
  },
  AvgCommunicate_70509_Content_11 = {
    Text = "El poder de la montaña nevada comparte el mismo origen que nosotros. Busca devorarnos."
  },
  AvgCommunicate_70509_Content_12 = {
    Text = "Ella y yo estábamos de un lado. Nuestros poderes se fusionaron..."
  },
  AvgCommunicate_70509_Content_13 = {Text = "¿Y luego?"},
  AvgCommunicate_70509_Content_14 = {Text = "Luego..."},
  AvgCommunicate_70509_Content_15 = {
    Text = "Hemos devorado la Montaña de Nieve."
  },
  AvgCommunicate_70509_Content_16 = {Text = "¡!!!"},
  AvgCommunicate_70509_Content_17 = {
    Text = "Dije que lo derrotaría."
  },
  AvgCommunicate_70509_Content_18 = {
    Text = "Un guerrero nunca rompe su palabra. ¡Eres un verdadero guerrero, Helot!"
  },
  AvgCommunicate_70509_Content_19 = {
    Text = "Regresaré pronto. Por favor, ten a Lotan listo, Guardián."
  },
  AvgCommunicate_70509_Content_2 = {Text = "¿Helot?!"},
  AvgCommunicate_70509_Content_20 = {
    Text = "He encontrado la poderosa raíz de un guerrero. He encontrado mi creencia."
  },
  AvgCommunicate_70509_Content_21 = {
    Text = "Estoy agradecido por las palabras que una vez me dijiste y las cosas que hiciste por mí."
  },
  AvgCommunicate_70509_Content_22 = {
    Text = "A cambio, le dejaré presenciar el poder de la Montaña de Nieve."
  },
  AvgCommunicate_70509_Content_23 = {
    Text = "Tu forma de devolver la amabilidad es un poco extraña... Pero Lotan debería estar muy contento por ello."
  },
  AvgCommunicate_70509_Content_24 = {
    Text = "En resumen, ¡bienvenido de nuevo, Helot!"
  },
  AvgCommunicate_70509_Content_3 = {
    Text = "Vi el hielo y la nieve de Elworth derritiéndose, con un diente de león creciendo desde la montaña nevada allí..."
  },
  AvgCommunicate_70509_Content_4 = {
    Text = "¿Realmente... saliste de la Montaña de Nieve?!"
  },
  AvgCommunicate_70509_Content_5 = {
    Text = "Esa montaña no puede detenerme."
  },
  AvgCommunicate_70509_Content_6 = {
    Text = "¿Qué pasó en la montaña nevada?"
  },
  AvgCommunicate_70509_Content_7 = {
    Text = "Fui tragado por la montaña de nieve. Entonces, la vi..."
  },
  AvgCommunicate_70509_Content_8 = {
    Text = "¿Dices... otro Helot?"
  },
  AvgCommunicate_70509_Content_9 = {Text = "Sí."},
  AvgCommunicate_70509_Option_13 = {Text = "¿Y luego?"},
  AvgCommunicate_70509_Option_18 = {
    Text = "¡Eres un verdadero guerrero, Helot!"
  },
  AvgCommunicate_70509_Option_23 = {
    Text = "Tu forma de devolver la amabilidad es un poco extraña..."
  },
  AvgCommunicate_70509_Option_3 = {
    Text = "Vi el hielo y la nieve de Elworth derritiéndose..."
  },
  AvgCommunicate_70509_Option_6 = {
    Text = "¿Qué pasó dentro de la montaña nevada?"
  },
  AvgCommunicate_70509_Option_8 = {
    Text = "¿Otro Helot?"
  },
  AvgCommunicate_70510_Content_1 = {
    Text = "Hola, Guardián."
  },
  AvgCommunicate_70510_Content_10 = {
    Text = "Reúne a aquellos que deseas proteger y únete a nosotros..."
  },
  AvgCommunicate_70510_Content_11 = {
    Text = "Juntos, demos la bienvenida a la verdadera..."
  },
  AvgCommunicate_70510_Content_12 = {Text = "..."},
  AvgCommunicate_70510_Content_13 = {
    Text = "¿Erica? ¿Estás bien?"
  },
  AvgCommunicate_70510_Content_14 = {Text = "¿Erica?!"},
  AvgCommunicate_70510_Content_15 = {Text = "..."},
  AvgCommunicate_70510_Content_16 = {
    Text = "Lo siento, Guardián. El dispositivo de supresión psíquica falló hace un momento."
  },
  AvgCommunicate_70510_Content_17 = {
    Text = "Esa personalidad es la misma de siempre, completamente desquiciada..."
  },
  AvgCommunicate_70510_Content_18 = {
    Text = "¿Estás bien?"
  },
  AvgCommunicate_70510_Content_19 = {
    Text = "Gracias por tu preocupación, Guardián."
  },
  AvgCommunicate_70510_Content_2 = {
    Text = "¿Erica? ¿Hay otra invitación a la prueba hoy?"
  },
  AvgCommunicate_70510_Content_20 = {
    Text = "La profesora Doll instaló un dispositivo auxiliar de monitoreo y autorreparación en mi interior. La avería se ha resuelto con éxito."
  },
  AvgCommunicate_70510_Content_21 = {
    Text = "Me alegra saber que estás bien."
  },
  AvgCommunicate_70510_Content_22 = {
    Text = "La teoría de la evolución mecánica de esa personalidad es extrema y parcial."
  },
  AvgCommunicate_70510_Content_23 = {
    Text = "En cierto modo, podría considerarse una especie de fe maligna."
  },
  AvgCommunicate_70510_Content_24 = {
    Text = "La teoría de la evolución mecánica de esa personalidad, aunque algo extrema y parcial..."
  },
  AvgCommunicate_70510_Content_25 = {
    Text = "En cierto modo, es de hecho un enfoque que podría contrarrestar la Disolución."
  },
  AvgCommunicate_70510_Content_26 = {
    Text = "Sin embargo, también implicaría numerosos problemas técnicos y éticos..."
  },
  AvgCommunicate_70510_Content_27 = {
    Text = "No hay registros relevantes en mi base de datos, por lo que no puedo proporcionar opiniones de referencia efectivas."
  },
  AvgCommunicate_70510_Content_28 = {
    Text = "Si este enfoque es viable o no, es algo que te corresponde juzgar a ti, Guardián."
  },
  AvgCommunicate_70510_Content_3 = {
    Text = "Una invitación de prueba... Supongo que podrías llamarlo así."
  },
  AvgCommunicate_70510_Content_4 = {
    Text = "Pero no es uno de esos pequeños experimentos triviales."
  },
  AvgCommunicate_70510_Content_5 = {
    Text = "Es un gran invento que puede cambiar verdaderamente nuestra situación."
  },
  AvgCommunicate_70510_Content_6 = {
    Text = "Has estado luchando contra la sustancia negra todo este tiempo, pero la solución ha estado frente a ti desde el principio."
  },
  AvgCommunicate_70510_Content_7 = {
    Text = "¿De qué estás hablando..."
  },
  AvgCommunicate_70510_Content_8 = {
    Text = "Es la maquinaria, Guardián."
  },
  AvgCommunicate_70510_Content_9 = {
    Text = "En la maquinaria no hay dolor ni muerte. ¡En la maquinaria podemos poseer una vida que trasciende la carne!"
  },
  AvgCommunicate_70510_Option_13 = {
    Text = "¿Erica? ¿Estás bien?"
  },
  AvgCommunicate_70510_Option_17 = {
    Text = "¿Todo bien?"
  },
  AvgCommunicate_70510_Option_2 = {
    Text = "¿Hay otra invitación a la prueba hoy?"
  },
  AvgCommunicate_70510_Option_22 = {
    Text = "Su teoría de la evolución mecánica es, en cierto modo, una especie de fe maligna."
  },
  AvgCommunicate_70510_Option_24 = {
    Text = "Su teoría de la evolución mecánica no carece del todo de mérito..."
  },
  AvgCommunicate_70510_Option_7 = {
    Text = "¿De qué estás hablando..."
  },
  AvgCommunicate_70511_Content_1 = {
    Text = "Mi señor... hay algo que me gustaría preguntarte..."
  },
  AvgCommunicate_70511_Content_10 = {
    Text = "Si tanto la Princesa como yo estuviéramos en peligro al mismo tiempo, ¿a quién salvarías primero?"
  },
  AvgCommunicate_70511_Content_11 = {
    Text = "Mi... mi señor... eso... yo..."
  },
  AvgCommunicate_70511_Content_12 = {
    Text = "Está bien, está bien... Es culpa mía. No debería haberte provocado así."
  },
  AvgCommunicate_70511_Content_13 = {
    Text = "Lo sé, eres un Caballero entregado. Sin importar el peligro que enfrentes, siempre mantendrás tu juramento."
  },
  AvgCommunicate_70511_Content_14 = {
    Text = "Esta Experiencia en el Sueño me ha ayudado a comprenderte aún mejor."
  },
  AvgCommunicate_70511_Content_15 = {
    Text = "Gracias... Gracias, mi señor..."
  },
  AvgCommunicate_70511_Content_16 = {
    Text = "Ahora entreno todos los días. Me convertiré en un Caballero capacitado para proteger a mi señor. Lo que ocurrió antes... ¡nunca permitiré que vuelva a suceder!"
  },
  AvgCommunicate_70511_Content_17 = {
    Text = "Entonces, mi señor... ¿de verdad no puedo practicar equitación en la escuela..."
  },
  AvgCommunicate_70511_Content_18 = {Text = "¡No!"},
  AvgCommunicate_70511_Content_19 = {
    Text = "Sin embargo, hay un picadero recién inaugurado en la Zona Oeste... ¿Qué te parece si te llevo este Fin de semana para que lo pruebes?"
  },
  AvgCommunicate_70511_Content_2 = {
    Text = "Ogier, aunque tu desempeño habitual ha sido bastante bueno, las reglas de Misaq establecen que no se permite montar a caballo Dentro del campus, y mucho menos practicar ejercicios de carga..."
  },
  AvgCommunicate_70511_Content_20 = {Text = "¡¡¡!!"},
  AvgCommunicate_70511_Content_21 = {
    Text = "¡¡¡Gracias, mi señor!!!"
  },
  AvgCommunicate_70511_Content_3 = {
    Text = "¡Me malinterpretáis, mi señor! Lo que quería preguntaros es... el asunto de los Sueños..."
  },
  AvgCommunicate_70511_Content_4 = {
    Text = "¿Es sobre ese \"Sueño\" que tuve?"
  },
  AvgCommunicate_70511_Content_5 = {
    Text = "¡Sí, mi señor!"
  },
  AvgCommunicate_70511_Content_6 = {
    Text = "Quiero saber, ¿qué fue exactamente lo que visteis en ese Sueño?"
  },
  AvgCommunicate_70511_Content_7 = {
    Text = "Vi una catástrofe, una Princesa bondadosa y un pequeño Caballero valiente y Firme."
  },
  AvgCommunicate_70511_Content_8 = {
    Text = "También tengo una pregunta que me gustaría hacerte."
  },
  AvgCommunicate_70511_Content_9 = {
    Text = "Mi señor, por favor, adelante."
  },
  AvgCommunicate_70511_Option_10 = {
    Text = "Entre la Princesa y yo, ¿a quién salvarías primero?"
  },
  AvgCommunicate_70511_Option_13 = {
    Text = "Lo sé, eres un Caballero cumplidor"
  },
  AvgCommunicate_70511_Option_18 = {Text = "¡No!"},
  AvgCommunicate_70511_Option_2 = {
    Text = "¿Sobre montar a caballo en el campo?"
  },
  AvgCommunicate_70511_Option_4 = {
    Text = "¿Sobre el \"Sueño\"?"
  },
  AvgCommunicate_70512_Content_1 = {
    Text = "Después de separarnos de Le Whai, ha pasado mucho tiempo desde la última vez que nos vimos, Guardián del Secreto {Male=señor,Female=señorita}."
  },
  AvgCommunicate_70512_Content_10 = {
    Text = "La decadencia en ruinas de este mundo es algo que ustedes, personas mimadas, nunca entenderán."
  },
  AvgCommunicate_70512_Content_11 = {
    Text = "La voluntad suprema, la reliquia original, traerá una purificación definitiva al mundo."
  },
  AvgCommunicate_70512_Content_12 = {
    Text = "No tengo intención de apuntar a Mitag, pero Mitag está bloqueando el camino hacia la Llegada del Nuevo Mundo."
  },
  AvgCommunicate_70512_Content_13 = {
    Text = "Quédate tranquilo/a, {Male=Mr.,Female=Miss} Guardián, mi Señor no te abandonará por esto."
  },
  AvgCommunicate_70512_Content_14 = {
    Text = "También te convertirás en un miembro del nuevo mundo."
  },
  AvgCommunicate_70512_Content_15 = {
    Text = "Él te mostrará todo ese futuro completamente nuevo."
  },
  AvgCommunicate_70512_Content_16 = {
    Text = "En ese momento, Él oirá tus sinceras confesiones."
  },
  AvgCommunicate_70512_Content_17 = {
    Text = "Puedes estar tranquila, Juliette."
  },
  AvgCommunicate_70512_Content_18 = {
    Text = "Tu maestro no tendrá oportunidad de llegar."
  },
  AvgCommunicate_70512_Content_19 = {
    Text = "Te detendré. ¡Definitivamente!"
  },
  AvgCommunicate_70512_Content_2 = {
    Text = "¡Juliette... ¿qué exactamente quieres lograr al romper en Mythag?!"
  },
  AvgCommunicate_70512_Content_3 = {
    Text = "En Lemwashi, alguna vez te lo dije."
  },
  AvgCommunicate_70512_Content_4 = {
    Text = "Nuestro Dios creará un futuro mejor para el mundo."
  },
  AvgCommunicate_70512_Content_5 = {
    Text = "¿Recuerdas, Guardián?"
  },
  AvgCommunicate_70512_Content_6 = {
    Text = "Por supuesto, no olvidaré esta información importante."
  },
  AvgCommunicate_70512_Content_7 = {
    Text = "¿Qué tiene esto que ver con Mythag?"
  },
  AvgCommunicate_70512_Content_8 = {
    Text = "No recuerdo las seductoras palabras del enemigo."
  },
  AvgCommunicate_70512_Content_9 = {
    Text = "He visto a muchas personas obstinadamente tercas, y no me sorprende."
  },
  AvgCommunicate_70512_Option_17 = {
    Text = "Te detendré."
  },
  AvgCommunicate_70512_Option_2 = {
    Text = "¿Qué quieres hacer?!"
  },
  AvgCommunicate_70512_Option_6 = {Text = "Recuerdo"},
  AvgCommunicate_70512_Option_8 = {
    Text = "No recuerdo las insidiosas palabras del enemigo"
  },
  AvgCommunicate_70513_Content_1 = {
    Text = "Fui a investigar el sonido de la flauta que escuchaste mientras estabas inconsciente."
  },
  AvgCommunicate_70513_Content_10 = {
    Text = "No sé si elogiar tu optimismo o criticar tu ignorancia."
  },
  AvgCommunicate_70513_Content_11 = {
    Text = "Lo que Tawil menciona específicamente suele ser una calamidad."
  },
  AvgCommunicate_70513_Content_12 = {
    Text = "La peor clase."
  },
  AvgCommunicate_70513_Content_13 = {
    Text = "Dado que ya ha ocurrido... tomémonos un momento para auto consolarse."
  },
  AvgCommunicate_70513_Content_14 = {
    Text = "En resumen, seguiré investigando este asunto."
  },
  AvgCommunicate_70513_Content_15 = {
    Text = "Actualmente no tiene un efecto sustancial sobre ti, así que no hay necesidad de preocuparse por ello por ahora."
  },
  AvgCommunicate_70513_Content_16 = {
    Text = "Primero, tratemos con el problema a la mano."
  },
  AvgCommunicate_70513_Content_2 = {
    Text = "¿Hay algún resultado?"
  },
  AvgCommunicate_70513_Content_3 = {
    Text = "Muy pocos, pero hay algunos."
  },
  AvgCommunicate_70513_Content_4 = {
    Text = "¿Es mi ilusión?"
  },
  AvgCommunicate_70513_Content_5 = {
    Text = "Se puede afirmar con claridad: No."
  },
  AvgCommunicate_70513_Content_6 = {
    Text = "Consulté al Profesor Alistair."
  },
  AvgCommunicate_70513_Content_7 = {
    Text = "Aunque actualmente no hay registro de este sonido de flauta, Tawil una vez le mencionó algo sobre la flauta."
  },
  AvgCommunicate_70513_Content_8 = {Text = "¿Tawil?!"},
  AvgCommunicate_70513_Content_9 = {
    Text = "Solo un sueño, pero involucra personajes de tan alto rango..."
  },
  AvgCommunicate_70513_Option_13 = {
    Text = "Justo considérelo una forma de auto-confort."
  },
  AvgCommunicate_70513_Option_2 = {
    Text = "¿Hay algún resultado?"
  },
  AvgCommunicate_70513_Option_4 = {
    Text = "¿Es mi ilusión?"
  },
  AvgCommunicate_70513_Option_8 = {Text = "¿Tawil?!"},
  AvgCommunicate_70514_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} Guardián, la editorial me ha enviado una carta."
  },
  AvgCommunicate_70514_Content_10 = {
    Text = "Es bajo su protección que puedo vagar despreocupado en el mundo de las flores y la poesía."
  },
  AvgCommunicate_70514_Content_11 = {
    Text = "Esas protecciones y daños ahora son todos parte del pasado..."
  },
  AvgCommunicate_70514_Content_12 = {
    Text = "Guardián, gracias por llevarme a Cité esta vez... Este viaje es muy importante para mí."
  },
  AvgCommunicate_70514_Content_13 = {
    Text = "Eso es correcto. Todo lo de tu pasado con Corrette ya ha quedado atrás."
  },
  AvgCommunicate_70514_Content_14 = {
    Text = "Mira hacia adelante, Horla."
  },
  AvgCommunicate_70514_Content_15 = {
    Text = "De acuerdo, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgCommunicate_70514_Content_16 = {
    Text = "Esta colección de poesías es mi despedida al pasado."
  },
  AvgCommunicate_70514_Content_17 = {
    Text = "Recordaré a Colette en su juventud. Recordaré a Colette en su vejez. También me despediré de ella..."
  },
  AvgCommunicate_70514_Content_18 = {
    Text = "Hay nuevas vidas y nuevos poemas esperándome."
  },
  AvgCommunicate_70514_Content_2 = {
    Text = "Me felicitaron, diciendo que esta colección de poemas había logrado excelentes resultados."
  },
  AvgCommunicate_70514_Content_3 = {
    Text = "¡Felicidades, Horla!"
  },
  AvgCommunicate_70514_Content_4 = {
    Text = "Gracias, Guardián."
  },
  AvgCommunicate_70514_Content_5 = {
    Text = "En el pasado, Colette estaba a cargo de todos estos asuntos."
  },
  AvgCommunicate_70514_Content_6 = {
    Text = "Desde el principio, ha sido ella quien ha llevado esta parte."
  },
  AvgCommunicate_70514_Content_7 = {
    Text = "En mi memoria, esta es la primera vez que te he visto mostrar preocupación por las ventas."
  },
  AvgCommunicate_70514_Content_8 = {
    Text = "Porque el autor de esta colección de poesía es Horla Corlet......"
  },
  AvgCommunicate_70514_Content_9 = {
    Text = "Colette se preocupará. Ella ha estado soportando esta parte todo el tiempo."
  },
  AvgCommunicate_70514_Option_13 = {
    Text = "Mira hacia adelante."
  },
  AvgCommunicate_70514_Option_3 = {
    Text = "¡Felicidades!"
  },
  AvgCommunicate_70514_Option_7 = {
    Text = "La primera vez que te he visto preocuparte por las ventas."
  },
  AvgCommunicate_70515_Content_1 = {
    Text = "Solo eché un vistazo alrededor del museo de cera... Es realmente un lío."
  },
  AvgCommunicate_70515_Content_10 = {
    Text = "Para evitar a esos perros locos del Comité, no he jugado mi juego durante mucho tiempo..."
  },
  AvgCommunicate_70515_Content_11 = {
    Text = "Podrías considerar rendirte en Mythag junto a Rogers."
  },
  AvgCommunicate_70515_Content_12 = {
    Text = "Deberías conocer las consecuencias de ser atrapado por el Comité."
  },
  AvgCommunicate_70515_Content_13 = {
    Text = "Tu boca sabe cómo engañar, querido/a."
  },
  AvgCommunicate_70515_Content_14 = {
    Text = "Sin embargo, me divertí mucho jugando con todos ustedes en el museo de cera."
  },
  AvgCommunicate_70515_Content_15 = {
    Text = "Quizás lo pensaré seriamente."
  },
  AvgCommunicate_70515_Content_16 = {
    Text = "Quizás llegue otro día en que nos encontremos. Lo espero con ansias, {Male=Mr.,Female=Miss} Guardián～"
  },
  AvgCommunicate_70515_Content_2 = {
    Text = "¡Realmente no sabes cómo valorar!"
  },
  AvgCommunicate_70515_Content_3 = {Text = "¿Pandia?"},
  AvgCommunicate_70515_Content_4 = {
    Text = "¿A dónde han ido tú y Rogers?"
  },
  AvgCommunicate_70515_Content_5 = {
    Text = "¿Qué, estás pensando en el látigo de alguien?"
  },
  AvgCommunicate_70515_Content_6 = {
    Text = "Has cometido tantos crímenes; solo quiero arrestarte y llevarte ante la justicia."
  },
  AvgCommunicate_70515_Content_7 = {
    Text = "Aquellos que perdieron la vida por culpa del museo de cera merecen una explicación."
  },
  AvgCommunicate_70515_Content_8 = {
    Text = "Oh querido, esas son todas obras del Lord Rogers; ciertamente no tengo ese talento artístico."
  },
  AvgCommunicate_70515_Content_9 = {
    Text = "Qué pena, qué pena. La mano del Señor Rogers, nacida para el arte, se ha ido."
  },
  AvgCommunicate_70515_Option_11 = {
    Text = "Quizás puedas elegir venir a Mitag."
  },
  AvgCommunicate_70515_Option_3 = {Text = "¿Pandia?"},
  AvgCommunicate_70515_Option_6 = {
    Text = "Quiero... arrestarte y llevarte ante la justicia."
  },
  AvgCommunicate_70516_Content_1 = {
    Text = "%player%..."
  },
  AvgCommunicate_70516_Content_10 = {
    Text = "¡Asegúrate de cuidarte bien, Ramona!"
  },
  AvgCommunicate_70516_Content_11 = {
    Text = "¿Tienes tan poca confianza en tu compañero?"
  },
  AvgCommunicate_70516_Content_12 = {
    Text = "No te preocupes, me uniré a ti después de que termine con las cosas aquí."
  },
  AvgCommunicate_70516_Content_13 = {
    Text = "Tu situación es la más peligrosa en este momento; debes tener cuidado, %player%..."
  },
  AvgCommunicate_70516_Content_2 = {
    Text = "¿Ramona?! ¿Estás bien?"
  },
  AvgCommunicate_70516_Content_3 = {
    Text = "Hmm, estoy bien."
  },
  AvgCommunicate_70516_Content_4 = {
    Text = "Acabo de encontrarme con algunos miembros del Comité, y ya me he hecho cargo de ello."
  },
  AvgCommunicate_70516_Content_5 = {
    Text = "Quería venir y unirme a ti, pero vi a un grupo de miembros del Comité dirigiéndose hacia el edificio de enseñanza..."
  },
  AvgCommunicate_70516_Content_6 = {
    Text = "Muchos maestros y estudiantes están en clase allí; me preocupa que la gente del Comité pueda hacerles daño."
  },
  AvgCommunicate_70516_Content_7 = {
    Text = "Necesito escoltarlos a un lugar seguro."
  },
  AvgCommunicate_70516_Content_8 = {
    Text = "Acabo de enfrentar a Clementine; me encargaré de las cosas aquí."
  },
  AvgCommunicate_70516_Content_9 = {
    Text = "Te dejaré el edificio de enseñanza."
  },
  AvgCommunicate_70516_Option_2 = {
    Text = "¿Ramona?! ¿Estás bien?"
  },
  AvgCommunicate_70516_Option_8 = {
    Text = "¡Cuídate, Ramona!"
  },
  AvgCommunicate_70517_Content_1 = {
    Text = "Desolado. Pedante. Careciendo de la pasión que la vida debería tener..."
  },
  AvgCommunicate_70517_Content_10 = {
    Text = "Tú, como entonces, todavía te importan mucho las reglas."
  },
  AvgCommunicate_70517_Content_11 = {
    Text = "Está bien, ya he alquilado el auditorio de la escuela."
  },
  AvgCommunicate_70517_Content_12 = {
    Text = "¿Alquilar el salón? ¿Por qué?"
  },
  AvgCommunicate_70517_Content_13 = {
    Text = "Porque la junta escolar de Mythag no estuvo de acuerdo con mi decisión de comprarlo."
  },
  AvgCommunicate_70517_Content_14 = {
    Text = "Parece que has malinterpretado mi pregunta..."
  },
  AvgCommunicate_70517_Content_15 = {
    Text = "Ya no importa. Mañana por la noche, organizaré un banquete en el salón."
  },
  AvgCommunicate_70517_Content_16 = {
    Text = "Un banquete apasionado, novel y verdaderamente vibrante, rebosante de la vitalidad de la vida, como aquellos en un antiguo castillo."
  },
  AvgCommunicate_70517_Content_17 = {
    Text = "Los artículos que deben prepararse están ahora completamente listos."
  },
  AvgCommunicate_70517_Content_18 = {
    Text = "Ya he eludido los obstáculos que plantean las reglas por adelantado. Nadie nos molestará."
  },
  AvgCommunicate_70517_Content_19 = {
    Text = "¿Puedes encontrar el camino hacia el vestíbulo, Guardián?"
  },
  AvgCommunicate_70517_Content_2 = {
    Text = "¿De qué estás hablando..."
  },
  AvgCommunicate_70517_Content_3 = {
    Text = "Me refiero, no hemos celebrado un banquete en mucho tiempo."
  },
  AvgCommunicate_70517_Content_4 = {
    Text = "¿No hubo una reunión para cenar en el salón el fin de semana pasado?"
  },
  AvgCommunicate_70517_Content_5 = {
    Text = "Un grupo de personas bien vestidas sentadas juntas, manteniendo una distancia social cortés, comportándose con cortesía, pero siempre teniendo cuidado de ocultar los pensamientos sordidos en sus corazones..."
  },
  AvgCommunicate_70517_Content_6 = {
    Text = "Esta agotadora actividad social no puede llamarse un banquete."
  },
  AvgCommunicate_70517_Content_7 = {
    Text = "Ya has visto el verdadero banquete en el antiguo castillo, ¿no es así?"
  },
  AvgCommunicate_70517_Content_8 = {
    Text = "Madame Wanda, después de todo, esto es Londinium, no tu castillo..."
  },
  AvgCommunicate_70517_Content_9 = {
    Text = "Algunas de las reglas más básicas son aún aquellas que debemos cumplir..."
  },
  AvgCommunicate_70517_Option_12 = {
    Text = "Hmm? ¿Por qué?"
  },
  AvgCommunicate_70517_Option_14 = {
    Text = "Parece que has malinterpretado mi pregunta..."
  },
  AvgCommunicate_70517_Option_2 = {
    Text = "¿De qué estás hablando..."
  },
  AvgCommunicate_70517_Option_4 = {
    Text = "¿No hubo una reunión para cenar en el salón el fin de semana pasado?"
  },
  AvgCommunicate_70517_Option_8 = {
    Text = "Después de todo, esto es Londinium, no tu antiguo castillo..."
  },
  AvgCommunicate_70518_Content_1 = {
    Text = "Hey, ¿dónde ha ido Miryam?"
  },
  AvgCommunicate_70518_Content_10 = {
    Text = "Ambicioso... Me gusta ese título."
  },
  AvgCommunicate_70518_Content_11 = {
    Text = "No te preocupes. Ya he realizado ajustes en el plan."
  },
  AvgCommunicate_70518_Content_12 = {
    Text = "La resurrección del Perishtite no se limita a apoderarse del poder del Marinero."
  },
  AvgCommunicate_70518_Content_13 = {
    Text = "Estoy buscando a ella porque quiero discutir el siguiente paso en nuestra colaboración."
  },
  AvgCommunicate_70518_Content_14 = {
    Text = "Los recursos y poderes que Mitag posee son de gran utilidad tanto para ella como para mí."
  },
  AvgCommunicate_70518_Content_15 = {
    Text = "¿Planificando en voz alta contra Mitag justo frente a mí... no es eso un poco inapropiado?"
  },
  AvgCommunicate_70518_Content_16 = {
    Text = "Es cooperación. Después de todo, si se pueden utilizar los poderes del Marinero y el Perishite, tu investigación será mucho más fácil, ¿verdad?"
  },
  AvgCommunicate_70518_Content_17 = {
    Text = "Suena como si... pudiera haber algo de verdad en ello..."
  },
  AvgCommunicate_70518_Content_18 = {
    Text = "Muy bien, muy perspicaz, Guardián."
  },
  AvgCommunicate_70518_Content_19 = {
    Text = "No te preocupes, una vez que la misión esté completa, recibirás todo lo que te pertenece."
  },
  AvgCommunicate_70518_Content_2 = {
    Text = "¡Goliat, ¿qué intentas hacer?!"
  },
  AvgCommunicate_70518_Content_20 = {
    Text = "Después de todo... fue el pequeño quien me siguió en el Sueño."
  },
  AvgCommunicate_70518_Content_21 = {
    Text = "Yo, Goliat, nunca maltrato a los que están a mi alrededor."
  },
  AvgCommunicate_70518_Content_3 = {
    Text = "Sé de tus problemas con Miryam; cálmate, ¡no es el momento para pelear y matar!"
  },
  AvgCommunicate_70518_Content_4 = {Text = "..."},
  AvgCommunicate_70518_Content_5 = {
    Text = "¿En tus ojos, soy solo un bruto que solo sabe pelear?"
  },
  AvgCommunicate_70518_Content_6 = {
    Text = "¿Hay alguna otra posibilidad?"
  },
  AvgCommunicate_70518_Content_7 = {
    Text = "El Guardián de Mitag, que carece incluso de este poco juicio. Este lugar realmente tiene un futuro preocupante."
  },
  AvgCommunicate_70518_Content_8 = {
    Text = "Sé que una persona ambiciosa no es un loco imprudente."
  },
  AvgCommunicate_70518_Content_9 = {
    Text = "Sin embargo, por si acaso, es mejor preguntar algunas cosas de manera más clara."
  },
  AvgCommunicate_70518_Option_15 = {
    Text = "Conspirar en voz alta, ¿no es eso inapropiado?"
  },
  AvgCommunicate_70518_Option_17 = {
    Text = "También suena razonable..."
  },
  AvgCommunicate_70518_Option_2 = {
    Text = "¿Qué intentas hacer?!"
  },
  AvgCommunicate_70518_Option_6 = {
    Text = "¿No es así?"
  },
  AvgCommunicate_70518_Option_8 = {
    Text = "¡Por supuesto que no!"
  },
