  AvgCommunicate_70520_Content_1 = {Text = "Meow~"},
  AvgCommunicate_70520_Content_10 = {
    Text = "He ganado peso y mi sueño ha empeorado, ¡todo por ella!"
  },
  AvgCommunicate_70520_Content_11 = {
    Text = "El payaso 24 cuenta chistes bastante bien y nos trae una gran alegría..."
  },
  AvgCommunicate_70520_Content_12 = {
    Text = "Un bromista insípido que anhela atención, ¿qué hay para gustar?"
  },
  AvgCommunicate_70520_Content_13 = {
    Text = "Si te gustan los payasos, más te vale visitar el circo. También puedes mirarte en el espejo."
  },
  AvgCommunicate_70520_Content_14 = {
    Text = "¡Kitty 24 es tan adorable!"
  },
  AvgCommunicate_70520_Content_15 = {
    Text = "¿Eh? ¿Qué tiene de agradable un tipo que ni siquiera puede hablar el idioma humano?"
  },
  AvgCommunicate_70520_Content_16 = {
    Text = "¿Es porque necesitas mascotas para llenar el vacío de tu vida aburrida?"
  },
  AvgCommunicate_70520_Content_17 = {
    Text = "Veo, debes ser llamado Veneno Lengua 24."
  },
  AvgCommunicate_70520_Content_18 = {
    Text = "Qué lengua tan afilada, 24. ¡Soy digna!"
  },
  AvgCommunicate_70520_Content_19 = {Text = "..."},
  AvgCommunicate_70520_Content_2 = {
    Text = "24, tu personalidad ha cambiado de nuevo..."
  },
  AvgCommunicate_70520_Content_20 = {
    Text = "Estoy... lo siento, Guardián"
  },
  AvgCommunicate_70520_Content_21 = {
    Text = "Recientemente, fui a la calle con Jenkin. Después de escuchar a esas personas pelear tanto, mi personalidad recién formada también se ha vuelto tan grosera..."
  },
  AvgCommunicate_70520_Content_22 = {
    Text = "¡Por favor, mantén la calma, Guardián! ¡Definitivamente educaré bien a esta personalidad lo antes posible!"
