  AvgCommunicate_70521_Content_7 = {
    Text = "A Lily le gusta el final de esa historia."
  },
  AvgCommunicate_70521_Content_8 = {
    Text = "\"La niña vivió feliz para siempre con su madre...\"..."
  },
  AvgCommunicate_70521_Content_9 = {
    Text = "Según la señora Davendale, la película ya ha sido procesada."
  },
  AvgCommunicate_70521_Option_2 = {
