  },
  AvgCommunicate_70522_Content_1 = {
    Text = "Varios consolidaciones de tierras dentro de Londinium están avanzando sin problemas, y esos contratos problemáticos han sido resueltos."
  },
  AvgCommunicate_70522_Content_10 = {
    Text = "¿Qué? ¿El Guardián de Mitag, podría ser una persona que rompe su palabra?"
  },
  AvgCommunicate_70522_Content_11 = {
    Text = "¡Ciertamente no! Solo es..."
  },
  AvgCommunicate_70522_Content_12 = {
    Text = "Heh... qué tipo más infantil. Aunque no puedo verlo, apuesto a que tu cara debe estar roja hasta el cuello mientras piensas en cómo mentir, ¿verdad?"
  },
  AvgCommunicate_70522_Content_13 = {
    Text = "Aquí está el trato. El objeto que prometí entregar a Mythag necesita ser entregado por ti. ¿Es esa razón suficiente?"
  },
  AvgCommunicate_70522_Content_14 = {Text = "Pero..."},
  AvgCommunicate_70522_Content_15 = {
    Text = "Está bien, no más \"peros\"; está decidido."
  },
  AvgCommunicate_70522_Content_16 = {
    Text = "Está bien, te lo prometo... Es un honor para mí, Lady Sorel."
  },
  AvgCommunicate_70522_Content_17 = {
    Text = "Eso es correcto."
  },
  AvgCommunicate_70522_Content_18 = {
    Text = "Entre nosotros, ya no es necesario usar esas formalidades y tanteos mutuos."
  },
  AvgCommunicate_70522_Content_19 = {
    Text = "A las 8 PM de esta noche, en la bodega de mi mansión. Nadie te detendrá."
  },
  AvgCommunicate_70522_Content_2 = {
    Text = "Todo esto es gracias a tu ayuda, Guardián."
  },
  AvgCommunicate_70522_Content_20 = {
    Text = "Te estoy esperando, mi pequeño caballero."
  },
  AvgCommunicate_70522_Content_3 = {
    Text = "Esos tediosos salones de negocios finalmente están llegando a su fin."
  },
  AvgCommunicate_70522_Content_4 = {
    Text = "Mientras tengas algo de tiempo libre, ¿vienes y tomas una bebida conmigo?"
  },
  AvgCommunicate_70522_Content_5 = {
    Text = "Se prohíbe a los estudiantes de Mitag beber..."
  },
  AvgCommunicate_70522_Content_6 = {
    Text = "¿Es así? El profesor Dexter no me dijo eso de esta manera."
  },
  AvgCommunicate_70522_Content_7 = {
    Text = "¿Quién hizo esta regla? Necesita ser cambiada."
  },
  AvgCommunicate_70522_Content_8 = {
    Text = "Ah, esto..."
  },
  AvgCommunicate_70522_Content_9 = {
    Text = "Todavía me debes una bebida. ¿Recuerdas?"
  },
  AvgCommunicate_70522_Option_11 = {
    Text = "¡Ciertamente no! Solo es..."
  },
  AvgCommunicate_70522_Option_16 = {
    Text = "Es mi honor, Lady Sorel."
  },
  AvgCommunicate_70522_Option_5 = {
    Text = "Se prohíbe a los estudiantes de Mitag beber..."
  },
  AvgCommunicate_70523_Content_1 = {
    Text = "En la prisa, no tuve la oportunidad de presentarles a todos las costumbres y la cultura locales."
  },
  AvgCommunicate_70523_Content_10 = {
    Text = "Como mencioné antes, soy solo un mensajero proclamando las enseñanzas de mi Señor."
  },
  AvgCommunicate_70523_Content_11 = {
    Text = "Nuestro Dios creará un futuro mejor para el mundo."
  },
  AvgCommunicate_70523_Content_12 = {
    Text = "Grupos primitivos como el Aram también son parte de este futuro y siguen siendo nuestros amigos más leales."
  },
  AvgCommunicate_70523_Content_13 = {
    Text = "Por supuesto, también comprendo las dudas del {Male=Mr.,Female=Miss} Guardián."
  },
  AvgCommunicate_70523_Content_14 = {
    Text = "Creo que mientras pasemos un poco más de tiempo juntos, estas dudas desaparecerán naturalmente."
  },
  AvgCommunicate_70523_Content_15 = {
    Text = "Todos han recorrido un largo camino, por favor descansen bien."
  },
  AvgCommunicate_70523_Content_16 = {
    Text = "Le represento a Le Whai y le doy la más sincera bienvenida, Guardián del Secreto {Male=señor,Female=señorita}."
  },
  AvgCommunicate_70523_Content_2 = {
    Text = "Me pregunto si el {Male=Mr.,Female=Miss} Guardián tiene alguna pregunta para mí."
  },
  AvgCommunicate_70523_Content_3 = {
    Text = "Tengo un poco de curiosidad sobre las costumbres aquí."
  },
  AvgCommunicate_70523_Content_4 = {
    Text = "Aunque el pueblo Aram ha vivido de la ganadería durante generaciones, lejos de la sociedad industrial, por favor no los consideren como tribus bárbaras no civilizadas."
  },
  AvgCommunicate_70523_Content_5 = {
    Text = "No hay reglas aquí; siéntete libre de interactuar con ellos."
  },
  AvgCommunicate_70523_Content_6 = {
    Text = "El entusiasmo del pueblo Aram, que todos pronto podrán sentir."
  },
  AvgCommunicate_70523_Content_7 = {
    Text = "Es bastante extraño que alguien como Juliette exista en una tribu tan primitiva, ¿no es así?"
  },
  AvgCommunicate_70523_Content_8 = {
    Text = "Guiado por el llamado del Sueño para liderar a Arlan, esta razón suena algo forzada."
  },
  AvgCommunicate_70523_Content_9 = {
    Text = "{Male=Mr.,Female=Miss} Guardián, por favor no le dé demasiadas vueltas."
  },
  AvgCommunicate_70523_Option_3 = {
    Text = "Tengo un poco de curiosidad sobre las costumbres aquí."
  },
  AvgCommunicate_70523_Option_7 = {
    Text = "Tengo mucha curiosidad sobre la mensajera Juliette."
  },
  AvgCommunicate_70524_Content_1 = {
    Text = "Hablando de eso, ha pasado mucho tiempo desde nuestra última colaboración después del museo de cera."
  },
  AvgCommunicate_70524_Content_10 = {
    Text = "Espero que esta colaboración transcurra sin problemas."
  },
  AvgCommunicate_70524_Content_11 = {
    Text = "¡Con la ayuda del Senior William, definitivamente irá sin problemas!"
  },
  AvgCommunicate_70524_Content_2 = {
    Text = "¡El Senior William también ayudó mucho con el último incidente que involucró al Marinero!"
  },
  AvgCommunicate_70524_Content_3 = {
    Text = "...Solo estaba conduciendo, no era nada particularmente útil."
  },
  AvgCommunicate_70524_Content_4 = {
    Text = "Después de todo, asignar dos ases a la misma misión se siente un poco desperdiciado."
  },
  AvgCommunicate_70524_Content_5 = {Text = "..."},
  AvgCommunicate_70524_Content_6 = {
    Text = "Realmente no te importa lo incómodo de decir esto."
  },
  AvgCommunicate_70524_Content_7 = {
    Text = "Una vez me salvaste en el museo de cera. Repagaré esta deuda de gratitud."
  },
  AvgCommunicate_70524_Content_8 = {
    Text = "Por esta tarea, tú y Ramona están a la vista, lo que hace inconveniente hacer ciertas cosas."
  },
  AvgCommunicate_70524_Content_9 = {
    Text = "Me ocuparé de la investigación en las sombras."
  },
  AvgCommunicate_70524_Option_11 = {
    Text = "¡Ciertamente!"
  },
  AvgCommunicate_70524_Option_2 = {
    Text = "La última vez, con el Marinero, el Señor William ayudó mucho."
  },
  AvgCommunicate_70524_Option_4 = {
    Text = "Después de todo, asignar dos ases a la misma misión es un poco desperdiciado."
  },
  AvgCommunicate_70525_Content_1 = {
    Text = "¡Ding ding ding!"
  },
  AvgCommunicate_70525_Content_10 = {
    Text = "Veo. Eso también funciona."
  },
  AvgCommunicate_70525_Content_11 = {
    Text = "¡Espero que esta vez puedas mostrar algo de respeto por la actuación y te abstengas de mencionar algo como \"la chica vivió feliz con su madre desde entonces\"!"
  },
  AvgCommunicate_70525_Content_2 = {
    Text = "Así que, Guardián, ¡te sorprende el escenario de Andy Johnson!"
  },
  AvgCommunicate_70525_Content_3 = {
    Text = "Cuando el gran director realmente se vuelve adicto..."
  },
  AvgCommunicate_70525_Content_4 = {
    Text = "Sin embargo, el escenario que has preparado es verdaderamente impresionante."
  },
  AvgCommunicate_70525_Content_5 = {
    Text = "La programación de la actuación también está bien ejecutada."
  },
  AvgCommunicate_70525_Content_6 = {
    Text = "Estamos preparando el próximo proyecto."
  },
  AvgCommunicate_70525_Content_7 = {
    Text = "Luego, ¡el set y el director para la próxima entrega dependen de ti!"
  },
  AvgCommunicate_70525_Content_8 = {
    Text = "¿Qué? ¿No incluye al guionista?"
  },
  AvgCommunicate_70525_Content_9 = {
    Text = "Uh, Jenkin tiene algunas pequeñas reflexiones sobre la historia del Errante Nocturno..."
  },
  AvgCommunicate_70525_Option_3 = {
    Text = "De verdad, ¡bastante bien!"
  },
  AvgCommunicate_70525_Option_6 = {
    Text = "El próximo trabajo dependerá de ti!"
  },
  AvgCommunicate_70525_Option_9 = {
    Text = "Jenkin tiene algunas reflexiones sobre la historia del Guardabosques de la Noche Eterna..."
  },
  AvgCommunicate_70526_Content_1 = {
    Text = "Mi colaboración con Herbert ha llegado a su fin."
  },
  AvgCommunicate_70526_Content_10 = {
    Text = "En resumen, quiero ver un mundo más amplio."
  },
  AvgCommunicate_70526_Content_11 = {
    Text = "Lotan me derrotó tres veces. Me pregunto, ¿qué más, más allá del odio, puede otorgar a alguien tal inmenso poder?"
  },
  AvgCommunicate_70526_Content_12 = {
    Text = "Después de que encuentre la respuesta, regresaré."
  },
  AvgCommunicate_70526_Content_13 = {
    Text = "Para entonces, espero que tú y Lotan estén dispuestos a ser mis oponentes una vez más."
  },
  AvgCommunicate_70526_Content_14 = {
    Text = "Mientras ya no seas un enemigo, ya sea como oponente o compañero, eres bienvenido."
  },
  AvgCommunicate_70526_Content_15 = {
    Text = "Transmitiré esto a Lotan. Creo que estaría muy ansiosa por ver al nuevo tú."
  },
  AvgCommunicate_70526_Content_16 = {
    Text = "El barco ha zarpado."
  },
  AvgCommunicate_70526_Content_17 = {
    Text = "Tendremos un día para encontrarnos de nuevo. Adiós, Helot."
  },
  AvgCommunicate_70526_Content_2 = {
    Text = "No me opondré más a ti. Esta es mi promesa."
  },
  AvgCommunicate_70526_Content_3 = {
    Text = "Después de esa batalla, simplemente desapareciste sin dejar rastro..."
  },
  AvgCommunicate_70526_Content_4 = {
    Text = "Herbert es nuestro enemigo común, y estamos más que dispuestos a convertir a los enemigos en amigos contigo."
  },
  AvgCommunicate_70526_Content_5 = {
    Text = "Si deseas venir, **Mitag** te da la bienvenida en cualquier momento."
  },
  AvgCommunicate_70526_Content_6 = {
    Text = "Lo aprecio. Pero me estoy preparando para irme."
  },
  AvgCommunicate_70526_Content_7 = {
    Text = "¿Dejando? ¿A dónde vas?"
  },
  AvgCommunicate_70526_Content_8 = {
    Text = "Poco claro. Quizás es un cierto mar."
  },
  AvgCommunicate_70526_Content_9 = {
    Text = "Quizás es una cierta montaña. Siempre la escucho llamando."
  },
  AvgCommunicate_70526_Option_14 = {
    Text = "Se lo pasaré a ella"
  },
  AvgCommunicate_70526_Option_17 = {
    Text = "Adiós, Helot."
  },
  AvgCommunicate_70526_Option_3 = {
    Text = "Podrías considerar venir a Mythag."
  },
  AvgCommunicate_70526_Option_7 = {
    Text = "¿A dónde vas?"
  },
  AvgCommunicate_70527_Content_1 = {
    Text = "Aurita le mostró a Lily la medusa que había criado."
  },
  AvgCommunicate_70527_Content_10 = {
    Text = "Porque ella cumplió su mayor deseo: que tú vivieras una vida feliz."
  },
  AvgCommunicate_70527_Content_11 = {
    Text = "Lily quiere ver a su madre sonreír así."
  },
  AvgCommunicate_70527_Content_12 = {
    Text = "Para hacer feliz a la Madre, ¡Lily seguirá siendo alegre!"
  },
  AvgCommunicate_70527_Content_13 = {
    Text = "¡Eso es correcto!"
  },
  AvgCommunicate_70527_Content_14 = {
    Text = "¿Lily aún quiere tomar el metro? Si es así, puedo llevarla allí ahora mismo."
  },
  AvgCommunicate_70527_Content_15 = {
    Text = "¿De verdad?! ¡Gracias, Maestro!"
  },
  AvgCommunicate_70527_Content_2 = {
    Text = "Jenkin llevó a Lily a escalar la torre del reloj."
  },
  AvgCommunicate_70527_Content_3 = {
    Text = "Hermana Ramona trajo a Lily una gran cantidad de comida deliciosa..."
  },
  AvgCommunicate_70527_Content_4 = {
    Text = "Lily, ¿cómo te sientes ahora? ¿Te encuentras mejor?"
  },
  AvgCommunicate_70527_Content_5 = {
    Text = "...¡Está bien!"
  },
  AvgCommunicate_70527_Content_6 = {
    Text = "Lily soñó anoche, soñando con su madre..."
  },
  AvgCommunicate_70527_Content_7 = {
    Text = "Madre dice que me está observando."
  },
  AvgCommunicate_70527_Content_8 = {
    Text = "Verme feliz también hace feliz a Madre."
  },
  AvgCommunicate_70527_Content_9 = {
    Text = "Madre está sonriendo. Lily no ha visto a su madre sonreír así en mucho tiempo."
  },
  AvgCommunicate_70527_Option_10 = {
    Text = "Porque cumplió su deseo"
  },
  AvgCommunicate_70527_Option_14 = {
    Text = "¿Todavía quieres tomar el metro?"
  },
  AvgCommunicate_70527_Option_4 = {
    Text = "Lily, ¿cómo te sientes ahora?"
  },
  AvgCommunicate_70528_Content_1 = {
    Text = "Durante este tiempo desde el regreso, también he explorado algunas nuevas posibilidades."
  },
  AvgCommunicate_70528_Content_10 = {
    Text = "Sobrevive, Guardián... con Ramona, encuentra una manera de luchar contra la Disolución."
  },
  AvgCommunicate_70528_Content_11 = {
    Text = "Si hay algo que necesitas que haga, no dudes en decírmelo."
  },
  AvgCommunicate_70528_Content_12 = {
    Text = "No dejes que ese mundo se convierta como el mío."
  },
  AvgCommunicate_70528_Content_13 = {
    Text = "Esta es mi única esperanza, y solo tú puedes hacerlo realidad."
  },
  AvgCommunicate_70528_Content_2 = {
    Text = "Sin excepción, todas estas opciones son incorrectas."
  },
  AvgCommunicate_70528_Content_3 = {
    Text = "Estás en el único camino correcto, Guardián."
  },
  AvgCommunicate_70528_Content_4 = {
    Text = "Gracias por tu arduo trabajo, Ramona..."
  },
  AvgCommunicate_70528_Content_5 = {
    Text = "¿Está mejorando la situación de tu lado ahora?"
  },
  AvgCommunicate_70528_Content_6 = {
    Text = "Aún lo mismo... Todo está sumergido en Disolución, el único refugio que queda."
  },
  AvgCommunicate_70528_Content_7 = {
    Text = "El Maestro Alistair mantiene este lugar, y su condición tampoco es buena..."
