  AvgCommunicate_70528_Content_8 = {
    Text = "Ramona... ¿hay algo que pueda hacer por ti?"
  },
  AvgCommunicate_70528_Content_9 = {
    Text = "Está bien. Ya nos hemos acostumbrado a esto."
  },
  AvgCommunicate_70528_Option_4 = {
    Text = "Gracias por tu arduo trabajo, Ramona..."
  },
  AvgCommunicate_70528_Option_8 = {
    Text = "¿Hay algo que pueda hacer por ti?"
  },
  AvgCommunicate_70529_Content_1 = {
    Text = "Hola, Guardián {Male=Mr.,Female=Miss}."
  },
  AvgCommunicate_70529_Content_10 = {
    Text = "Por supuesto. Justo en este momento, la condición de un paciente empeoró repentinamente, y necesito atenderlo de inmediato."
  },
  AvgCommunicate_70529_Content_11 = {
    Text = "Gracias por traer a Lily de vuelta a casa. La sala de estar y los refrigerios han sido preparados para todos."
  },
  AvgCommunicate_70529_Content_12 = {
    Text = "Bienvenido a Rai, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgCommunicate_70529_Content_2 = {
    Text = "A través de la presentación de la señora Davendale, Missaga me proporcionó tus datos de contacto."
  },
  AvgCommunicate_70529_Content_3 = {
    Text = "¿Puedo preguntar, dónde están todos ustedes con Lily?"
  },
  AvgCommunicate_70529_Content_4 = {
    Text = "Hemos llegado al Puente de Acero Fowler y pronto alcanzaremos el sanatorio."
  },
  AvgCommunicate_70529_Content_5 = {
    Text = "¿Causó Lily algún problema para todos en este viaje?"
  },
  AvgCommunicate_70529_Content_6 = {
    Text = "Por favor, no te preocupes; Lily ha sido muy obediente todo este tiempo."
  },
  AvgCommunicate_70529_Content_7 = {
    Text = "Sra. Francis, respecto al sanatorio, me gustaría..."
  },
  AvgCommunicate_70529_Content_8 = {
    Text = "Lo siento, Guardián. La condición de un paciente ha empeorado repentinamente y debo atenderlo de inmediato."
  },
  AvgCommunicate_70529_Content_9 = {
    Text = "Entonces, ¿nos reunimos en el sanatorio?"
  },
  AvgCommunicate_70529_Option_4 = {
    Text = "Casi está aquí."
  },
  AvgCommunicate_70529_Option_6 = {
    Text = "Lily es muy obediente."
  },
  AvgCommunicate_70529_Option_7 = {
    Text = "Pregunta a Francis sobre las anomalías en el sanatorio"
  },
  AvgCommunicate_70529_Option_9 = {
    Text = "Resiste por ahora, para no elevar su alerta."
  },
  AvgCommunicate_70530_Content_1 = {
    Text = "Mi preciada Semilla fue rechazada... Es verdaderamente triste, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgCommunicate_70530_Content_10 = {
    Text = "Cuanto más precioso es algo, más debe ser recibido con una ceremonia solemne."
  },
  AvgCommunicate_70530_Content_11 = {
    Text = "Esta semilla más preciosa, tarde o temprano, te pertenecerá."
  },
  AvgCommunicate_70530_Content_12 = {
    Text = "No te preocupes, Guardián. Ese día no te hará esperar mucho."
  },
  AvgCommunicate_70530_Content_2 = {
    Text = "Thais, eso no es lo que quise decir..."
  },
  AvgCommunicate_70530_Content_3 = {
    Text = "Oh? ¿Qué significa el Guardián, entonces?"
  },
  AvgCommunicate_70530_Content_4 = {Text = "Yo..."},
  AvgCommunicate_70530_Content_5 = {
    Text = "Lo siento, pero la situación en aquel entonces fue demasiado apresurada. No tuve tiempo de pensar..."
  },
  AvgCommunicate_70530_Content_6 = {
    Text = "Entonces, ¿y si la situación no es urgente?"
  },
  AvgCommunicate_70530_Content_7 = {Text = "Yo..."},
  AvgCommunicate_70530_Content_8 = {
    Text = "Está bien, está bien, no te haré más bromas."
  },
  AvgCommunicate_70530_Content_9 = {
    Text = "Entiendo, Guardián."
  },
  AvgCommunicate_70530_Option_2 = {
    Text = "Thais, eso no es lo que quise decir..."
  },
  AvgCommunicate_70530_Option_5 = {
    Text = "Lo siento, pero la situación en aquel entonces fue demasiado apresurada..."
  },
  AvgCommunicate_70531_Content_1 = {
    Text = "Guardián, ¿puedo preguntar"
  },
  AvgCommunicate_70531_Content_10 = {
    Text = "Bienvenido a Mythag."
  },
  AvgCommunicate_70531_Content_11 = {
    Text = "...Hannah llegó a verme hace un momento."
  },
  AvgCommunicate_70531_Content_12 = {
    Text = "La creación del Despertar de Jenkin se completó con éxito."
  },
  AvgCommunicate_70531_Content_13 = {Text = "¡!!!"},
  AvgCommunicate_70531_Content_14 = {
    Text = "Vayamos a conocer a nuestro pequeño héroe."
  },
  AvgCommunicate_70531_Content_2 = {
    Text = "¿Cómo va el despertar de Jenkin?"
  },
  AvgCommunicate_70531_Content_3 = {
    Text = "La biblioteca de materiales de la escuela ha preparado los objetos necesarios para su Cuerpo, y el proceso de creación del Despertador está actualmente en curso."
  },
  AvgCommunicate_70531_Content_4 = {
    Text = "¡Pronto podremos verla nuevamente!"
  },
  AvgCommunicate_70531_Content_5 = {
    Text = "¡Excelente! ¡Excelente..."
  },
  AvgCommunicate_70531_Content_6 = {
    Text = "Gracias, Guardián. Gracias a todos..."
  },
  AvgCommunicate_70531_Content_7 = {
    Text = "Tú y Jenkin nos salvaron."
  },
  AvgCommunicate_70531_Content_8 = {
    Text = "Ella murió para salvar a Mitag; esto es lo que debemos hacer."
  },
  AvgCommunicate_70531_Content_9 = {
    Text = "El comité escolar ha discutido y aprobado, por lo que ustedes dos no necesitan preocuparse más por quedarse atrás."
  },
  AvgCommunicate_70531_Option_11 = {
    Text = "Recibí un mensaje..."
  },
  AvgCommunicate_70531_Option_3 = {Text = "Casi allí"},
  AvgCommunicate_70531_Option_7 = {
    Text = "Deberíamos agradecerte, así como a Jenkin."
  },
  AvgCommunicate_70532_Content_1 = {
    Text = "¡Guardián!"
  },
  AvgCommunicate_70532_Content_2 = {
    Text = "¿Cuándo volveremos a filmar!"
  },
  AvgCommunicate_70532_Content_3 = {
    Text = "¿Qué, te has vuelto adicto a los aplausos?"
  },
  AvgCommunicate_70532_Content_4 = {
    Text = "No es que esté adicto; ¡es que esta ciudad nos necesita!"
  },
  AvgCommunicate_70532_Content_5 = {
    Text = "¡Esta ciudad está llena de los más hambrientos, necesitados de los Exploradores Nocturnos y sus asistentes!"
  },
  AvgCommunicate_70532_Content_6 = {
    Text = "Le preguntaré a Muñeca si puedo pedir prestada la cámara de nuevo."
  },
  AvgCommunicate_70532_Content_7 = {
    Text = "Por cierto, ¿has estado asistiendo a las clases de alfabetización adecuadamente? ¡Cuántos errores has hecho!"
  },
  AvgCommunicate_70532_Content_8 = {
    Text = "¡Ocúpate de tus propios asuntos, chico de Westside!"
  },
  AvgCommunicate_70532_Content_9 = {
    Text = "¡Esta ciudad nos necesita; los Errantes Nocturnos y su asistente están extremadamente ocupados!"
  },
  AvgCommunicate_70532_Option_3 = {
    Text = "¿Adicto a tomar fotos?"
  },
  AvgCommunicate_70532_Option_6 = {
    Text = "Déjame ir a preguntar a la Muñeca..."
  },
  AvgCommunicate_70533_Content_1 = {
    Text = "Guardián, ¡Guardián!"
  },
  AvgCommunicate_70533_Content_10 = {
    Text = "Pero ¿por qué Aurita no los recuerda?"
  },
  AvgCommunicate_70533_Content_11 = {
    Text = "Cachorro, Pony, Pequeña Medusa... Todos fueron una vez amigos de Aurita."
  },
  AvgCommunicate_70533_Content_12 = {
    Text = "Más tarde, necesitan ir a un lugar distante."
  },
  AvgCommunicate_70533_Content_13 = {
    Text = "Tenían miedo de causar dolor a Aurita, así que borraron los recuerdos de Aurita sobre ellos."
  },
  AvgCommunicate_70533_Content_14 = {
    Text = "Pero aún deseaban quedarse al lado de Aurita, así que dejaron sus cuerpos atrás."
  },
  AvgCommunicate_70533_Content_15 = {
    Text = "Estos cuerpos se han convertido en pequeñas muñecas de barro y fueron dejados en el Palacio de Agua de Aurita."
  },
  AvgCommunicate_70533_Content_16 = {
    Text = "...Siempre han cuidado y acompañado a Aurita, y esto nunca ha cambiado."
  },
  AvgCommunicate_70533_Content_17 = {
    Text = "Parece que lo entiendo, sin embargo también siento que no lo entiendo..."
  },
  AvgCommunicate_70533_Content_18 = {
    Text = "Pero ¡Aurita lo sabe! Los que están en el Palacio de Agua son todos buenos amigos de Aurita."
  },
  AvgCommunicate_70533_Content_19 = {
    Text = "¡Aurita cuidará bien de ellos y jugará con ellos todos los días!"
  },
  AvgCommunicate_70533_Content_2 = {
    Text = "¿Sabes qué hay dentro del Palacio de Agua de Aurita?"
  },
  AvgCommunicate_70533_Content_3 = {
    Text = "¿Qué piensa Aurita que son esos?"
  },
  AvgCommunicate_70533_Content_4 = {
    Text = "Hmm... Aurita parece no poder recordar..."
  },
  AvgCommunicate_70533_Content_5 = {
    Text = "Se siente familiar, como... como..."
  },
  AvgCommunicate_70533_Content_6 = {Text = "Amigo..."},
  AvgCommunicate_70533_Content_7 = {
    Text = "Aurita ama a sus amigos más que a nada, pero ¿por qué Aurita no los recuerda?"
  },
  AvgCommunicate_70533_Content_8 = {
    Text = "Esos son todos amigos de Aurita."
  },
  AvgCommunicate_70533_Content_9 = {
    Text = "¿Amigo? ¡Aurita ama a los amigos más!"
  },
  AvgCommunicate_70533_Option_11 = {
    Text = "Dile a Aurita su historia"
  },
  AvgCommunicate_70533_Option_3 = {
    Text = "¿Qué piensa Aurita?"
  },
  AvgCommunicate_70533_Option_8 = {
    Text = "Esos son todos los amigos de Aurita."
  },
  AvgCommunicate_72037_Content_1 = {
    Text = "Ayer soñé con mi infancia, soñé con muchas personas del pasado de Limoria."
  },
  AvgCommunicate_72037_Content_10 = {
    Text = "Nada escapa a tu atención."
  },
  AvgCommunicate_72037_Content_11 = {
    Text = "Lo que persiste en el sueño es una sensación particularmente cercana y familiar, y al principio pensé que era algo traído por Noa."
  },
  AvgCommunicate_72037_Content_12 = {
    Text = "Más tarde descubrí que, tras largos años, lo más familiar para mí ya no era ninguna persona, sino un objeto frío y sin vida."
  },
  AvgCommunicate_72037_Content_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Content_14 = {
    Text = "Guarda tu compasión. Desde el momento en que me puse la corona, ya me había preparado para todo."
  },
  AvgCommunicate_72037_Content_15 = {
    Text = "El Rey de Lemuria no necesita que nadie llore por él."
  },
  AvgCommunicate_72037_Content_16 = {
    Text = "Entonces... Rey de Lemuria, ¿estás interesado en probar ese dulce de arroz nuevamente? Creo que el chef de Mythag debería poder recrearlo hasta cierto punto."
  },
  AvgCommunicate_72037_Content_17 = {Text = "..."},
  AvgCommunicate_72037_Content_18 = {
    Text = "Hmm, eres bastante considerado."
  },
  AvgCommunicate_72037_Content_19 = {
    Text = "Bueno, considérelo su tributo."
  },
  AvgCommunicate_72037_Content_2 = {
    Text = "Esos son los recuerdos de los que nunca me gustó hablar, pero, en el sueño de ayer, eras tú, ¿verdad?"
  },
  AvgCommunicate_72037_Content_3 = {
    Text = "¿Cómo lo supiste?"
  },
  AvgCommunicate_72037_Content_4 = {
    Text = "El tiempo que pasé en el Sueño supera con creces el del mundo ordinario; ¿estás cuestionando la percepción de alguien que vive en un sueño?"
  },
  AvgCommunicate_72037_Content_5 = {
    Text = "Además de profecías, a veces tengo sueños como las personas comunes, pero ninguno de esos sueños es tan vívido y continuo como el sueño de ayer..."
  },
  AvgCommunicate_72037_Content_6 = {
    Text = "Como si alguien estuviera sentado junto a Yu, reviviendo punto por punto todo lo ocurrido en el pasado."
  },
  AvgCommunicate_72037_Content_7 = {
    Text = "Este sentimiento de no estar solo... es bastante agradable."
  },
  AvgCommunicate_72037_Content_8 = {
    Text = "Siempre he estado a tu lado."
  },
  AvgCommunicate_72037_Content_9 = {
    Text = "Déjame adivinar, debes estar poseyendo la corona, ¿verdad?"
  },
  AvgCommunicate_72037_Option_10 = {Text = "Sí"},
  AvgCommunicate_72037_Option_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Option_16 = {
    Text = "Entonces... ¿por qué tú..."
  },
  AvgCommunicate_72037_Option_3 = {Text = "?!"},
  AvgCommunicate_72037_Option_8 = {
    Text = "Siempre he estado a tu lado."
  },
  AvgCommunicate_80100_Content_1 = {
    Text = "%player%, si no es molestia, ¿podrías venir a hacer un test psicológico?"
  },
  AvgCommunicate_80100_Content_10 = {
    Text = "Ramona, Lotan, Ogier... cuando estoy solo, sus figuras siempre flotan en mi mente."
  },
  AvgCommunicate_80100_Content_11 = {
    Text = "No hay necesidad de aguantar solo. Cualquier problema y confusión que tengas, puedes decírmelo."
  },
  AvgCommunicate_80100_Content_12 = {
    Text = "Incluso preparé té caliente y bocadillos para ti, así que podemos charlar despacio."
  },
  AvgCommunicate_80100_Content_13 = {
    Text = "...Voy sobre eso ahora."
  },
  AvgCommunicate_80100_Content_2 = {
    Text = "...¿Un test psicológico?"
  },
  AvgCommunicate_80100_Content_3 = {
    Text = "Es muy sencillo. Solo tienes que dibujar una casa, un árbol y una persona en una hoja en blanco."
  },
  AvgCommunicate_80100_Content_4 = {
    Text = "Confía en mí, no te llevará demasiado tiempo."
  },
  AvgCommunicate_80100_Content_5 = {
    Text = "...Pero creo que mi salud mental está perfectamente bien."
  },
  AvgCommunicate_80100_Content_6 = {
    Text = "El propósito final de la prueba no es juzgar la salud, sino observar problemas psicológicos potenciales."
  },
  AvgCommunicate_80100_Content_7 = {
    Text = "%player%, después de venir aquí, ¿sientes soledad? ¿Extrañas a los amigos de ese mundo?"
  },
  AvgCommunicate_80100_Content_8 = {
    Text = "Esa soledad y ese aislamiento se enterrarán en lo más profundo de tu corazón, fermentando con el tiempo y produciendo efectos desconocidos."
  },
  AvgCommunicate_80100_Content_9 = {
    Text = "Quizás tengas razón, los extraño"
  },
  AvgCommunicate_80100_Option_13 = {
    Text = "...Voy sobre eso ahora."
  },
  AvgCommunicate_80100_Option_2 = {
    Text = "...¿Un test psicológico?"
  },
  AvgCommunicate_80100_Option_5 = {
    Text = "...Pero creo que mi salud mental está perfectamente bien."
  },
  AvgCommunicate_80100_Option_9 = {Text = "..."},
  AvgCommunicate_80101_Content_1 = {
    Text = "He oído que te has estado sintiendo mal últimamente; si no te importa, puedes venir a mí para una consulta."
  },
  AvgCommunicate_80101_Content_10 = {
    Text = "¡Ah, solo describirlo así hace que mi corazón plateado tiemble sin parar..."
  },
  AvgCommunicate_80101_Content_11 = {
    Text = "%player%, no puedo esperar para hurgar en tu corazón y saborear tus recuerdos."
  },
  AvgCommunicate_80101_Content_12 = {
    Text = "Entonces quedarás decepcionado. Ya me he ido."
  },
  AvgCommunicate_80101_Content_13 = {
    Text = "Lo sé. Uno de mis pacientes me ha enviado un mensaje para informarme sobre este asunto."
  },
  AvgCommunicate_80101_Content_14 = {
    Text = "Incluso adjuntó cuidadosamente tu ubicación actual, así que..."
  },
  AvgCommunicate_80101_Content_15 = {
    Text = "Estaré allí en breve."
  },
  AvgCommunicate_80101_Content_2 = {
    Text = "No hay necesidad de presumir, Guardián. Las sugerencias de profesionales pueden ayudarte a ajustar tu estrés más rápido."
  },
  AvgCommunicate_80101_Content_3 = {
    Text = "¿Cómo podrías saber estas...?"
  },
  AvgCommunicate_80101_Content_4 = {Text = "Secreto~"},
  AvgCommunicate_80101_Content_5 = {
    Text = "Entonces, ¿cuál es tu respuesta?"
  },
  AvgCommunicate_80101_Content_6 = {
    Text = "Prometo que esta vez no haré ninguna otra orientación."
  },
  AvgCommunicate_80101_Content_7 = {
    Text = "Dijiste lo mismo la última vez y la vez anterior a esa..."
  },
  AvgCommunicate_80101_Content_8 = {
    Text = "Eso no es culpa mía, sino que tu conciencia está llena de recuerdos agradables."
  },
  AvgCommunicate_80101_Content_9 = {
    Text = "Esos recuerdos superan con creces el dolor que una persona normal puede soportar y llevan el aura de esa gran existencia, que es la dulzura más suprema."
  },
  AvgCommunicate_80101_Option_12 = {
    Text = "...Entonces te decepcionarás"
  },
  AvgCommunicate_80101_Option_3 = {
    Text = "¿Cómo podrías saber estas...?"
  },
  AvgCommunicate_80101_Option_7 = {
    Text = "Dijiste lo mismo la última vez y la vez anterior a esa..."
  },
  AvgCommunicate_80102_Content_1 = {
    Text = "%player%, ¿Te importaría que yo me encargara de tu terapia psicológica?"
  },
  AvgCommunicate_80102_Content_10 = {
    Text = "Pero no tomaré medidas excesivas. Confía en mí."
  },
  AvgCommunicate_80102_Content_11 = {
    Text = "......¿De verdad?"
  },
  AvgCommunicate_80102_Content_12 = {
    Text = "Claro. Después de todo, solo soy un psicólogo."
  },
  AvgCommunicate_80102_Content_2 = {
    Text = "Creo que necesitas un psicólogo especializado."
  },
  AvgCommunicate_80102_Content_3 = {
    Text = "......No creo que sea necesario."
  },
  AvgCommunicate_80102_Content_4 = {
    Text = "No, como el único Guardián del Secreto, tu existencia en sí misma merece atención."
  },
  AvgCommunicate_80102_Content_5 = {
    Text = "Solo quiero utilizar mi habilidad profesional para ayudarte."
  },
  AvgCommunicate_80102_Content_6 = {
    Text = "¿Así es de verdad? ¿Por qué siento que tienes otro propósito...?"
  },
  AvgCommunicate_80102_Content_7 = {
    Text = "Por ejemplo, aprovechándote de tu rol como psicólogo personal, espias mis recuerdos."
  },
  AvgCommunicate_80102_Content_8 = {
    Text = "¡Ay, me descubrieron? Entonces no hay remedio."
  },
  AvgCommunicate_80102_Content_9 = {
    Text = "De hecho, me interesa muchísimo tu memoria. Especialmente después de que mencionaste cosas sobre ese mundo."
  },
  AvgCommunicate_80102_Option_11 = {
    Text = "......¿De verdad?"
  },
  AvgCommunicate_80102_Option_3 = {
    Text = "......No creo que sea necesario."
  },
  AvgCommunicate_80102_Option_6 = {
    Text = "......¿Así es de verdad?"
  },
  AvgCommunicate_80104_Content_1 = {
    Text = "Gracias por enviarme ese informe."
  },
  AvgCommunicate_80104_Content_10 = {
    Text = "Y para poder regresar a ese mundo, solo con mi fuerza y la de Fusión·muñeca, claramente no será suficiente."
  },
  AvgCommunicate_80104_Content_11 = {
    Text = "¿Necesitas mi poder...? Entiendo."
  },
  AvgCommunicate_80104_Content_12 = {
    Text = "Acepté este regalo. Y el regalo de regreso es una consulta psicológica gratuita."
  },
  AvgCommunicate_80104_Content_13 = {
    Text = "%player%, ¿cuándo tienes tiempo libre?"
  },
  AvgCommunicate_80104_Content_14 = {
    Text = "Ya sea como Doctor o amigo, tengo el deber de comprender profundamente tu yo interior."
  },
  AvgCommunicate_80104_Content_15 = {
    Text = "Estoy de servicio en el campo... la señal es mala... continuaré más tarde..."
  },
  AvgCommunicate_80104_Content_16 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_17 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_18 = {
    Text = "Heh, sé que todavía estás aquí. Pero está bien, aún tenemos mucho tiempo."
  },
  AvgCommunicate_80104_Content_2 = {
    Text = "Esa es un informe copiado a mano y redactado sobre la especie de insecto, sin problemas de filtración, siéntete libre de conservarlo."
  },
  AvgCommunicate_80104_Content_3 = {
    Text = "¿Es esta la \"recompensa\" pagada por adelantado?"
  },
  AvgCommunicate_80104_Content_4 = {
    Text = "Pero lo siento, no tengo información interna del Comité para compartir recientemente."
  },
  AvgCommunicate_80104_Content_5 = {
    Text = "Esto no es una recompensa, sino un regalo."
  },
  AvgCommunicate_80104_Content_6 = {
    Text = "Felicidades por tu renacimiento, y gracias por elegirme."
  },
  AvgCommunicate_80104_Content_7 = {
    Text = "¿Porque no me estoy opuesto a ti como \"ella\" de ese mundo?"
  },
  AvgCommunicate_80104_Content_8 = {
    Text = "Puedes pensarlo de esa manera"
  },
  AvgCommunicate_80104_Content_9 = {
    Text = "Como Guardián, siempre creo que yo y el Despertar somos amigos, no enemigos."
  },
  AvgCommunicate_80104_Option_15 = {
    Text = "...La señal es mala"
  },
  AvgCommunicate_80104_Option_2 = {
    Text = "Parece que has recibido el correo electrónico"
  },
  AvgCommunicate_80104_Option_5 = {
    Text = "No, esto es un Don..."
  },
  AvgCommunicate_80104_Option_8 = {
    Text = "Puedes pensarlo de esa manera"
  },
  AvgCommunicate_81323_Content_1 = {
    Text = "Mi benefactor, ¿cuándo me entregarás el nuevo cuaderno de trabajo?"
  },
  AvgCommunicate_81323_Content_10 = {
    Text = "Entiendo, entonces, ¿tiene el benefactor otros maestros competentes en estos dos temas que pueda recomendar?"
  },
  AvgCommunicate_81323_Content_11 = {
    Text = "Si es absolutamente necesario, puedo leer algunos otros libros e intentar aprender un poco por mi cuenta."
  },
  AvgCommunicate_81323_Content_12 = {
    Text = "Hay... hay, pero su temperamento no es muy bueno."
  },
  AvgCommunicate_81323_Content_13 = {
    Text = "Está bien, no tengo miedo."
  },
  AvgCommunicate_81323_Content_14 = {
    Text = "¡Tengo miedo! Bueno, si voy a buscar a Bígaro... eh, probablemente se volvería loca primero."
  },
  AvgCommunicate_81323_Content_15 = {
    Text = "¿Loco? ¿Este Maestro Winkle tiene algún tipo de enfermedad?"
  },
  AvgCommunicate_81323_Content_16 = {
    Text = "No... no puedo decir que no hay, ah ah ah! En resumen, déjame primero enseñarte una verdad del aprendizaje"
  },
  AvgCommunicate_81323_Content_17 = {
    Text = "Está bien, benefactor, estoy todo oídos."
  },
  AvgCommunicate_81323_Content_18 = {
    Text = "Es decir, ¡no hagas preguntas sobre todo!!!"
  },
  AvgCommunicate_81323_Content_19 = {
    Text = "¿Por qué está sucediendo esto de nuevo? Benefactor, no entiendo del todo. Si no pregunto con claridad, ¿cómo puedo aprender a fondo...?"
  },
  AvgCommunicate_81323_Content_2 = {
    Text = "Y en cuanto a los últimos dos libros, los he leído detenidamente y he hecho un total de 107 notas de preguntas; espero que el benefactor pueda proporcionar algo de orientación en su tiempo libre."
  },
  AvgCommunicate_81323_Content_20 = {
    Text = "¡¿No estás cansado?! Con un espíritu tan diligente entrando en el mar del conocimiento, tendrás éxito en todo lo que hagas..."
  },
  AvgCommunicate_81323_Content_21 = {
    Text = "Gracias, benefactor. Tener la libertad de aprender lo que me interesa es realmente algo precioso y alegre."
  },
  AvgCommunicate_81323_Content_22 = {
    Text = "Está bien tomarse un descanso cuando se siente realmente somnoliento; ¿cómo podría uno estar cansado?"
  },
  AvgCommunicate_81323_Content_23 = {
    Text = "Así que, ¿cuándo podrá mi benefactor presentarme al nuevo maestro? Haré todo lo posible por no ser demasiado inquisitivo."
  },
  AvgCommunicate_81323_Content_24 = {
    Text = "Um... ¿qué tal si hago 97 preguntas?"
  },
  AvgCommunicate_81323_Content_3 = {
    Text = "Me equivoqué"
  },
  AvgCommunicate_81323_Content_4 = {
    Text = "Estuve realmente equivocado"
  },
  AvgCommunicate_81323_Content_6 = {
    Text = "No debería haber hecho tu tarea por ti; uno debería encargarse de sus propios asuntos..."
  },
  AvgCommunicate_81323_Content_7 = {
    Text = "Por favor, ¡deja de preguntarme! Si esto sigue así, ¡voy a tener pesadillas por la noche!"
  },
  AvgCommunicate_81323_Content_8 = {
    Text = "Ah... lo siento, no esperaba que mi intrusión causara tanto problema a mi benefactor; realmente soy demasiado torpe."
  },
  AvgCommunicate_81323_Content_9 = {
    Text = "No, en absoluto, tal vez simplemente no estoy hecho para ser profesor..."
  },
  AvgCommunicate_81323_Option_12 = {
    Text = "Hay... hay."
  },
  AvgCommunicate_81323_Option_14 = {
    Text = "¡Tengo miedo!"
  },
  AvgCommunicate_81323_Option_16 = {
    Text = "No... no puedo decir que no hay..."
  },
  AvgCommunicate_81323_Option_18 = {
    Text = "Es decir, ¡no hagas preguntas sobre todo!!!"
  },
  AvgCommunicate_81323_Option_20 = {
    Text = "¡¿No estás cansado?!"
  },
  AvgCommunicate_81323_Option_3 = {
    Text = "Me equivoqué"
  },
  AvgCommunicate_81323_Option_4 = {
    Text = "Estuve realmente equivocado"
  },
  AvgCommunicate_81323_Option_9 = {
    Text = "No, en absoluto, tal vez simplemente no estoy hecho para ser profesor..."
  },
  AvgCommunicate_81324_Content_1 = {
    Text = "Mi benefactor, tengo nuevas preguntas desde que he estado leyendo últimamente."
  },
  AvgCommunicate_81324_Content_10 = {
    Text = "¿Estás diciendo... que depende de los pensamientos mientras haces esto?"
  },
  AvgCommunicate_81324_Content_11 = {
    Text = "Así es, piénsalo, cuando te pedí que escribieras esas dos tareas, ¿quería explotarte para trabajo gratuito o esperaba que obtuvieras una oportunidad de aprendizaje?"
  },
  AvgCommunicate_81324_Content_12 = {Text = "No sé."},
  AvgCommunicate_81324_Content_13 = {
    Text = "¿Cómo podría ser esto desconocido? ¡Por supuesto, es para ayudarte a aprender mejor!"
  },
  AvgCommunicate_81324_Content_14 = {
    Text = "Así que así es. Me malinterpreté; pensé que el benefactor solo quería que te ayudara con tu tarea."
  },
  AvgCommunicate_81324_Content_16 = {
    Text = "Cof, cof... Bueno, pensemos de nuevo. Cuando realizamos una acción con una persona como objetivo final, considerando sinceramente al otro, eso puede llamarse moral."
  },
  AvgCommunicate_81324_Content_17 = {
    Text = "Si tratas a los humanos como herramientas puras, eso es ciertamente inmoral."
  },
  AvgCommunicate_81324_Content_18 = {
    Text = "Creo que entiendo, es como usar una linterna para tratarme a mí y a Polyx como herramientas para el sacrificio, sin considerar genuinamente nuestros sentimientos. Eso es inmoral."
  },
  AvgCommunicate_81324_Content_19 = {
    Text = "¡Así es, así es, tu percepción es grandiosa!"
  },
  AvgCommunicate_81324_Content_2 = {
    Text = "Dijiste antes que las tareas están destinadas a probar y refinar tu conocimiento, siempre que el conocimiento esté dominado, no es necesario estar atado por si la tarea está completa."
  },
  AvgCommunicate_81324_Content_20 = {
    Text = "Entiendo, benefactor, ¡tú eres verdaderamente una persona moral! Entonces, por favor, benefactor, dame algunas tareas más, las completaré con cuidado y volveré a consultar"
  },
  AvgCommunicate_81324_Content_21 = {
    Text = "¿Benefactor?"
  },
  AvgCommunicate_81324_Content_22 = {
    Text = "Eso, de repente tengo algo que atender. ¡Deberías ir directamente a la Muñeca sobre la tarea!"
  },
  AvgCommunicate_81324_Content_3 = {
    Text = "Um... parece que he dicho algo así antes."
  },
  AvgCommunicate_81324_Content_4 = {
    Text = "Pero los libros recientes que he leído mencionan que hacer que otros hagan el trabajo por ti parece ser un acto poco ético."
  },
  AvgCommunicate_81324_Content_6 = {
    Text = "Entonces, ¿cómo juzgas si este asunto es moral?"
  },
  AvgCommunicate_81324_Content_7 = {
    Text = "Uh... sobre este asunto, deberías verlo dialécticamente."
  },
  AvgCommunicate_81324_Content_8 = {
    Text = "No podemos decir con certeza que sí o que no."
  },
  AvgCommunicate_81324_Content_9 = {
    Text = "Al juzgar algo, no puedes solo observar el resultado, sino también considerar el propósito detrás de la acción."
  },
  AvgCommunicate_81324_Option_11 = {
    Text = "¡Sí, claro!"
  },
  AvgCommunicate_81324_Option_13 = {
    Text = "¿Cómo podría ser esto desconocido?"
  },
  AvgCommunicate_81324_Option_19 = {
    Text = "¡Así es, así es, tu percepción es grandiosa!"
  },
  AvgCommunicate_81324_Option_22 = {
    Text = "Eso, de repente tengo algo que atender..."
  },
  AvgCommunicate_81324_Option_3 = {
    Text = "Um... parece que he dicho algo así antes."
  },
  AvgCommunicate_81324_Option_7 = {
    Text = "Uh... sobre este asunto, deberías verlo dialécticamente."
  },
  AvgCommunicate_81324_Option_8 = {
    Text = "No podemos decir con certeza que sí o que no."
  },
  AvgCommunicate_81325_Content_1 = {
    Text = "Qué caja mágica, benefactor, ¿realmente no está alimentada por algún tipo de magia o ritual?"
  },
  AvgCommunicate_81325_Content_10 = {
    Text = "No es el caso, es solo que estos dos temas también están desarrollándose actualmente, y muchos académicos ampliarán y profundizarán estos estudios, creando nuevos conocimientos."
  },
  AvgCommunicate_81325_Content_11 = {
    Text = "Si tomas esta floreciente disciplina como tu objetivo de aprendizaje, por supuesto, deberías aprender hasta que envejezcas."
  },
  AvgCommunicate_81325_Content_12 = {
    Text = "Así que eso es, conocimiento que continúa desarrollándose... verdaderamente magnífico."
  },
  AvgCommunicate_81325_Content_13 = {
    Text = "Cuando estudiamos las escrituras de la linterna, no podemos cambiar una sola palabra; todo el contenido está asegurado, repetido y permanece sin cambios."
  },
  AvgCommunicate_81325_Content_14 = {
    Text = "Pero cada vez que estudio las escrituras, siento una sensación de estar en una caja, mirando el final de un vistazo."
  },
  AvgCommunicate_81325_Content_15 = {
    Text = "De hecho, ¡solo el conocimiento que crece constantemente corresponde a la verdadera esencia de la vida!"
  },
  AvgCommunicate_81325_Content_16 = {
    Text = "De repente siento la trascendencia..."
  },
  AvgCommunicate_81325_Content_17 = {
    Text = "Hablando de eso, tengo una excelente oportunidad de aprendizaje que puedo regalarte generosamente de forma gratuita."
  },
  AvgCommunicate_81325_Content_18 = {
    Text = "¡Realmente, benefactor! Mi gratitud está más allá de las palabras."
  },
  AvgCommunicate_81325_Content_19 = {
    Text = "Por supuesto que es cierto, este ejercicio de tecnología plateada y práctica de principios de mantenimiento, junto con este manual obligatorio para estrategias de psicología de investigadores, ¿cuál te gustaría escribir primero..."
  },
  AvgCommunicate_81325_Content_2 = {
    Text = "No, esto es pura Tecnología de ficha de plata, y solo para recordarte, el comunicador es caro, así que te sugiero que no lo desarmes descuidadamente."
  },
  AvgCommunicate_81325_Content_20 = {
    Text = "Ah no, ¿cuál debería aprender primero?"
  },
  AvgCommunicate_81325_Content_3 = {
    Text = "Ah, qué pena... ¿cómo supo el benefactor que estaba a punto de desmantelarlo? ¿Es esto lectura mental?"
  },
  AvgCommunicate_81325_Content_4 = {
    Text = "No realmente... ¡supongo que tus pensamientos ni siquiera se aplican a la psicología!"
  },
  AvgCommunicate_81325_Content_5 = {
    Text = "La psicología debe ser otro conocimiento profundo; lamentablemente, mi comprensión es en verdad estéril..."
  },
  AvgCommunicate_81325_Content_6 = {
    Text = "Mi benefactor, ¿cuánto tiempo lleva aprender esta tecnología y psicología de chip plateado?"
  },
  AvgCommunicate_81325_Content_7 = {
    Text = "¿Aprender? Hmm..."
  },
  AvgCommunicate_81325_Content_8 = {
    Text = "Se necesitan de cuatro a cinco años para poder acceder, y aprenderlo puede llevar toda una vida de estudio."
  },
  AvgCommunicate_81325_Content_9 = {
    Text = "¡Una vida! ¿Podría realmente haber miles de estos volúmenes de Conocimiento?"
  },
  AvgCommunicate_81325_Option_10 = {
    Text = "Eso no es así..."
  },
  AvgCommunicate_81325_Option_16 = {
    Text = "De repente siento la trascendencia..."
  },
  AvgCommunicate_81325_Option_19 = {
    Text = "Por supuesto que es cierto."
  },
  AvgCommunicate_81325_Option_2 = {Text = "No"},
  AvgCommunicate_81325_Option_4 = {
    Text = "No realmente..."
  },
  AvgCommunicate_81325_Option_7 = {
    Text = "¿Aprender? Hmm..."
  },
  AvgCommunicate_84107_Content_1 = {
    Text = "¿Cuándo terminan las vacaciones?"
  },
  AvgCommunicate_84107_Content_10 = {
    Text = "Al considerar todos estos factores y sopesar cuidadosamente sus ventajas y desventajas, se podrá planificar la ruta más eficiente y razonable."
  },
  AvgCommunicate_84107_Content_11 = {
    Text = "......Entendido. Al parecer, cada trabajo tiene su significado."
  },
  AvgCommunicate_84107_Content_12 = {
    Text = "Sí, ya que he tomado una decisión, debo asumir mis responsabilidades."
  },
  AvgCommunicate_84107_Content_13 = {
    Text = "A partir de ahora, también realizaré rondas nocturnas todos los días para asegurarme de que no haya incidentes en la academia durante las vacaciones."
  },
  AvgCommunicate_84107_Content_14 = {
    Text = "Guardián del Secreto, por ahora hablemos hasta aquí. Tengo que ir a trabajar."
  },
  AvgCommunicate_84107_Content_2 = {
    Text = "...¿las vacaciones no acaban de comenzar?"
  },
  AvgCommunicate_84107_Content_4 = {
    Text = "Solo estoy haciendo preparativos para después."
  },
  AvgCommunicate_84107_Content_5 = {
    Text = "El mapa de la academia se ha actualizado, el reloj ha sido calibrado y las banderas junto con sus mástiles también han sido limpiados."
  },
  AvgCommunicate_84107_Content_6 = {
    Text = "En los días posteriores, continuaré con el mantenimiento para garantizar que esté listo para comenzar en cualquier momento."
  },
  AvgCommunicate_84107_Content_7 = {
    Text = "...Solo se trata del tráfico durante la hora del almuerzo en la Academia de Dirección, ¿es necesario hacer tantos preparativos?"
  },
  AvgCommunicate_84107_Content_8 = {
    Text = "Por supuesto. Cuál cafetería es la más popular, en qué facultad hay más estudiantes y qué estudiantes quieren prioridad para ir a la cafetería, todo esto afectará la planificación de la ruta completa."
  },
  AvgCommunicate_84107_Content_9 = {
    Text = "¿Qué macizo de flores ha sido convertido en hogar por los nuevos gatos callejeros, qué área ha sido pisoteada por los estudiantes creando un nuevo camino, y qué carretera necesita mantenimiento...?"
  },
  AvgCommunicate_84107_Option_11 = {
    Text = "......Entiendo."
  },
  AvgCommunicate_84107_Option_2 = {
    Text = "...¿las vacaciones no acaban de comenzar?"
  },
  AvgCommunicate_84107_Option_7 = {
    Text = "Solo se trata del tráfico durante la hora del almuerzo en la Academia de Dirección..."
  },
  AvgCommunicate_84108_Content_1 = {
    Text = "Guardián, lamento profundamente lo que ocurrió la última vez."
  },
  AvgCommunicate_84108_Content_10 = {
    Text = "Pero como no estamos en el mar, he hecho algunos ajustes según las circunstancias."
  },
  AvgCommunicate_84108_Content_11 = {
    Text = "Esos ajustes no serán... esposarte a mí, ¿verdad..."
  },
  AvgCommunicate_84108_Content_12 = {
    Text = "Sí. De esta manera, si algo sale mal conmigo, podrás detectarlo e intervenir de inmediato."
  },
  AvgCommunicate_84108_Content_13 = {
    Text = "...¿Puedo negarme?"
  },
  AvgCommunicate_84108_Content_14 = {
    Text = "Por supuesto, puedes rechazar."
  },
  AvgCommunicate_84108_Content_15 = {
    Text = "Pero ya estoy frente a tu puerta."
  },
  AvgCommunicate_84108_Content_2 = {
    Text = "...¿Te refieres a cuando tu insomnio hizo que el Fuego de San Telmo se descontrolara?"
  },
  AvgCommunicate_84108_Content_3 = {
    Text = "Aunque Fusión·Dól me dejó inconsciente a tiempo, sigo sintiendo remordimientos."
  },
  AvgCommunicate_84108_Content_4 = {
    Text = "He pensado en ello durante mucho tiempo y he llegado a la conclusión de que merezco ser castigado."
  },
  AvgCommunicate_84108_Content_5 = {
    Text = "Eso realmente no es necesario. El último incidente no causó ninguna consecuencia grave."
  },
  AvgCommunicate_84108_Content_6 = {
    Text = "No, los errores deben ser castigados. Esas son las reglas."
  },
  AvgCommunicate_84108_Content_7 = {
    Text = "Ya me he puesto un extremo de las esposas. El otro extremo requiere tu cooperación."
  },
  AvgCommunicate_84108_Content_8 = {
    Text = "¿Mi cooperación?"
  },
  AvgCommunicate_84108_Content_9 = {
    Text = "Normalmente, quienes cometen errores en un barco son encadenados por los tobillos y dejados al sol en la cubierta durante varias horas."
  },
  AvgCommunicate_84108_Option_11 = {
    Text = "Esos ajustes no serán..."
  },
  AvgCommunicate_84108_Option_13 = {
    Text = "...¿Puedo negarme?"
  },
  AvgCommunicate_84108_Option_2 = {
    Text = "¿Te refieres a que..."
  },
  AvgCommunicate_84108_Option_5 = {
    Text = "De verdad que no es necesario."
  },
  AvgCommunicate_84108_Option_8 = {
    Text = "¿Mi cooperación?"
  },
  AvgCommunicate_84109_Content_1 = {
    Text = "Guardián, gracias."
  },
  AvgCommunicate_84109_Content_10 = {Text = "..."},
  AvgCommunicate_84109_Content_11 = {
    Text = "En realidad..."
  },
  AvgCommunicate_84109_Content_12 = {
    Text = "¿En realidad? ¿Por qué estás tartamudeando de repente al hablar, no es propio de ti?"
  },
  AvgCommunicate_84109_Content_13 = {
    Text = "En realidad, no necesitas visitar el museo marítimo; solo \"relajarte\" un poco debería estar bien."
  },
  AvgCommunicate_84109_Content_14 = {
    Text = "Aunque no comprendo lo que quieres decir con \"relajación\" normal, me siento tranquilo cuando estoy contigo."
  },
  AvgCommunicate_84109_Content_15 = {
    Text = "Se siente como si estuviera en un mar en calma, sin tormentas, y sin encontrar tormentas, simplemente siguiendo el rumbo, podemos alcanzar nuestro destino de manera segura."
  },
  AvgCommunicate_84109_Content_16 = {
    Text = "......Aunque esta metáfora es difícil de entender, entiendo aproximadamente lo que quieres decir."
  },
  AvgCommunicate_84109_Content_17 = {
    Text = "En el futuro, podremos explorar diferentes lugares. Este mundo es vasto, más allá de los océanos, hay muchos paisajes hermosos."
  },
  AvgCommunicate_84109_Content_18 = {
    Text = "......Entiendo. Haré un esfuerzo."
  },
  AvgCommunicate_84109_Content_19 = {
    Text = "Mira... el hermoso paisaje que es diferente del océano."
  },
  AvgCommunicate_84109_Content_2 = {
    Text = "¿Por qué expresar gratitud de repente?"
  },
  AvgCommunicate_84109_Content_3 = {
    Text = "En este viaje al Museo Marítimo de Londres, aprendí mucho."
  },
  AvgCommunicate_84109_Content_4 = {
    Text = "Los relojes marítimos exhibidos, los mapas náuticos dibujados a mano y los fragmentos de los diarios de navegación contribuyen a mejorar las habilidades de navegación."
  },
  AvgCommunicate_84109_Content_5 = {
    Text = "Pondré todo esto en uso en el próximo viaje, asegurando que todos regresen sanos y salvos al puerto."
  },
  AvgCommunicate_84109_Content_6 = {
    Text = "Recuerdo que el propósito de ir al Museo Marítimo de Londres aquel día era \"relajarme\"..."
  },
  AvgCommunicate_84109_Content_7 = {
    Text = "Olvídalo, mientras seas feliz."
  },
  AvgCommunicate_84109_Content_8 = {
    Text = "Sí, estoy muy feliz y espero salir a relajarnos juntos a menudo en el futuro."
  },
  AvgCommunicate_84109_Content_9 = {
    Text = "No hay problema, verificaré qué museos marítimos en Londres puedo visitar."
  },
  AvgCommunicate_84109_Option_12 = {
    Text = "¿En realidad?"
  },
  AvgCommunicate_84109_Option_16 = {
    Text = "......Qué metáfora tan compleja"
  },
  AvgCommunicate_84109_Option_2 = {
    Text = "¿Por qué expresar gratitud de repente?"
  },
  AvgCommunicate_84109_Option_6 = {Text = "......?"},
  AvgCommunicate_84109_Option_9 = {
    Text = "No hay problema"
  },
  AvgCommunicate_84110_Content_1 = {
    Text = "¿Podrías enviarme el próximo lote de suministros de cafeína por adelantado, Guardián?"
  },
  AvgCommunicate_84110_Content_10 = {
    Text = "Espera, ¡cómo podría volverse más absurdo!"
  },
  AvgCommunicate_84110_Content_11 = {
    Text = "¿Dónde está Winkle ahora?"
  },
  AvgCommunicate_84110_Content_12 = {
    Text = "Justo aquí, conduciendo experimentos en el dispositivo de conducción, probando si la energía de @2<AvgCommunicateConfuseColor.Light> se puede transformar en energía luminosa."
  },
  AvgCommunicate_84110_Content_13 = {
    Text = "¿Por qué no te niegas?"
  },
  AvgCommunicate_84110_Content_14 = {
    Text = "¿Por qué negarse? Servir a los pasajeros es uno de mis deberes."
  },
  AvgCommunicate_84110_Content_15 = {Text = "..."},
  AvgCommunicate_84110_Content_16 = {
    Text = "Voy ahora. Tú sostén el Bígaro por mí."
  },
  AvgCommunicate_84110_Content_17 = {
    Text = "Recibido, juré cumplir tu mandato."
  },
  AvgCommunicate_84110_Content_2 = {
    Text = "¿También te los llevó el Bígaro?"
  },
  AvgCommunicate_84110_Content_3 = {
    Text = "Para ser precisos, no fue \"tomado\", sino que se lo di a ese pasajero."
  },
  AvgCommunicate_84110_Content_4 = {
    Text = "......¿Otra vez con la razón de \"me uniré al viaje la próxima vez\"?"
  },
  AvgCommunicate_84110_Content_5 = {
    Text = "Solo estoy cumpliendo con mis deberes. Atender a los pasajeros también es una de mis responsabilidades."
  },
  AvgCommunicate_84110_Content_6 = {
    Text = "......La solicitud de suministros ha sido aprobada. Esta es la última vez."
  },
  AvgCommunicate_84110_Content_7 = {
    Text = "Por cierto, ¿Winkle aún intenta extraer el @2 de tu pecho recientemente?"
  },
  AvgCommunicate_84110_Content_8 = {
    Text = "Ya no; este pasajero ha cambiado la forma en que se realiza la investigación."
  },
  AvgCommunicate_84110_Content_9 = {
    Text = "Por ejemplo, probando la intensidad de @2<AvgCommunicateConfuseColor.Light> con un medidor de corriente de impacto, escaneando las líneas espectrales de @2<AvgCommunicateConfuseColor.Light> con un prisma, utilizando una plataforma de prueba humana para verificar la conexión de @2<AvgCommunicateConfuseColor.Light> con fibras nerviosas..."
  },
  AvgCommunicate_84110_Option_10 = {
    Text = "Espera, ¡cómo podría volverse más absurdo!"
  },
  AvgCommunicate_84110_Option_13 = {
    Text = "¿Por qué no te niegas?"
  },
  AvgCommunicate_84110_Option_15 = {Text = "..."},
  AvgCommunicate_84110_Option_2 = {
    Text = "¿También te los llevó el Bígaro?"
  },
  AvgCommunicate_84110_Option_4 = {
    Text = "De nuevo es porque..."
  },
  AvgCommunicate_84110_Option_6 = {
    Text = "La solicitud de suministro ha sido aprobada..."
  },
  AvgCommunicate_94500_Content_1 = {
    Text = "Gracias a tu presentación, después de conocer al Señor Ogier, él nos presentó a más amigos."
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "El Señor Ogier también mencionó que el entrenamiento de caballeros es aún más complejo y tedioso que esto, parece que, como se indica en los libros, cada caballero es de hecho una persona digna de respeto."
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "Ciertamente, ¡Ogier es el más diligente en el entrenamiento entre los Despertados!"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "También hemos descubierto que incluso con una discapacidad, la Instructora Alva está haciendo el mismo entrenamiento que nosotros."
  },
  AvgCommunicate_94500_Content_13 = {
    Text = "Originalmente pensábamos que la Instructora Alva también era una caballero, pero ella dijo que solía ser soldado. No sé qué tipo de profesión es un soldado, pero debe ser tan respetable como la de un caballero."
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "Los soldados son aquellos que luchan por el país, que también pueden considerarse una especie de caballero; sin embargo, en comparación con los estrictos códigos morales de los caballeros, las acciones de los soldados no necesariamente representan la justicia."
  },
  AvgCommunicate_94500_Content_15 = {
    Text = "Alva solo se dio cuenta de esto después de dejar el ejército; tal vez la vida ahora es más cómoda para ella."
  },
  AvgCommunicate_94500_Content_16 = {
    Text = "Entiendo, lo que quieres decir es que un caballero representa no poder, sino un espíritu de justicia, como el Instructor Alva y las personas justas como tú, todos poseen el alma de un caballero."
  },
  AvgCommunicate_94500_Content_18 = {
    Text = "Aunque hablaste muy bien, se siente bastante embarazoso..."
  },
  AvgCommunicate_94500_Content_2 = {
    Text = "Esa es una buena noticia; realmente me alegro por ti."
  },
  AvgCommunicate_94500_Content_3 = {
    Text = "Ya nos hemos encontrado con muchos Despertados y, tal como usted dijo, la mayoría son personas amables."
  },
  AvgCommunicate_94500_Content_4 = {
    Text = "Me siento avergonzado al recordar cuando llegué aquí por primera vez, a menudo tenía dudas sospechosas hacia los demás."
  },
  AvgCommunicate_94500_Content_5 = {
    Text = "De hecho, no está tan mal porque hay muchas personas que merecen precaución..."
  },
  AvgCommunicate_94500_Content_6 = {
    Text = "Ahora estoy con Castor, asistiendo al curso de entrenamiento del Instructor Alva junto al Lord Ogier"
  },
  AvgCommunicate_94500_Content_7 = {
    Text = "La postura de batalla del Señor Ogier es verdaderamente deslumbrante, pero él mismo parece no estar acostumbrado a los elogios, qué persona tan humilde."
  },
  AvgCommunicate_94500_Content_8 = {
    Text = "¡Ja ja, Ogier solo es fácil de evadir, solo háblale normalmente!"
  },
  AvgCommunicate_94500_Content_9 = {
    Text = "Resulta que Castor y yo nunca hemos recibido entrenamiento en combate en la iglesia; tal entreno es realmente duro, sin embargo, el Señor Ogier dice que lo hace todos los días; qué gran perseverancia."
  },
  AvgCommunicate_94500_Option_11 = {
    Text = "Ciertamente, Ogier es el más diligente en el entrenamiento entre los Despertados!"
  },
  AvgCommunicate_94500_Option_14 = {Text = "Supongo..."},
  AvgCommunicate_94500_Option_2 = {
    Text = "Esa es una buena noticia; realmente me alegro por ti."
  },
  AvgCommunicate_94500_Option_5 = {
    Text = "De hecho, no está tan mal porque hay muchas personas que merecen precaución..."
  },
  AvgCommunicate_94500_Option_8 = {
    Text = "Ogier es solo un poco tímido."
  },
  AvgCommunicate_94501_Content_1 = {
    Text = "Respetado señor, gracias por preparar un refugio para mí y Castor."
  },
  AvgCommunicate_94501_Content_10 = {
    Text = "A ese chico Castor le gustaba lavarse cinco veces al día, pero después de que lo detuve, se convirtió en tres veces al día."
  },
  AvgCommunicate_94501_Content_12 = {
    Text = "¡Lavar tu cara demasiadas veces causará daño!!"
  },
  AvgCommunicate_94501_Content_13 = {
    Text = "¿Ninguno de ustedes ha usado estas cosas antes? No imaginaba que la iglesia de la luz del templo fuera tan avara."
  },
  AvgCommunicate_94501_Content_14 = {
    Text = "De hecho no, pero no porque la iglesia sea tacaña, sino porque como el Hijo, siempre se nos ha exigido contener deseos y enfocarnos en la práctica."
  },
  AvgCommunicate_94501_Content_15 = {
    Text = "Casi nunca hemos estado en contacto con estos productos tecnológicos, y hay muchas reglas respecto a nuestras vidas diarias y comidas."
  },
  AvgCommunicate_94501_Content_16 = {
    Text = "Aunque la ropa y la comida son generalmente lujosas, no puedes comer excepto durante las horas de las comidas, y debes dejar los dormitorios una vez que es hora de levantarse."
  },
  AvgCommunicate_94501_Content_17 = {
    Text = "De niño, a menudo imaginaba cuándo podría dejar de despertar temprano y comer lo que quisiera todo el día."
  },
  AvgCommunicate_94501_Content_18 = {
    Text = "En estos días, he visto repetidamente a una joven llevando comida pasar por la tarde; parece que la vida con la que soñé aquí ya se ha convertido en rutina."
  },
  AvgCommunicate_94501_Content_19 = {
    Text = "¡Ah, es probable que Murphy haya ido a buscar los pastelitos... de hecho, tu vida parece realmente agotadora!"
  },
  AvgCommunicate_94501_Content_2 = {
    Text = "Escuché a Castor decir que se había añadido una cama especialmente a la casa, así que supe que debía ser tu obra."
  },
  AvgCommunicate_94501_Content_20 = {
    Text = "Todo ha pasado, esos errores y distorsiones quedarán en el pasado. Emprenderemos el camino correcto con un aspecto completamente nuevo, por favor sean testigos."
  },
  AvgCommunicate_94501_Content_21 = {
    Text = "¡No seas tan cortés! Si tienes algún problema, solo tienes que venir a verme a mí. Con una actitud así, ya eres incontablemente más tranquilo que algunos Despertados."
  },
  AvgCommunicate_94501_Content_3 = {
    Text = "Estamos acostumbrados a vivir juntos en el palacio desde jóvenes, y escuchar que los cuarteles aquí requieren una habitación por persona aún nos preocupa."
  },
  AvgCommunicate_94501_Content_4 = {
    Text = "Al ver que ahora consideras meticulosamente por nosotros, realmente me doy cuenta de que la sugerencia de Lady Thais de buscar refugio contigo en aquel entonces fue correcta."
  },
  AvgCommunicate_94501_Content_5 = {
    Text = "Ja, no es nada, ¿están todos cómodos viviendo aquí después de venir?"
  },
  AvgCommunicate_94501_Content_6 = {
    Text = "Gracias a tus cuidados, todo está bien. Aunque el palacio aquí es tan pequeño como la habitación de una sirvienta, está completamente amueblado y tras adaptarnos, se siente bastante cálido."
  },
  AvgCommunicate_94501_Content_7 = {
    Text = "Ahaha, ¿es así? Entonces eso es bueno, eso es bueno..."
  },
  AvgCommunicate_94501_Content_8 = {
    Text = "Hemos aprendido lentamente a vivir sin ser servidos; no necesitas preocuparte por nosotros. De hecho, esto es algo que ambos hemos soñado durante años."
  },
  AvgCommunicate_94501_Content_9 = {
    Text = "Especialmente el limpiador facial proporcionado en la habitación es verdaderamente mágico. Después de usarlo de acuerdo con las instrucciones, produce muchas burbujas similares a nubes, y el sabor de esa pasta de dientes también es muy refrescante."
  },
  AvgCommunicate_94501_Option_19 = {
    Text = "¡Ah, es probable que Murphy haya ido a buscar los pastelitos...!"
  },
  AvgCommunicate_94501_Option_21 = {
    Text = "Demasiado educado."
  },
  AvgCommunicate_94501_Option_5 = {
    Text = "Sin preocupaciones, sin preocupaciones."
  },
  AvgCommunicate_94501_Option_7 = {
    Text = "Ahaha, ¿es así? Entonces eso es bueno, eso es bueno..."
  },
  AvgCommunicate_94502_Content_1 = {
    Text = "Pido disculpas por la irrupción, pero, ¿podrías proporcionarnos una breve introducción...?"
  },
  AvgCommunicate_94502_Content_10 = {
    Text = "¡Oh! Debería ser Ogier y Lotan."
  },
  AvgCommunicate_94502_Content_11 = {
    Text = "Ogier... He anotado este nombre, esa juventud es recta y heroica, haciendo que nuestros corazones latan más rápido. Castor y yo inicialmente queríamos avanzar, pero rápidamente pasaron y se fueron."
  },
  AvgCommunicate_94502_Content_12 = {
    Text = "Después de regresar al dormitorio, nos revolvimos en la cama, realmente queriendo conocer a ese caballero, pero sin saber cómo empezar, así que vinimos a pedirte tu introducción, esperando que pudieras tomarte el tiempo y el esfuerzo para facilitar nuestro encuentro."
  },
  AvgCommunicate_94502_Content_13 = {
    Text = "Entiendo; en realidad, no necesitas ser tan cortés. Ogier es una persona muy cálida; siempre que hables, estará muy feliz de hacerse amigo de ti."
  },
  AvgCommunicate_94502_Content_14 = {
    Text = "Realmente admirable como un verdadero caballero, esta amplitud de miras es encomiable, dispuesto a aceptarnos a nosotros que alguna vez fuimos enemigos."
  },
  AvgCommunicate_94502_Content_15 = {
    Text = "No, no, esto no tiene nada que ver con ser de mente amplia! ¡Así es como hacen amigos las personas normales!"
  },
  AvgCommunicate_94502_Content_16 = {
    Text = "Aunque no todos los Despertados son personas normales... la mayoría aquí es bastante amable. Pueden interactuar con normalidad sin reservas."
  },
  AvgCommunicate_94502_Content_17 = {
    Text = "Lo siento, ¿podrías iluminarme, qué es... comunicación normal?"
  },
  AvgCommunicate_94502_Content_19 = {
    Text = "Entiendo, ¡déjame decirte el secreto para hacer amigos!"
  },
  AvgCommunicate_94502_Content_2 = {
    Text = "Desde que sugeriste que hiciéramos más amigos, Castor y yo hemos estado merodeando a menudo en lugares concurridos."
  },
  AvgCommunicate_94502_Content_20 = {
    Text = "¡Eso es iniciativa! ¡La sinceridad y la iniciativa son lo más conmovedor!"
  },
  AvgCommunicate_94502_Content_21 = {
    Text = "Recuerda, podrías ser rechazada o engañada, pero ese es el problema de quienes te hacen daño; nunca dudes de que la sinceridad es correcta."
  },
  AvgCommunicate_94502_Content_22 = {
    Text = "Entrena un corazón fuerte y luego experimenta valientemente la amistad"
  },
  AvgCommunicate_94502_Content_23 = {
    Text = "Tu sabiduría siempre me ha hecho venerarte y admirarte; realmente contemplaré tus enseñanzas, te agradeceré sinceramente, mi luz guía."
  },
  AvgCommunicate_94502_Content_3 = {Text = "¿Errante?"},
  AvgCommunicate_94502_Content_4 = {
    Text = "Así es, a menudo nos sentamos en silencio en el restaurante o en la plaza, observando a la multitud que pasa, tratando de no molestar a nadie."
  },
  AvgCommunicate_94502_Content_6 = {
    Text = "Eh, aunque tus intenciones son buenas, ¡sentarse aquí no hará amigos!"
  },
  AvgCommunicate_94502_Content_7 = {
    Text = "¡Así que así es! Estábamos restringidos por la etiqueta, pero no esperaba que hubiera un verdadero caballero aquí"
  },
  AvgCommunicate_94502_Content_8 = {
    Text = "Es posible que hayas escuchado de Castor que ambos siempre hemos admirado las historias de caballeros."
  },
  AvgCommunicate_94502_Content_9 = {
    Text = "Aquel día en la plaza, vimos a un joven sosteniendo una larga lanza, discutiendo la técnica de la lanza del caballero con una dama."
  },
  AvgCommunicate_94502_Option_10 = {
    Text = "¡Oh! Debería ser Ogier y Lotan."
  },
  AvgCommunicate_94502_Option_13 = {
    Text = "En realidad, no necesitas ser tan educado."
  },
  AvgCommunicate_94502_Option_15 = {
    Text = "¡Esto no tiene nada que ver con la sentimentalidad!"
  },
  AvgCommunicate_94502_Option_3 = {Text = "¿Errante?"},
  AvgCommunicate_95003_Content_1 = {
    Text = "Hey, pequeño, ¿tienes tiempo?"
  },
  AvgCommunicate_95003_Content_10 = {
    Text = "\"... Cuando las estrellas se alinean, el Santo Infante nacerá del vientre de la Madre Divina.\""
  },
  AvgCommunicate_95003_Content_11 = {
    Text = "\"... Aunque ya no realizamos rituales ni sacrificios, espero que esta información pueda inspirarte de alguna manera.\""
  },
  AvgCommunicate_95003_Content_12 = {
    Text = "\"... Si tengo tiempo, me gustaría discutir nuestro Rey Niño y Salvador contigo...\""
  },
  AvgCommunicate_95003_Content_13 = {
    Text = "......Ahora sé quién es."
  },
  AvgCommunicate_95003_Content_14 = {
    Text = "......Debí haber pensado en eso."
  },
  AvgCommunicate_95003_Content_15 = {
    Text = "Parece que este pequeño amigo conoce a alguien?"
  },
  AvgCommunicate_95003_Content_16 = {
    Text = "Así es... déjamelo a mí."
  },
  AvgCommunicate_95003_Content_17 = {
    Text = "La próxima vez que veas este tipo de carta, por favor no respondas, ¡y avísame de inmediato!"
  },
  AvgCommunicate_95003_Content_2 = {
    Text = "¿Hay algo mal?"
  },
  AvgCommunicate_95003_Content_3 = {
    Text = "No esperaba que después de ese día, algunas cartas realmente llegaran."
  },
  AvgCommunicate_95003_Content_4 = {
    Text = "Excluye aquellos que son tan falsos a simple vista, sorprendentemente hay algunos genuinos dentro."
  },
  AvgCommunicate_95003_Content_5 = {
    Text = "¡No puedo creer que alguien realmente cayó en eso!"
  },
  AvgCommunicate_95003_Content_6 = {
    Text = "Sin embargo, hay una carta que es bastante extraña; la ubicación de envío está dentro de Mitag."
  },
  AvgCommunicate_95003_Content_7 = {
    Text = "¡¿Qué?! Necesitamos notificar de inmediato a la oficina de seguridad."
  },
  AvgCommunicate_95003_Content_8 = {
    Text = "No te apresures; solo por si acaso, déjame primero decirte los puntos clave."
  },
  AvgCommunicate_95003_Content_9 = {
    Text = "\"... Antes, seleccionábamos a los bebés adecuados para llevar las responsabilidades de la Madre Divina.\""
  },
  AvgCommunicate_95003_Option_13 = {
    Text = "......Ahora sé quién es."
  },
  AvgCommunicate_95003_Option_14 = {
    Text = "......Debí haber pensado en eso."
  },
  AvgCommunicate_95004_Content_1 = {
    Text = "Hace tiempo que no te veo, mi pequeño Guardián."
  },
  AvgCommunicate_95004_Content_10 = {
    Text = "¡Ciertamente estas cosas son extrañas!!!"
  },
  AvgCommunicate_95004_Content_11 = {
    Text = "¡Ja ja, tal como pensé!"
  },
  AvgCommunicate_95004_Content_12 = {
    Text = "¿W... qué es lo mismo?"
  },
  AvgCommunicate_95004_Content_13 = {
    Text = "Aposté a Ismael que el pequeño se quedaría sorprendido al ver esto."
  },
  AvgCommunicate_95004_Content_14 = {
    Text = "Parece que he ganado"
  },
  AvgCommunicate_95004_Content_15 = {
    Text = "......¿Puedes decirme quién escribió este pasaje?"
  },
  AvgCommunicate_95004_Content_16 = {
    Text = "Aunque puedo escribir algo similar."
  },
  AvgCommunicate_95004_Content_17 = {
    Text = "Sin embargo, la declaración anterior fue de hecho solicitada por Ismael."
  },
  AvgCommunicate_95004_Content_18 = {
    Text = "......Muy bien, parece que ambos son los culpables."
  },
  AvgCommunicate_95004_Content_19 = {Text = "Eh, eh..."},
  AvgCommunicate_95004_Content_2 = {
    Text = "Ha pasado un tiempo desde que nos vimos por última vez, me pregunto si tu salud está bien."
  },
  AvgCommunicate_95004_Content_20 = {
    Text = "Hey, ¿pequeño?"
  },
  AvgCommunicate_95004_Content_21 = {
    Text = "Hey, ¿pequeño? ¿Todavía aquí?"
  },
  AvgCommunicate_95004_Content_22 = {
    Text = "No disponible, por favor deje un mensaje."
  },
  AvgCommunicate_95004_Content_23 = {
    Text = "Lo siento, lo siento, pequeño, no te enojes."
  },
  AvgCommunicate_95004_Content_24 = {
    Text = "Como compensación, los botines de esta caza serán entregados todos al pequeño como Dones."
  },
  AvgCommunicate_95004_Content_25 = {
    Text = "Vamos, ha pasado un tiempo, todos te extrañan tanto."
  },
  AvgCommunicate_95004_Content_26 = {
    Text = "......Hmph, bien, por el bien del regalo, te perdonaré esta vez!"
  },
  AvgCommunicate_95004_Content_27 = {
    Text = "Voy a arreglarme y luego iré, ¡no habrá una próxima vez!"
  },
  AvgCommunicate_95004_Content_28 = {
    Text = "(La próxima vez, utilicemos otros métodos para entretener al pequeño.)"
  },
  AvgCommunicate_95004_Content_29 = {
    Text = "¡Lo vi! ¡No habrá una próxima vez!"
  },
  AvgCommunicate_95004_Content_3 = {
    Text = "Si no hay nada ocurriendo hoy, me gustaría invitarte a participar en esta gran caza."
  },
  AvgCommunicate_95004_Content_4 = {
    Text = "Hemos preparado una buena posición para ti; todos están esperando tu llegada."
  },
  AvgCommunicate_95004_Content_5 = {
    Text = "Kai, ¿Kathigu-Ra? ¿Eres Kathigu-Ra???"
  },
  AvgCommunicate_95004_Content_6 = {
    Text = "Por supuesto, quien te habla es el Señor de las Llamas Explosivas, que nunca será olvidado."
  },
  AvgCommunicate_95004_Content_7 = {
    Text = "¡Kathigu-Ra, sé normal! ¡Estoy asustada!"
  },
  AvgCommunicate_95004_Content_8 = {
    Text = "¿Hay algo extraño en mis palabras?"
  },
  AvgCommunicate_95004_Content_9 = {
    Text = "¡Qué extraño!"
  },
  AvgCommunicate_95004_Option_10 = {
    Text = "¡Ciertamente estas cosas son extrañas!!!"
  },
  AvgCommunicate_95004_Option_9 = {
    Text = "¡Qué extraño!"
  },
  AvgCommunicate_95005_Content_1 = {
    Text = "Los amigos que a menudo hacen sacrificios saben esto."
  },
  AvgCommunicate_95005_Content_10 = {
    Text = "¿Crees que alguien caerá en esto?"
  },
  AvgCommunicate_95005_Content_11 = {
    Text = "¿Qué tal si, después de todo, nadie sabe lo que los cultistas están pensando?"
  },
  AvgCommunicate_95005_Content_12 = {
    Text = "¿Sería mejor llamar a Ryker para que te ayude?"
  },
  AvgCommunicate_95005_Content_13 = {
    Text = "Con su suerte, podría atrapar verdaderamente a varios cultistas."
  },
  AvgCommunicate_95005_Content_14 = {
    Text = "No hace falta, solo quiero ver al pequeño decir estas palabras."
  },
  AvgCommunicate_95005_Content_15 = {
    Text = "(?! ¿¡Es este un juego especial!)"
  },
  AvgCommunicate_95005_Content_16 = {
    Text = "La fecha de la acción se notificará más tarde, el pequeño no faltará."
  },
  AvgCommunicate_95005_Content_2 = {
    Text = "Es fácil reunir sacrificios, pero difícil invitar a lo divino."
  },
  AvgCommunicate_95005_Content_3 = {
    Text = "Por lo tanto, una invocación exitosa a menudo requiere múltiples modificaciones al sacrificio y ajustes al círculo ritual."
  },
  AvgCommunicate_95005_Content_4 = {
    Text = "Estamos aquí usando una mezcla secreta de sangre, complementada por setecientos setenta y siete cadáveres vivos, colocados en un círculo mágico especialmente diseñado."
  },
  AvgCommunicate_95005_Content_5 = {
    Text = "Esto puede maximizar la oportunidad de ganar el favor del Dios y convocarlo con éxito."
  },
  AvgCommunicate_95005_Content_6 = {
    Text = "¿Cuál es el método sacrificial allá?"
  },
  AvgCommunicate_95005_Content_7 = {
    Text = "¿Puedes escribir para decírmelo?"
  },
  AvgCommunicate_95005_Content_8 = {
    Text = "Por favor, escribe para compartir con nosotros."
  },
  AvgCommunicate_95005_Content_9 = {
    Text = "Esa es la sensación, buen trabajo pequeño."
  },
  AvgCommunicate_95005_Option_7 = {
    Text = "¿Puedes escribir para decírmelo?"
  },
  AvgCommunicate_95005_Option_8 = {
    Text = "Por favor, escribe para compartir con nosotros."
  },
  AvgCommunicate_96408_Content_1 = {
    Text = "¡Hola! Nos encargamos de la recuperación de cadáveres, precios asequibles, ¡ponte en contacto con nosotros! Se priorizan los cuerpos más completos antes del fallecimiento, ¡también ofrecemos envío a otras regiones!"
  },
  AvgCommunicate_96408_Content_10 = {
    Text = "¡Ah...! ¡Un invitado ha contactado! No me equivoqué al juzgarla."
  },
  AvgCommunicate_96408_Content_11 = {
    Text = "Mis utensilios de cocina han estado esperando por mucho tiempo. Hablamos luego."
  },
  AvgCommunicate_96408_Content_12 = {Text = "..."},
  AvgCommunicate_96408_Content_13 = {
    Text = "Supongo que haré como si no supiera qué planeas hacer."
  },
  AvgCommunicate_96408_Content_2 = {Text = "?!"},
  AvgCommunicate_96408_Content_3 = {
    Text = "¿Dul...Dursayn? ¿Ah???"
  },
  AvgCommunicate_96408_Content_4 = {
    Text = "¿Te han poseído???"
  },
  AvgCommunicate_96408_Content_5 = {
    Text = "Resulta ser el honorable Guardián del Secreto. Estaba intentando usar el comunicador para atraer clientes."
  },
  AvgCommunicate_96408_Content_6 = {
    Text = "¿Ya desde la primera vez que se usa se envían anuncios en grupo...? ¿De dónde has aprendido eso...?"
  },
  AvgCommunicate_96408_Content_7 = {
    Text = "El niño llamado Jenkins tiene una capacidad impresionante para comprender los sentimientos de las personas aquí."
  },
  AvgCommunicate_96408_Content_8 = {
    Text = "......Es ella."
  },
  AvgCommunicate_96408_Content_9 = {
    Text = "En comparación con el esfuerzo de escalar la cima de la gastronomía, comprender esta tecnología no es difícil."
  },
  AvgCommunicate_96408_Option_12 = {Text = "..."},
  AvgCommunicate_96408_Option_2 = {Text = "?!"},
  AvgCommunicate_96408_Option_3 = {Text = "¿Dursayn?"},
  AvgCommunicate_96408_Option_4 = {
    Text = "¿Te han quitado el cuerpo?"
  },
  AvgCommunicate_96408_Option_6 = {Text = "Cliente..."},
  AvgCommunicate_96408_Option_8 = {Text = "¡Jenkin!"},
  AvgCommunicate_96409_Content_1 = {
    Text = "Excelentísimo Guardián del Secreto, ¿tengo el honor de invitarlo a cenar?"
  },
  AvgCommunicate_96409_Content_10 = {
    Text = "He usado una nueva salsa que preparé especialmente para esta comida."
  },
  AvgCommunicate_96409_Content_11 = {
    Text = "¿Quieres probarlo? Excelencia, el Guardián del Secreto."
  },
  AvgCommunicate_96409_Content_12 = {
    Text = "Gracias por su favor..."
  },
  AvgCommunicate_96409_Content_13 = {
    Text = "Gracias por su favor..."
  },
  AvgCommunicate_96409_Content_14 = {
    Text = "Pero anoche me sentó mal la comida, me temo que no podré disfrutarlo."
  },
  AvgCommunicate_96409_Content_15 = {
    Text = "¿Así? Qué lástima."
  },
  AvgCommunicate_96409_Content_16 = {
    Text = "¿Cuántas veces has tenido problemas estomacales por comer?"
  },
  AvgCommunicate_96409_Content_17 = {Text = "Er..."},
  AvgCommunicate_96409_Content_18 = {
    Text = "Nunca haber probado la delicia de un cadáver fresco es realmente lamentable. Espero que puedas considerar seriamente mi invitación."
  },
  AvgCommunicate_96409_Content_19 = {
    Text = "La próxima vez seguro, la próxima vez seguro."
  },
  AvgCommunicate_96409_Content_2 = {
    Text = "He preparado una ensalada de tuétano con costillas de hombro sazonadas con ajo, tiernas y sabrosas, con un toque de nostalgia cálida de la infancia."
  },
  AvgCommunicate_96409_Content_3 = {
    Text = "Eh... suena como un olor que dejaría una sombra psicológica."
  },
  AvgCommunicate_96409_Content_4 = {
    Text = "Eso es natural. La materia prima era fisioterapeuta en vida, con un carácter suave y casi sin resentimientos."
  },
  AvgCommunicate_96409_Content_5 = {
    Text = "El dolor del pasado no dejó cicatrices en el alma, sino que la hizo especialmente dulce gracias al perdón..."
  },
  AvgCommunicate_96409_Content_6 = {
    Text = "...por lo tanto, su carne es cálida y suave, un manjar de primera calidad."
  },
  AvgCommunicate_96409_Content_7 = {Text = "..."},
  AvgCommunicate_96409_Content_8 = {
    Text = "Esto... realmente es muy especial."
  },
  AvgCommunicate_96409_Content_9 = {
    Text = "Lo más importante es que falleció en sueños esta mañana temprano, y su cuerpo aún está bastante fresco."
  },
  AvgCommunicate_96409_Option_12 = {
    Text = "¡Necesito medicina!"
  },
  AvgCommunicate_96409_Option_13 = {
    Text = "<Yellow:Rechazo cortés>"
  },
  AvgCommunicate_96409_Option_19 = {
    Text = "La próxima vez, seguro que sí."
  },
  AvgCommunicate_96409_Option_3 = {
    Text = "¿Es comestible esto...?"
