    Text = "Nivel máximo?"
  },
  AvgCommunicate_96410_Content_1 = {
    Text = "Guardián del secreto."
  },
  AvgCommunicate_96410_Content_10 = {
    Text = "¿Podría pasar por el mercado para averiguar la situación? Mi posición no me permite hacerlo."
  },
  AvgCommunicate_96410_Content_11 = {
    Text = "Como recompensa, prepararé para ti un plato que acabo de crear..."
  },
  AvgCommunicate_96410_Content_12 = {
    Text = "No es necesaria ninguna recompensa... Me alegra poder ayudar."
  },
  AvgCommunicate_96410_Content_13 = {
    Text = "No es necesaria ninguna recompensa... Me alegra poder ayudar."
  },
  AvgCommunicate_96410_Content_14 = {
    Text = "Gracias, Guardián del Secreto Excelencia."
  },
  AvgCommunicate_96410_Content_2 = {
    Text = "Con la llegada del Festival de los Espíritus, he decidido cocinar personalmente para agasajar a mis súbditos."
  },
  AvgCommunicate_96410_Content_3 = {
    Text = "Para determinar los lugares para comer juntos, quiero organizar un sorteo. Pero..."
  },
  AvgCommunicate_96410_Content_4 = {
    Text = "¿Qué problema hay?"
  },
  AvgCommunicate_96410_Content_5 = {
    Text = "¿Necesitas que te ayude?"
  },
  AvgCommunicate_96410_Content_6 = {
    Text = "La situación resultó tan caótica que algunos ciudadanos aprovecharon la confusión para hacerse con la mayoría de los lugares disponibles."
  },
  AvgCommunicate_96410_Content_7 = {
    Text = "¡Los lugares se subastaron a precios elevados en el mercado!"
  },
  AvgCommunicate_96410_Content_8 = {
    Text = "Por supuesto que entiendo el cariño de mis súbditos hacia mí. Pero comer debería ser una experiencia artística, y un privilegio otorgado no debe convertirse en un medio para obtener beneficios."
  },
  AvgCommunicate_96410_Content_9 = {
    Text = "Entonces, ¿qué quieres que haga?"
  },
  AvgCommunicate_96410_Option_12 = {
    Text = "¿Es esto una recompensa o un castigo?"
  },
  AvgCommunicate_96410_Option_13 = {Text = "..."},
  AvgCommunicate_96410_Option_4 = {
    Text = "Así que no viniste a invitarme a comer, qué bueno."
